/// Насколько быстрее вставки складывается убираемая строка очереди.
///
/// Уход короче прихода намеренно: приходящее провожают взглядом, уходящее —
/// нет, и равная длительность читается как задержка.
const QUEUE_LEAVE: f32 = 0.85;

/// За сколько гаснет окно под модалкой.
///
/// Короче прихода самой модалки намеренно: затемнение обязано успеть лечь
/// **до** того, как приедет окно, иначе слоя не читается — оба движения
/// сливаются в одно.
const MODAL_VEIL: f32 = 0.20;

/// Насколько модальное окно меньше своего размера, когда только приезжает.
///
/// Четыре процента: заметно, что окно приблизилось, и не заметно, что оно
/// при этом было другого размера. Больше — и текст внутри плывёт.
const MODAL_SCALE: f32 = 0.96;

/// Как модальное окно приезжает на этом кадре.
#[derive(Clone, Copy)]
struct ModalArrival {
    /// Насколько уже погасло окно под ним.
    veil: f32,
    /// Насколько приехало само окно: масштаб и не более того.
    rise: f32,
}

impl ModalArrival {
    /// Кладёт затемнение под модалку — своим слоем, ниже её собственного.
    ///
    /// Своим, а не `Modal::backdrop_color`, и это не прихоть: свою вуаль
    /// `Modal` рисует **в том же слое**, что и содержимое, — а слой модалки
    /// масштабируется (приём 11), и вуаль вместе с ним съёжилась бы, оставив
    /// по краям окна неприкрытую полосу. Модалке поэтому достаётся
    /// прозрачный цвет: щелчок мимо окна она ловит своим невидимым фоном,
    /// и `should_close` от этого не страдает.
    ///
    /// `Order::Middle` — выше панелей (`Background`) и ниже самой модалки
    /// (`Foreground`).
    fn veil(self, pal: theme::Palette, ctx: &egui::Context, name: &'static str) {
        if self.veil <= 0.0 {
            return;
        }
        let color = motion::mix(egui::Color32::TRANSPARENT, pal.modal_backdrop, self.veil);
        ctx.layer_painter(egui::LayerId::new(
            egui::Order::Middle,
            egui::Id::new("modal-veil").with(name),
        ))
        .rect_filled(ctx.content_rect(), 0.0, color);
    }

    /// Ставит слою модалки масштаб вокруг её середины.
    ///
    /// Своей вуали `Modal` при этом не рисует (ей передан прозрачный цвет),
    /// и это обязательно: вуаль он кладёт **в тот же слой**, что содержимое,
    /// — вместе со слоем она съёжилась бы, оставив по краям окна неприкрытую
    /// полосу. Поэтому затемнение рисуется отдельно, до модалки.
    ///
    /// Тождественное преобразование ставится тоже, а не пропускается:
    /// слой помнит своё, и забытый масштаб остался бы на окне навсегда.
    fn apply(self, ctx: &egui::Context, response: &egui::Response) {
        let scale = MODAL_SCALE + (1.0 - MODAL_SCALE) * self.rise;
        let centre = response.rect.center().to_vec2();
        ctx.set_transform_layer(
            response.layer_id,
            egui::emath::TSTransform::new(centre * (1.0 - scale), scale),
        );
    }
}

/// За сколько полоса прогресса догоняет присланную долю.
///
/// Не токен движения, а своё число, и намеренно: три общие длительности
/// описывают отклик интерфейса, а здесь речь о чужом темпе. yt-dlp шлёт
/// проценты рывками, и полоса обязана ехать **чуть дольше**, чем приходит
/// следующая строка, — иначе она успевает встать и снова дёрнуться.
const PROGRESS_CATCH_UP: f32 = 0.32;

const LOG_LIMIT: usize = 400;

/// Высота тела журнала в его панели, когда окну есть что отдать.
const LOG_HEIGHT: f32 = 150.0;

/// Ниже этого тело журнала не сжимается ни в каком окне.
///
/// Три строки: меньше журнал перестаёт читаться как журнал. В разрешённом
/// окне до пола дело не доходит (в 520×420 тело — 76 точек), он нужен окну
/// ниже разрешённого: такую геометрию выдают оконные менеджеры (см.
/// [`GpuErrors`]), и без пола высота тела ушла бы в минус.
const LOG_MIN_HEIGHT: f32 = 64.0;

/// Сколько прокрутки раздела остаётся на виду при открытом журнале, самое
/// меньшее.
///
/// Раньше журнал брал свои 150 точек при любом окне, и в окне 520×420 его
/// панель занимала 249 точек из 420, а разделу оставалось 86 — заголовок
/// карточки и поле ссылки, разрезанное поперёк (замер 2026-09-23; до
/// переезда кнопок в рельс, с подвалом, было и вовсе 22). Теперь уступает
/// журнал: 160 точек — это почти вдвое больше прежнего, а журналу в том же
/// окне остаются свои три строки с небольшим.
const SECTION_VIEW_MIN: f32 = 160.0;

/// Всё по высоте окна, что не тело журнала и не прокрутка раздела.
///
/// У журнала 99 точек — поля панели, кнопка «Скопировать», рамка вокруг
/// строк; у раздела 85 — поля, строка заголовка и зазор под ней. Снято
/// замером кадра 2026-09-23, и держит число
/// `the_open_log_leaves_the_section_its_view`: подрастёт обвязка — прокрутке
/// раздела не хватит до [`SECTION_VIEW_MIN`], и проверка упадёт.
const LOG_FRAMING: f32 = 184.0;

/// Высота тела журнала в окне такой высоты.
///
/// Считается от окна, а не от панели, и это главное. Панель узнаёт свой
/// размер по прошлому кадру, и счёт от неё замкнул бы тот же круг, что в
/// дефекте 27; размер окна раскладка не меняет, и кругу взяться неоткуда.
///
/// Прежде высота была числом, и в низком окне журнал съедал вкладку
/// (дефект 60). Урезается тело только в низком окне: с 494 точек высоты —
/// а значит, и в окне по умолчанию, 720×560, — оно во весь рост.
fn log_height(window: f32) -> f32 {
    (window - LOG_FRAMING - SECTION_VIEW_MIN).clamp(LOG_MIN_HEIGHT, LOG_HEIGHT)
}

/// Сколько сообщений от wgpu держим до того, как их разберёт кадр.
///
/// Потолок обязателен по Правилу 1, как `LOG_LIMIT` у журнала: пока окно
/// остаётся слишком большим, ошибка приходит на каждую попытку настроить
/// поверхность, то есть много раз в секунду и без конца.
const GPU_ERROR_LIMIT: usize = 4;

/// Ошибки wgpu, пойманные вместо падения процесса.
///
/// Клиентская часть окна — это текстура, и egui-wgpu просит у устройства ровно
/// 8192 пикселя по стороне жёстко зашитым числом, а поверхность настраивает
/// сырым размером окна, ничем его не ограничивая. Окно больше этого предела —
/// и `Surface::configure` отдаёт ошибку проверки, которую по умолчанию никто не
/// ловит: wgpu роняет процесс паникой. Программный размер окна приходит откуда
/// угодно — от оконного менеджера, удалённого рабочего стола, смены
/// разрешения, — и предотвратить его приложение не может: `max_inner_size`
/// система спрашивает только при перетаскивании рамки. Значит, остаётся
/// пережить: с этим обработчиком процесс остаётся жив, старая цепочка кадров
/// продолжает работать (wgpu-core выходит из `configure` до подмены
/// поверхности), а когда размер снова становится законным, рисование
/// восстанавливается само. Идущая загрузка при этом не теряется — ровно то,
/// ради чего всё и делается.
///
/// Проверено вживую: без обработчика окно с клиентом 504×8193 убивает процесс,
/// с ним — приложение живо и после возврата обычного размера рисует дальше.
#[derive(Default)]
struct GpuErrors {
    /// Взводится обработчиком, гасится кадром. Нужен, чтобы в обычном кадре
    /// (а ошибок не бывает почти никогда) дело не доходило до мьютекса:
    /// `ui()` зовут 60 раз в секунду.
    pending: AtomicBool,
    messages: Mutex<Vec<String>>,
}

impl GpuErrors {
    /// Зовётся из обработчика wgpu, то есть посреди чужого кода. Здесь нельзя
    /// ни паниковать, ни трогать состояние приложения — только отложить.
    fn push(&self, message: String) {
        let Ok(mut messages) = self.messages.lock() else {
            return;
        };
        // Пока окно остаётся большим, приходит одно и то же сообщение. Писать
        // его в журнал десятками одинаковых строк — значит вытеснить оттуда
        // всё остальное: у журнала свой предел, и он общий.
        if messages.last().is_some_and(|last| *last == message) {
            return;
        }
        if messages.len() < GPU_ERROR_LIMIT {
            messages.push(message);
            self.pending.store(true, Ordering::Release);
        }
    }

    /// Забирает накопленное. Пусто в подавляющем большинстве кадров, и тогда
    /// стоит одного атомарного чтения.
    fn take(&self) -> Vec<String> {
        if !self.pending.swap(false, Ordering::Acquire) {
            return Vec::new();
        }
        match self.messages.lock() {
            Ok(mut messages) => std::mem::take(&mut *messages),
            Err(_) => Vec::new(),
        }
    }
}

/// Приметы, по которым ошибка wgpu опознаётся как «окно больше, чем умеет
/// отрисовать видеокарта».
///
/// Подстроки английские и принадлежат wgpu — они могут смениться с новой
/// версией, и промах не поймает ни компилятор, ни тест (Правило 6). Поэтому
/// объяснение — не единственный исход: не узнали причину, значит показываем
/// сырой текст, а не молчим.
const GPU_TOO_LARGE_MARKS: [&str; 2] = [
    "maximum supported texture size",
    "max_texture_dimension_2d",
];

/// Строка для журнала по сообщению wgpu.
///
/// Приметы остаются английскими: они принадлежат wgpu и от языка окна
/// не зависят. Переводится только объяснение.
fn gpu_error_line(message: &str, lang: Lang) -> String {
    if GPU_TOO_LARGE_MARKS.iter().any(|mark| message.contains(mark)) {
        i18n::t(lang, Key::GpuTooLarge).to_owned()
    } else {
        i18n::fill(i18n::t(lang, Key::GpuDrawError), &[message])
    }
}

/// Ширина превью обложки в точках.
///
/// 128 — примерно четверть того, что остаётся от окна минимальной ширины
/// (520 минус поля дают 480): рядом с картинкой обязано помещаться название,
/// а сама она стоит теперь в карточке управления, между полем ссылки и
/// переключателем формата, — то есть отнимает высоту у всего остального.
/// Движок уменьшает обложку до 480 настоящих точек, так что на экране
/// с двойной плотностью превью остаётся резким.
const PREVIEW_WIDTH: f32 = 128.0;

/// Потолок высоты превью.
///
/// Нужен из-за вертикальных роликов: обложка 9:16 при ширине 128 заняла бы
/// 227 точек — половину окна минимальной высоты (420) на одну картинку.
/// С потолком такая просто становится узкой, а не выдавливает поля ввода
/// в прокрутку. 72 — высота обычной обложки 16:9 при ширине 128.
const PREVIEW_MAX_HEIGHT: f32 = 72.0;

/// Сколько ждать после правки ссылки, прежде чем спрашивать сайт.
///
/// Окно ожидания обязательно. Без него запрос уходил бы на каждый набранный
/// символ: вставка из буфера — это одно изменение, а ссылка, набранная руками
/// или правленная по частям, — десятки, и сайт получил бы десятки запросов
/// об одном ролике. Прямая дорога к «Sign in to confirm you're not a bot»,
/// заработанная на ровном месте и ровно тем, что должно было помогать.
const PREVIEW_DEBOUNCE: f64 = 0.8;

/// Потолок высоты раскрытого списка источников входа.
///
/// Считается от числа источников, а не подобран на глаз: добавится браузер —
/// список подрастёт сам, и никто не будет гадать, почему последний пункт
/// уехал в прокрутку. 28 — строка списка (26 точек) плюс промежуток (2),
/// 12 — поля рамки меню сверху и снизу.
const COOKIE_LIST_HEIGHT: f32 = CookieSource::ALL.len() as f32 * 28.0 + 12.0;

/// Что написано на кнопке файла cookies, пока файла нет.
///
/// Щелчками в окне до этой надписи не дойти: пункт «Из файла…» сам открывает
/// диалог, а отказ от диалога возвращает прежний выбор (см. `cookie_selector`).
/// А вот запомненные настройки — доходят: в `settings.json` может стоять
/// `"cookies": "file"` без пути, если путь не выразился в UTF-8. Кнопка тогда
/// приглашает выбрать файл, то есть предлагает ровно то, что делает по нажатию.
const PICK_COOKIE_FILE: Key = Key::UiPickCookieFile;


/// Потолок высоты раскрытого списка языков субтитров.
///
/// Здесь, в отличие от списка браузеров, вместить всё нельзя и пытаться:
/// список приходит от источника, и у YouTube в автоматических субтитрах
/// полторы сотни языков (проверено на живом ответе `-J`). Значение выбрано
