/// Лицензия. Из `Cargo.toml` по той же причине, что и адрес страницы.
const LICENSE: &str = env!("CARGO_PKG_LICENSE");

enum State {
    Idle,
    /// В очереди есть ссылки, но ничего не качается: их поставили и ещё не
    /// запустили. Отдельно от `Idle`, потому что экран говорит разное:
    /// «вставьте ссылку» и «нажмите „Скачать“ — очередь пойдёт» — это
    /// два разных следующих шага.
    Queued,
    Running,
    Done(PathBuf),
    Failed(String),
    Cancelled,
}

/// Установка недостающих инструментов при первом запуске.
///
/// Отдельно от `State`: это состояние подготовки, а не загрузки, и живёт оно
/// строго до первого показа основного экрана.
enum Setup {
    /// Всё на месте — обычный случай при любом запуске, кроме первого.
    Ready,
    Installing,
    /// Обновление одного инструмента по кнопке. Отдельно от `Installing` ради
    /// подписи в модалке: «Установка зависимостей» при обновлении сбивала бы
    /// с толку — пользователь ничего не устанавливал. И с указанием, чего
    /// именно: тексты у обновления yt-dlp и ffmpeg разные не для красоты —
    /// одно занимает секунды, другое качает больше сотни мегабайт.
    Updating(setup::Component),
    /// Установка не удалась. Приложение всё равно открывается: без `yt-dlp`
    /// пользователь увидит привычную подсказку, что делать дальше.
    Failed(String),
}

impl Setup {
    /// Идёт ли работа с внешними инструментами прямо сейчас. Пока идёт,
    /// показана модалка и занят единственный канал событий.
    fn busy(&self) -> bool {
        matches!(self, Setup::Installing | Setup::Updating(_))
    }
}

/// Какой экран показан.
///
/// Вкладки, а не один длинный экран: в окне минимального размера (520×420)
/// загрузка и работа с метаданными вместе уехали бы в прокрутку целиком.
///
/// В дорожке шапки их три, а не пять, и это выбор макета. Пять коротких
/// подписей в одной дорожке кончались тем, что «Метаданные» вставали впритык
/// и шестой вкладке места уже не оставалось. Поэтому «Система» и «Монитор» —
/// это подвкладки «Машины» (там и там речь об одной и той же машине, только
/// в разрезе «сейчас» и «состав»), «История» переехала в правую колонку
/// экрана загрузки, к очереди, а всё, что сверх трёх, живёт в меню «Ещё»
/// (см. [`MORE_TABS`]).
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum Tab {
    Download,
    Metadata,
    Machine,
    /// Живёт в меню «Ещё», а не в дорожке.
    Weather,
    /// Раздача файлов на телефон. Тоже в меню «Ещё».
    Phone,
}

/// Все разделы — для тех, кто обязан спросить про каждый (см. `tab_arrival`).
const ALL_TABS: [Tab; 5] = [
    Tab::Download,
    Tab::Metadata,
    Tab::Machine,
    Tab::Weather,
    Tab::Phone,
];

/// Значок раздела в свёрнутом рельсе.
///
/// Рисуется кистью, а не знаком из шрифта, и это не вкусовщина. Подходящих
/// знаков в наших девяти гарнитурах нет, а штатный хвост eframe закрывает
/// далеко не всё: «✓» (U+2713) не нашлось **ни в одном** из тринадцати
/// доступных файлов, «⋯» (U+22EF) есть только в Hack, а Hack стоит лишь
/// в `Monospace`, куда запасной глиф egui не заглядывает. Отсутствующий знак
/// рисуется пустым прямоугольником, и не видят этого ни сборка, ни `clippy`,
/// ни тесты — только глаза. Кисть от этого избавлена вовсе.
#[derive(Clone, Copy, PartialEq, Eq)]
enum NavIcon {
    /// Стрелка вниз в поддон — загрузка.
    Download,
    /// Ярлык с отверстием — метаданные.
    Metadata,
    /// Стрелка на шкале — что происходит сейчас.
    Gauge,
    /// Кристалл с ножками — из чего машина состоит.
    Chip,
    /// Облако с солнцем — погода.
    Sky,
    /// Прямоугольник с кнопкой — телефон.
    Phone,
}

/// Пункт рельса: раздел, его подпись и значок.
#[derive(Clone, Copy)]
struct NavItem {
    tab: Tab,
    /// Для «Машины» — какая из её половин. У остальных `None`.
    half: Option<MachineTab>,
    label: Key,
    icon: NavIcon,
    /// Строка «что это даёт» под названием раздела в приветствии.
    ///
    /// Полем пункта, а не своим списком у приветствия: раздел, добавленный
    /// в рельс без этой строки, не соберётся — а свой список отстал бы от
    /// рельса молча, и новый раздел просто не попал бы в приветствие.
    pitch: Key,
}

impl NavItem {
    /// Открыт ли сейчас этот пункт.
    fn is_open(&self, tab: Tab, half: MachineTab) -> bool {
        self.tab == tab && self.half.is_none_or(|mine| mine == half)
    }
}

/// Состав рельса: три группы по смыслу, шесть пунктов на виду.
///
/// «Ещё» больше нет, и это главное, ради чего рельс и заведён: «Погода»
/// с «Телефоном» жили в меню, то есть не существовали для того, кто в меню
/// не залез. Половины «Машины» тоже стали обычными пунктами — опрос
/// по-прежнему привязан к открытой половине (`machine_tab`), меняется только
/// то, чем она выбирается.
const NAV: [(Key, &[NavItem]); 3] = [
    (
        Key::NavGroupFiles,
        &[
            NavItem {
                tab: Tab::Download,
                half: None,
                label: Key::TabDownload,
                icon: NavIcon::Download,
                pitch: Key::WelcomeDownloadPitch,
            },
            NavItem {
                tab: Tab::Metadata,
                half: None,
                label: Key::TabMetadata,
                icon: NavIcon::Metadata,
                pitch: Key::WelcomeMetadataPitch,
            },
        ],
    ),
    (
        Key::NavGroupComputer,
        &[
            NavItem {
                tab: Tab::Machine,
                half: Some(MachineTab::Now),
                label: Key::MachineNow,
                icon: NavIcon::Gauge,
                pitch: Key::WelcomeMachineNowPitch,
            },
            NavItem {
                tab: Tab::Machine,
                half: Some(MachineTab::Spec),
                label: Key::MachineSpec,
                icon: NavIcon::Chip,
                pitch: Key::WelcomeMachineSpecPitch,
            },
        ],
    ),
    (
        Key::NavGroupNearby,
        &[
            NavItem {
                tab: Tab::Weather,
                half: None,
                label: Key::TabWeather,
                icon: NavIcon::Sky,
                pitch: Key::WelcomeWeatherPitch,
            },
            NavItem {
                tab: Tab::Phone,
                half: None,
                label: Key::TabPhone,
                icon: NavIcon::Phone,
                pitch: Key::WelcomePhonePitch,
            },
        ],
    ),
];

/// Что случилось в рельсе за кадр.
///
/// Всё собирается и применяется **после** отрисовки, а не по месту: половина
/// этих действий трогает `self` целиком (смена языка пересобирает десяток
/// заранее собранных строк), а `self` на это время занят рисованием.
#[derive(Default)]
struct RailPicks {
    /// Выбранный раздел и, для «Машины», половина.
    section: Option<(Tab, Option<MachineTab>)>,
    about: bool,
    lang: Option<Lang>,
    appearance: Option<Appearance>,
    toggle_log: bool,
    /// Нажали «?» — открыть приветствие.
    welcome: bool,
    smooth: Option<bool>,
    update: Option<setup::Component>,
    /// Открыто ли меню свёрнутого рельса. Ездит туда и обратно, а не полем
    /// окна внутри отрисовки: `RailState` заимствует `self` целиком, и
    /// `&mut self.more_open` рядом с ним не ужился бы.
    more_open: bool,
}

/// Как разложен рельс разделов.
///
/// Три вида, а не «свёрнут или развёрнут». Развёрнутому рельсу со всем
/// блоком обслуживания нужно под 800 точек высоты, а окно ноутбука
/// 1920×1080 при масштабе 125 % даёт меньше: свернуть там рельс целиком
/// значило бы отнять подписи разделов у самого частого окна. Поэтому между
/// крайностями есть середина — подписи на месте, а блок, как у свёрнутого,
/// во всплывающем меню.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum RailLayout {
    /// Одни значки; нижний блок — во всплывающем меню.
    Narrow,
    /// Подписи на месте, нижний блок — во всплывающем меню.
    Labels,
    /// Подписи и нижний блок на месте.
    Full,
}

impl RailLayout {
    /// Вид рельса для окна такого размера.
    ///
    /// Ширина решает, есть ли место подписям (`theme::NAV_WIDE_MIN`), высота
    /// — поместятся ли пункты и блок, не ложась друг на друга: прокрутки у
    /// рельса нет, и в низком окне блок рисовался прямо поверх пунктов.
    fn for_window(room: egui::Vec2) -> Self {
        if room.x < theme::NAV_WIDE_MIN || room.y < theme::NAV_LABELS_MIN_HEIGHT {
            Self::Narrow
        } else if room.y < theme::NAV_WIDE_MIN_HEIGHT {
            Self::Labels
        } else {
            Self::Full
        }
    }

    /// Видны ли подписи пунктов.
    fn labels(self) -> bool {
        self != Self::Narrow
    }

    /// Ширина рельса.
    fn width(self) -> f32 {
        if self.labels() {
            theme::NAV_WIDTH
        } else {
            theme::NAV_NARROW
        }
    }
}

impl RailPicks {
    /// Нажато ли то, что открывает своё окно или панель.
    ///
    /// Меню свёрнутого рельса после такого закрывается само: оставшись
    /// поверх, оно заслоняло бы то, ради чего нажимали. Переключатели темы
    /// и плавности его не закрывают — в развёрнутом рельсе тот же блок стоит
    /// на месте, и результат щелчка там видно сразу, без повторного захода.
    fn opens_something(&self) -> bool {
        self.about || self.welcome || self.toggle_log || self.update.is_some()
    }
}

/// Всё, что рельсу нужно знать об окне, чтобы себя нарисовать.
///
/// Группой, а не дюжиной аргументов подряд: столько позиционных аргументов
/// на месте вызова не прочитать, да и `clippy` их не пропустит. Заодно это
/// делает рельс проверяемым кадром без окна — собрать `RailState` дешевле,
/// чем целый `SavioApp`.
struct RailState<'a> {
    pal: theme::Palette,
    speed: f32,
    lang: Lang,
    tab: Tab,
    half: MachineTab,
    appearance: Appearance,
    /// Названия групп прописными, собранные заранее (Правило 1).
    groups: &'a [String; 3],
    /// Строка версий инструментов. Пустая — опрос ещё идёт.
    tools: &'a str,
    smooth: bool,
    /// Есть ли что показывать в журнале.
    has_log: bool,
    log_open: bool,
    /// Занят ли единственный канал событий: обновляться нечем.
    busy: bool,
    more_open: bool,
}

/// Какая половина вкладки «Машина» показана.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum MachineTab {
    /// Что происходит с машиной прямо сейчас — бывшая вкладка «Монитор».
    Now,
    /// Из чего машина состоит и в каком она состоянии — бывшая «Система».
    Spec,
}

/// Что показано в правой колонке экрана загрузки.
#[derive(Clone, Copy, PartialEq, Eq)]
enum RailTab {
    Queue,
    History,
}

/// Сколько загрузок помним.
///
/// Потолок обязателен по Правилу 1, как и `LOG_LIMIT`: без него список рос бы
/// всё время работы окна, а по одной ссылке-плейлисту приезжают сотни готовых
/// файлов подряд. 50 — заведомо больше, чем скачивают за один запуск, и при
/// этом столько, сколько ещё можно пролистать глазами.
const HISTORY_LIMIT: usize = 50;

/// Одна строка истории: что скачали и где оно лежит.
///
/// Строки собираются один раз, на приёме `Event::Done`, — в кадре отрисовки
/// не остаётся ни `format!`, ни `display()` (Правило 1).
struct HistoryEntry {
    /// Имя файла.
    name: String,
    /// Папка, которую открывает кнопка. `None` — открывать нечего,
    /// и кнопки тогда нет.
    dir: Option<PathBuf>,
    /// Та же папка строкой. Пустая, когда `dir` — `None`.
    dir_display: String,
    /// Полный путь: по нему узнаём повторную загрузку того же файла.
    path: PathBuf,
}

/// История загрузок за текущий запуск.
///
/// Живёт только в памяти и только до закрытия окна — на диск не пишется
/// ничего. Отдельный тип, а не голый `Vec`, ровно ради потолка: держать его
/// в одном месте надёжнее, чем помнить про `truncate` в каждом месте, где
/// в список что-то кладут.
#[derive(Default)]
struct History {
    /// Сверху самое свежее: ищут обычно последнее скачанное.
    entries: Vec<HistoryEntry>,
}

impl History {
    /// Запоминает готовый файл.
    ///
    /// Тот же путь второй раз не заводит новую строку, а поднимает старую
    /// наверх: перекачать файл заново — обычное дело (выбрали не тот формат,
    /// оборвалась связь), и две одинаковые строки подряд выглядели бы сбоем.
    fn remember(&mut self, path: &Path) {
        self.entries.retain(|entry| entry.path.as_path() != path);

        // Пустого родителя отбрасываем вместе с отсутствующим: у относительного
        // «file.mp4» `parent()` возвращает не `None`, а `Some("")`, и такой
        // «папкой» проводнику открывать нечего. От yt-dlp приходят абсолютные
        // пути, так что это страховка, а не рабочий случай.
        let dir = path
            .parent()
            .filter(|dir| !dir.as_os_str().is_empty())
            .map(Path::to_path_buf);

        self.entries.insert(
            0,
            HistoryEntry {
                // Путь без имени файла (корень диска) в `Event::Done` прийти
                // не может, но пустая строка в списке выглядела бы поломкой —
                // показываем тогда путь целиком.
                name: path
                    .file_name()
                    .unwrap_or(path.as_os_str())
                    .to_string_lossy()
                    .into_owned(),
                dir_display: dir
                    .as_deref()
                    .map(|dir| dir.display().to_string())
                    .unwrap_or_default(),
                dir,
                path: path.to_path_buf(),
            },
        );

        self.entries.truncate(HISTORY_LIMIT);
    }
}

// ---------------------------------------------------------------------------
// Очередь загрузок
// ---------------------------------------------------------------------------

/// Сколько ссылок помещается в очередь.
///
/// Потолок обязателен по Правилу 1, как `LOG_LIMIT` у журнала и
/// `HISTORY_LIMIT` у истории: без него список рос бы всё время работы окна.
/// 50 — столько же, сколько помнит история, и заведомо больше, чем ставят
/// в очередь за один заход.
const QUEUE_LIMIT: usize = 50;

/// Что происходит с элементом очереди.
///
/// `Failed` несёт текст причины, а не голый признак. Причина в сроке жизни:
/// журнал очищается перед каждой следующей загрузкой, и к тому времени, как
/// человек вернётся к ушедшей в ночь очереди, от объяснения не осталось бы
/// ничего. А узнать, почему не скачалась третья ссылка из десяти, — ровно то,
/// зачем в этот список потом смотрят.
#[derive(Clone, PartialEq, Eq, Debug)]
enum QueueStatus {
    /// Ждёт своей очереди.
    Waiting,
    /// Качается прямо сейчас. Такой элемент в списке не больше одного —
    /// это и есть правило «строго по одному» из `start_next`.
    Running,
    Done,
    Failed(String),
    /// Снята человеком: нажали «Отмена», пока она качалась. Не ошибка
    /// (Правило 2), поэтому и слово, и цвет у неё спокойные.
    Cancelled,
}

impl QueueStatus {
    /// Отработал ли элемент — всё равно, чем кончилось.
    ///
    /// По этому признаку очередь освобождает место под новые ссылки:
    /// выбрасывать можно только то, что уже отработало.
    fn finished(&self) -> bool {
        matches!(
            self,
            QueueStatus::Done | QueueStatus::Failed(_) | QueueStatus::Cancelled
        )
    }

    /// Слово для строки списка. Статическое: в кадре отрисовки ничего
    /// не собирается и не выделяется.
    fn label(&self, lang: Lang) -> &'static str {
        i18n::t(
            lang,
            match self {
                QueueStatus::Waiting => Key::QueueWaiting,
                QueueStatus::Running => Key::QueueRunning,
                QueueStatus::Done => Key::QueueDone,
                QueueStatus::Failed(_) => Key::QueueFailed,
                QueueStatus::Cancelled => Key::QueueCancelled,
            },
        )
    }

    /// Цвет точки и подписи состояния.
    ///
    /// Все пары проверены на `BG_ELEVATED` (заливка строки списка) по
    /// WCAG 2.1: `ACCENT` — 11.07:1, `STATE_SUCCESS` — 8.91:1,
    /// `STATE_ERROR` — 5.61:1, `TEXT_SECONDARY` — 7.83:1,
    /// `TEXT_MUTED` — 5.12:1. Порог 4.5:1 проходят все.
    ///
    /// Цветом одним состояние не передаётся: рядом с точкой всегда стоит
    /// слово из `label()`.
    fn color(&self, pal: theme::Palette) -> egui::Color32 {
        match self {
            QueueStatus::Waiting => pal.text_muted,
            QueueStatus::Running => pal.accent,
            QueueStatus::Done => pal.state_success,
            QueueStatus::Failed(_) => pal.state_error,
            QueueStatus::Cancelled => pal.text_secondary,
        }
    }
}

/// Одна ссылка в очереди.
///
/// Запрос и папку держим снимком, а не подсматриваем текущий выбор на экране:
/// пока очередь идёт, человек волен переключить формат под следующую ссылку,
/// и уже поставленное от этого меняться не должно. Иначе десяток ссылок,
/// поставленных как MP3, доехал бы до диска как MP4 — и заметить это можно
/// было бы, только открыв файлы.
struct QueueItem {
    id: DownloadId,
    request: Request,
    out_dir: PathBuf,
    /// Первая строка списка: название ролика, а пока оно не приехало от
    /// `probe` — сама ссылка.
    title: String,
    /// Вторая строка: «состояние · формат · качество». Собирается при смене
    /// состояния, а не в кадре отрисовки (Правило 1).
    detail: String,
    /// Причина отказа, разложенная в одну строку. Пустая — отказа не было.
    error_line: String,
    status: QueueStatus,
    /// Ответ `probe`, если предпросмотр успел его получить до того, как ссылку
    /// поставили в очередь.
    ///
    /// Едет вместе со ссылкой, а не берётся из предпросмотра в момент запуска,
    /// по той же причине, по какой снимком держится сам запрос: пока очередь
    /// идёт, в поле давно другая ссылка, и ответ там про неё.
    known: Option<MediaInfo>,
    /// Когда по крестику щёлкнули, по часам egui. `None` — строка живёт.
    ///
    /// Строка не пропадает по щелчку, а складывается: соседи сходятся, а не
    /// прыгают на её место (приём 10). Убирает её из списка `sweep_queue`,
    /// когда складывание доиграло, — то есть удаление отложено ровно на один
    /// цикл и **не** отменяется ничем: помеченная строка уже не считается
    /// живой очередью нигде, кроме отрисовки.
    removing_since: Option<f64>,
}

impl QueueItem {
    /// Пересобирает строки, зависящие от состояния. Зовётся при его смене —
    /// в кадре отрисовки здесь не собирается ничего (Правило 1).
    fn rebuild_strings(&mut self, lang: Lang) {
        let format = self.request.format;
        self.detail.clear();
        self.detail.push_str(self.status.label(lang));
        self.detail.push_str(" · ");
        self.detail.push_str(format.short());
        self.detail.push_str(" · ");
        self.detail
            .push_str(self.request.quality.label_with_unit(format, lang));

        // Причину раскладываем в одну строку, и это не косметика:
        // `explain_failure` отдаёт текст с переносами, а метка с `truncate()`
        // показывает ровно первую строку. Выходило «Ошибка (код 1):…» —
        // подпись, которая не говорит ничего. Проверено глазами.
        self.error_line.clear();
        if let QueueStatus::Failed(message) = &self.status {
            for (index, word) in message.split_whitespace().enumerate() {
                if index > 0 {
                    self.error_line.push(' ');
                }
                self.error_line.push_str(word);
            }
        }
    }
}

/// Очередь загрузок за текущий запуск.
///
/// Отдельный тип, а не голый `Vec` в `SavioApp`, — по той же причине, что и
/// у `History`: потолок и сводка обязаны пересчитываться в одном месте.
/// Забыть про них в одной из точек изменения значило бы либо съесть память,
/// либо показать вчерашние цифры — и ни того ни другого не увидят ни сборка,
/// ни `clippy`.
///
/// Живёт только в памяти и только до закрытия окна, как и история.
struct Queue {
    /// Порядок здесь — порядок загрузки: сверху вниз, строго по одной.
    items: Vec<QueueItem>,
    /// Номер следующей загрузки. Растёт и никогда не переиспользуется:
    /// на этом держится вся развязка событий (см. `model::DownloadId`).
    next_id: DownloadId,
    /// «Идёт: 1 · В очереди: 3 · Готово: 5» — собирается при изменении
    /// очереди, а не в кадре отрисовки.
    summary: String,
    /// Мест больше нет, и освободить нечем. Считается там же, где сводка:
    /// перебирать полсотни строк 60 раз в секунду ради одного `bool` незачем.
    full: bool,
    /// На каком языке собраны готовые строки списка.
    ///
    /// Полем, а не аргументом каждого вызова: строки пересобираются в десятке
    /// мест, и язык, забытый в одном из них, оставил бы одну строку списка
    /// на прежнем языке — молча и только у той ссылки, которую как раз
    /// переключили.
    lang: Lang,
}

impl Queue {
    fn new(lang: Lang) -> Self {
        Self {
            items: Vec::new(),
            // С единицы, а не с нуля: ноль занят под `NO_DOWNLOAD`.
            next_id: 1,
            summary: String::new(),
            full: false,
            lang,
        }
    }

    /// Пересобирает все готовые строки на новом языке.
    fn relabel(&mut self, lang: Lang) {
        self.lang = lang;
        for item in &mut self.items {
            item.rebuild_strings(lang);
        }
        self.rebuild_summary();
    }

    /// Ставит ссылку в конец очереди и отдаёт её номер.
    ///
    /// `None` — места нет: все `QUEUE_LIMIT` ссылок ещё ждут своего часа.
    ///
    /// `known` — ответ предпросмотра по этой ссылке, если он есть. С ним
    /// строка списка сразу называется роликом, а не адресом: до появления
    /// предпросмотра название приезжало только с началом загрузки, то есть
    /// у девятой ссылки — через час после того, как её поставили.
    fn push(
        &mut self,
        request: Request,
        out_dir: PathBuf,
        known: Option<MediaInfo>,
    ) -> Option<DownloadId> {
        if !self.make_room() {
            return None;
        }

        let id = self.next_id;
        // Четыре миллиарда ссылок за один запуск недостижимы, но `+= 1`
        // в отладочной сборке паникует на переполнении, а `wrapping_add` нет.
        // `max(1)` держит ноль занятым под `NO_DOWNLOAD`.
        self.next_id = self.next_id.wrapping_add(1).max(1);

        let mut item = QueueItem {
            id,
            title: known
                .as_ref()
                .and_then(|info| info.title.clone())
                .unwrap_or_else(|| request.url.clone()),
            detail: String::new(),
            error_line: String::new(),
            request,
            out_dir,
            status: QueueStatus::Waiting,
            known,
            removing_since: None,
        };
        item.rebuild_strings(self.lang);

        self.items.push(item);
        self.rebuild_summary();
        Some(id)
    }

    /// Освобождает место под новую ссылку.
    ///
    /// Выбрасывает самую старую отработавшую строку, а не самую старую вообще:
    /// ожидающая ссылка — это невыполненная просьба, и молча терять её нельзя.
    /// Не нашлось ни одной отработавшей — очередь и правда полна, и сказать
    /// об этом надо словами, а не молчаливым отказом.
    fn make_room(&mut self) -> bool {
        if self.items.len() < QUEUE_LIMIT {
            return true;
        }
        match self.items.iter().position(|item| item.status.finished()) {
            Some(index) => {
                self.items.remove(index);
                true
            }
            None => false,
        }
    }

    /// Что запускать следующим: номер, запрос, папка и готовый ответ `probe`.
    ///
    /// Отдаёт копии, а не ссылки: `engine::start` забирает `Request` во
    /// владение, а строка обязана остаться в списке — по ней рисуется
    /// состояние, и в неё же приходит исход.
    fn next_waiting(&self) -> Option<(DownloadId, Request, PathBuf, Option<MediaInfo>)> {
        // Помеченная крестиком строка ждущей больше не считается, хотя ещё
        // и рисуется: иначе «Скачать», нажатое в те четверть секунды, что она
        // складывается, запустило бы ровно то, что убрали.
        let item = self
            .items
            .iter()
            .find(|item| item.status == QueueStatus::Waiting && item.removing_since.is_none())?;
        Some((
            item.id,
            item.request.clone(),
            item.out_dir.clone(),
            item.known.clone(),
        ))
    }

    fn has_waiting(&self) -> bool {
        self.items
            .iter()
            .any(|item| item.status == QueueStatus::Waiting && item.removing_since.is_none())
    }

    /// Помечает строку убираемой: с этого мгновения она складывается.
    ///
    /// Не удаляет сразу и не откладывает решение до следующего кадра: строка
    /// остаётся в списке ровно затем, чтобы её было чем рисовать, пока
    /// складывание идёт. Убирает её [`SavioApp::sweep_queue`].
    fn mark_removing(&mut self, id: DownloadId, now: f64) {
        if let Some(item) = self
            .items
            .iter_mut()
            .find(|item| item.id == id && item.status == QueueStatus::Waiting)
        {
            item.removing_since = Some(now);
            self.rebuild_summary();
        }
    }

    /// Номер идущей загрузки. Такая в списке не больше одной.
    fn running_id(&self) -> Option<DownloadId> {
        self.items
            .iter()
            .find(|item| item.status == QueueStatus::Running)
            .map(|item| item.id)
    }

    /// Запрос идущей загрузки. Нужен, чтобы понять, про ту ли ссылку приехали
    /// её метаданные, — см. `Preview::is_about`.
    fn running_request(&self) -> Option<&Request> {
        self.items
            .iter()
            .find(|item| item.status == QueueStatus::Running)
            .map(|item| &item.request)
    }

    /// Идёт ли прямо сейчас загрузка с таким номером.
    ///
    /// Здесь и живёт вся развязка событий: у снятой секунду назад загрузки
    /// процесс ещё дописывает свой вывод, и её `Failed` пометил бы ошибкой
    /// уже следующий элемент очереди. Событию установки (`NO_DOWNLOAD`)
    /// эта проверка отвечает «нет» — номера с нуля не начинаются.
    fn is_running(&self, id: DownloadId) -> bool {
        self.items
            .iter()
            .any(|item| item.id == id && item.status == QueueStatus::Running)
    }

    fn set_status(&mut self, id: DownloadId, status: QueueStatus) {
        let lang = self.lang;
        if let Some(item) = self.items.iter_mut().find(|item| item.id == id) {
            item.status = status;
            item.rebuild_strings(lang);
        }
        self.rebuild_summary();
    }

    /// Заменяет ссылку в строке названием ролика.
    ///
    /// До `probe` названия нет, и в списке стоит сама ссылка. Как только оно
    /// приезжает — меняем: десяток ссылок с одного сайта различается тремя
    /// символами в конце, а названия — с первого взгляда.
    fn set_title(&mut self, id: DownloadId, title: &str) {
        if let Some(item) = self.items.iter_mut().find(|item| item.id == id) {
            item.title.clear();
            item.title.push_str(title);
        }
    }

    /// Убирает строку из списка.
    ///
    /// Идущую загрузку не трогает: её процесс продолжил бы качать, а показать
    /// исход стало бы негде. Кнопки «убрать» у неё и нет — это страховка на
    /// случай, если она там однажды появится. Останавливают загрузку
    /// «Отменой», и это другое действие.
    fn remove(&mut self, id: DownloadId) {
        self.items
            .retain(|item| item.id != id || item.status == QueueStatus::Running);
        self.rebuild_summary();
    }

    /// Убирает всё, кроме идущей загрузки, — по кнопке «Очистить».
    fn clear(&mut self) {
        self.items
            .retain(|item| item.status == QueueStatus::Running);
        self.rebuild_summary();
    }

    fn rebuild_summary(&mut self) {
        use std::fmt::Write as _;

        let (mut running, mut waiting, mut done, mut failed, mut cancelled) = (0, 0, 0, 0, 0);
        // Помеченные крестиком не считаем: строка ещё складывается, но
        // очередью она уже не является, и сводка обязана сказать это сразу —
        // иначе «В очереди: 3» держится лишнюю четверть секунды после того,
        // как убрали третью.
        for item in self.items.iter().filter(|item| item.removing_since.is_none()) {
            // Разбор по вариантам, а не `_`: появится состояние — компилятор
            // потребует решить, куда его считать.
            match &item.status {
                QueueStatus::Running => running += 1,
                QueueStatus::Waiting => waiting += 1,
                QueueStatus::Done => done += 1,
                QueueStatus::Failed(_) => failed += 1,
                QueueStatus::Cancelled => cancelled += 1,
            }
        }

        // Полна очередь ровно тогда, когда мест нет и освободить нечем:
        // отработавшую строку `make_room` выбросит сам.
        self.full = self.items.len() >= QUEUE_LIMIT && done + failed + cancelled == 0;

        // Пары «слово: число», а не «3 ждут»: у русских числительных
        // окончание зависит от последней цифры, и «1 ждут» с «2 готово»
        // бросались бы в глаза. Двоеточие снимает вопрос вовсе.
        self.summary.clear();
        for (key, count) in [
            (Key::SummaryRunning, running),
            (Key::SummaryWaiting, waiting),
            (Key::SummaryDone, done),
            (Key::SummaryFailed, failed),
            (Key::SummaryCancelled, cancelled),
        ] {
            if count == 0 {
                continue;
            }
            if !self.summary.is_empty() {
                self.summary.push_str(" · ");
            }
            let _ = write!(
                self.summary,
                "{}",
                i18n::fill(
                    i18n::t(self.lang, Key::SummaryPair),
                    &[i18n::t(self.lang, key), &count.to_string()],
                )
            );
        }
    }
}

/// Каким по смыслу читается короткое сообщение панели.
///
/// Роль, а не готовый `Color32`, и это не педантизм. Такие сообщения кладутся
/// в поле панели, когда приходит событие движка, и живут там до следующего;
/// положи туда цвет — он пережил бы смену темы и остался бы от прежней
/// палитры. Это ровно та беда, что у строки, собранной заранее и не
/// пересобранной в `set_lang`, только тише: текст хотя бы читается, а вот
/// песочная подпись на белой карточке пропадёт. Роль же разрешается в цвет
/// в кадре отрисовки, то есть всегда по текущей теме.
///
/// Заодно это и про слои: `drain` панели разбирает события движка, и знать
/// ему про палитру незачем.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum Tone {
    /// Обычное сообщение: «удалять было нечего».
    Plain,
    /// Тише обычного: подсказки поиска, «ничего не нашлось».
    Quiet,
    /// Получилось.
    Good,
    /// Получилось не так, как ждали, но это не отказ.
    Warn,
    /// Не получилось.
    Bad,
}

impl Tone {
    fn color(self, pal: theme::Palette) -> egui::Color32 {
        match self {
            Tone::Plain => pal.text_secondary,
            Tone::Quiet => pal.text_muted,
            Tone::Good => pal.state_success,
            Tone::Warn => pal.state_warning,
            Tone::Bad => pal.state_error,
        }
    }
}

/// Состояние вкладки «Метаданные».
///
/// Со своим приёмником событий: чистить метаданные во время скачивания —
/// законный сценарий, и события двух задач не должны попадать в один канал.
/// Движка это не касается, он по-прежнему знает только `Sender<Event>`.
///
/// Файл читается сам — как только выбран и сразу после очистки. Кнопка
/// поэтому называется «Прочитать снова»: первым шагом чтение больше не
/// бывает, а таблица после «Стереть всё» показывает, что осталось, — то есть
/// сама доказывает, что очистка сработала.
struct MetaPanel {
    path: Option<PathBuf>,
    /// Полный путь строкой — подсказка по наведению на имя файла и строка
    /// в вопросе «точно перезаписать?». Собирается при выборе файла, а не
    /// в кадре отрисовки.
    path_display: String,
    /// Имя файла без папок: то, что стоит в таблетке первого шага.
    file_name: String,
    /// Хвост таблетки: «· 4.2 МБ · 3:25». Пусто, пока файл не прочитан.
    /// Собирается, когда пришёл отчёт, — не в кадре.
    file_facts: String,
    /// Почему с этим файлом работать нельзя. `None` — можно.
    blocked: Option<String>,
    readable: bool,
    cleanable: bool,
    /// Файл — звук. Под его таблицей своя строка: про место и время съёмки
    /// у песни говорить нечего.
    audio: bool,
    /// Что сейчас идёт в потоке. `None` — ничего.
    ///
    /// Задача, а не флаг «занято», потому что `Event::Failed` не говорит, чья
    /// это неудача, а показывать её надо в разных местах: несостоявшееся
    /// чтение — вместо таблицы, несостоявшуюся очистку — под кнопками, рядом
    /// с таблицей, которая после неё по-прежнему верна: файл не тронут.
    running: Option<MetaTask>,
    stage: String,
    /// Прочитанное, сложенное для экрана. `None` — ещё не читали, читаем
    /// впервые или только что стёрли. Пустая сводка — законный исход.
    summary: Option<MetaSummary>,
    /// Почему прочитать не вышло.
    read_error: Option<String>,
    /// Итог последней очистки: текст и цвет плашки.
    outcome: Option<(String, Tone)>,
    /// Сколько освободила последняя очистка. Число, а не только готовая
    /// строка, чтобы итог можно было пересобрать на новом языке.
    freed: Option<u64>,
    /// Раскрыт ли хвост служебных записей.
    service_open: bool,
    /// Номер выбранного файла: растёт с каждым выбором.
    ///
    /// Из него строятся идентификаторы анимаций хвоста. Состояние анимации
    /// egui держит по идентификатору, а не по файлу, и без номера хвост
    /// нового снимка с той же камеры — с тем же числом служебных записей —
    /// появлялся раскрытым и сворачивался у всех на глазах, доезжая
    /// анимацию прошлого файла (найдено ревью задачи 65).
    generation: u64,
    /// Показан вопрос «точно перезаписать?».
    confirming: bool,
    rx: Option<Receiver<Event>>,
}

impl MetaPanel {
    fn new() -> Self {
        Self {
            path: None,
            path_display: String::new(),
            file_name: String::new(),
            file_facts: String::new(),
            blocked: None,
            readable: false,
            cleanable: false,
            audio: false,
            running: None,
            stage: String::new(),
            summary: None,
            read_error: None,
            outcome: None,
            freed: None,
            service_open: false,
            generation: 0,
            confirming: false,
            rx: None,
        }
    }

    fn busy(&self) -> bool {
        self.running.is_some()
    }

    /// Пересобирает то, что собрано заранее, на новом языке.
    ///
    /// Объяснение «с этим форматом работать нельзя» и итог очистки — готовые
    /// строки, и сами они не обновятся. А таблицу пересобрать не из чего:
    /// имена и значения записей переводит движок в момент чтения. Поэтому
    /// показанный файл читается заново — это доли секунды, и идёт оно
    /// в потоке. Пока идёт очистка, заново не читаем: сразу после неё файл
    /// перечитается и так, уже на новом языке, а второе чтение рядом с
    /// перезаписью файла только спорило бы с ней за диск.
    fn relabel(&mut self, lang: Lang, ctx: &egui::Context) {
        if let Some(path) = &self.path {
            let kind = meta_kind(path);
            self.blocked = (!kind.readable() || !kind.cleanable())
                .then(|| metadata::unsupported_message(kind, lang));
        }
        if let Some(freed) = self.freed {
            self.outcome = Some(wipe_outcome(freed, lang));
        }

        let shown = self.summary.is_some()
            || self.read_error.is_some()
            || self.running == Some(MetaTask::Read);
        if self.readable && shown && self.running != Some(MetaTask::Clean) {
            self.start(MetaTask::Read, lang, ctx);
        }
    }

    /// Запоминает выбранный файл, решает, что с ним можно делать, и сразу
    /// его читает.
    ///
    /// Решение принимается один раз здесь, а не в кадре отрисовки: иначе
    /// расширение разбиралось бы 60 раз в секунду ради двух флагов.
    fn select(&mut self, path: PathBuf, lang: Lang, ctx: &egui::Context) {
        let kind = meta_kind(&path);
        self.readable = kind.readable();
        self.cleanable = kind.cleanable();
        self.audio = kind == MetaKind::Mp3;
        self.blocked = (!kind.readable() || !kind.cleanable())
            .then(|| metadata::unsupported_message(kind, lang));
        self.path_display = path.display().to_string();
        self.file_name = path
            .file_name()
            .map_or_else(|| self.path_display.clone(), |name| name.to_string_lossy().into_owned());
        self.path = Some(path);
        // Результаты относились к прошлому файлу — показывать их рядом
        // с новым нельзя, это прямой повод перепутать.
        self.summary = None;
        self.file_facts.clear();
        self.read_error = None;
        self.outcome = None;
        self.freed = None;
        self.service_open = false;
        self.generation = self.generation.wrapping_add(1);
        self.stage.clear();
        // Приёмник прошлого файла бросаем, даже если новый прочитать нельзя:
        // иначе запоздалый ответ про прежний файл лёг бы под именем нового.
        self.rx = None;
        self.running = None;

        if self.readable {
            self.start(MetaTask::Read, lang, ctx);
        }
    }

    fn start(&mut self, task: MetaTask, lang: Lang, ctx: &egui::Context) {
        let Some(path) = self.path.clone() else {
            return;
        };

        let (tx, rx) = channel();
        let notify_ctx = ctx.clone();
        engine::start_metadata(path, task, lang, tx, move || notify_ctx.request_repaint());

        // Прежний приёмник уходит вместе с заменой, а с ним — и запоздалые
        // события прежнего запуска: перечитывание на смене языка не должно
        // получить ответ старого чтения на старом языке.
        self.rx = Some(rx);
        self.running = Some(task);
        self.stage = i18n::t(lang, Key::StageStarting).to_owned();
        match task {
            // Прочитанное остаётся на экране до нового ответа: при смене
            // языка оно верно, только названо по-старому, и мигать пустым
            // местом таблице незачем.
            MetaTask::Read => self.read_error = None,
            MetaTask::Clean => {
                self.outcome = None;
                self.freed = None;
            }
        }
    }

    fn drain(&mut self, lang: Lang, ctx: &egui::Context) {
        let mut events = Vec::new();
        let mut disconnected = false;

        if let Some(rx) = &self.rx {
            loop {
                match rx.try_recv() {
                    Ok(event) => events.push(event),
                    Err(TryRecvError::Empty) => break,
                    Err(TryRecvError::Disconnected) => {
                        disconnected = true;
                        break;
                    }
                }
            }
        }

        let mut reread = false;
        for event in events {
            match event {
                Event::Stage(stage) => self.stage = stage,
                Event::Tags(report) => {
                    let summary = MetaSummary::new(&report, lang);
                    self.file_facts = if summary.facts.is_empty() {
                        String::new()
                    } else {
                        format!("· {}", summary.facts)
                    };
                    self.summary = Some(summary);
                    self.running = None;
                }
                Event::Cleaned(freed) => {
                    self.outcome = Some(wipe_outcome(freed, lang));
                    self.freed = Some(freed);
                    self.running = None;
                    // Таблица описывала файл до очистки — стёртое на экране
                    // осталось бы висеть как найденное, а размер был бы
                    // прежним. Файл перечитывается, и таблица показывает то,
                    // что в нём теперь.
                    self.summary = None;
                    self.file_facts.clear();
                    reread = true;
                }
                // Номер загрузки здесь всегда `NO_DOWNLOAD` и никого
                // не интересует: канал у метаданных свой, разводить нечего.
                Event::Failed { message, .. } => {
                    if self.running == Some(MetaTask::Read) {
                        self.summary = None;
                        self.file_facts.clear();
                        self.read_error = Some(message);
                    } else {
                        self.outcome = Some((message, Tone::Bad));
                    }
                    self.running = None;
                }
                // Остальные варианты рождаются только загрузкой и установкой,
                // а у них свой приёмник. Пустая ветка вместо `_` — чтобы
                // компилятор и дальше ловил здесь новые варианты `Event`.
                Event::Info(_)
                | Event::Thumbnail(_)
                | Event::Progress(_)
                | Event::Log(_)
                | Event::Done { .. }
                | Event::Ready
                | Event::Warning(_)
                | Event::Notice(_)
                | Event::Versions(_)
                | Event::SystemReport(_)
                | Event::Power(_)
                | Event::Perf(_)
                | Event::WeatherPlace(_)
                | Event::WeatherPlaces(_)
                | Event::Weather(_)
                | Event::Share(_) => {}
            }
        }

        // Поток кончился — ждать больше нечего. Проверяется до перечитывания:
        // иначе закрытие старого канала сбросило бы новый. Если задача всё
        // ещё числится идущей, поток умер, не прислав ни ответа, ни отказа
        // (паника разбора на битом файле), и это надо сказать словами: без
        // этого на месте таблицы навсегда остался бы индикатор «читаю».
        if disconnected {
            self.rx = None;
            match self.running.take() {
                Some(MetaTask::Read) => {
                    self.summary = None;
                    self.file_facts.clear();
                    self.read_error = Some(i18n::t(lang, Key::UiMetaNoAnswer).to_owned());
                }
                Some(MetaTask::Clean) => {
                    self.outcome = Some((i18n::t(lang, Key::UiMetaNoAnswer).to_owned(), Tone::Bad));
                }
                None => {}
            }
        }
        if reread {
            self.start(MetaTask::Read, lang, ctx);
        }
    }
}

/// Итог очистки словами.
///
/// Ноль освобождённых байт — это не неудача, а чистый файл. Сказать об этом
/// надо иначе: «освобождено 0 Б» выглядит как сломавшаяся операция.
fn wipe_outcome(freed: u64, lang: Lang) -> (String, Tone) {
    if freed == 0 {
        (
            i18n::t(lang, Key::UiMetaNothingToWipe).to_owned(),
            Tone::Plain,
        )
    } else {
        (
            i18n::fill(i18n::t(lang, Key::UiMetaWiped), &[&human_bytes(freed, lang)]),
            Tone::Good,
        )
    }
}

/// Состояние вкладки «Система».
///
/// Устроена как `MetaPanel`: свой приёмник на каждый запуск, работа в потоке,
/// готовый результат приезжает событием. Общего канала с загрузкой здесь быть
/// не может — опрашивать железо можно и посреди скачивания.
struct SystemPanel {
    /// Готовый снимок. `None` — ещё не спрашивали или спрашиваем прямо сейчас.
    report: Option<SystemReport>,
    busy: bool,
    /// Чем занят движок прямо сейчас.
    stage: String,
    /// Спрашивали ли хоть раз. Нужно, чтобы опрос пошёл сам при первом
    /// открытии вкладки: пустой экран с одной кнопкой «Проверить» — лишний
    /// шаг там, где ответ всё равно нужен всегда.
    asked: bool,
    /// Итог последнего сохранения отчёта в файл.
    saved: Option<(String, Tone)>,
    rx: Option<Receiver<Event>>,
}

impl SystemPanel {
    fn new() -> Self {
        Self {
            report: None,
            busy: false,
            stage: String::new(),
            asked: false,
            saved: None,
            rx: None,
        }
    }

    fn start(&mut self, gpu: Option<GpuInfo>, lang: Lang, ctx: &egui::Context) {
        let (tx, rx) = channel();
        let notify_ctx = ctx.clone();
        engine::hardware::start(gpu, lang, tx, move || notify_ctx.request_repaint());

        self.rx = Some(rx);
        self.busy = true;
        self.asked = true;
        self.stage = i18n::t(lang, Key::StageStarting).to_owned();
        // Прошлый снимок убираем сразу: показывать вчерашние числа рядом
        // с надписью «опрашиваю» — прямой повод их перепутать.
        self.report = None;
        self.saved = None;
    }

    fn drain(&mut self) {
        let mut events = Vec::new();
        let mut disconnected = false;

        if let Some(rx) = &self.rx {
            loop {
                match rx.try_recv() {
                    Ok(event) => events.push(event),
                    Err(TryRecvError::Empty) => break,
                    Err(TryRecvError::Disconnected) => {
                        disconnected = true;
                        break;
                    }
                }
            }
        }

        for event in events {
            match event {
                Event::Stage(stage) => self.stage = stage,
                Event::SystemReport(report) => {
                    self.report = Some(report);
                    self.busy = false;
                }
                // Опрос железа отказать целиком не умеет: не ответивший
                // источник приезжает пунктом со статусом «нет данных», а не
                // ошибкой на весь отчёт. Ветка всё равно выписана — на случай,
                // если это когда-нибудь изменится.
                Event::Failed { .. } => self.busy = false,
                // Остальное ходит по чужим каналам. Перечислено явно, а не
                // через `_`, чтобы компилятор и дальше требовал разбирать
                // новые варианты `Event` во всех приёмниках.
                Event::Info(_)
                | Event::Thumbnail(_)
                | Event::Progress(_)
                | Event::Log(_)
                | Event::Done { .. }
                | Event::Ready
                | Event::Warning(_)
                | Event::Notice(_)
                | Event::Tags(_)
                | Event::Cleaned(_)
                | Event::Versions(_)
                | Event::Power(_)
                | Event::Perf(_)
                | Event::WeatherPlace(_)
                | Event::WeatherPlaces(_)
                | Event::Weather(_)
                | Event::Share(_) => {}
            }
        }

        if disconnected {
            self.rx = None;
            self.busy = false;
        }
    }
}

// ---------------------------------------------------------------------------
// Питание
// ---------------------------------------------------------------------------

/// Состояние карточки «Питание».
///
/// Устроена как `SystemPanel`: свой приёмник на каждый запуск, работа в
/// потоке, готовый ответ приезжает событием. Отличие в том, когда спрашивают.
/// Снимок железа берут по кнопке, а питание перечитывается само — при каждом
/// открытии половины «Сейчас» и после каждого переключения. Иначе кнопки
/// показывали бы вчерашнее положение: схему и режим меняют и мимо Savio,
/// из параметров Windows.
struct PowerPanel {
    state: PowerState,
    /// Спрашивали ли хоть раз. До первого ответа кнопок нет вовсе — рисовать
    /// переключатель, не зная его положения, значит выдумать положение.
    asked: bool,
    /// Идёт чтение или переключение: кнопки на это время выключены.
    busy: bool,
    /// Открыта ли половина «Сейчас». По изменению этого флага и идёт
    /// перечитывание.
    open: bool,
    /// Итог последнего переключения: текст и цвет.
    outcome: Option<(String, Tone)>,
    /// Оговорка под рядом режимов. Собирается на приёме события, а не в кадре
    /// отрисовки: `format!` в `ui()` — это аллокация шестьдесят раз в секунду
    /// ради строки, которая меняется раз в минуту (Правило 1).
    hint: String,
    rx: Option<Receiver<Event>>,
}

impl PowerPanel {
    fn new() -> Self {
        Self {
            state: PowerState::default(),
            asked: false,
            busy: false,
            open: false,
            outcome: None,
            hint: String::new(),
            rx: None,
        }
    }

    /// Перечитывает состояние, когда половину «Сейчас» открыли.
    ///
    /// Именно по открытию, а не каждую секунду вместе с замерами монитора:
    /// чтение стоит запуска потока, а меняется питание раз в день. И не
    /// однажды за весь запуск: половину открывают ровно тогда, когда хотят
    /// увидеть, что с машиной сейчас.
    fn watch(&mut self, open: bool, lang: Lang, ctx: &egui::Context) {
        if open && !self.open {
            self.start(lang, ctx);
        }
        self.open = open;
    }

    fn start(&mut self, lang: Lang, ctx: &egui::Context) {
        let (tx, rx) = channel();
        let notify_ctx = ctx.clone();
        engine::power::start(lang, tx, move || notify_ctx.request_repaint());

        self.rx = Some(rx);
        self.busy = true;
        self.asked = true;
    }

    /// Просит систему переключиться и перечитать состояние.
    fn change(&mut self, change: power::Change, lang: Lang, ctx: &egui::Context) {
        let (tx, rx) = channel();
        let notify_ctx = ctx.clone();
        engine::power::start_change(change, lang, tx, move || notify_ctx.request_repaint());

        self.rx = Some(rx);
        self.busy = true;
        self.asked = true;
        // Прошлый итог относился к прошлому нажатию: оставить его рядом
        // с новым — прямой повод их перепутать.
        self.outcome = None;
    }

    /// Принимает свежее состояние и пересобирает оговорку под ним.
    fn accept(&mut self, state: PowerState, lang: Lang) {
        self.hint = power_hint(&state, lang);
        self.state = state;
    }

    /// Пересобирает оговорку на новом языке. Исход прошлого переключения
    /// не трогаем: он пришёл от движка и относится к тому нажатию.
    fn relabel(&mut self, lang: Lang) {
        self.hint = power_hint(&self.state, lang);
    }

    fn drain(&mut self, lang: Lang) {
        let mut events = Vec::new();
        let mut disconnected = false;

        if let Some(rx) = &self.rx {
            loop {
                match rx.try_recv() {
                    Ok(event) => events.push(event),
                    Err(TryRecvError::Empty) => break,
                    Err(TryRecvError::Disconnected) => {
                        disconnected = true;
                        break;
                    }
                }
            }
        }

        for event in events {
            match event {
                Event::Power(state) => {
                    self.accept(state, lang);
                    self.busy = false;
                }
                // Переключилось и проверено перечитыванием.
                Event::Notice(text) => self.outcome = Some((text, Tone::Good)),
                // Система приняла просьбу, но работает по-прежнему. Не ошибка
                // и не успех — свой цвет (Правило 6).
                Event::Warning(text) => self.outcome = Some((text, Tone::Warn)),
                Event::Failed { message, .. } => {
                    self.outcome = Some((message, Tone::Bad));
                    self.busy = false;
                }
                // Остальное ходит по чужим каналам. Перечислено явно, а не
                // через `_`, чтобы компилятор и дальше требовал разбирать
                // новые варианты `Event` во всех приёмниках.
                Event::Info(_)
                | Event::Thumbnail(_)
                | Event::Stage(_)
                | Event::Progress(_)
                | Event::Log(_)
                | Event::Done { .. }
                | Event::Ready
                | Event::Tags(_)
                | Event::Cleaned(_)
                | Event::Versions(_)
                | Event::SystemReport(_)
                | Event::Perf(_)
                | Event::WeatherPlace(_)
                | Event::WeatherPlaces(_)
                | Event::Weather(_)
                | Event::Share(_) => {}
            }
        }

        if disconnected {
            self.rx = None;
            self.busy = false;
        }
    }
}

/// Оговорка под рядом режимов питания: чего ждать от нажатия.
///
/// Свободная функция, а не метод панели, потому что она чистая: из состояния
/// делается строка, и ничего больше. Так её и проверяют тесты — а проверять
/// её надо, потому что это единственное место, где Savio предупреждает
/// о молчаливом отказе Windows **до** нажатия, а не после.
fn power_hint(state: &PowerState, lang: Lang) -> String {
    let PowerModes::Known { effective, ignored } = state.modes else {
        return String::new();
    };

    // Название сбалансированной схемы берём из списка, а не пишем своё: на
    // английской Windows она называется «Balanced», и подменять её название
    // значило бы отправить человека искать в системе то, чего там нет.
    // Своё название — только когда система вовсе не назвала ни одной схемы.
    let balanced = state
        .plan_name(BALANCED_PLAN)
        .unwrap_or_else(|| i18n::t(lang, Key::UiPowerBalancedFallback));
    // Как назвать активную схему: по имени, если система его дала, и
    // обезличенно, если нет. Пустое место вместо названия читалось бы как
    // недорисованная строка, а выдуманное имя — как чужая схема.
    // Кавычки — из таблицы строк, а не зашитые в код: `«»` в английском
    // тексте выглядят опечаткой, а проверка кавычек смотрит только таблицу
    // и зашитые в код не видит. Ровно так «ёлочки» и прожили в английской
    // подсказке с 0.28.0 до переноса дизайна — нашлось глазами.
    let active = match state.active_name() {
        Some(name) => i18n::fill(i18n::t(lang, Key::QuotedName), &[name]),
        None => i18n::t(lang, Key::UiPowerOtherPlan).to_owned(),
    };

    if let Some(stored) = ignored {
        return i18n::fill(
            i18n::t(lang, Key::UiPowerModeIgnoredHint),
            &[
                stored.label(lang),
                effective.map_or(i18n::t(lang, Key::UiPowerModeUnnamed), |mode| {
                    mode.label(lang)
                }),
                balanced,
                &active,
            ],
        );
    }

    if state.active.is_some_and(|id| id != BALANCED_PLAN) {
        return i18n::fill(
            i18n::t(lang, Key::UiPowerWrongPlanHint),
            &[&active, balanced],
        );
    }

    String::new()
}

// ---------------------------------------------------------------------------
// Погода
// ---------------------------------------------------------------------------

/// Состояние вкладки «Погода».
///
/// Устроена как `SystemPanel`: свой приёмник на каждый запуск, работа в
/// потоке, готовый отчёт приезжает событием. Приёмников два — у прогноза и
/// у поиска: искать другой город, пока грузится прогноз этого, законно.
///
/// **Опроса в фоне у вкладки нет вовсе.** Автообновление — не поток, а срок:
/// пока вкладка открыта, кадр просится ровно к нему (`request_repaint_after`),
/// а закрытая вкладка не просит ничего, и Savio в покое по-прежнему не тратит
/// ни кадра. Просить кадр на каждом проходе было бы обратной бедой — 60 к/с
/// ради часов, которые меняются раз в пятнадцать минут.
struct WeatherPanel {
    /// Выбранное место. `None` — ещё не выбирали и не определяли.
    place: Option<Place>,
    units: WeatherUnits,
    favorites: Vec<Place>,
    report: Option<WeatherReport>,
    /// Прогноз строками. Пересобирается на приёме отчёта и при смене единиц,
    /// а не в кадре (Правило 1).
    view: Option<WeatherView>,
    /// Название выбранного места — для шапки, пока отчёта ещё нет.
    place_title: String,
    /// Место определено по IP-адресу в этом запуске. Ради оговорки: через VPN
    /// это чужая страна, и человек должен видеть, откуда город взялся.
    located: bool,
    busy: bool,
    stage: String,
    /// Почему не вышло. Живёт до следующей попытки.
    error: Option<String>,
    /// Открывали ли вкладку в этом запуске.
    asked: bool,
    /// Когда в последний раз ходили за прогнозом, по часам egui.
    ///
    /// От этого мгновения, а не от прихода отчёта, считается автообновление —
    /// и после неудачи тоже: иначе без сети вкладка стучалась бы в сервер
    /// на каждом кадре.
    last_attempt: Option<f64>,
    rx: Option<Receiver<Event>>,

    /// Текст в поле поиска.
    query: String,
    /// Что искали — для «по запросу «…» ничего не нашлось». Своей строкой:
    /// поле к приходу ответа могли уже поправить.
    searched_for: String,
    searching: bool,
    /// Найденное. `None` — не искали, не нашли или уже выбрали.
    results: Option<Vec<Place>>,
    /// Вторые строки найденного («область, страна»), готовые к показу.
    result_details: Vec<String>,
    /// Что сказать под полем поиска: текст и цвет.
    search_note: Option<(String, Tone)>,
    search_rx: Option<Receiver<Event>>,
}

impl WeatherPanel {
    fn new(place: Option<Place>, units: WeatherUnits, favorites: Vec<Place>) -> Self {
        Self {
            place_title: place.as_ref().map(Place::title).unwrap_or_default(),
            place,
            units,
            favorites,
            report: None,
            view: None,
            located: false,
            busy: false,
            stage: String::new(),
            error: None,
            asked: false,
            last_attempt: None,
            rx: None,
            query: String::new(),
            searched_for: String::new(),
            searching: false,
            results: None,
            result_details: Vec::new(),
            search_note: None,
            search_rx: None,
        }
    }

    /// Ведёт вкладку: первый запрос при первом открытии и обновление по сроку,
    /// пока открыта.
    ///
    /// Зовётся на каждом кадре из `ui`, а не из самой вкладки — по той же
    /// причине, что и останов опроса монитора: закрытая вкладка не рисуется,
    /// и сверить срок из неё было бы некому. Работы в обычном кадре здесь нет:
    /// пара сравнений.
    /// Пересобирает прогноз на новом языке.
    ///
    /// Название места при этом остаётся прежним: оно пришло от сервера и
    /// переводу не подлежит — придуманное имя города хуже неперевёденного.
    /// Свежее название приедет со следующим поиском или определением по IP.
    fn relabel(&mut self, lang: Lang) {
        self.rebuild_view(lang);
    }

    fn watch(&mut self, open: bool, lang: Lang, ctx: &egui::Context) {
        if !open {
            return;
        }

        if !self.asked {
            // Первое открытие. Место по IP определяется здесь, а не при запуске
            // Savio: запрос отдаёт чужому серверу IP-адрес человека, а
            // запускал он загрузчик роликов, а не прогноз погоды.
            self.asked = true;
            let place = self.place.clone();
            self.start(place, true, lang, ctx);
            return;
        }

        if self.busy {
            return;
        }
        // Без места обновлять нечего: определение по IP после неудачи
        // повторяется по кнопке, а не само раз в пятнадцать минут.
        let (Some(place), Some(at)) = (&self.place, self.last_attempt) else {
            return;
        };
        let left = weather::REFRESH_SECS - (ctx.input(|i| i.time) - at);
        if left > 0.0 {
            // Кадр к сроку приходится просить: egui рисует по вводу, и
            // вкладка, оставленная открытой, обновилась бы при первом
            // движении мыши, а не через пятнадцать минут.
            ctx.request_repaint_after(std::time::Duration::from_secs_f64(left));
        } else {
            let place = place.clone();
            self.start(Some(place), false, lang, ctx);
        }
    }

    /// Идёт за прогнозом. `place` — `None`: сначала определить место по IP.
    fn start(&mut self, place: Option<Place>, saved: bool, lang: Lang, ctx: &egui::Context) {
        let (tx, rx) = channel();
        let notify_ctx = ctx.clone();
        weather::start(place, saved, lang, tx, move || notify_ctx.request_repaint());

        // Прежний приёмник бросается здесь, и в этом вся развязка: ответ про
        // прошлое место, пришедший позже нового, лечь в окно уже не сможет.
        self.rx = Some(rx);
        self.busy = true;
        self.error = None;
        self.stage = i18n::t(lang, Key::StageStarting).to_owned();
        self.last_attempt = Some(ctx.input(|i| i.time));
    }

    /// Выбирает место: из найденного, из избранного или заново по IP (`None`).
    fn pick(&mut self, place: Option<Place>, lang: Lang, ctx: &egui::Context) {
        self.results = None;
        self.result_details.clear();
        self.search_note = None;
        if let Some(place) = &place {
            self.set_place(place.clone(), false);
        }
        self.start(place, false, lang, ctx);
    }

    /// Запоминает место. Прежний прогноз убирается, если место другое:
    /// числа прошлого города под названием нового — прямой повод их перепутать.
    fn set_place(&mut self, place: Place, located: bool) {
        if !self.place.as_ref().is_some_and(|old| old.same_as(&place)) {
            self.report = None;
            self.view = None;
        }
        self.place_title = place.title();
        self.located = located;
        self.place = Some(place);
    }

    /// Ищет места по тексту из поля.
    fn search(&mut self, lang: Lang, ctx: &egui::Context) {
        let query = self.query.trim();
        // Однобуквенный запрос сервер оставляет без ответа (проверено вживую),
        // и тратить на него поход в сеть незачем.
        if query.chars().count() < 2 {
            self.results = None;
            self.search_note = Some((
                i18n::t(lang, Key::UiWeatherTwoLetters).to_owned(),
                Tone::Quiet,
            ));
            return;
        }

        let (tx, rx) = channel();
        let notify_ctx = ctx.clone();
        weather::start_search(query.to_owned(), lang, tx, move || notify_ctx.request_repaint());
        self.searched_for = query.to_owned();
        self.search_rx = Some(rx);
        self.searching = true;
        self.results = None;
        self.result_details.clear();
        self.search_note = None;
    }

    /// Стоит ли выбранное место в избранном.
    fn is_favorite(&self) -> bool {
        self.place
            .as_ref()
            .is_some_and(|place| self.favorites.iter().any(|fav| fav.same_as(place)))
    }

    /// Кладёт выбранное место в избранное или убирает оттуда. `true` — список
    /// изменился и его надо запомнить.
    fn toggle_favorite(&mut self) -> bool {
        let Some(place) = &self.place else {
            return false;
        };
        if let Some(index) = self.favorites.iter().position(|fav| fav.same_as(place)) {
            self.favorites.remove(index);
            return true;
        }
        if self.favorites.len() >= FAVORITES_LIMIT {
            return false;
        }
        self.favorites.push(place.clone());
        true
    }

    /// Меняет единицы и пересобирает строки. `true` — поменялось.
    fn set_units(&mut self, units: WeatherUnits, lang: Lang) -> bool {
        if units == self.units {
            return false;
        }
        self.units = units;
        self.rebuild_view(lang);
        true
    }

    /// Пересобирает строки прогноза.
    ///
    /// Час «сейчас» и сегодняшний день считаются от часов машины на момент
    /// сборки, поэтому звать надо и тогда, когда отчёт не менялся, а время
    /// ушло: после неудачной попытки обновления старые числа остаются на
    /// экране, но прошедший час с них уходит.
    fn rebuild_view(&mut self, lang: Lang) {
        self.view = self.report.as_ref().map(|report| {
            let now = weather::now_unix();
            weather_view(
                report,
                self.units,
                now,
                now.and_then(weather::local_offset),
                lang,
            )
        });
    }

    /// Забирает ответ о прогнозе. `true` — место сменилось, и его надо
    /// запомнить.
    fn drain(&mut self, lang: Lang) -> bool {
        let mut events = Vec::new();
        let mut disconnected = false;

        if let Some(rx) = &self.rx {
            loop {
                match rx.try_recv() {
                    Ok(event) => events.push(event),
                    Err(TryRecvError::Empty) => break,
                    Err(TryRecvError::Disconnected) => {
                        disconnected = true;
                        break;
                    }
                }
            }
        }

        let mut place_changed = false;
        let mut dirty = false;
        for event in events {
            match event {
                Event::Stage(stage) => self.stage = stage,
                Event::WeatherPlace(place) => {
                    self.set_place(place, true);
                    place_changed = true;
                }
                Event::Weather(report) => {
                    // Сохранённый отчёт — не конец работы: следом за ним идёт
                    // свежий, и надпись о запросе должна остаться.
                    if !report.saved {
                        self.busy = false;
                    }
                    self.report = Some(*report);
                    dirty = true;
                }
                Event::Failed { message, .. } => {
                    self.error = Some(message);
                    self.busy = false;
                    dirty = self.report.is_some();
                }
                // Остальное ходит по чужим каналам. Перечислено явно, а не
                // через `_`, чтобы компилятор и дальше требовал разбирать
                // новые варианты `Event` во всех приёмниках.
                Event::Info(_)
                | Event::Thumbnail(_)
                | Event::Progress(_)
                | Event::Log(_)
                | Event::Done { .. }
                | Event::Ready
                | Event::Warning(_)
                | Event::Notice(_)
                | Event::Tags(_)
                | Event::Cleaned(_)
                | Event::Versions(_)
                | Event::SystemReport(_)
                | Event::Power(_)
                | Event::Perf(_)
                | Event::WeatherPlaces(_)
                | Event::Share(_) => {}
            }
        }

        if dirty {
            self.rebuild_view(lang);
        }
        if disconnected {
            self.rx = None;
            self.busy = false;
        }
        place_changed
    }

    /// Забирает найденное.
    fn drain_search(&mut self, lang: Lang) {
        let mut events = Vec::new();
        let mut disconnected = false;

        if let Some(rx) = &self.search_rx {
            loop {
                match rx.try_recv() {
                    Ok(event) => events.push(event),
                    Err(TryRecvError::Empty) => break,
                    Err(TryRecvError::Disconnected) => {
                        disconnected = true;
                        break;
                    }
                }
            }
        }

        for event in events {
            match event {
                Event::WeatherPlaces(places) => {
                    self.searching = false;
                    if places.is_empty() {
                        // Пустой список без слов читался бы как «поиск не
                        // сработал» — а он сработал, просто не нашёл.
                        self.search_note = Some((
                            i18n::fill(
                                i18n::t(lang, Key::UiWeatherNothingFound),
                                &[&self.searched_for],
                            ),
                            Tone::Quiet,
                        ));
                        self.results = None;
                    } else {
                        self.result_details = places.iter().map(Place::detail).collect();
                        self.results = Some(places);
                    }
                }
                Event::Failed { message, .. } => {
                    self.searching = false;
                    self.search_note = Some((message, Tone::Bad));
                }
                // Остальное по этому каналу не ходит. Ветка выписана явно,
                // а не через `_`, по той же причине, что и выше.
                Event::Info(_)
                | Event::Thumbnail(_)
                | Event::Stage(_)
                | Event::Progress(_)
                | Event::Log(_)
                | Event::Done { .. }
                | Event::Ready
                | Event::Warning(_)
                | Event::Notice(_)
                | Event::Tags(_)
                | Event::Cleaned(_)
                | Event::Versions(_)
                | Event::SystemReport(_)
                | Event::Power(_)
                | Event::Perf(_)
                | Event::WeatherPlace(_)
                | Event::Weather(_)
                | Event::Share(_) => {}
            }
        }

        if disconnected {
            self.search_rx = None;
            self.searching = false;
        }
    }
}

// ---------------------------------------------------------------------------
// Раздача файлов на телефон
// ---------------------------------------------------------------------------

/// Сколько ждём первого подключения, прежде чем подсказка про брандмауэр
/// станет предупреждением.
///
/// Полминуты — столько уходит на то, чтобы достать телефон, навести камеру
/// и дождаться страницы. Раньше жёлтая плашка пугала бы того, кто ещё не
/// успел; позже человек уже решил бы, что Savio сломан.
const SHARE_QUIET_SECS: f64 = 30.0;

/// Сторона QR-кода на экране, точек. Камера телефона читает его с полуметра.
const QR_SIDE: f32 = 184.0;

/// Тихая зона вокруг кода, в модулях. Четыре — требование стандарта: без неё
/// край кода сливается с карточкой, и часть камер его не находит.
const QR_QUIET: usize = 4;

/// Что объяснить, если телефон так и не подключился.
///
/// Savio узнать это сам не может: подключение к своему же адресу идёт мимо
/// брандмауэра, и изнутри раздача видна всегда (см. `engine::share`). Отсюда
/// слова, а не проверка.
const SHARE_HELP: Key = Key::UiShareHelp;

#[derive(Clone, Copy, PartialEq, Eq)]
enum ShareState {
    Off,
    /// Поток запущен, адресов ещё нет.
    Starting,
    On,
}

/// Чем кончилась передача.
enum TransferOutcome {
    Going,
    Done,
    Failed(String),
}

/// Строка списка передач. Все строки готовые: прогресс приезжает несколько
/// раз в секунду, а кадров шестьдесят (Правило 1).
struct TransferRow {
    id: u64,
    direction: TransferDirection,
    name: String,
    total: Option<u64>,
    /// Сколько байт уже прошло.
    ///
    /// Полем, хотя рисуется из него только готовая строка: без него строку
    /// нечем пересобрать при смене языка, и половина списка передач осталась
    /// бы на прежнем.
    done: u64,
    /// Доля для полосы. `None` — неизвестна.
    fraction: Option<f32>,
    /// «На компьютер · 12.4 МБ из 1.2 ГБ».
    line: String,
    outcome: TransferOutcome,
}

impl TransferRow {
    fn rebuild(&mut self, done: u64, lang: Lang) {
        self.done = done;
        self.fraction = self
            .total
            .filter(|total| *total > 0)
            .map(|total| (done as f32 / total as f32).clamp(0.0, 1.0));
        self.line = format!(
            "{} · {}",
            self.direction.label(lang),
            transfer_line(done, self.total, lang)
        );
    }

    /// Помечает передачу дошедшей.
    ///
    /// Отдельно от `rebuild`, потому что строка у неё другая: у дошедшего
    /// файла «12.4 МБ из 12.4 МБ» читается как недосказанность.
    fn finish(&mut self, lang: Lang) {
        self.outcome = TransferOutcome::Done;
        self.fraction = Some(1.0);
        self.line = i18n::fill(
            i18n::t(lang, Key::UiShareTransferDone),
            &[
                self.direction.label(lang),
                &self
                    .total
                    .map(|total| human_bytes(total, lang))
                    .unwrap_or_default(),
            ],
        );
    }
}

/// Состояние экрана «Телефон».
///
/// Устроено как `MonitorPanel`: поток, свой приёмник и останов, когда на
/// экран не смотрят. Причина останова здесь серьёзнее, чем там: забытый
/// опрос греет ноутбук, а забытая раздача держит папку открытой всей сети.
struct SharePanel {
    state: ShareState,
    handle: Option<share::Handle>,
    rx: Option<Receiver<Event>>,
    /// Своя папка раздачи. `None` — папка сохранения загрузок.
    own_dir: Option<PathBuf>,
    own_dir_display: String,
    /// Какая папка раздаётся сейчас, для подписи. Своей строкой, потому что
    /// папку сохранения могут сменить на экране загрузки посреди раздачи,
    /// а сервер раздаёт ту, с которой запущен.
    serving_display: String,
    addresses: Vec<ShareAddress>,
    picked: usize,
    /// QR-код выбранного адреса. Текстура, а не тысяча прямоугольников
    /// в кадре: собирается один раз на адрес.
    qr: Option<egui::TextureHandle>,
    /// Когда раздача заработала, по часам egui.
    started_at: f64,
    visitors: Vec<String>,
    /// «Android · 192.168.1.50, iPhone · 192.168.1.51» — готовой строкой.
    visitors_line: String,
    /// Старые сверху, свежие снизу; рисуются в обратном порядке.
    transfers: Vec<TransferRow>,
    /// Что сказать о прошлой раздаче: почему остановилась.
    note: Option<(String, Tone)>,
    copied_at: Option<f64>,
}

impl SharePanel {
    fn new() -> Self {
        Self {
            state: ShareState::Off,
            handle: None,
            rx: None,
            own_dir: None,
            own_dir_display: String::new(),
            serving_display: String::new(),
            addresses: Vec::new(),
            picked: 0,
            qr: None,
            started_at: 0.0,
            visitors: Vec::new(),
            visitors_line: String::new(),
            transfers: Vec::new(),
            note: None,
            copied_at: None,
        }
    }

    fn running(&self) -> bool {
        self.state != ShareState::Off
    }

    fn start(&mut self, dir: PathBuf, lang: Lang, ctx: &egui::Context) {
        self.stop(None, lang);
        let (tx, rx) = channel();
        let notify_ctx = ctx.clone();
        self.serving_display = display_dir(Some(&dir), lang);
        self.handle = Some(share::start(dir, lang, tx, move || {
            notify_ctx.request_repaint()
        }));
        self.rx = Some(rx);
        self.state = ShareState::Starting;
        self.note = None;
        self.visitors.clear();
        self.visitors_line.clear();
        self.transfers.clear();
    }

    /// Останавливает раздачу. `why` — что сказать под кнопкой.
    fn stop(&mut self, why: Option<&str>, lang: Lang) {
        if let Some(handle) = self.handle.take() {
            handle.stop();
        }
        // Приёмник бросаем вместе с ручкой: исходы оборванных передач сюда
        // уже не дойдут, поэтому их и помечаем сами.
        self.rx = None;
        for row in &mut self.transfers {
            if matches!(row.outcome, TransferOutcome::Going) {
                row.outcome = TransferOutcome::Failed(
                    i18n::t(lang, Key::UiShareStoppedUnfinished).to_owned(),
                );
            }
        }
        if self.running() && let Some(why) = why {
            self.note = Some((why.to_owned(), Tone::Quiet));
        }
        self.state = ShareState::Off;
        self.addresses.clear();
        self.qr = None;
        self.copied_at = None;
    }

    /// Останавливает раздачу, когда экран закрыли, и просит кадр к сроку
    /// подсказки про брандмауэр.
    ///
    /// Зовётся на каждом кадре из `ui`, а не из экрана, — по той же причине,
    /// что у монитора: закрытый экран не рисуется, и заметить своё закрытие
    /// ему нечем.
    fn watch(&mut self, open: bool, lang: Lang, ctx: &egui::Context) {
        if !open {
            if self.running() {
                self.stop(Some(i18n::t(lang, Key::UiShareLeftScreen)), lang);
            }
            return;
        }
        // Подсказка сменится на предупреждение сама, но только если в этот
        // момент будет кадр: egui рисует по вводу, а человек в это время
        // смотрит в телефон, а не водит мышью.
        if self.state == ShareState::On && self.visitors.is_empty() {
            let left = SHARE_QUIET_SECS - (ctx.input(|i| i.time) - self.started_at);
            if left > 0.0 {
                ctx.request_repaint_after(std::time::Duration::from_secs_f64(left));
            }
        }
    }

    /// Выбирает адрес для показа.
    fn pick(&mut self, index: usize, ctx: &egui::Context) {
        if index < self.addresses.len() && index != self.picked {
            self.picked = index;
            self.copied_at = None;
            self.rebuild_qr(ctx);
        }
    }

    fn rebuild_qr(&mut self, ctx: &egui::Context) {
        self.qr = self.addresses.get(self.picked).and_then(|address| {
            let (width, dark) = qr_modules(&address.url)?;
            let side = width + QR_QUIET * 2;
            let mut pixels = vec![theme::QR_LIGHT; side * side];
            for (index, _) in dark.iter().enumerate().filter(|(_, dark)| **dark) {
                let x = index % width + QR_QUIET;
                let y = index / width + QR_QUIET;
                pixels[y * side + x] = theme::QR_DARK;
            }
            // Ближайший сосед, а не сглаживание: модуль в несколько точек,
            // размытый по краям, камера читает хуже.
            Some(ctx.load_texture(
                "savio-share-qr",
                egui::ColorImage::new([side, side], pixels),
                egui::TextureOptions::NEAREST,
            ))
        });
    }

    fn drain(&mut self, lang: Lang, ctx: &egui::Context) {
        let mut events = Vec::new();
        let mut disconnected = false;

        if let Some(rx) = &self.rx {
            loop {
                match rx.try_recv() {
                    Ok(event) => events.push(event),
                    Err(TryRecvError::Empty) => break,
                    Err(TryRecvError::Disconnected) => {
                        disconnected = true;
                        break;
                    }
                }
            }
        }

        for event in events {
            match event {
                Event::Share(event) => self.accept(event, lang, ctx),
                // Остальное ходит по чужим каналам. Перечислено явно, а не
                // через `_`, чтобы компилятор и дальше требовал разбирать
                // новые варианты `Event` во всех приёмниках.
                Event::Info(_)
                | Event::Thumbnail(_)
                | Event::Stage(_)
                | Event::Progress(_)
                | Event::Log(_)
                | Event::Done { .. }
                | Event::Failed { .. }
                | Event::Ready
                | Event::Warning(_)
                | Event::Notice(_)
                | Event::Tags(_)
                | Event::Cleaned(_)
                | Event::Versions(_)
                | Event::SystemReport(_)
                | Event::Perf(_)
                | Event::Power(_)
                | Event::WeatherPlace(_)
                | Event::WeatherPlaces(_)
                | Event::Weather(_) => {}
            }
        }

        if disconnected && self.running() {
            // Поток кончился сам, не сказав почему. Держать экран в состоянии
            // «раздача идёт» при мёртвом сервере — ровно то враньё, которого
            // здесь быть не должно.
            self.stop(None, lang);
            self.note = Some((
                i18n::t(lang, Key::UiShareDied).to_owned(),
                Tone::Warn,
            ));
        }
    }

    /// Пересобирает строки передач на новом языке.
    ///
    /// Исходы, пришедшие от движка (`TransferOutcome::Failed`), остаются как
    /// есть: они про то, что уже случилось, и пересказать их нечем.
    fn relabel(&mut self, lang: Lang) {
        for row in &mut self.transfers {
            let done = row.done;
            let finished = matches!(row.outcome, TransferOutcome::Done);
            row.rebuild(done, lang);
            if finished {
                row.finish(lang);
            }
        }
    }

    fn accept(&mut self, event: ShareEvent, lang: Lang, ctx: &egui::Context) {
        match event {
            ShareEvent::Ready(addresses) => {
                self.state = ShareState::On;
                self.addresses = addresses;
                self.picked = 0;
                self.started_at = ctx.input(|i| i.time);
                self.rebuild_qr(ctx);
            }
            ShareEvent::Visitor(who) => {
                if !self.visitors.contains(&who) {
                    if self.visitors.len() >= VISITOR_LIMIT {
                        self.visitors.remove(0);
                    }
                    self.visitors.push(who);
                    self.visitors_line = self.visitors.join(", ");
                }
            }
            ShareEvent::Started { id, direction, name, total } => {
                if self.transfers.len() >= TRANSFER_LIMIT {
                    // Уходит старейшая законченная; идущие не трогаем, пока
                    // есть что убрать кроме них.
                    let index = self
                        .transfers
                        .iter()
                        .position(|row| !matches!(row.outcome, TransferOutcome::Going))
                        .unwrap_or(0);
                    self.transfers.remove(index);
                }
                let mut row = TransferRow {
                    id,
                    direction,
                    name,
                    total,
                    done: 0,
                    fraction: None,
                    line: String::new(),
                    outcome: TransferOutcome::Going,
                };
                row.rebuild(0, lang);
                self.transfers.push(row);
            }
            ShareEvent::Progress { id, done } => {
                if let Some(row) = self.row(id) {
                    row.rebuild(done, lang);
                }
            }
            ShareEvent::Finished { id, name } => {
                if let Some(row) = self.row(id) {
                    row.name = name;
                    row.finish(lang);
                }
            }
            ShareEvent::Failed { id, message } => match self.row(id) {
                Some(row) => row.outcome = TransferOutcome::Failed(message),
                // Отказ до начала передачи (в папку нельзя писать): строки
                // ещё нет, а сказать надо.
                None => self.note = Some((message, Tone::Bad)),
            },
            ShareEvent::Stopped(message) => {
                self.stop(None, lang);
                self.note = Some((message, Tone::Bad));
            }
        }
    }

    fn row(&mut self, id: u64) -> Option<&mut TransferRow> {
        self.transfers.iter_mut().find(|row| row.id == id)
    }
}

// ---------------------------------------------------------------------------
// Монитор производительности
// ---------------------------------------------------------------------------

/// Размер окна оверлея.
///
/// Фиксированный, и окно неизменяемое: содержимое у него — четыре строки
/// известной длины, и растягивать его некуда. Заодно это снимает целый класс
/// бед из дефекта 13: у окна, которому нельзя менять размер, не бывает
/// клиентской части шире 8192 пикселей.
///
/// Ширина подобрана по самой длинной строке — «Приём 1.2 МБ/с · Отдача
/// 128.0 КБ/с». На 230 точках она обрезалась многоточием, то есть оверлей
/// показывал половину того, ради чего его открыли. Высота — под четыре
/// строки и заголовок ровно с теми отступами, что заданы в `overlay_ui`:
/// со штатными отступами темы (строка виджета 32 точки) четвёртая строка
/// не влезала и молча пропадала.
const OVERLAY_SIZE: [f32; 2] = [300.0, 122.0];

/// Состояние вкладки «Монитор».
///
/// Устроена как `SystemPanel`: свой приёмник, работа в потоке, готовый
/// результат приезжает событием. Отличие одно, и оно определяет всё
/// остальное: снимок системы спрашивают однажды, а монитор — каждую секунду,
/// пока на него смотрят. Отсюда и ручка опроса, и явный останов.
struct MonitorPanel {
    /// Последний замер. `None` — опрос только начался, первого замера ещё нет.
    sample: Option<PerfSample>,
    /// Когда он пришёл, по часам egui. От этого мгновения считается дробная
    /// фаза графика: ломаная едет влево ровно на один шаг за такт замера
    /// (приём 13). `None` — замеров ещё не было, ехать нечему.
    sampled_at: Option<f64>,
    /// История загрузки процессора и памяти — для графиков.
    cpu_trace: Trace,
    mem_trace: Trace,
    rx: Option<Receiver<Event>>,
    /// Чем остановить опрос. `Some` — поток работает.
    handle: Option<monitor::Handle>,

    /// Показывать ли окно поверх остальных.
    overlay: bool,
    /// Пропускать ли щелчки мыши сквозь оверлей.
    ///
    /// Отдельная галочка, а не всегда включённый режим: с пропуском оверлей
    /// нельзя ни передвинуть, ни закрыть его же кнопкой — щелчок уходит
    /// в окно под ним. Поэтому по умолчанию выключен, а сказано об этом
    /// рядом с галочкой.
    passthrough: bool,
    /// Оверлей попросили закрыть из него самого.
    ///
    /// Через общий флаг, а не напрямую: рисует оверлей замыкание, которому
    /// до полей панели не дотянуться (`show_viewport_deferred` требует
    /// `Send + Sync + 'static`).
    overlay_closing: Arc<AtomicBool>,
    /// То, что рисует оверлей. По той же причине — через общую ячейку.
    overlay_sample: Arc<Mutex<Option<PerfSample>>>,
    /// Кто такой оверлей для egui.
    ///
    /// Считается один раз и хранится полем, а не пересчитывается по имени
    /// в каждом обращении: `ViewportId::from_hash_of` — это хеш строки, а
    /// зовут его несколько раз за кадр. Константой его не сделать: функция
    /// не `const`, а `ViewportId(Id::NULL)`, которым это тянет записать, —
    /// это `ViewportId::ROOT`, то есть само главное окно.
    overlay_id: egui::ViewportId,
}

impl MonitorPanel {
    fn new() -> Self {
        Self {
            sample: None,
            sampled_at: None,
            cpu_trace: Trace::default(),
            mem_trace: Trace::default(),
            rx: None,
            handle: None,
            overlay: false,
            passthrough: false,
            overlay_closing: Arc::new(AtomicBool::new(false)),
            overlay_sample: Arc::new(Mutex::new(None)),
            overlay_id: egui::ViewportId::from_hash_of("savio-overlay"),
        }
    }

    /// Идёт ли опрос прямо сейчас.
    fn running(&self) -> bool {
        self.handle.is_some()
    }

    /// Включает и выключает опрос по тому, смотрят ли на него.
    ///
    /// Это и есть ответ на главный риск задачи: Savio в покое не тратит ни
    /// кадра, а секундный опрос будит окно раз в секунду до конца дня. Пока
    /// открыта вкладка или включён оверлей — есть кому смотреть; во всех
    /// прочих случаях поток обязан остановиться, иначе загрузчик греет
    /// ноутбук в фоне.
    fn set_running(&mut self, wanted: bool, lang: Lang, ctx: &egui::Context) {
        if wanted == self.running() {
            return;
        }
        if wanted {
            self.start(lang, ctx);
        } else {
            self.stop();
        }
    }

    fn start(&mut self, lang: Lang, ctx: &egui::Context) {
        let (tx, rx) = channel();
        let notify_ctx = ctx.clone();
        self.handle = Some(monitor::start(lang, tx, move || {
            notify_ctx.request_repaint()
        }));
        self.rx = Some(rx);

        // Прошлые числа и графики убираем: между двумя включениями монитора
        // проходит сколько угодно времени, и склеенный с сегодняшним вчерашний
        // график показал бы провал, которого не было.
        self.sample = None;
        self.cpu_trace.clear();
        self.mem_trace.clear();
    }

    fn stop(&mut self) {
        if let Some(handle) = self.handle.take() {
            handle.stop();
        }
        // Приёмник бросаем вместе с ручкой — как это делает `Preview::stop`.
        // Замер, снятый в последний миг перед остановкой, уже не про то,
        // что показано, и лечь в окно он не должен.
        self.rx = None;
    }

    /// Забирает замеры, приехавшие с прошлого кадра.
    fn drain(&mut self, ctx: &egui::Context) {
        let mut events = Vec::new();
        let mut disconnected = false;

        if let Some(rx) = &self.rx {
            loop {
                match rx.try_recv() {
                    Ok(event) => events.push(event),
                    Err(TryRecvError::Empty) => break,
                    Err(TryRecvError::Disconnected) => {
                        disconnected = true;
                        break;
                    }
                }
            }
        }

        for event in events {
            match event {
                Event::Perf(sample) => self.accept(sample, ctx),
                // Остальное ходит по чужим каналам. Перечислено явно, а не
                // через `_`, чтобы компилятор и дальше требовал разбирать
                // новые варианты `Event` во всех приёмниках.
                Event::Info(_)
                | Event::Thumbnail(_)
                | Event::Stage(_)
                | Event::Progress(_)
                | Event::Log(_)
                | Event::Done { .. }
                | Event::Failed { .. }
                | Event::Ready
                | Event::Warning(_)
                | Event::Notice(_)
                | Event::Tags(_)
                | Event::Cleaned(_)
                | Event::Versions(_)
                | Event::Power(_)
                | Event::SystemReport(_)
                | Event::WeatherPlace(_)
                | Event::WeatherPlaces(_)
                | Event::Weather(_)
                | Event::Share(_) => {}
            }
        }

        if disconnected {
            // Поток кончился сам — например, приёмник умер раньше ручки.
            // Держать мёртвый канал и мёртвую ручку незачем: следующий кадр
            // заведёт опрос заново, если на него всё ещё смотрят.
            self.rx = None;
            self.handle = None;
        }
    }

    /// Принимает свежий замер.
    fn accept(&mut self, sample: PerfSample, ctx: &egui::Context) {
        self.sampled_at = Some(ctx.input(|i| i.time));
        // В график кладём только то, что система вправду сказала: `None`
        // здесь означает «показания нет», и подставить на его месте ноль
        // значило бы нарисовать провал загрузки, которого не было.
        if let Some(cpu) = sample.cpu.percent {
            self.cpu_trace.push(cpu);
        }
        if let Some(mem) = sample.mem.percent {
            self.mem_trace.push(mem);
        }

        if let Ok(mut slot) = self.overlay_sample.lock() {
            *slot = Some(sample.clone());
        }
        if self.overlay {
            // Оверлею кадр надо просить отдельно: `request_repaint` из потока
            // опроса будит главное окно, а дочернее окно egui само по себе
            // за родителем не перерисовывается — числа в нём просто застыли
            // бы до первого движения мышью над ним.
            ctx.request_repaint_of(self.overlay_id);
        }

        self.sample = Some(sample);
    }

    /// Дробная фаза графика: сколько прошло от последнего замера, долей такта.
    ///
    /// Кадры отсюда **не** просятся: сколько их нужно, знает только сам
    /// график — там известна ширина шага сетки (см. `trace_plot`).
    ///
    /// С выключенными «Плавными переходами» отдаёт ноль: график стоит на
    /// месте и обновляется раз в секунду, как до всех приёмов.
    fn trace_phase(&self, ctx: &egui::Context, speed: f32) -> f32 {
        let Some(at) = self.sampled_at.filter(|_| speed > 0.0) else {
            return 0.0;
        };
        ((ctx.input(|i| i.time) - at) as f32 / motion::SAMPLE).clamp(0.0, 1.0)
    }

    /// Рисует оверлей, пока он включён.
    ///
    /// Зовётся каждый кадр: egui держит дочернее окно ровно до тех пор, пока
    /// его просят на каждом проходе. Замыкание при этом собирается заново —
    /// так требует API (`Fn + Send + Sync + 'static`), и дешевле этого здесь
    /// ничего нет: сами данные лежат в общей ячейке и не копируются.
    fn show_overlay(&mut self, pal: theme::Palette, lang: Lang, ctx: &egui::Context) {
        // Закрыли изнутри — гасим галочку и забываем просьбу: иначе окно,
        // открытое заново, тут же закрылось бы старым флагом.
        if self.overlay_closing.swap(false, Ordering::Relaxed) {
            self.overlay = false;
        }
        if !self.overlay {
            return;
        }

        let builder = egui::ViewportBuilder::default()
            .with_title(i18n::t(lang, Key::UiOverlayTitle))
            .with_inner_size(OVERLAY_SIZE)
            // Оба предела равны размеру: окно без рамки всё равно нечем
            // тянуть, а верхний предел заодно закрывает дорогу дефекту 13.
            .with_min_inner_size(OVERLAY_SIZE)
            .with_max_inner_size(OVERLAY_SIZE)
            .with_resizable(false)
            .with_decorations(false)
            .with_always_on_top()
            // В панели задач оверлею делать нечего: это не второе приложение,
            // а полоска поверх игры.
            .with_taskbar(false)
            // Забирать фокус нельзя ни в коем случае: в игре это потеря
            // управления, а в полноэкранной игре — ещё и сворачивание.
            .with_active(false)
            .with_mouse_passthrough(self.passthrough);

        let sample = Arc::clone(&self.overlay_sample);
        let closing = Arc::clone(&self.overlay_closing);
        ctx.show_viewport_deferred(self.overlay_id, builder, move |ui, class| {
            overlay_ui(ui, pal, class, lang, &sample, &closing);
        });
    }
}

/// Что показывать под полем ссылки.
#[derive(Clone, Copy, PartialEq, Eq, Debug, Default)]
enum PreviewState {
    /// Спрашивать не о чем: поле пустое или в нём не ссылка.
    #[default]
    Idle,
    /// Ждём — окна дебаунса или самого ответа.
    Asking,
    /// Ответ пришёл.
    Ready,
    /// Спросили, а ответа не будет.
    Failed,
}

/// Сведения о ссылке из поля, полученные до нажатия «Скачать».
///
/// Ради этого превью и задумывалось: убедиться, что в буфере оказалась та
/// самая ссылка, надо **до** загрузки, а не посреди неё. Заодно до неё же
/// становятся известны доступные высоты кадра и список языков субтитров —
/// то, из чего человек выбирает прямо здесь, в карточке управления.
///
/// Свой приёмник и своя ручка, отдельно от загрузки: спрашивать про новую
/// ссылку можно и во время скачивания (`MetaPanel` устроен так же), и события
/// двух задач не должны попадать в один сток.
#[derive(Default)]
struct Preview {
    /// Ссылка, о которой спрашиваем или уже спросили. Пусто — спрашивать
    /// нечего.
    url: String,
    /// Cookies, которыми спрашивали. Часть цели, а не мелочь: тот же адрес
    /// с cookies и без них отдаёт разные ответы (у YouTube — вплоть до
    /// пустого списка дорожек), и смена браузера в списке обязана запрос
    /// перезапустить.
    cookies: CookieSource,
    /// Каким файлом cookies спрашивали. Такая же часть цели, как и сам
    /// источник: два разных файла — это два разных входа в аккаунт, и ответы
    /// по ним отличаются ровно так же, как ответ Firefox от ответа без
    /// cookies. Без этого поля смена файла оставила бы на экране карточку,
    /// собранную по прежнему входу.
    cookie_file: Option<PathBuf>,
    /// Когда истекает окно дебаунса, по часам egui. `None` — ждать нечего:
    /// либо уже спросили, либо спрашивать не о чем.
    due: Option<f64>,
    /// Приёмник ответа. Свой на каждый запуск, и в этом вся развязка
    /// поколений: бросив его вместе со сменой цели, мы разом перестаём
    /// слышать устаревший запрос. Без этого ответ по прежней ссылке,
    /// вернувшийся позже нового, положил бы в окно чужое название — беда
    /// тихая, её не видят ни компилятор, ни сборка.
    rx: Option<Receiver<Event>>,
    /// Чем бросить сам процесс. Без него `-J` по забытой ссылке дочитывает
    /// медленный сайт до конца, и на десятке правок подряд таких процессов
    /// накапливается десяток.
    handle: Option<Handle>,
    /// Что ответили. Отдаётся загрузке (см. `Queue::push`), чтобы та
    /// не ходила на сайт за тем же самым второй раз.
    info: Option<MediaInfo>,
    /// Обложка ролика, уже залитая в текстуру egui.
    ///
    /// Именно текстура, а не байты: заводится она один раз, на приёме
    /// `Event::Thumbnail`, и в кадре отрисовки остаётся только нарисовать.
    /// Освобождает текстуру egui сам, когда ручку заменяют или бросают.
    thumbnail: Option<egui::TextureHandle>,
    state: PreviewState,
}

impl Preview {
    /// Нацеливает предпросмотр на ссылку из поля.
    ///
    /// Возвращает `true`, если цель сменилась: прежний ответ больше не про то,
    /// что в поле, и всё, что из него собрано (название, оговорка про высоту,
    /// список языков), показывать уже нельзя.
    fn retarget(
        &mut self,
        url: &str,
        cookies: CookieSource,
        cookie_file: Option<&Path>,
        now: f64,
    ) -> bool {
        if self.url == url && self.cookies == cookies && self.cookie_file.as_deref() == cookie_file
        {
            return false;
        }

        self.stop();
        self.cookies = cookies;
        self.cookie_file = cookie_file.map(Path::to_path_buf);
        // Мусор из буфера обмена в yt-dlp не отправляем. Список поддерживаемых
        // сайтов принадлежит ему, и кнопку «непохожая» ссылка не блокирует, —
        // но каждый такой запуск это процесс и поход в сеть, а обрывок текста
        // из буфера не стоит ни того ни другого.
        if looks_like_url(url) {
            self.url.push_str(url);
            self.due = Some(now + PREVIEW_DEBOUNCE);
            self.state = PreviewState::Asking;
        }
        true
    }

    /// Спрашивает заново про ту же ссылку — когда изменилось не то, что
    /// в поле, а то, чем спрашивают.
    fn retry(&mut self, now: f64) {
        if self.url.is_empty() {
            return;
        }
        self.due = Some(now + PREVIEW_DEBOUNCE);
        self.state = PreviewState::Asking;
    }

    /// Бросает начатое и забывает ответ.
    fn stop(&mut self) {
        if let Some(handle) = self.handle.take() {
            handle.cancel();
        }
        self.rx = None;
        self.url.clear();
        self.due = None;
        self.info = None;
        self.thumbnail = None;
        self.state = PreviewState::Idle;
    }

    /// Запоминает запущенный запрос.
    fn asked(&mut self, rx: Receiver<Event>, handle: Handle) {
        self.due = None;
        self.rx = Some(rx);
        self.handle = Some(handle);
    }

    /// Забирает то, что успел ответить движок.
    ///
    /// Сначала собираем, потом применяем — как в `drain_events`: заимствование
    /// приёмника иначе живёт во время правки остального состояния.
    fn take_events(&mut self) -> Vec<Event> {
        let mut events = Vec::new();
        let Some(rx) = &self.rx else {
            return events;
        };

        loop {
            match rx.try_recv() {
                Ok(event) => events.push(event),
                Err(TryRecvError::Empty) => return events,
                Err(TryRecvError::Disconnected) => break,
            }
        }

        // Поток кончился — слушать больше нечего. Ответа при этом могло и не
        // быть вовсе: про отсутствие yt-dlp, незнакомый сайт и молчащий сервер
        // предпросмотр не говорит ничего (см. `engine::start_probe`), так что
        // единственный признак неудачи — закрытый канал без `Info`.
        self.rx = None;
        self.handle = None;
        if self.state == PreviewState::Asking
            && self.info.is_none()
            && !events.iter().any(|event| matches!(event, Event::Info(_)))
        {
            self.state = PreviewState::Failed;
        }
        events
    }

    /// Заводит текстуру под приехавшую обложку.
    ///
    /// Единственная заливка текстуры за весь запрос — и она здесь, на приёме
    /// события, а не в кадре. Разбор картинки уже сделал движок: сюда
    /// приезжает готовый RGBA.
    ///
    /// Размеры проверяем, хотя движок это уже сделал: между ним и нами канал,
    /// а `ColorImage` на несовпадении не возвращает ошибку, а паникует.
    /// Уронить окно из-за украшения нельзя, поэтому проверка на обеих сторонах.
    fn set_cover(&mut self, cover: &Thumbnail, ctx: &egui::Context) {
        if !cover.is_valid() {
            return;
        }
        self.thumbnail = Some(ctx.load_texture(
            "savio-cover",
            egui::ColorImage::from_rgba_unmultiplied([cover.width, cover.height], &cover.rgba),
            egui::TextureOptions::LINEAR,
        ));
    }

    /// Про ту же ли ссылку этот запрос.
    ///
    /// Сверяем и адрес, и вход в аккаунт целиком — источник вместе с файлом:
    /// ответ на один и тот же адрес с чужим входом — это другой ответ.
    fn is_about(&self, request: Option<&Request>) -> bool {
        request.is_some_and(|request| {
            request.url == self.url
                && request.cookies == self.cookies
                && request.cookie_file == self.cookie_file
        })
    }

    /// Ответ, годный для этой загрузки, — чтобы та не спрашивала сайт второй
    /// раз о том же самом.
    ///
    /// Копия, а не перенос: ссылку из поля после «В очередь» обычно не стирают,
    /// и карточка под ним обязана остаться на месте.
    fn answer_for(&self, request: &Request) -> Option<MediaInfo> {
        self.is_about(Some(request))
            .then(|| self.info.clone())
            .flatten()
    }
}

pub struct SavioApp {
    /// Язык интерфейса. Запоминается между запусками (`settings::Settings`).
    ///
    /// Полем, а не глобалью: ровно по той же причине, по какой `Lang` ездит
    /// параметром через движок — скрытое состояние, которое читают шестьсот
    /// раз за кадр, перестаёт быть проверяемым. Стоит он байт и копируется
    /// бесплатно.
    ///
    /// Смена языка — не только новые подписи: готовые строки (`meta_line`,
    /// `progress_line`, `quality_note`, `subs_note`, сводка очереди, прогноз)
    /// собраны заранее и сами не обновятся, а идущие потоки движка говорят
    /// на том языке, с которым их запускали. И то и другое чинит
    /// [`SavioApp::set_lang`].
    lang: Lang,
    url: String,
    format: Format,
    /// Выбранная ступень качества. Отдельно от формата, как и в модели:
    /// переключение MP4 ↔ MP3 не должно её сбрасывать.
    quality: Quality,
    /// Галочки «вшить метаданные / обложку / субтитры».
    options: DownloadOptions,
    /// На каком языке нужны субтитры.
    ///
    /// Отдельно от `options` по той же причине, что и `cookies`: там всё
    /// `Copy`, а язык — строка. Между запусками не запоминается: язык
    /// относится к конкретному ролику, и вчерашний «немецкий», молча
    /// применённый к сегодняшней ссылке, дал бы не те субтитры.
    sub_lang: SubLang,
    /// Границы фрагмента — как их набрал человек. Строки, а не числа: поле
    /// ввода хранит текст, а разбирает его домен (`parse_section`).
    ///
    /// Между запусками намеренно не запоминаются, в отличие от формата,
    /// качества, папки и входа на сайт: границы относятся к конкретному
    /// ролику, и вчерашние «1:30 — 4:00», молча применённые к сегодняшней
    /// ссылке, дали бы не тот файл.
    section_start: String,
    section_end: String,
    /// Разобранные границы. Пересобираются на правке поля, а не в кадре:
    /// `ui()` зовут 60 раз в секунду, а меняется это от нажатия клавиши.
    section: Section,
    /// Чем именно плох набранный диапазон. `None` — всё в порядке (в том
    /// числе когда оба поля пусты).
    section_error: Option<SectionError>,
    /// Откуда брать вход в аккаунт: браузер или файл.
    ///
    /// Запоминается между запусками наравне с форматом, качеством и папкой
    /// (задача 24 реестра). До 0.22 — намеренно нет, и опасение было
    /// разумным: это доступ к чужому профилю браузера. Перевесила обратная
    /// сторона — тот, кто качает с закрытого сайта постоянно, выбирал вход
    /// при каждом запуске.
    ///
    /// **Из-за этого решения указатели на включённый вход стали
    /// обязательными, а не украшением.** Состояние хрупкое — у YouTube
    /// cookies ломают загрузку совсем, при открытом браузере база занята, —
    /// и, придя из прошлого запуска, оно объясняет отказ, который иначе
    /// выглядит бедой сегодняшней ссылки.
    ///
    /// Указателя два, и работают они в разное время. Жёлтая оговорка под
    /// списком видна только при раскрытых «Тонких настройках», а при запуске
    /// `advanced` = `false`, то есть группа свёрнута. Поэтому весь груз при
    /// запуске несёт `advanced_summary` — «вход на сайт» в заголовке группы,
    /// и несёт его видом, а не словами: жёлтой точкой и цветом. Словами
    /// не вышло бы — заглушка нетронутой группы перечисляет те же слова
    /// (задача 51 реестра, подробности у [`advanced_summary`]).
    cookies: CookieSource,
    /// Выбранный файл cookies. Осмыслен только при `CookieSource::File`,
    /// но переживает переключение списка: вернувшись к «Из файла…», человек
    /// не должен искать тот же файл заново. Между запусками — по той же
    /// причине: обрывать эту память на закрытии окна было бы странностью
    /// без причины.
    ///
    /// `None` при `CookieSource::File` — законное состояние, хотя щелчками
    /// в него не попасть: так открывается запуск с запомненным «из файла»,
    /// у которого путь не выразился в UTF-8 и в `settings.json` не попал.
    cookie_file: Option<PathBuf>,
    /// Путь к файлу cookies строкой — для кнопки под списком. Полем, а не
    /// сборкой в кадре: `ui()` идёт 60 раз в секунду, а меняется это по
    /// выбору файла. Пока файла нет — приглашение выбрать его, а не пустая
    /// строка: пустая кнопка не сказала бы ничего.
    cookie_file_display: String,
    /// ffmpeg не нашёлся при последней проверке. Снимок с запуска (и с конца
    /// установки) — единственное, что можно спросить, не трогая диск в кадре.
    /// Нужен, чтобы предупредить о бесполезных галочках **до** нажатия
    /// «Скачать»; окончательное слово всё равно за движком в момент запуска.
    ffmpeg_missing: bool,
    out_dir: Option<PathBuf>,
    state: State,
    progress: Progress,
    stage: String,
    /// Что за ролик лежит по ссылке из поля. Наполняется фоновым запросом
    /// по вставке ссылки, а не загрузкой: см. [`Preview`].
    preview: Preview,
    log: Vec<String>,
    rx: Option<Receiver<Event>>,
    handle: Option<Handle>,
    /// Проверяем наличие yt-dlp один раз на старте, чтобы сразу показать
    /// внятную подсказку вместо провала при первой попытке скачать.
    setup_error: Option<String>,
    /// Ход установки недостающих инструментов.
    setup: Setup,
    /// Предупреждение, которое переживает установку: например, что ffmpeg
    /// поставить не удалось. Живёт до конца сеанса и не стирается вместе
    /// с журналом при старте загрузки.
    warning: Option<String>,
    /// Хорошая новость с тем же сроком жизни: до какой версии обновился
    /// движок или что он и так был свежим. Без неё удачное обновление
    /// выглядело бы как молча закрывшаяся модалка.
    notice: Option<String>,
    /// Ручка установки — нужна, чтобы её можно было прервать.
    setup_handle: Option<setup::Handle>,
    /// Приёмник ответа о версиях инструментов.
    ///
    /// Отдельный от `rx`: опрос версий идёт при запуске, когда общий канал ещё
    /// может быть занят установкой недостающего, — попади ответ туда, его
    /// разбирали бы вместе с событиями установки.
    versions_rx: Option<Receiver<Event>>,

    // Строки ниже пересобираются только при изменении состояния, а не в кадре.
    // `ui()` вызывается 60 раз в секунду: `format!` и `join` здесь стоили бы
    // сотен лишних аллокаций в секунду на ровном месте.
    /// Путь к папке сохранения в виде текста.
    out_dir_display: String,
    /// «Автор · длительность» — собирается один раз, когда приходят метаданные.
    meta_line: String,
    /// Строка под прогресс-баром: стадия, проценты, объём, скорость, остаток.
    progress_line: String,
    /// Путь к готовому файлу.
    done_path_display: String,
    /// Оговорка под переключателем качества: источник не отдаёт столько,
    /// сколько запросили. Пустая строка — оговорки нет.
    quality_note: String,
    /// Подпись выбранного языка субтитров — то, что написано на закрытом
    /// списке. Готовой строкой, а не поиском по дорожкам в кадре: их
    /// у YouTube полторы сотни.
    sub_lang_label: String,
    /// Оговорка под списком языков: субтитров, которые просят, у ролика нет.
    /// Пустая строка — всё в порядке или сказать пока нечего.
    subs_note: String,
    /// Что стоит в свёрнутых тонких настройках — одной строкой в их заголовке,
    /// с меткой, если там включено хоть что-то.
    ///
    /// Готовой строкой, а не сборкой в кадре: `ui()` зовут 60 раз в секунду,
    /// а меняется она от щелчка. И она обязательна: свёрнутая группа без
    /// сводки прячет включённую обрезку, а человек потом ищет, почему ролик
    /// скачался куском.
    advanced_summary: GroupSummary,
    /// Версии инструментов одной строкой для нижнего блока рельса.
    ///
    /// Одна, а не две: в рельсе она обрезается по ширине, и вторая строка
    /// удвоила бы её высоту на всех вкладках сразу. yt-dlp в ней стоит
    /// первым намеренно. Обрезается конец строки, а версия ffmpeg у
    /// git-сборки — это `N-125365-g9a01c1cb6a-20260630`, то есть ровно то,
    /// чем в узком окне можно пожертвовать; полностью её всё равно
    /// показывает подсказка обрезанной метки.
    tools_line: String,
    /// Ссылка не похожа на ссылку. Только подсветка поля — кнопку не блокирует.
    url_invalid: bool,
    /// Когда журнал скопировали, по часам egui. Нужно только для подписи
    /// «Скопировано»: она живёт `COPIED_NOTICE_SECS` и гаснет сама.
    log_copied_at: Option<f64>,
    /// Открыто ли окно «О программе».
    about_open: bool,
    /// Когда скопировали адрес для отзывов — ради той же подписи
    /// «Скопировано», что у журнала, только в окне «О программе».
    about_copied_at: Option<f64>,
    /// Когда главная кнопка ряда загрузки сменила «Скачать» на «Отмену» или
    /// обратно: полсекунды после этого она не принимает щелчков (задача 54,
    /// см. [`SwapPause`]).
    swap_pause: SwapPause,
    /// Показанная вкладка.
    tab: Tab,
    /// Половина вкладки «Машина».
    machine_tab: MachineTab,
    /// Что показано в правой колонке экрана загрузки.
    rail_tab: RailTab,
    /// Раскрыты ли тонкие настройки: фрагмент, вход на сайт, язык субтитров.
    ///
    /// Свёрнуты по умолчанию, и это главное, ради чего они собраны вместе:
    /// в развёрнутом виде они занимали половину карточки у всех, а нужны
    /// далеко не каждому. Сводка в заголовке говорит, что там сейчас стоит, —
    /// без неё свёрнутая группа прятала бы включённую обрезку.
    advanced: bool,
    /// Раскрыт ли журнал.
    log_open: bool,
    /// Включены ли плавные переходы. Запоминается между запусками.
    ///
    /// Это и есть тот самый выключатель движения, которого не сообщает ни
    /// eframe, ни winit: системного «уменьшить движение» они не отдают, так
    /// что спросить об этом можно только у человека.
    smooth: bool,
    /// Где сейчас бегущий по кромке блик, долей пути (приём 06).
    ///
    /// Считается один раз за кадр, там же, где `arrive`, и по тем же
    /// соображениям. Живёт дольше самого прихода: карточка приезжает за
    /// `LAYER`, а блик пробегает по её кромке за `GLOSS` — почти секунду.
    sweep: f32,
    /// Когда в последний раз сменили раздел, по часам egui.
    ///
    /// От этого мгновения считается блик: он длиннее самого прихода, и
    /// `animate_*` для него уже не годится.
    tab_changed_at: f64,
    /// Раздел сменился, и следующий кадр должен показать его с начала.
    ///
    /// Прокрутка у всех разделов одна, и без сброса новый раздел открывался
    /// на смещении прежнего: кнопка «Открыть «Загрузку»» стоит внизу
    /// «Метаданных», и «Загрузка» открывалась с полем ссылки за верхней
    /// кромкой (найдено ревью задачи 65).
    scroll_to_top: bool,
    /// Наибольшая доля, которую полоса прогресса уже показывала в этой
    /// загрузке.
    ///
    /// Полоса едет к присланному значению чуть дольше, чем приходит
    /// следующее, — но **назад не дёргается никогда**, и потолок нужен
    /// именно ради этого. Доля сама по себе не монотонна: yt-dlp качает
    /// видео и звук по отдельности и на каждой дорожке начинает счёт байтов
    /// заново, так что «73%» честно сменяется «2%». Сбрасывается там же, где
    /// сама `progress`.
    progress_peak: f32,
    /// Насколько содержимое показанного раздела уже приехало: 0 — только что
    /// переключились, 1 — стоит на месте (приём 04).
    ///
    /// Полем, а не расчётом по месту: карточек в разделе несколько, каждая
    /// берёт из этого числа свою долю, и спрашивать egui об одном и том же
    /// по разу на карточку было бы лишней работой в кадре. Считается один
    /// раз за кадр, в `ui`.
    arrive: f32,
    /// Множитель длительностей, посчитанный из `smooth`.
    ///
    /// Отдельным полем, а не `motion::scale(self.smooth)` по месту, и по той
    /// же причине, по какой рядом лежат готовые строки: `ui()` зовут 60 раз
    /// в секунду, и каждый виджет спрашивал бы его заново. Меняется он от
    /// щелчка по галочке — там и пересчитывается.
    ///
    /// Ноль означает «без движения», и отдельной ветки «если анимации
    /// выключены» из-за этого не нужно нигде: `animate_*` с нулевым временем
    /// встают на конечное значение сразу.
    speed: f32,
    /// Состояние вкладки «Метаданные».
    meta: MetaPanel,
    /// Состояние вкладки «Система».
    system: SystemPanel,
    /// Состояние вкладки «Монитор» и оверлея.
    monitor: MonitorPanel,
    /// Состояние карточки «Питание» на половине «Сейчас».
    power: PowerPanel,
    /// Состояние вкладки «Погода».
    weather: WeatherPanel,
    /// Состояние экрана «Телефон».
    share: SharePanel,
    /// Открыто ли меню нижнего блока в свёрнутом рельсе.
    more_open: bool,
    /// Чем eframe рисует это окно.
    ///
    /// Снимается один раз при создании приложения с того же адаптера, что уже
    /// открыт для отрисовки, — второй открывать незачем, и стоит это ноль.
    /// `get_info()` собирает четыре строки, так что в кадре его звать нельзя
    /// (Правило 1); здесь он вызван ровно один раз за запуск. `None` —
    /// сборка без wgpu: не ошибка, просто пункта про видеокарту не будет.
    gpu: Option<GpuInfo>,
    /// Что скачано за этот запуск. Наполняется из `Event::Done`.
    history: History,
    /// Ссылки, поставленные в очередь. Идут строго по одной, сверху вниз.
    queue: Queue,
    /// Окно нужно развернуть на первом кадре.
    ///
    /// Одного `with_maximized(true)` в `main.rs` мало: вместе с
    /// `with_inner_size` он выставляет окну признак развёрнутого, но не
    /// применяет саму геометрию — окно открывается прежнего размера, хотя
    /// `IsZoomed` уже отвечает «развёрнуто». Проверено на Windows 11.
    /// Команду шлём **однократно**: каждый кадр — и пользователь не смог бы
    /// вернуть окну обычный размер.
    maximize_pending: bool,
    /// Кто запоминает выбор на следующий запуск.
    ///
    /// Пишет на своём потоке: сама запись — это ввод-вывод, а зовут её из
    /// обработчика щелчка, то есть из кадра отрисовки.
    saver: settings::Saver,

    /// Сюда обработчик wgpu складывает то, из-за чего процесс раньше падал.
    /// Разделяется с обработчиком, поэтому `Arc`, а не поле по значению.
    gpu_errors: Arc<GpuErrors>,

    /// Показано ли сейчас приветствие.
    ///
    /// При первом запуске — да, дальше только по кнопке «?». Отметку
    /// «показали» держит пустой файл в папке инструментов
    /// (`binaries::welcome_seen`), а не поле настроек: это не выбор
    /// человека, а след того, что он здесь уже был.
    welcome_open: bool,
    /// Подписи вкладок правой колонки вместе с числами: «Очередь 3».
    ///
    /// Собраны заранее, и пересобираются только когда число вправду
    /// изменилось: `format!` в кадре отрисовки — это аллокация шестьдесят
    /// раз в секунду ни за что (Правило 1). Сравнение двух чисел — вся цена.
    rail_labels: (String, String),
    /// Числа, по которым собраны `rail_labels`. `None` — пересобрать.
    rail_counts: Option<(usize, usize)>,
    /// Названия групп рельса прописными.
    ///
    /// Собраны заранее, а не в кадре: `to_uppercase` — это аллокация на
    /// каждую группу, а рельс рисуется шестьдесят раз в секунду. Значит,
    /// и пересобрать их обязан `set_lang` — пропусти его, и группы
    /// останутся на прежнем языке до следующего запуска.
    nav_groups: [String; 3],
    /// Выбранная тема, тёмная или светлая. Сохраняется.
    appearance: Appearance,
    /// Цвета выбранной темы.
    ///
    /// Полем, а не вызовом `Palette::of` в кадре: палитра меняется только
    /// щелчком по переключателю, а собирать её шестьдесят раз в секунду было
    /// бы ровно той лишней работой, которой не велит Правило 1. Отсюда же она
    /// раздаётся вниз параметром — как `Lang`, и по той же причине.
    palette: theme::Palette,
}

impl SavioApp {
    /// Собирает приложение и, если нужно, сразу запускает установку.
    ///
    /// Проверка наличия инструментов — это несколько обращений к файловой
    /// системе, поэтому её можно делать прямо здесь: когда всё на месте (любой
    /// запуск, кроме первого) окно открывается без единой задержки, как и
    /// требуется. Сама загрузка идёт в отдельном потоке.
    pub fn new(ctx: &egui::Context) -> Self {
        // Выбор прошлого запуска. Файла нет, он битый или папка исчезла —
        // получаем ровно те умолчания, что раньше были зашиты здесь: MP4,
        // максимальное качество и каталог загрузок.
        let saved = settings::load();
        let out_dir = saved.out_dir.or_else(default_download_dir);

        let lang = saved.lang;
        let mut app = Self {
            lang,
            url: String::new(),
            format: saved.format,
            quality: saved.quality,
            // Галочки вшивания восстанавливаются как есть, **не** оглядываясь
            // на то, нашёлся ли ffmpeg. Без него человек увидит под ними
            // жёлтую оговорку «Вшивать нечем» — и это правда: он просил вшить,
            // а вшить нечем. Погасить их было бы тише, но соврало бы дважды:
            // сегодня — про то, чего он не отменял, а в тот день, когда ffmpeg
            // доставится, — молчаливым отказом вшить то, что он выбрал.
            options: saved.options,
            sub_lang: SubLang::default(),
            section_start: String::new(),
            section_end: String::new(),
            section: Section::default(),
            section_error: None,
            // Вход на сайт восстанавливается как есть, включая «Из файла…»
            // с пропавшим файлом: молча вернуть «Не использовать» значило бы
            // скачать без входа в аккаунт, а закрытый сайт ответил бы на это
            // «нужен вход» — подсказкой не про ту беду. Про пропажу скажет
            // движок перед загрузкой, назвав файл по имени.
            cookies: saved.cookies,
            cookie_file_display: display_cookie_file(saved.cookie_file.as_deref(), lang),
            cookie_file: saved.cookie_file,
            ffmpeg_missing: false,
            out_dir_display: display_dir(out_dir.as_deref(), lang),
            out_dir,
            state: State::Idle,
            progress: Progress::default(),
            stage: String::new(),
            preview: Preview::default(),
            log: Vec::new(),
            rx: None,
            handle: None,
            setup_error: None,
            setup: Setup::Ready,
            warning: None,
            notice: None,
            setup_handle: None,
            versions_rx: None,
            meta_line: String::new(),
            progress_line: String::new(),
            done_path_display: String::new(),
            quality_note: String::new(),
            sub_lang_label: SubLang::original_label(lang).to_owned(),
            subs_note: String::new(),
            // Пустая до первого ответа: рельс просто не показывает версий,
            // пока их не спросили, — «неизвестно» там было бы враньём
            // на те доли секунды, что идёт опрос.
            tools_line: String::new(),
            advanced_summary: GroupSummary::default(),
            url_invalid: false,
            log_copied_at: None,
            about_open: false,
            about_copied_at: None,
            swap_pause: SwapPause::default(),
            tab: Tab::Download,
            machine_tab: MachineTab::Now,
            rail_tab: RailTab::Queue,
            advanced: false,
            log_open: false,
            smooth: saved.smooth,
            progress_peak: 0.0,
            // Единица — «блика нет». При запуске он всё же пробежит: время
            // egui начинается с нуля, и `GLOSS` от нуля ещё не истёк.
            sweep: 0.0,
            tab_changed_at: 0.0,
            scroll_to_top: false,
            // Единица, а не ноль: первый кадр — это не смена раздела, и
            // проявляться при запуске окну незачем.
            arrive: 1.0,
            speed: motion::scale(saved.smooth),
            meta: MetaPanel::new(),
            system: SystemPanel::new(),
            monitor: MonitorPanel::new(),
            power: PowerPanel::new(),
            // Место, единицы и избранное — из прошлого запуска. В сеть здесь
            // не ходит ничего: прогноз спрашивается при первом открытии
            // вкладки (см. `WeatherPanel::watch`).
            weather: WeatherPanel::new(
                saved.weather_place,
                saved.weather_units,
                saved.weather_favorites,
            ),
            // Своя папка раздачи не запоминается: запоминаемая настройка
            // встречает человека при запуске, а папку, открытую для всей
            // сети, лучше выбирать осознанно, а не находить выбранной неделю
            // назад. По умолчанию — папка сохранения.
            share: SharePanel::new(),
            more_open: false,
            gpu: None,
            history: History::default(),
            queue: Queue::new(lang),
            maximize_pending: true,
            saver: settings::Saver::spawn(),
            gpu_errors: Arc::default(),
            welcome_open: !binaries::welcome_seen(WELCOME_EDITION),
            rail_labels: (String::new(), String::new()),
            rail_counts: None,
            nav_groups: nav_groups(lang),
            appearance: saved.appearance,
            palette: theme::Palette::of(saved.appearance),
        };

        // Стиль ставится здесь, а не в `main`: тема лежит в настройках,
        // а читает их этот конструктор. Шрифты к этому моменту уже стоят.
        theme::apply(ctx, app.palette);

        app.ffmpeg_missing = !engine::has_ffmpeg();
        app.rebuild_advanced_summary();

        let what = setup::missing();
        if what.any() {
            let (tx, rx) = channel();
            let notify_ctx = ctx.clone();
            app.setup_handle = Some(setup::start(what, lang, tx, move || {
                notify_ctx.request_repaint()
            }));
            app.rx = Some(rx);
            app.setup = Setup::Installing;
            app.stage = i18n::t(lang, Key::StageCheckingMissing).into();
            app.rebuild_progress_line();
        } else {
            app.setup_error = engine::discover(lang).err();
        }

        // Версии спрашиваем сразу — но в отдельном потоке: это запуск двух
        // чужих программ, и в конструкторе окна ему не место. До ответа строка
        // обслуживания просто без версий, и открытию окна опрос не мешает.
        app.refresh_versions(ctx);

        app
    }

    /// Ставит перехват ошибок wgpu вместо падения процесса — см. [`GpuErrors`].
    ///
    /// Отдельным вызовом, а не внутри `new`: устройство появляется только у
    /// рендерера wgpu, и его может не быть вовсе (сборка на glow). Тогда
    /// перехватывать нечего, и это не ошибка — приложение работает как прежде.
    pub fn catch_gpu_errors(&self, cc: &eframe::CreationContext<'_>) {
        let Some(state) = &cc.wgpu_render_state else {
            return;
        };
        let errors = Arc::clone(&self.gpu_errors);
        let ctx = cc.egui_ctx.clone();
        state.device.on_uncaptured_error(Arc::new(move |error| {
            errors.push(error.to_string());
            // Сообщение попадёт в журнал в ближайшем кадре, а сам кадр без
            // этой строки может и не наступить: окно в этот момент как раз
            // ничего не рисует.
            ctx.request_repaint();
        }));
    }

    /// Забирает сведения о видеокарте с адаптера, которым рисуется окно.
    ///
    /// Зовётся один раз при создании приложения, из того же места, что и
    /// `catch_gpu_errors`, и по той же причине: `RenderState` виден только
    /// здесь. Второй адаптер не открываем — этот уже готов, и данные с него
    /// стоят ноль. Отдельным методом, а не внутри `catch_gpu_errors`: тот
    /// про выживание процесса, этот про содержимое вкладки, и смешивать
    /// два несвязанных дела в одном имени незачем.
    ///
    /// Обновлять нечего: адаптер у окна один на всю жизнь процесса.
    pub fn read_gpu_info(&mut self, cc: &eframe::CreationContext<'_>) {
        // `None` — сборка на glow либо wgpu не поднялся. Не ошибка: пункта
        // про видеокарту в отчёте просто не будет.
        let Some(state) = &cc.wgpu_render_state else {
            return;
        };
        let info = state.adapter.get_info();

        // Пустые строки у `AdapterInfo` — обычное дело: `driver` и
        // `driver_info` приходят пустыми на Metal и на GL через ANGLE, и это
        // штатно. Пустоту превращаем в `None` здесь, у самого источника,
        // чтобы дальше по коду «нет данных» имело один-единственный вид.
        let text = |s: String| (!s.trim().is_empty()).then_some(s);

        self.gpu = text(info.name.clone()).map(|name| GpuInfo {
            name,
            // Ключ, а не готовая строка: снимок берётся один раз при старте,
            // а язык человек волен переключить потом.
            kind: match info.device_type {
                eframe::wgpu::DeviceType::DiscreteGpu => Key::HwGpuDiscrete,
                eframe::wgpu::DeviceType::IntegratedGpu => Key::HwGpuIntegrated,
                eframe::wgpu::DeviceType::VirtualGpu => Key::HwGpuVirtual,
                // Программный растеризатор: карты нет вовсе или её драйвер
                // не подошёл. Сказать об этом стоит — рисование в этом
                // случае заметно медленнее.
                eframe::wgpu::DeviceType::Cpu => Key::HwGpuSoftware,
                eframe::wgpu::DeviceType::Other => Key::HwGpuUnknownKind,
            },
            // Ноль здесь — «идентификатор неизвестен», и звать по нему
            // разбор вендора незачем: он ответил бы «Unknown».
            vendor: (info.vendor != 0)
                .then(|| eframe::egui_wgpu::parse_vendor_id(info.vendor))
                .filter(|name| *name != "Unknown")
                .map(str::to_owned),
            // Имя драйвера и его версия лежат в разных полях, и порознь
            // каждое бесполезно: «NVIDIA» без числа не отличает свежий
            // драйвер от трёхлетнего. Склеиваем, но только непустые — на
            // Metal и на GL через ANGLE оба поля приходят пустыми, и это
            // штатно.
            driver: match (text(info.driver.clone()), text(info.driver_info.clone())) {
                (Some(name), Some(version)) => Some(format!("{name} {version}")),
                (Some(one), None) | (None, Some(one)) => Some(one),
                (None, None) => None,
            },
            backend: info.backend.to_string(),
        });
    }

    /// Переносит пойманное в журнал. Зовётся из кадра, где это уже безопасно:
    /// сам обработчик работает посреди чужого кода.
    fn drain_gpu_errors(&mut self) {
        for message in self.gpu_errors.take() {
            let line = gpu_error_line(&message, self.lang);
            // Повтор гасится здесь, по готовой строке, а не по сообщению
            // wgpu. Иначе в журнале двоится: про один и тот же предел
            // приходят два РАЗНЫХ сообщения (про поверхность и про
            // `set_viewport`), а человеку они говорят одно и то же. Заодно
            // это гасит повтор между кадрами: пока окно остаётся большим,
            // ошибка приходит заново в каждом.
            if self.log.last().is_some_and(|last| *last == line) {
                continue;
            }
            self.log.push(line);
            if self.log.len() > LOG_LIMIT {
                self.log.drain(..self.log.len() - LOG_LIMIT);
            }
        }
    }

    /// Вызывается, когда установка закончилась — успехом или нет.
    /// Инструменты после неё нужно искать заново: до установки их не было.
    fn finish_setup(&mut self, outcome: Setup, ctx: &egui::Context) {
        self.setup = outcome;
        self.setup_handle = None;
        self.rx = None;
        self.handle = None;
        self.setup_error = engine::discover(self.lang).err();
        // Ради этой строки установка и затевалась: до неё ffmpeg могло не быть.
        self.ffmpeg_missing = !engine::has_ffmpeg();
        self.stage.clear();
        self.progress = Progress::default();
        self.progress_peak = 0.0;
        self.progress_line.clear();
        // Предпросмотр мог споткнуться ровно о то, чего до этой минуты не было:
        // без yt-dlp спрашивать сайт нечем, а молчит он об этом одинаково — и
        // про отсутствие инструмента, и про незнакомый сайт. Раз инструменты
        // появились, пробуем ещё раз: иначе ссылка, лежащая в поле с прошлой
        // попытки, останется без карточки до следующей правки текста.
        if self.preview.state == PreviewState::Failed {
            self.preview.retry(ctx.input(|i| i.time));
        }

        // Версии после установки или обновления другие — показанные устарели
        // ровно в этот момент. Спросить заново обязательно: иначе кнопка
        // «Обновить» отчитывалась бы об успехе, а строка над ней продолжала бы
        // показывать прежний номер, и обновление выглядело бы несработавшим.
        self.refresh_versions(ctx);
    }

    fn cancel_setup(&mut self, ctx: &egui::Context) {
        if let Some(handle) = &self.setup_handle {
            handle.cancel();
        }
        self.finish_setup(Setup::Ready, ctx);
    }

    /// Обновление инструмента по кнопке.
    ///
    /// Идёт по тому же каналу и в ту же модалку, что и установка при первом
    /// запуске: задача та же — скачать бинарник и показать прогресс, поэтому
    /// заводить второй механизм незачем.
    fn start_update(&mut self, what: setup::Component, ctx: &egui::Context) {
        let (tx, rx) = channel();
        let notify_ctx = ctx.clone();

        // Прошлый исход убираем: иначе рядом со свежим результатом висела бы
        // причина позапрошлой неудачи и было бы не понять, к чему она.
        self.notice = None;
        self.warning = None;
        if matches!(self.setup, Setup::Failed(_)) {
            self.setup = Setup::Ready;
        }

        self.setup_handle = Some(setup::start_update(what, self.lang, tx, move || {
            notify_ctx.request_repaint()
        }));
        self.rx = Some(rx);
        self.setup = Setup::Updating(what);
        self.progress = Progress::default();
        self.progress_peak = 0.0;
        // Первая стадия у двух веток разная: у yt-dlp следом идёт запрос
        // выпуска, у ffmpeg — сразу загрузка, и «Проверяю версию…» висела бы
        // над полосой, которая на самом деле качает архив.
        self.stage = self
            .t(match what {
                setup::Component::Ytdlp => Key::StageCheckingVersion,
                setup::Component::Ffmpeg => Key::StageGettingReady,
            })
            .into();
        self.rebuild_progress_line();
    }

    /// Спрашивает версии установленных инструментов заново.
    ///
    /// Свой приёмник, а не общий `rx`: тот занят загрузкой или установкой, и
    /// ответ о версиях, пришедший в него, разбирался бы вместе с их событиями.
    /// Так же устроена вкладка метаданных — образец готовый.
    ///
    /// Зовётся при запуске и после каждой установки или обновления: ровно
    /// тогда версии и меняются. В кадре отрисовки — никогда.
    fn refresh_versions(&mut self, ctx: &egui::Context) {
        let (tx, rx) = channel();
        let notify_ctx = ctx.clone();
        setup::start_versions(tx, move || notify_ctx.request_repaint());
        self.versions_rx = Some(rx);
    }

    /// Отдаёт текущий выбор писателю настроек.
    ///
    /// Зовётся из обработчиков переключателей — там же, где вызывается
    /// `rebuild_*`, и ровно по той же причине: собирать снимок 60 раз
    /// в секунду незачем, меняется он от щелчка. **Новое запоминаемое поле
    /// нужно не только добавить в `Settings`, но и не забыть позвать
    /// `remember` там, где его меняют**: пропуск ничего не сломает и никак
    /// не проявится, кроме как «эта настройка почему-то не запоминается».
    fn remember(&self) {
        self.saver.save(settings::Settings {
            format: self.format,
            quality: self.quality,
            out_dir: self.out_dir.clone(),
            // Флажки уезжают такими, какие есть, даже когда их не видно:
            // «Субтитры» при MP3 и «Можно автоматические» при снятых
            // субтитрах спрятаны, но значения своего не теряли. Обнулять
            // спрятанное нельзя — один запуск в режиме MP3 стёр бы настройку
            // насовсем, хотя человек к ней не прикасался.
            options: self.options,
            cookies: self.cookies,
            // Файл уезжает и тогда, когда вход выключен: в окне выбранный
            // файл переживает переключение списка на «Не использовать» и
            // обратно, и на закрытии окна эта память обрываться не должна.
            cookie_file: self.cookie_file.clone(),
            smooth: self.smooth,
            // Каждое поле погоды выписано, а не заткнуто `..Default::default()`:
            // иначе первый же щелчок по формату записал бы файл с пустой
            // погодой и молча стёр бы выбранное место и избранное.
            weather_place: self.weather.place.clone(),
            weather_units: self.weather.units,
            weather_favorites: self.weather.favorites.clone(),
            lang: self.lang,
            appearance: self.appearance,
        });
    }

    /// Переключает тему окна.
    ///
    /// Стиль пересобирается здесь, а не в кадре: `Style` содержит `BTreeMap`
    /// шрифтов. Сами шрифты при этом не трогаются — `set_fonts` пересобрал бы
    /// атлас глифов, то есть подвесил бы окно на ровном месте.
    fn set_appearance(&mut self, appearance: Appearance, ctx: &egui::Context) {
        if self.appearance == appearance {
            return;
        }
        self.appearance = appearance;
        self.palette = theme::Palette::of(appearance);
        theme::apply(ctx, self.palette);
        self.remember();
    }

    /// Пересобирает подписи вкладок правой колонки, если числа изменились.
    ///
    /// Ноль в подписи не пишется: «История 0» рядом с пустым списком —
    /// это то же самое, сказанное дважды, а место в колонке шириной 340
    /// не бесплатно.
    fn rebuild_rail_labels(&mut self) {
        let counts = (self.queue.items.len(), self.history.entries.len());
        if self.rail_counts == Some(counts) {
            return;
        }
        self.rail_counts = Some(counts);

        let lang = self.lang;
        let label = |key, count: usize| {
            let name = i18n::t(lang, key);
            if count == 0 {
                name.to_owned()
            } else {
                format!("{name} {count}")
            }
        };
        self.rail_labels = (
            label(Key::RailQueue, counts.0),
            label(Key::RailHistory, counts.1),
        );
    }

    /// Строка интерфейса на выбранном языке.
    ///
    /// Короткий доступ, чтобы `i18n::t(self.lang, …)` не повторялся в каждой
    /// строке кадра. Звать из `ui()` можно: внутри `match` по ключу, ни одной
    /// аллокации (Правило 1).
    fn t(&self, key: Key) -> &'static str {
        i18n::t(self.lang, key)
    }

    /// Переключает язык и приводит окно в порядок.
    ///
    /// Одних новых подписей мало, и это главная ловушка задачи. Готовые строки
    /// (`meta_line`, `progress_line`, сводка очереди, прогноз погоды, строки
    /// передач) собраны заранее — из кадра они не пересобираются, и половина
    /// экрана осталась бы на прежнем языке до следующего события движка.
    /// Поэтому здесь их пересобирают **явно**.
    ///
    /// Идущие потоки движка перезапускать нельзя: смена языка не должна ни
    /// останавливать загрузку, ни терять её состояние. Те, что молча говорят
    /// на старом языке и живут долго, — опрос монитора и раздача — перезапуск
    /// переживают без потерь: опрос соберёт свежий замер через секунду, а
    /// раздача у выключенного экрана и не идёт.
    fn set_lang(&mut self, lang: Lang, ctx: &egui::Context) {
        if lang == self.lang {
            return;
        }
        self.lang = lang;
        self.remember();

        // Строки, собранные заранее. Пропусти любую — и она останется
        // на прежнем языке до следующего события движка, то есть, возможно,
        // навсегда.
        self.nav_groups = nav_groups(lang);
        // Числа те же, а слова другие — сбрасываем память о числах, иначе
        // подписи остались бы на прежнем языке до первой правки очереди.
        self.rail_counts = None;
        self.rebuild_rail_labels();
        self.out_dir_display = display_dir(self.out_dir.as_deref(), lang);
        self.cookie_file_display = display_cookie_file(self.cookie_file.as_deref(), lang);
        self.meta.relabel(lang, ctx);
        self.rebuild_progress_line();
        self.rebuild_meta_line();
        self.rebuild_quality_note();
        self.rebuild_subtitles();
        self.rebuild_advanced_summary();
        self.queue.relabel(lang);
        self.weather.relabel(lang);
        self.share.relabel(lang);

        self.power.relabel(lang);

        // Опрос монитора перезапускаем: подробности замера («8 ядер · 3.2 ГГц»,
        // «13.1 ГБ из 31.9 ГБ») собирает поток, и сменить их на ходу нечем.
        // Свежий замер приедет через секунду.
        if self.monitor.running() {
            self.monitor.stop();
            self.monitor.start(lang, ctx);
        }
        // Питание — по той же причине: «Питанием Savio управляет только
        // в Windows» собрано потоком и на месте не переводится. Перечитываем
        // только то, что уже спрашивали: до первого открытия половины
        // переводить нечего.
        if !self.power.state.is_blank() || self.power.state.trouble.is_some() {
            self.power.start(lang, ctx);
        }
    }
}

fn default_download_dir() -> Option<PathBuf> {
    #[cfg(windows)]
    let home = std::env::var_os("USERPROFILE");
    #[cfg(not(windows))]
    let home = std::env::var_os("HOME");

    let downloads = PathBuf::from(home?).join("Downloads");
    downloads.is_dir().then_some(downloads)
}

fn display_dir(dir: Option<&Path>, lang: Lang) -> String {
    match dir {
        Some(dir) => dir.display().to_string(),
        // Не пустая строка: пустая кнопка не сказала бы ничего.
        None => i18n::t(lang, Key::UiNoFolderChosen).to_owned(),
    }
}

/// Путь к файлу cookies для кнопки под списком входа.
///
/// Отдельной функцией, а не двумя одинаковыми строчками у выбора файла и
/// у старта: правило показа тут одно, и разъедься оно, кнопка выглядела бы
/// по-разному в зависимости от того, откуда взялся путь.
fn display_cookie_file(file: Option<&Path>, lang: Lang) -> String {
    match file {
        Some(file) => file.display().to_string(),
        None => i18n::t(lang, PICK_COOKIE_FILE).to_owned(),
    }
}

impl SavioApp {
    /// Проверки, общие для «Скачать» и «В очередь»: они относятся к ссылке
    /// в поле, а не к тому, что с ней собираются делать.
    fn url_is_ready(&self) -> bool {
        !self.url.trim().is_empty()
            && self.out_dir.is_some()
            && self.setup_error.is_none()
            // Неразобранный диапазон кнопку **блокирует**, в отличие от
            // непохожей на ссылку строки. Разница не в строгости, а в том,
            // чья это проверка: список поддерживаемых сайтов принадлежит
            // yt-dlp, и наша догадка о ссылке не повод запрещать попытку.
            // А границы фрагмента — наши целиком, и промах в них yt-dlp
            // ошибкой не считает: он молча отдаёт файл не с тем содержимым,
            // и заметить подмену можно, только открыв его.
            && self.section_error.is_none()
    }

    /// Можно ли поставить ссылку из поля в конец очереди.
    ///
    /// В отличие от «Скачать», работает и во время загрузки: очередь затем
    /// и нужна, чтобы докладывать ссылки, пока идёт первая.
    fn can_enqueue(&self) -> bool {
        self.url_is_ready() && !self.queue.full
    }

    fn can_start(&self) -> bool {
        if matches!(self.state, State::Running) || self.setup_error.is_some() {
            return false;
        }
        // Ссылка в поле поедет в очередь первой — её проверки прежние.
        // Поле пустое — запускать имеет смысл только то, что уже стоит
        // в очереди: ровно так возвращаются к остатку после «Отмены».
        if self.url.trim().is_empty() {
            self.queue.has_waiting()
        } else {
            self.url_is_ready()
        }
    }

    /// Ставит ссылку из поля в конец очереди.
    ///
    /// Возвращает `false`, если ставить было нечего или места не нашлось.
    fn enqueue(&mut self) -> bool {
        if !self.can_enqueue() {
            return false;
        }
        let Some(out_dir) = self.out_dir.clone() else {
            return false;
        };

        let request = Request {
            url: self.url.trim().to_owned(),
            format: self.format,
            quality: self.quality,
            options: self.options,
            cookies: self.cookies,
            cookie_file: self.cookie_file.clone(),
            section: self.section,
            sub_lang: self.sub_lang.clone(),
        };

        // Ответ предпросмотра уезжает вместе со ссылкой: спрашивать сайт
        // второй раз о том же самом незачем — ни ради названия в списке,
        // ни ради обложки, которая и так уже показана.
        let known = self.preview.answer_for(&request);
        if self.queue.push(request, out_dir, known).is_none() {
            return false;
        }

        // Пока ничего не идёт, экран описывает не прошлую загрузку, а то,
        // что человек только что попросил. Во время загрузки состояние
        // не трогаем: там оно про неё.
        if !matches!(self.state, State::Running) {
            self.state = State::Queued;
        }
        true
    }

    /// Нажали «Скачать»: ссылка из поля уходит в конец очереди, и очередь
    /// идёт сверху вниз.
    ///
    /// Пустое поле при непустой очереди — это «продолжить»: так возвращаются
    /// к тому, что осталось после «Отмены». Поле при этом не очищается — до
    /// появления очереди «Скачать» его тоже не трогал, и повторить ту же
    /// ссылку по-прежнему можно вторым нажатием.
    fn start(&mut self, ctx: &egui::Context) {
        self.enqueue();
        self.start_next(ctx);
    }

    /// Запускает следующую ожидающую ссылку.
    ///
    /// Строго по одной: пока идёт загрузка, второго потока не заводим —
    /// десяток ссылок обернулся бы десятком yt-dlp разом, поделивших канал
    /// и полосу на всех. Очередь кончилась — просто ничего не делаем:
    /// на экране остаётся исход последней загрузки.
    fn start_next(&mut self, ctx: &egui::Context) {
        // `setup.busy()` в проверке не для полноты: установка занимает тот же
        // единственный `rx`, и запуск загрузки поверх неё отобрал бы у модалки
        // её же события.
        if matches!(self.state, State::Running) || self.setup.busy() {
            return;
        }
        let Some((id, request, out_dir, known)) = self.queue.next_waiting() else {
            return;
        };

        let (tx, rx) = channel();
        let notify_ctx = ctx.clone();

        match engine::start(id, request, out_dir, known, self.lang, tx, move || {
            notify_ctx.request_repaint()
        }) {
            Ok(handle) => {
                self.queue.set_status(id, QueueStatus::Running);
                self.rx = Some(rx);
                self.handle = Some(handle);
                self.state = State::Running;
                self.progress = Progress::default();
                self.progress_peak = 0.0;
                self.stage = self.t(Key::StageStarting).into();
                self.log.clear();
                self.done_path_display.clear();
                self.rebuild_progress_line();
                // Карточку под полем ссылки здесь не трогаем, и это не
                // упущение: она описывает то, что лежит в поле, а не то, что
                // качается. Запуск ссылки из середины очереди поля не меняет —
                // и стирать по нему название с обложкой значило бы гасить
                // сведения о совсем другом ролике.
            }
            Err(err) => {
                // Не нашёлся yt-dlp — дальше по очереди идти незачем:
                // следующая ссылка споткнётся ровно о то же самое. Значит,
                // останавливаемся и говорим об этом один раз, а не полсотни.
                self.queue.set_status(id, QueueStatus::Failed(err.clone()));
                self.setup_error = Some(err.clone());
                self.state = State::Failed(err);
            }
        }
    }

    fn cancel(&mut self) {
        if let Some(handle) = &self.handle {
            handle.cancel();
        }
        self.handle = None;
        // Приёмник роняем сразу, и это не только уборка: у убитого процесса
        // поток движка живёт ещё секунду-другую и досылает свой `Failed`.
        // Закрытый канал глушит его, а заодно сообщает самому движку, что
        // UI про эту загрузку забыл (см. проверку перед запуском в `run`).
        self.rx = None;
        // Снятая — не проваленная: отмена показывается «Отменено», а не
        // ошибкой (Правило 2). Остальные ссылки остаются ждать: «Отмена»
        // останавливает очередь, а не стирает её, и «Скачать» продолжит
        // с того же места.
        if let Some(id) = self.queue.running_id() {
            self.queue.set_status(id, QueueStatus::Cancelled);
        }
        self.state = State::Cancelled;
        self.stage = self.t(Key::StageCancelled).into();
        self.progress_line.clear();
    }

    /// Собирает строку под прогресс-баром. Вызывается только на событиях
    /// движка, поэтому `format!` внутри безопасен — это не горячий путь.
    fn rebuild_progress_line(&mut self) {
        use std::fmt::Write as _;

        let p = self.progress;
        let lang = self.lang;
        // Собираем в свою строку, а не в поле: `self.t` — это заём `self`,
        // и с уже взятым изменяемым заёмом поля он не уживается.
        let mut line = String::new();
        line.push_str(&self.stage);

        let sep = |line: &mut String| {
            if !line.is_empty() {
                line.push_str(" · ");
            }
        };

        if let Some(fraction) = p.fraction() {
            sep(&mut line);
            let _ = write!(line, "{:.0}%", fraction * 100.0);
        }
        if p.total > 0 {
            sep(&mut line);
            line.push_str(&i18n::fill(
                i18n::t(lang, Key::AmountOfTotal),
                &[
                    &human_bytes(p.downloaded, lang),
                    &human_bytes(p.total, lang),
                ],
            ));
        }
        if let Some(speed) = p.speed_bps {
            sep(&mut line);
            line.push_str(&human_speed(speed, lang));
        }
        if let Some(eta) = p.eta_secs {
            sep(&mut line);
            line.push_str(&i18n::fill(
                i18n::t(lang, Key::UiTimeLeft),
                &[&human_duration(eta)],
            ));
        }

        self.progress_line = line;
    }

    fn rebuild_meta_line(&mut self) {
        use std::fmt::Write as _;

        self.meta_line.clear();
        let Some(info) = &self.preview.info else {
            return;
        };
        if let Some(uploader) = &info.uploader {
            self.meta_line.push_str(uploader);
        }
        if let Some(secs) = info.duration_secs {
            if !self.meta_line.is_empty() {
                self.meta_line.push_str(" · ");
            }
            self.meta_line.push_str(&human_duration(secs as u64));
        }
        // Что источник вообще способен отдать. Показываем и при выборе MP3:
        // это свойство ролика, а не запроса, и знать его полезно до того,
        // как выбирать высоту в следующий раз.
        if let Some(height) = info.max_height() {
            if !self.meta_line.is_empty() {
                self.meta_line.push_str(" · ");
            }
            let _ = write!(
                self.meta_line,
                "{}",
                i18n::fill(self.t(Key::UiUpToHeight), &[&height.to_string()])
            );
        }
    }

    /// Оговорка под переключателем качества.
    ///
    /// Ошибкой это не является: цепочка `-f` заканчивается общим запасным
    /// вариантом и молча опустится до лучшего доступного. Но молча — плохо:
    /// «1080p» в окне и 480p в файле выглядят как обман, поэтому о разнице
    /// говорим сразу, как только высоты приехали от `probe`.
    fn rebuild_quality_note(&mut self) {
        use std::fmt::Write as _;

        self.quality_note.clear();

        // У звука высота ни при чём: там ступень — это битрейт, и потолка,
        // о котором `probe` мог бы рассказать, у него нет.
        if self.format != Format::Mp4 {
            return;
        }
        let (Some(want), Some(have)) = (
            self.quality.max_height(),
            self.preview.info.as_ref().and_then(MediaInfo::max_height),
        ) else {
            return;
        };
        if want > have {
            let have = have.to_string();
            let _ = write!(
                self.quality_note,
                "{}",
                i18n::fill(self.t(Key::UiQualityNote), &[&have, &have])
            );
        }
    }

    /// Подпись выбранного языка субтитров и оговорка под списком.
    ///
    /// Обе строки собираются вместе намеренно: зависят они от одного и того
    /// же — от выбора человека и от ответа `probe`. Разъедься вызовы, и на
    /// списке был бы написан один язык, а оговорка говорила бы про другой.
    ///
    /// Зовётся только из обработчиков: смены формата, щелчка по галочке,
    /// выбора в списке и приезда `Event::Info`. В кадре отрисовки здесь
    /// собирать нечего — обе строки уже готовы.
    fn rebuild_subtitles(&mut self) {
        self.sub_lang_label.clear();
        match &self.sub_lang {
            SubLang::Original => self
                .sub_lang_label
                .push_str(SubLang::original_label(self.lang)),
            SubLang::Code(code) => {
                // Подписи может не быть: список остался от прошлой ссылки,
                // а у нынешней такого языка нет. Показываем тогда сам код —
                // он и уедет в `--sub-langs`.
                let label = self
                    .preview
                    .info
                    .as_ref()
                    .and_then(|info| info.subtitle_label(code))
                    .unwrap_or(code);
                self.sub_lang_label.push_str(label);
            }
        }

        self.subs_note.clear();
        // Говорим только тогда, когда знаем наверняка: субтитры просят,
        // положить их есть куда, и `probe` уже ответил. Молчание честнее
        // догадки.
        if self.format != Format::Mp4 || !self.options.embed_subs {
            return;
        }
        let Some(info) = &self.preview.info else {
            return;
        };
        if let Some(note) = info.subtitle_note(&self.sub_lang, self.options.auto_subs, self.lang) {
            self.subs_note = note;
        }
    }

    /// Сводка свёрнутых тонких настроек: что из них включено.
    ///
    /// Пишем только про то, что отличается от умолчания. Перечислять «фрагмент
    /// не задан · вход не используется» смысла нет: это состояние у почти всех
    /// и почти всегда, и в заголовке оно превратилось бы в шум, за которым
    /// перестанут замечать настоящую строку.
    ///
    /// Зовётся из обработчиков — правки полей фрагмента, выбора браузера,
    /// выбора языка, галочки субтитров и формата, — а не из кадра: `ui()`
    /// идёт 60 раз в секунду.
    fn rebuild_advanced_summary(&mut self) {
        self.advanced_summary = advanced_summary(
            self.section_error.is_some(),
            self.section.any(),
            self.cookies.any(),
            self.subs_requested().then_some(&self.sub_lang),
            self.lang,
        );
    }

    /// Просят ли субтитры: галочка стоит, и положить их есть куда.
    ///
    /// Одним методом на два места, которые обязаны отвечать одинаково: поле
    /// языка внутри тонких настроек и пункт «субтитры» в их заголовке.
    /// Разъедься условия — и свёрнутая группа называла бы то, чего, раскрыв
    /// её, не найти.
    fn subs_requested(&self) -> bool {
        self.format == Format::Mp4 && self.options.embed_subs
    }

    /// Короткая подпись состояния для плашки. Строки статические —
    /// в кадре отрисовки ничего не выделяется.
    fn status(&self) -> (&'static str, egui::Color32) {
        let pal = self.palette;
        match self.state {
            State::Idle => (self.t(Key::StateIdle), pal.text_secondary),
            State::Queued => (self.t(Key::StateQueued), pal.text_secondary),
            State::Running => (self.t(Key::StateRunning), pal.accent),
            State::Done(_) => (self.t(Key::StateDone), pal.state_success),
            State::Failed(_) => (self.t(Key::StateFailed), pal.state_error),
            State::Cancelled => (self.t(Key::StateCancelled), pal.text_secondary),
        }
    }

    /// Сначала собираем сообщения, потом применяем: иначе заимствование
    /// `self.rx` живёт во время мутации `self` и код не компилируется.
    ///
    /// `ctx` нужен обложке: текстура заводится здесь, на приёме события, —
    /// единственный момент, когда это делается за всю загрузку.
    fn drain_events(&mut self, ctx: &egui::Context) {
        let mut events = Vec::new();
        let mut disconnected = false;

        if let Some(rx) = &self.rx {
            loop {
                match rx.try_recv() {
                    Ok(event) => events.push(event),
                    Err(TryRecvError::Empty) => break,
                    Err(TryRecvError::Disconnected) => {
                        disconnected = true;
                        break;
                    }
                }
            }
        }

        // Строки пересобираем один раз после разбора пачки, а не на каждом
        // событии: прогресс приходит часто, а показать нужно только итог.
        let mut progress_dirty = false;
        let mut meta_dirty = false;
        // Текущая загрузка доработала — пора брать следующую из очереди.
        // Флагом, а не вызовом прямо из ветки: `start_next` подменяет `rx`,
        // и делать это посреди разбора уже вычитанной пачки — значит гадать,
        // к какой из двух загрузок относился её хвост.
        let mut advance = false;

        for event in events {
            match event {
                Event::Info(info) => {
                    // Название ролика — единственное, по чему строку очереди
                    // узнают глазами: десяток ссылок с одного сайта
                    // различается тремя символами в конце.
                    if let Some(title) = &info.title
                        && let Some(id) = self.queue.running_id()
                    {
                        self.queue.set_title(id, title);
                    }
                    // Карточка под полем ссылки — не про эту загрузку, и
                    // класть в неё что попало нельзя: качается обычно уже не
                    // то, что набрано в поле. Но если ссылка та же, а
                    // предпросмотр по ней ничего не добился (не было yt-dlp,
                    // сайт промолчал), то показать ответ загрузки — ровно то,
                    // что сделал бы он сам, повезло бы ему чуть больше.
                    // Обычно этой ветки не бывает вовсе: при живом
                    // предпросмотре движок и не спрашивает (см. `known`
                    // в `engine::start`).
                    if self.preview.info.is_none()
                        && self.preview.is_about(self.queue.running_request())
                    {
                        self.preview.info = Some(info);
                        self.preview.state = PreviewState::Ready;
                        meta_dirty = true;
                    }
                }
                Event::Thumbnail(cover) => {
                    // Та же оговорка, что и у `Info`: чужую обложку под полем
                    // ссылки показывать нельзя — ровно от этого превью
                    // и должно спасать.
                    if self.preview.thumbnail.is_none()
                        && self.preview.is_about(self.queue.running_request())
                    {
                        self.preview.set_cover(&cover, ctx);
                    }
                }
                Event::Stage(stage) => {
                    self.stage = stage;
                    progress_dirty = true;
                }
                Event::Progress(p) => {
                    // Чужой прогресс — это прогресс уже снятой загрузки:
                    // её процесс досылает строки и после `kill`. Показать
                    // его на месте текущей значило бы дёрнуть полосу назад.
                    //
                    // Во время установки номера нет вовсе (`NO_DOWNLOAD`),
                    // и разводить там нечего: канал занят ею одной.
                    if self.setup.busy() || self.queue.is_running(p.download_id) {
                        self.progress = p;
                        self.progress_peak = self
                            .progress_peak
                            .max(self.progress.fraction().unwrap_or(0.0));
                        progress_dirty = true;
                    }
                }
                Event::Log(line) => self.push_log(line),
                Event::Done { id, path } => {
                    // Сверка номера обязательна: пока событие шло по каналу,
                    // загрузку могли снять, и «Готово» встало бы рядом
                    // с чужим путём.
                    if self.queue.is_running(id) {
                        self.stage = self.t(Key::StageDone).into();
                        self.done_path_display = path.display().to_string();
                        // Единственное место, где пополняется история: другого
                        // признака «файл готов и лежит вот здесь» у UI нет.
                        // Успех без пути (`Event::Stage("Готово (файл уже
                        // существовал)")`) сюда не попадает — записывать нечего.
                        self.history.remember(&path);
                        self.queue.set_status(id, QueueStatus::Done);
                        self.state = State::Done(path);
                        self.handle = None;
                        advance = true;
                        progress_dirty = true;
                    }
                }
                Event::Failed { id, message } => {
                    // Один и тот же вариант обслуживает три задачи, поэтому
                    // разводим их по режиму и по номеру: во время установки
                    // это сбой установки, а не сорвавшаяся загрузка ролика.
                    if self.setup.busy() {
                        self.finish_setup(Setup::Failed(message), ctx);
                    } else if self.queue.is_running(id) {
                        self.stage = self.t(Key::StageError).into();
                        self.queue
                            .set_status(id, QueueStatus::Failed(message.clone()));
                        self.state = State::Failed(message);
                        self.handle = None;
                        // Одна мёртвая ссылка — не повод бросать девять живых:
                        // очередь идёт дальше. Ради этого её и ставят, уходя.
                        // Причина никуда не денется: она лежит в самой строке
                        // очереди, а не только в журнале, который вот-вот
                        // очистится под следующую загрузку.
                        advance = true;
                        progress_dirty = true;
                    }
                }
                Event::Ready => {
                    self.finish_setup(Setup::Ready, ctx);
                }
                Event::Warning(text) => {
                    self.warning = Some(text);
                }
                Event::Notice(text) => {
                    self.notice = Some(text);
                }
                // Метаданные и версии ходят по своим каналам — сюда эти
                // события попасть не могут. Ветка выписана явно, а не через
                // `_`, чтобы компилятор и дальше требовал разбирать новые
                // варианты `Event` во всех приёмниках.
                Event::Tags(_)
                | Event::Cleaned(_)
                | Event::Versions(_)
                | Event::SystemReport(_)
                | Event::Power(_)
                | Event::Perf(_)
                | Event::WeatherPlace(_)
                | Event::WeatherPlaces(_)
                | Event::Weather(_)
                | Event::Share(_) => {}
            }
        }

        if progress_dirty {
            self.rebuild_progress_line();
        }
        if meta_dirty {
            self.rebuild_meta_line();
            self.rebuild_quality_note();
            // Дорожки субтитров приезжают тем же `Event::Info`: до него
            // список языков пуст, а сказать «вшивать нечего» нечем.
            self.rebuild_subtitles();
        }

        if disconnected {
            self.rx = None;
            // Поток движка кончился, не сказав ни `Done`, ни `Failed`. Так
            // выглядит успех без пути: файл уже лежал на диске, и стадию
            // `after_move` yt-dlp пропустил — по Правилу 2 это НЕ ошибка.
            // Отметить его обязательно: иначе строка навсегда осталась бы
            // «качается», а вся очередь встала бы на ровном месте.
            if let Some(id) = self.queue.running_id() {
                self.queue.set_status(id, QueueStatus::Done);
                advance = true;
            }
            if matches!(self.state, State::Running) {
                self.state = State::Idle;
            }
        }

        // Строго после разбора пачки и после разрыва канала: `start_next`
        // заводит новый `rx`, и сделай мы это раньше — обрыв старого канала
        // обнулил бы только что заведённый.
        if advance {
            self.start_next(ctx);
        }
    }

    /// Ведёт фоновый запрос по ссылке из поля: забирает ответ и, когда
    /// истекло окно дебаунса, заводит следующий.
    ///
    /// Зовётся каждый кадр, но работы в обычном кадре здесь нет: пустой
    /// приёмник и сравнение двух чисел.
    fn tick_preview(&mut self, ctx: &egui::Context) {
        // Ответ разбираем первым: он мог приехать, пока шло окно дебаунса
        // следующего запроса.
        let mut ready = false;
        for event in self.preview.take_events() {
            match event {
                Event::Info(info) => {
                    self.preview.info = Some(info);
                    self.preview.state = PreviewState::Ready;
                    ready = true;
                }
                Event::Thumbnail(cover) => self.preview.set_cover(&cover, ctx),
                // Сюда попадает разве что «обложка не загрузилась»: больше
                // предпросмотр в журнал ничего не пишет, и молчит он даже
                // о собственной неудаче (см. `engine::start_probe`).
                Event::Log(line) => self.push_log(line),
                // Остальное по этому каналу не ходит. Ветка выписана явно,
                // а не через `_`, чтобы компилятор и дальше требовал
                // разбирать новые варианты `Event` во всех приёмниках.
                Event::Stage(_)
                | Event::Progress(_)
                | Event::Done { .. }
                | Event::Failed { .. }
                | Event::Ready
                | Event::Warning(_)
                | Event::Notice(_)
                | Event::Tags(_)
                | Event::Cleaned(_)
                | Event::Versions(_)
                | Event::SystemReport(_)
                | Event::Power(_)
                | Event::Perf(_)
                | Event::WeatherPlace(_)
                | Event::WeatherPlaces(_)
                | Event::Weather(_)
                | Event::Share(_) => {}
            }
        }

        if ready {
            self.rebuild_meta_line();
            self.rebuild_quality_note();
            // Дорожки субтитров приезжают тем же `Event::Info`: до него
            // список языков пуст, а сказать «вшивать нечего» нечем.
            self.rebuild_subtitles();
        }

        let Some(due) = self.preview.due else {
            return;
        };
        let now = ctx.input(|i| i.time);
        if now < due {
            // Кадр к сроку приходится просить: без ввода egui окно не
            // перерисовывает, и запрос ушёл бы не через `PREVIEW_DEBOUNCE`,
            // а при первом движении мыши — то есть, если ссылку вставили
            // и убрали руки, не ушёл бы вовсе.
            ctx.request_repaint_after(std::time::Duration::from_secs_f64(due - now));
            return;
        }

        self.start_preview(ctx);
    }

    /// Спрашивает сайт о ссылке из поля.
    fn start_preview(&mut self, ctx: &egui::Context) {
        let request = Request {
            url: self.preview.url.clone(),
            cookies: self.preview.cookies,
            cookie_file: self.preview.cookie_file.clone(),
            // Остальное `probe` не спрашивает (см. `ytdlp::probe_args`), но
            // запрос — это запрос целиком, и половины его не бывает. Заодно
            // ровно эти поля уедут в загрузку, если нажмут «Скачать».
            format: self.format,
            quality: self.quality,
            options: self.options,
            section: self.section,
            sub_lang: self.sub_lang.clone(),
        };

        let (tx, rx) = channel();
        let notify_ctx = ctx.clone();
        let handle =
            engine::start_probe(request, self.lang, tx, move || notify_ctx.request_repaint());
        self.preview.asked(rx, handle);
    }

    /// Ссылку в поле правили — предпросмотр обязан догнать.
    ///
    /// Зовётся из обработчиков (правка поля, смена браузера в списке), а не
    /// из кадра: сравнивать строки шестьдесят раз в секунду незачем.
    fn retarget_preview(&mut self, ctx: &egui::Context) {
        let now = ctx.input(|i| i.time);
        if !self.preview.retarget(
            self.url.trim(),
            self.cookies,
            self.cookie_file.as_deref(),
            now,
        ) {
            return;
        }

        // Всё, что было собрано из прошлого ответа, теперь про другую ссылку.
        // Молча оставить это на экране — худший исход: «Выше 720p этот ролик
        // не отдают» под чужой ссылкой выглядит фактом о ней.
        self.meta_line.clear();
        self.quality_note.clear();
        self.rebuild_subtitles();
    }

    /// Добавляет строку в журнал, соблюдая его потолок.
    fn push_log(&mut self, line: String) {
        self.log.push(line);
        if self.log.len() > LOG_LIMIT {
            self.log.drain(..self.log.len() - LOG_LIMIT);
        }
    }

    /// Забирает ответ о версиях инструментов, если он подъехал.
    ///
    /// Приёмник бросаем сразу: ответ приходит ровно один, и держать канал
    /// дальше значило бы каждый кадр опрашивать заведомо мёртвую очередь.
    fn drain_versions(&mut self) {
        let Some(rx) = &self.versions_rx else {
            return;
        };

        let received = match rx.try_recv() {
            Ok(Event::Versions(versions)) => Some(versions),
            // Прочие варианты по этому каналу не ходят: отправитель один и
            // шлёт ровно `Versions`. Разбирать их незачем, а `_` вместо
            // явного `Ok(_)` спрятал бы от компилятора смену этого уговора.
            Ok(_) => None,
            Err(TryRecvError::Empty) => return,
            Err(TryRecvError::Disconnected) => None,
        };

        self.versions_rx = None;
        let Some(versions) = received else {
            return;
        };

        // Строку собираем здесь, на приёме события, а не в кадре отрисовки:
        // меняется она дважды за запуск, а `ui()` зовут 60 раз в секунду.
        self.tools_line = format!(
            "{} · {}",
            version_line("yt-dlp", &versions.ytdlp, self.lang),
            version_line("ffmpeg", &versions.ffmpeg, self.lang)
        );
    }
}

/// Сводка свёрнутой группы: что написать в её заголовке и чем это отметить.
///
/// Текст и метка — одно значение, а не два поля `SavioApp` рядом: считаются
/// они из одного и того же, и текст, пересобранный без метки, выглядел бы
/// исправным. Метка — роль, а не `Color32`, по той же причине, что у
/// [`Tone`]: сводка лежит в поле до следующей правки и обязана пережить
/// смену темы.
#[derive(Clone, PartialEq, Eq, Debug, Default)]
struct GroupSummary {
    text: String,
    /// `None` — всё по умолчанию, и текст перечисляет, что лежит внутри.
    /// Иначе заголовок ставит перед текстом точку этого тона и красит им
    /// сам текст.
    mark: Option<Tone>,
}

/// Сводка тонких настроек: перечисление того, что в них включено.
///
/// Свободная и чистая функция, а не кусок метода: сводка — единственное, что
/// говорит о заданном фрагменте, пока группа свёрнута, и промах в ней стоит
/// человеку скачанного куска вместо ролика. Такое покрывается тестом.
///
/// Пишем только про отличия от умолчания. Перечислять «фрагмент не задан ·
/// вход не используется» смысла нет: это состояние у почти всех и почти
/// всегда, и в заголовке оно превратилось бы в шум, за которым перестанут
/// замечать настоящую строку.
///
/// **Включённое отличается от заглушки видом, а не словами** (задача 51
/// реестра). Заглушка говорит, что лежит внутри, и «вход на сайт» стоит
/// в ней теми же словами, что у включённого входа, — иначе его и не назвать.
/// Пока вид был один, заголовок со входом, запомненным неделю назад, взглядом
/// не отличался от заголовка нетронутой группы, а при запуске он —
/// единственный указатель на вход: жёлтая оговорка под списком лежит внутри,
/// группа свёрнута. Поэтому у включённого есть метка — точка и жёлтый цвет
/// той самой оговорки: свёрнутая группа показывает, что оговорка внутри есть.
/// Зелёный, как у включённых галочек «Вшить», сказал бы «всё хорошо», а вход
/// с cookies на YouTube — ровно тот случай, когда не всё.
///
/// `subs` — язык субтитров, если субтитры просят, и `None`, если нет: без
/// `--embed-subs` язык в yt-dlp не уходит вовсе, и «субтитры: de» с горящей
/// точкой объявляли бы включённым то, что на загрузку не влияет.
fn advanced_summary(
    section_broken: bool,
    section_set: bool,
    cookies: bool,
    subs: Option<&SubLang>,
    lang: Lang,
) -> GroupSummary {
    let section = match (section_broken, section_set) {
        (true, _) => Some(i18n::t(lang, Key::UiSummarySectionBad).to_owned()),
        (false, true) => Some(i18n::t(lang, Key::UiSummarySection).to_owned()),
        (false, false) => None,
    };
    let cookies = cookies.then(|| i18n::t(lang, Key::UiSummaryLogin).to_owned());
    // Код языка, а не подпись: подпись бывает длинной («Русский
    // (автоматические)»), а места в заголовке ровно одна строка.
    let subs = match subs {
        Some(SubLang::Code(code)) => Some(i18n::fill(i18n::t(lang, Key::UiSummarySubs), &[code])),
        Some(SubLang::Original) | None => None,
    };

    let parts: Vec<String> = [section, cookies, subs].into_iter().flatten().collect();
    if parts.is_empty() {
        return GroupSummary {
            text: i18n::t(lang, Key::UiSummaryPlaceholder).to_owned(),
            mark: None,
        };
    }
    // Неверный фрагмент — уже не оговорка, а причина: пока он такой,
    // «Скачать» выключена. Отсюда тон ошибки, как у объяснения под полем,
    // и он перекрывает остальное: сначала чинят то, что не даёт начать.
    let tone = if section_broken { Tone::Bad } else { Tone::Warn };
    GroupSummary {
        text: parts.join(" · "),
        mark: Some(tone),
    }
}

/// Строка «инструмент — версия» для строки обслуживания.
///
/// «Не найден» и «версию узнать не вышло» говорят разное, и путать их нельзя:
/// в первом случае программы на машине нет и её надо ставить, во втором она
/// работает, просто печатает версию не так, как мы ожидали (см.
/// `setup::parse_version_line`). Сказать «не найден» про рабочую копию —
/// значит отправить человека решать несуществующую беду.
fn version_line(name: &str, version: &crate::model::ToolVersion, lang: Lang) -> String {
    use crate::model::ToolVersion;
    match version {
        ToolVersion::Known(version) => {
            i18n::fill(i18n::t(lang, Key::UiToolVersion), &[name, version])
        }
        ToolVersion::Unknown => i18n::fill(i18n::t(lang, Key::UiToolVersionUnknown), &[name]),
        ToolVersion::Missing => i18n::fill(i18n::t(lang, Key::UiToolMissing), &[name]),
    }
}

// ---------------------------------------------------------------------------
// Отрисовка
// ---------------------------------------------------------------------------

impl eframe::App for SavioApp {
    /// Фон окна до первой отрисовки, иначе при запуске и ресайзе видна
    /// вспышка чужого цвета. Берётся из выбранной темы: в светлой вспышка
    /// была бы чёрной, то есть заметнее, чем в тёмной.
    fn clear_color(&self, _visuals: &egui::Visuals) -> [f32; 4] {
        self.palette.bg.to_normalized_gamma_f32()
    }

    /// Последнее, что успевает случиться перед закрытием.
    ///
    /// Здесь дописывается отложенная настройка: переключить формат и тут же
    /// закрыть окно — обычное дело, а окно дебаунса к этому моменту ещё не
    /// истекло. Полагаться вместо этого на `Drop` нельзя: eframe сразу после
    /// `on_exit` зовёт `std::process::exit(0)`, и деструкторы не выполняются.
    ///
    /// `App::save` не годится по другой причине: он вызывается только с фичей
    /// `persistence`, а она тянет `ron`, `serde` и `home` ради файла, который
    /// у нас и так пишется своими силами через уже имеющийся `serde_json`.
    ///
    /// Подпись без аргумента — вариант для сборки без `glow`; Savio собирается
    /// на wgpu, то есть на умолчаниях eframe.
    fn on_exit(&mut self) {
        self.saver.flush();

        // Идущую загрузку останавливаем сами. Раньше она переживала закрытие
        // окна: yt-dlp с ffmpeg дописывали файл в опустевшей папке, и человек
        // находил его через несколько минут после того, как Savio закрыл.
        // На Windows это делает и `KILL_ON_JOB_CLOSE` — ручку группы закрывает
        // система, — но полагаться на него одного нельзя: на Unix группа
        // убивается только своими руками, и без этих строк две системы вели
        // бы себя по-разному. Заодно тут же гаснет фоновый запрос
        // предпросмотра: он тоже процесс, и тоже чужой.
        if let Some(handle) = &self.handle {
            handle.cancel();
        }
        self.preview.stop();
        // Раздачу тоже, и с ожиданием: сокеты закроет и смерть процесса, но
        // недопринятый файл удаляет только поток приёма, увидевший остановку,
        // а `process::exit` сразу за нами ему этого не дал бы. Ждём не дольше
        // секунды и только пока что-то передаётся — в покое выход мгновенный.
        if let Some(handle) = &self.share.handle {
            handle.stop_and_wait(std::time::Duration::from_secs(1));
        }
        self.share.stop(None, self.lang);
    }

    fn ui(&mut self, ui: &mut egui::Ui, _frame: &mut eframe::Frame) {
        self.drain_events(ui.ctx());
        self.tick_preview(ui.ctx());
        self.meta.drain(self.lang, ui.ctx());
        self.system.drain();
        self.monitor.drain(ui.ctx());
        self.power.drain(self.lang);
        // Место могло смениться ответом движка (определилось по IP) — тогда
        // его надо запомнить здесь же, иначе при следующем запуске IP-адрес
        // снова ушёл бы геолокатору.
        if self.weather.drain(self.lang) {
            self.remember();
        }
        self.weather.drain_search(self.lang);
        self.share.drain(self.lang, ui.ctx());
        self.drain_versions();
        self.drain_gpu_errors();

        // Опрос железа стоит кадра в секунду — и стоит его, только пока есть
        // кому смотреть. Решение принимается здесь, а не во вкладке: вкладка
        // при закрытом мониторе не рисуется вовсе, и остановить опрос из неё
        // было бы некому.
        let now_open = self.tab == Tab::Machine && self.machine_tab == MachineTab::Now;
        let watched = now_open || self.monitor.overlay;
        self.monitor.set_running(watched, self.lang, ui.ctx());
        // Питание перечитывается по открытию половины, а не по кадру: оно
        // меняется раз в день, но меняют его и мимо Savio. Место здесь, а не
        // во вкладке, по той же причине, что и у опроса: закрытая половина
        // не рисуется, и заметить её закрытие из неё самой некому.
        self.power.watch(now_open, self.lang, ui.ctx());
        // Погода — по той же причине здесь: срок обновления надо сверять и
        // тогда, когда вкладка ещё не рисовалась, а закрытая вкладка не
        // должна просить ни кадра.
        self.weather
            .watch(self.tab == Tab::Weather, self.lang, ui.ctx());
        // Раздача — по той же причине и строже: ушли с экрана — папка больше
        // не открыта для сети.
        self.share
            .watch(self.tab == Tab::Phone, self.lang, ui.ctx());

        if self.maximize_pending {
            self.maximize_pending = false;
            ui.ctx()
                .send_viewport_cmd(egui::ViewportCommand::Maximized(true));
        }

        self.arrive = self.tab_arrival(ui.ctx());
        self.sweep = motion::elapsed(
            ui.ctx(),
            self.tab_changed_at,
            motion::GLOSS * self.speed,
        );
        self.sweep_queue(ui.ctx());

        // Палитра берётся один раз на кадр и дальше ездит вниз параметром.
        // Копия, а не ссылка: `Palette` — `Copy` в полторы сотни байт, зато
        // методы ниже берут `&mut self`, и с заимствованием поля не ужились бы.
        let pal = self.palette;

        // Фон кладём первым и прямо в корневой `Ui`, до всех панелей: egui
        // рисует фигуры в порядке добавления, и всё, что появится дальше,
        // ляжет поверх. Заливки панелей одной этой заливки не заменяют —
        // между панелями остаются щели, в которых иначе просвечивал бы цвет
        // «до первого кадра».
        theme::paint_background(ui.painter(), pal, ui.max_rect());

        // Рельс — панель, а не первая колонка прокрутки: он обязан стоять
        // на месте, пока содержимое едет. У панели это даром, а в прокрутке
        // пришлось бы отмерять ширину руками.
        //
        // Свёрнут или развёрнут — решает прежде всего ширина окна, и порог
        // считается от того, что нужно содержимому (`theme::NAV_WIDE_MIN`):
        // разворот отнимает у него 160 точек, и разворачиваться раньше, чем
        // это можно себе позволить, значит ронять его в одну колонку ровно
        // на том, что окно стало шире. Высота решает остальное — см.
        // `RailLayout`.
        let window = ui.max_rect().size();
        let layout = RailLayout::for_window(window);
        let rail = egui::Panel::left("savio-rail")
            .resizable(false)
            .show_separator_line(false)
            .exact_size(layout.width())
            .frame(theme::rail_frame(pal))
            .show(ui, |ui| self.rail(ui, layout));
        theme::paint_rail_edge(ui.painter(), pal, rail.response.rect);

        // Журнал — панель внизу и только когда он открыт. Панелью, а не
        // последней строкой прокрутки, по той же причине, что и прежний
        // подвал: прокрутка внутри растущей панели схлопывается, и тело
        // журнала застревало вдвое ниже заказанного (дефект 27). Высота
        // тела — от окна: в низком окне уступает журнал, а не вкладка.
        if self.log_open && !self.log.is_empty() {
            log_panel(
                ui,
                pal,
                self.lang,
                self.speed,
                &self.log,
                &mut self.log_copied_at,
                log_height(window.y),
            );
        }

        egui::CentralPanel::default()
            .frame(content_frame())
            .show(ui, |ui| {
                self.section_title(ui);
                ui.add_space(SECTION_TITLE_GAP);
                // Прокрутка нужна на минимальном размере окна: без неё
                // кнопка «Скачать» просто обрезалась бы нижней кромкой.
                let mut scroll = egui::ScrollArea::vertical().auto_shrink([false, false]);
                if std::mem::take(&mut self.scroll_to_top) {
                    scroll = scroll.vertical_scroll_offset(0.0);
                }
                scroll.show(ui, |ui| match self.tab {
                        Tab::Download => self.download_tab(ui),
                        Tab::Metadata => self.metadata_tab(ui),
                        Tab::Machine => self.machine_tab(ui),
                        Tab::Weather => self.weather_tab(ui),
                        Tab::Phone => self.phone_tab(ui),
                    });
            });

        // Оверлей — отдельное окно, и просить его надо на каждом проходе,
        // иначе egui его закроет. Место здесь, а не во вкладке: оверлей живёт
        // и при закрытой вкладке — ради этого он и нужен.
        self.monitor.show_overlay(pal, self.lang, ui.ctx());

        // Модалки рисуются последними, поверх всего остального.
        let ctx = ui.ctx().clone();
        // Про приход спрашиваем **у всех сразу**, включая закрытые, и по
        // той же причине, что у разделов: `animate_bool_with_time`, впервые
        // увидев идентификатор, отдаёт конечное значение — окно, о котором
        // не спрашивали, пока его не было, возникло бы уже целиком.
        let install = self.modal_arrival(&ctx, "setup", self.setup.busy());
        let confirm = self.modal_arrival(&ctx, "confirm", self.meta.confirming);
        let about = self.modal_arrival(&ctx, "about", self.about_open);
        let welcome = self.modal_arrival(&ctx, "welcome", self.welcome_open);

        if self.setup.busy() {
            self.install_modal(&ctx, install);
        }
        if self.meta.confirming {
            self.confirm_modal(&ctx, confirm);
        }
        if self.about_open {
            self.about_modal(&ctx, about);
        }
        // Приветствие рисуется последним: при самом первом запуске поверх
        // него не должно оказаться ничего, кроме окна установки, — а то
        // рисуется раньше и потому ляжет ниже.
        if self.welcome_open {
            self.welcome_modal(&ctx, welcome);
        }
    }
}

impl SavioApp {
    /// Насколько содержимое показанного раздела уже приехало (приём 04).
    ///
    /// Коэффициент спрашивается **у всех** разделов, включая живущие в меню
    /// «Ещё», а не у одного показанного, и это не расточительство.
    /// `animate_bool_with_time`, увидев незнакомый идентификатор, отдаёт сразу
    /// конечное значение — то есть раздел, о котором не спрашивали, пока на
    /// нём стояли, вернулся бы уже приехавшим, и приём просто не сработал бы.
    /// Четыре сравнения в кадре — цена того, что уходящий раздел успевает
    /// погаснуть.
    fn tab_arrival(&self, ctx: &egui::Context) -> f32 {
        let mut arrive = 1.0;
        for (index, tab) in ALL_TABS.into_iter().enumerate() {
            let here = tab == self.tab;
            let t = ctx.animate_bool_with_time(
                egui::Id::new("tab-arrive").with(index),
                here,
                motion::LAYER * self.speed,
            );
            if here {
                arrive = t;
            }
        }
        arrive
    }

    /// Насколько модальное окно уже пришло (приём 11).
    ///
    /// Порядок здесь — половина приёма: сначала гаснет окно под ним, потом
    /// приезжает само окно. Так видно, что это слой поверх Savio, а не другое
    /// приложение.
    fn modal_arrival(&self, ctx: &egui::Context, name: &'static str, open: bool) -> ModalArrival {
        let id = egui::Id::new("modal").with(name);
        ModalArrival {
            veil: ctx.animate_bool_with_time(id.with("veil"), open, MODAL_VEIL * self.speed),
            rise: motion::glide(ctx.animate_bool_with_time(
                id.with("rise"),
                open,
                motion::LAYER * self.speed,
            )),
        }
    }

    /// Убирает строки очереди, у которых складывание доиграло (приём 10).
    ///
    /// Отложенное удаление, а не мгновенное, нужно ровно затем, чтобы строку
    /// было чем рисовать, пока она складывается. Ждущей она к этому моменту
    /// уже не считается нигде — ни в сводке, ни в `next_waiting`, — так что
    /// задержка не может ни запустить убранное, ни соврать в цифрах.
    ///
    /// Быстрый выход первой строкой не для красоты: помеченных строк почти
    /// всегда нет, а зовут это на каждом кадре.
    fn sweep_queue(&mut self, ctx: &egui::Context) {
        if !self
            .queue
            .items
            .iter()
            .any(|item| item.removing_since.is_some())
        {
            return;
        }

        let now = ctx.input(|i| i.time);
        let hold = f64::from(motion::MOVE * QUEUE_LEAVE * self.speed);

        // Убираем через `Queue::remove`, а не своим `retain`, ради его
        // страховки: идущую загрузку он не трогает, и держать это правило
        // в двух местах — верный способ однажды его разъехать.
        while let Some(id) = self
            .queue
            .items
            .iter()
            .find(|item| item.removing_since.is_some_and(|at| now - at >= hold))
            .map(|item| item.id)
        {
            self.queue.remove(id);
        }
    }

    /// Как выглядит на этом кадре элемент, появившийся по своему поводу:
    /// баннер, подпись «Скопировано», карточка истории (приём 05).
    ///
    /// Отдельно от [`SavioApp::appear`], потому что повод другой: там весь
    /// раздел приезжает разом и по номеру карточки, здесь — один элемент,
    /// у которого своё «показан или нет».
    fn appearing(
        ctx: &egui::Context,
        id: egui::Id,
        shown: bool,
        speed: f32,
    ) -> Option<theme::Appear> {
        let t = ctx.animate_bool_with_time(id, shown, motion::LAYER * speed);
        if t >= 1.0 {
            return None;
        }
        let t = motion::stagger(t, 0);
        Some(theme::Appear {
            offset: motion::RISE * (1.0 - t),
            opacity: t,
            // Блика у баннера нет: он не карточка стекла, а сообщение,
            // и светлая точка по его кромке читалась бы как ещё один
            // повод на него смотреть.
            sweep: 1.0,
        })
    }

    /// Как выглядит на этом кадре карточка номер `step` показанного раздела.
    ///
    /// `None` — карточка уже на месте: тогда `theme::card_rising` рисует ровно
    /// то же, что рисовал `theme::card` до всех приёмов, и не стоит ничего.
    fn appear(&self, step: u32) -> Option<theme::Appear> {
        // Блик живёт дольше прихода, поэтому проверяются оба: вернуть `None`
        // по одному только `arrive` значило бы гасить блик на трети пути.
        if self.arrive >= 1.0 && self.sweep >= 1.0 {
            return None;
        }
        let t = motion::stagger(self.arrive, step);
        Some(theme::Appear {
            offset: motion::RISE * (1.0 - t),
            opacity: t,
            sweep: self.sweep,
        })
    }

    /// Переходит в другой раздел — из рельса или по указателю внутри раздела.
    fn switch_tab(&mut self, tab: Tab, ctx: &egui::Context) {
        if tab != self.tab {
            self.tab = tab;
            // Момент смены нужен блику: ему отпущено больше времени,
            // чем самому приходу, и `animate_*` ему не подходит.
            self.tab_changed_at = ctx.input(|i| i.time);
            self.scroll_to_top = true;
        }
    }

    /// Открывает раздел рельса, у «Машины» — и нужную её половину.
    ///
    /// Общее у рельса и приветствия: карточка приветствия открывает ровно
    /// то, что пункт рельса с тем же названием, и разойтись им нельзя.
    fn open_section(&mut self, tab: Tab, half: Option<MachineTab>, ctx: &egui::Context) {
        if let Some(half) = half {
            self.machine_tab = half;
        }
        self.switch_tab(tab, ctx);
    }

    /// Рельс разделов слева.
    ///
    /// Собирает состояние, отдаёт его [`rail_body`] и применяет то, что
    /// человек нажал. Всё применяется **после** отрисовки, а не по месту:
    /// смена языка пересобирает десяток заранее собранных строк, а `self`
    /// на время кадра занят рисованием.
    fn rail(&mut self, ui: &mut egui::Ui, layout: RailLayout) {
        let state = RailState {
            pal: self.palette,
            speed: self.speed,
            lang: self.lang,
            tab: self.tab,
            half: self.machine_tab,
            appearance: self.appearance,
            groups: &self.nav_groups,
            tools: &self.tools_line,
            smooth: self.smooth,
            has_log: !self.log.is_empty(),
            log_open: self.log_open,
            // Пока занят единственный канал событий — обновляться нечем:
            // и загрузка, и установка ходят через тот же `rx`.
            busy: matches!(self.state, State::Running) || self.setup.busy(),
            more_open: self.more_open,
        };
        let picks = rail_body(ui, &state, layout);

        self.more_open = picks.more_open;
        if let Some((tab, half)) = picks.section {
            self.open_section(tab, half, ui.ctx());
        }
        if picks.about {
            self.about_open = true;
        }
        if let Some(lang) = picks.lang {
            self.set_lang(lang, ui.ctx());
        }
        if let Some(appearance) = picks.appearance {
            self.set_appearance(appearance, ui.ctx());
        }
        if picks.toggle_log {
            self.log_open = !self.log_open;
        }
        if picks.welcome {
            self.welcome_open = true;
        }
        if let Some(smooth) = picks.smooth {
            self.smooth = smooth;
            self.speed = motion::scale(smooth);
            self.remember();
        }
        if let Some(what) = picks.update {
            let ctx = ui.ctx().clone();
            self.start_update(what, &ctx);
        }
    }

    /// Приветствие: что это за программа и все её разделы.
    ///
    /// Закрывается кнопкой «Начать», щелчком по карточке раздела, щелчком
    /// мимо окна и клавишей Esc — любой из способов считается «показали».
    /// Запирать человека в окне нельзя, а объяснение, которое нельзя
    /// закрыть, из объяснения превращается в препятствие.
    fn welcome_modal(&mut self, ctx: &egui::Context, arrival: ModalArrival) {
        arrival.veil(self.palette, ctx, "welcome");
        let window = welcome_window(self.palette, ctx, self.lang, &self.nav_groups, self.speed);
        arrival.apply(ctx, &window.response);

        let action = window.inner;
        if action.is_some() || window.should_close() {
            self.welcome_open = false;
            // Метку ставим здесь, а не при запуске: закрыл — значит, видел.
            binaries::mark_welcome_seen(WELCOME_EDITION);
        }
        // Приветствие работает оглавлением: щелчок по разделу его и
        // открывает, а не отсылает искать тот же раздел в рельсе.
        if let Some(WelcomeAction::Open(tab, half)) = action {
            self.open_section(tab, half, ctx);
        }
    }

    /// Строка заголовка раздела над содержимым.
    ///
    /// Название крупным дисплейным начертанием, рядом короткое пояснение,
    /// справа — номер версии. Пояснение отвечает на «что я тут увижу» до
    /// того, как человек начнёт читать карточки, и меняется вместе с
    /// состоянием раздела: у загрузки и у раздачи их по два.
    fn section_title(&mut self, ui: &mut egui::Ui) {
        let pal = self.palette;
        let lang = self.lang;
        let speed = self.speed;
        let (title, note) = match self.tab {
            Tab::Download => (
                i18n::t(lang, Key::TabDownload),
                if matches!(self.state, State::Running) {
                    Key::NavDownloadBusyNote
                } else {
                    Key::NavDownloadNote
                },
            ),
            Tab::Metadata => (i18n::t(lang, Key::TabMetadata), Key::NavMetadataNote),
            Tab::Machine => match self.machine_tab {
                MachineTab::Now => (i18n::t(lang, Key::MachineNow), Key::NavMachineNowNote),
                MachineTab::Spec => (i18n::t(lang, Key::MachineSpec), Key::NavMachineSpecNote),
            },
            Tab::Weather => (i18n::t(lang, Key::TabWeather), Key::NavWeatherNote),
            Tab::Phone => (
                i18n::t(lang, Key::TabPhone),
                if self.share.running() {
                    Key::NavPhoneOnNote
                } else {
                    Key::NavPhoneNote
                },
            ),
        };

        let row = section_title_row(ui, pal, lang, speed, title, note);
        let about = row.about;
        if about {
            self.about_open = true;
        }
    }

    /// Вкладка загрузки: главная карточка слева, ход работы справа.
    ///
    /// Две колонки, а не одна длинная страница: очередь и история — это то,
    /// на что смотрят **во время** загрузки, и ради них прежде приходилось
    /// прокручивать экран мимо всей карточки настроек. Ниже
    /// [`theme::TWO_COLUMN_MIN`] колонки не помещаются рядом, и правая
    /// уходит под главную — иначе в окне 520 переключатель качества из
    /// шести ступеней вылез бы за кромку.
    fn download_tab(&mut self, ui: &mut egui::Ui) {
        // Баннеры идут над обеими колонками: они про экран целиком, а не
        // про настройки, и в узкой колонке их объяснения читались бы
        // по три слова в строке.
        self.download_banners(ui);

        const GAP: f32 = 18.0;
        if ui.available_width() < theme::TWO_COLUMN_MIN {
            self.download_main(ui);
            ui.add_space(GAP);
            self.download_rail(ui);
            return;
        }

        let total = ui.available_width();
        let rail = theme::RAIL_WIDTH;
        let main = total - rail - GAP;

        ui.horizontal_top(|ui| {
            ui.spacing_mut().item_spacing.x = GAP;
            for (width, which) in [(main, true), (rail, false)] {
                ui.allocate_ui_with_layout(
                    egui::vec2(width, 0.0),
                    egui::Layout::top_down(egui::Align::Min),
                    |ui| {
                        // Ширину задаём с обеих сторон: `allocate_ui_with_layout`
                        // двигает курсор не на запрошенный размер, а на тот,
                        // что занял потомок, — без нижней границы короткая
                        // колонка съехала бы к соседке, без верхней длинная
                        // подпись растянула бы её за кромку.
                        ui.set_min_width(width);
                        ui.set_max_width(width);
                        if which {
                            self.download_main(ui);
                        } else {
                            self.download_rail(ui);
                        }
                    },
                );
            }
        });
    }

    /// Сообщения, которые относятся ко всему экрану загрузки.
    fn download_banners(&mut self, ui: &mut egui::Ui) {
        let pal = self.palette;
        // Причина неудавшейся установки идёт первой: она объясняет, почему
        // инструмента нет, а баннер ниже — что с этим делать.
        let messages = [
            match &self.setup {
                Setup::Failed(err) => Some((err.as_str(), pal.state_warning)),
                _ => None,
            },
            self.warning
                .as_deref()
                .map(|text| (text, pal.state_warning)),
            self.notice
                .as_deref()
                .map(|text| (text, pal.state_success)),
            self.setup_error
                .as_deref()
                .map(|text| (text, pal.state_error)),
        ];

        // Про появление спрашиваем **у каждого места сразу**, включая пустые,
        // и по той же причине, что у разделов: `animate_bool_with_time`,
        // впервые увидев идентификатор, отдаёт конечное значение — баннер,
        // о котором не спрашивали, пока его не было, возник бы уже целиком.
        for (index, message) in messages.into_iter().enumerate() {
            let appear = Self::appearing(
                ui.ctx(),
                egui::Id::new("banner").with(index),
                message.is_some(),
                self.speed,
            );
            let Some((text, color)) = message else {
                continue;
            };
            theme::rising(ui, appear, |ui| banner(ui, pal, text, color));
            ui.add_space(12.0);
        }
    }

    /// Главная колонка: всё, что нужно решить до нажатия «Скачать».
    fn download_main(&mut self, ui: &mut egui::Ui) {
        let pal = self.palette;
        let lang = self.lang;
        // Ответ о ролике уже пришёл — говорим об этом плашкой у заголовка
        // шага, а не только карточкой под полем: до неё ещё надо опустить
        // взгляд, а «нашлось или нет» — первое, что хотят знать.
        let found = matches!(self.preview.state, PreviewState::Ready);

        theme::card_rising(ui, pal, self.appear(0), |ui| {
            step_header(ui, pal, 1, i18n::t(lang, Key::UiStepLink), None, |ui| {
                if found {
                    status_pill(ui, pal, i18n::t(lang, Key::UiFoundVideo), pal.state_success);
                }
            });
            ui.add_space(8.0);
            self.url_field(ui);
            // Список сайтов стоит постоянно, а не всплывает подсказкой:
            // «а мой сайт поддерживается?» спрашивают до того, как вставят
            // ссылку, то есть до того, как появится к чему навести курсор.
            ui.add_space(6.0);
            note(ui, i18n::t(lang, Key::UiLinkSourcesNote), pal.text_muted);
            // Превью идёт сразу под полем, а не в карточке хода работы
            // справа: оно про то, что собираются скачать, а не про то, что
            // качается. К моменту, когда очередь дойдёт до третьей ссылки,
            // в поле давно лежит пятая, и одна карточка на двоих врала бы
            // про обеих.
            self.preview_row(ui);

            ui.add_space(18.0);
            step_header(
                ui,
                pal,
                2,
                i18n::t(lang, Key::UiStepWhat),
                Some(i18n::t(lang, Key::UiStepWhatDefault)),
                |_| {},
            );
            ui.add_space(8.0);
            labelled_row(ui, pal, self.t(Key::UiFormat), |ui| self.format_selector(ui));

            ui.add_space(12.0);
            // Подпись зависит от формата: у видео ступени — это высота
            // кадра, у звука — килобиты в секунду. Берём её у домена, а не
            // пишем здесь второй раз: две копии одной подписи разъезжаются.
            let quality_label = self.format.quality_label(self.lang);
            labelled_row(ui, pal, quality_label, |ui| self.quality_selector(ui));
            // Что делает «Макс.», из самой дорожки не следует, а ступень
            // ниже выбирают не от хорошей жизни — про обе причины сказано
            // здесь. Когда сайт отдаёт меньше запрошенного, на это место
            // встаёт уже собранная оговорка: два объяснения подряд человек
            // читать не станет, а второе важнее.
            ui.add_space(4.0);
            labelled_row(ui, pal, "", |ui| {
                let (text, color) = if self.quality_note.is_empty() {
                    (i18n::t(lang, Key::UiQualityMaxNote), pal.text_muted)
                } else {
                    (self.quality_note.as_str(), pal.state_warning)
                };
                note(ui, text, color);
            });

            ui.add_space(12.0);
            labelled_row(ui, pal, self.t(Key::UiEmbed), |ui| self.embed_options(ui));
            ui.add_space(4.0);
            labelled_row(ui, pal, "", |ui| {
                note(ui, i18n::t(lang, Key::UiEmbedNote), pal.text_muted);
            });

            ui.add_space(14.0);
            self.advanced_group(ui);

            ui.add_space(18.0);
            step_header(ui, pal, 3, i18n::t(lang, Key::UiStepWhere), None, |_| {});
            ui.add_space(8.0);
            self.folder_row(ui);
            ui.add_space(12.0);
            self.action_button(ui);
        });
    }

    /// Правая колонка: что происходит и что стоит следом.
    fn download_rail(&mut self, ui: &mut egui::Ui) {
        self.status_section(ui);
        ui.add_space(14.0);
        self.rail_list(ui);
    }

    /// Вкладка «Машина»: две половины одной темы.
    ///
    /// «Сейчас» и «Состав» — это прежние «Монитор» и «Система». Вместе,
    /// потому что речь об одной и той же машине: одно про то, чем она занята
    /// сию секунду, другое — из чего она собрана. Порознь они занимали две
    /// из пяти вкладок и вытесняли в прокрутку всё остальное.
    fn machine_tab(&mut self, ui: &mut egui::Ui) {
        // «Машина» приезжает одним слоем, без раскладки по карточкам, и это
        // не небрежность. Задержка съедает начало общего хода (`STAGGER`),
        // так что дальше седьмой карточки очередь просто не доходит — хвост
        // остался бы недоехавшим навсегда. На половине «Сейчас» карточек
        // около десятка, и очередь тут не годится по устройству, а не по
        // вкусу; в «Загрузке» и «Метаданных» их две-три, там она к месту.
        let appear = self.appear(0);
        theme::rising(ui, appear, |ui| self.machine_body(ui));
    }

    /// Содержимое «Машины» без оболочки появления.
    fn machine_body(&mut self, ui: &mut egui::Ui) {
        // Своей дорожки «Сейчас | Состав» здесь больше нет: обе половины —
        // отдельные пункты рельса, и вторая дорожка над содержимым выбирала
        // бы то же самое во второй раз. Две навигации к одному месту — это
        // вопрос «а чем они отличаются», на который честный ответ «ничем».
        // Плашка «Опрос идёт» ушла вместе с дорожкой: о том же говорит
        // пояснение в строке заголовка раздела и первая карточка ниже.
        match self.machine_tab {
            MachineTab::Now => self.monitor_tab(ui),
            MachineTab::Spec => self.system_tab(ui),
        }
    }
}

impl SavioApp {
    /// Модальное окно установки.
    ///
    /// Закрыться само не может и не должно: `ModalResponse::should_close()`
    /// намеренно не вызывается — это не только предикат «щёлкнули мимо или
    /// нажали Esc», он ещё и поглощает Esc. Пока установка идёт, единственный
    /// выход — кнопка «Отменить», иначе оборвавшаяся загрузка заперла бы
    /// пользователя в окне без выхода.
    fn install_modal(&mut self, ctx: &egui::Context, arrival: ModalArrival) {
        let pal = self.palette;
        let speed = self.speed;
        arrival.veil(pal, ctx, "setup");
        // Строки статические и выбираются по режиму — в кадре ничего
        // не собирается и не выделяется.
        let (title, subtitle) = match self.setup {
            Setup::Updating(setup::Component::Ytdlp) => (
                self.t(Key::UiUpdatingEngineTitle),
                self.t(Key::UiUpdatingEngineText),
            ),
            // Про объём говорим прямо: ffmpeg весит больше сотни мегабайт, и
            // молчаливое ожидание на медленном канале выглядит зависанием.
            Setup::Updating(setup::Component::Ffmpeg) => (
                self.t(Key::UiUpdatingFfmpegTitle),
                self.t(Key::UiUpdatingFfmpegText),
            ),
            _ => (
                self.t(Key::UiInstallingTitle),
                self.t(Key::UiInstallingText),
            ),
        };

        let modal = egui::Modal::new(egui::Id::new("savio-setup"))
            .backdrop_color(egui::Color32::TRANSPARENT)
            .frame(
                egui::Frame::new()
                    .fill(pal.modal_fill)
                    .stroke(egui::Stroke::new(1.0, pal.border_subtle))
                    .corner_radius(egui::CornerRadius::same(theme::RADIUS_CARD))
                    .inner_margin(egui::Margin::same(24)),
            )
            .show(ctx, |ui| {
                // Ширину задаём явно: иначе окно скачет по кадрам вслед за
                // длиной строки прогресса. 400 подобрано так, чтобы строка
                // «стадия · проценты · объём · скорость» помещалась целиком.
                ui.set_width(400.0);

                ui.label(
                    egui::RichText::new(title)
                        .heading()
                        .strong()
                        .color(pal.text_primary),
                );
                ui.add_space(6.0);
                ui.label(egui::RichText::new(subtitle).color(pal.text_secondary));

                ui.add_space(16.0);

                ui.scope(|ui| {
                    ui.visuals_mut().extreme_bg_color = pal.progress_track;
                    // Скругление бару не задаём: вместе с `animate` оно
                    // отключает отрисовку бегущей полосы, а она здесь —
                    // единственный признак, что установка не зависла.
                    let bar = match self.progress.fraction() {
                        Some(f) => egui::ProgressBar::new(f),
                        None => egui::ProgressBar::new(0.0).animate(true),
                    };
                    ui.add(bar.fill(pal.accent).desired_height(8.0));
                });

                if !self.progress_line.is_empty() {
                    ui.add_space(8.0);
                    ui.add(
                        egui::Label::new(
                            egui::RichText::new(&self.progress_line)
                                .small()
                                .color(pal.text_secondary),
                        )
                        .truncate(),
                    );
                }

                ui.add_space(18.0);
                pill_button(ui, self.t(Key::UiCancelButton), speed).clicked()
            });
        arrival.apply(ctx, &modal.response);
        let cancelled = modal.inner;

        if cancelled {
            self.cancel_setup(ctx);
        }
    }

    fn url_field(&mut self, ui: &mut egui::Ui) {
        let pal = self.palette;
        let invalid = self.url_invalid;
        let lang = self.lang;

        let response = ui
            .scope(|ui| {
                if invalid {
                    mark_invalid(pal, ui);
                }

                // Поле выше остальных и без подписи над ним: это первое, к
                // чему тянется рука на экране, и подсказка внутри говорит
                // ровно то же, что сказала бы подпись.
                ui.add_sized(
                    [ui.available_width(), theme::FIELD_HEIGHT],
                    egui::TextEdit::singleline(&mut self.url)
                        .hint_text(i18n::t(lang, Key::UiUrlHint))
                        .text_color(pal.text_primary)
                        // Поля широкие: у «таблетки» текст обязан отступать
                        // от полукруглых торцов, иначе он в них упирается.
                        .margin(egui::Margin::symmetric(18, 8)),
                )
            })
            .inner;

        // Пересчитываем только при правке текста, а не каждый кадр.
        if response.changed() {
            let url = self.url.trim();
            self.url_invalid = !url.is_empty() && !looks_like_url(url);
            self.retarget_preview(ui.ctx());
        }

        if invalid {
            ui.add_space(6.0);
            ui.label(
                egui::RichText::new(i18n::t(lang, Key::UiNotALink))
                    .small()
                    .color(pal.state_warning),
            );
        }
    }

    /// Что за ролик лежит по ссылке из поля.
    ///
    /// Всё готово заранее: название и обложка приехали событием, строка
    /// «автор · длительность» собрана в `rebuild_meta_line`. В кадре здесь
    /// не считается и не выделяется ничего.
    fn preview_row(&mut self, ui: &mut egui::Ui) {
        let pal = self.palette;
        match self.preview.state {
            PreviewState::Idle => return,
            // Про ожидание говорим словами: пустое место под ссылкой человек
            // читает как «Savio ничего про неё не понял», а не как «идёт
            // запрос», и ждать перестаёт.
            PreviewState::Asking => {
                ui.add_space(8.0);
                note(ui, self.t(Key::UiPreviewAsking), pal.text_muted);
                return;
            }
            // Не ошибка и баннера не заслуживает: сведения — украшение,
            // и «Скачать» после этого работает как ни в чём не бывало.
            PreviewState::Failed => {
                ui.add_space(8.0);
                note(ui, self.t(Key::UiPreviewFailed), pal.text_muted);
                return;
            }
            PreviewState::Ready => {}
        }

        ui.add_space(10.0);
        ui.horizontal(|ui| {
            if let Some(cover) = &self.preview.thumbnail {
                ui.add(
                    egui::Image::new(cover)
                        // `max_size`, а не `max_width`: у вертикальных роликов
                        // ограничивать надо высоту (см. `PREVIEW_MAX_HEIGHT`),
                        // а пропорцию egui сохраняет сам.
                        .max_size(egui::vec2(PREVIEW_WIDTH, PREVIEW_MAX_HEIGHT))
                        .corner_radius(egui::CornerRadius::same(theme::RADIUS_INNER)),
                );
                ui.add_space(6.0);
            }

            // Текст кладём в свою вертикальную раскладку: в горизонтальной
            // egui берёт для подписей режим `Extend` и вытягивает строку любой
            // длины за кромку окна, а `truncate()` там ограничивать нечем.
            ui.vertical(|ui| {
                if let Some(title) = self
                    .preview
                    .info
                    .as_ref()
                    .and_then(|info| info.title.as_deref())
                {
                    // Своей подсказки нет намеренно: у обрезанной метки egui
                    // вешает её сам, и вторая встала бы под первой (Правило 4).
                    ui.add(
                        egui::Label::new(
                            egui::RichText::new(title)
                                // Полужирным настоящим, а не `strong()`: у egui
                                // нет оси насыщенности, и `strong()` меняет
                                // только цвет. Начертание живёт отдельным
                                // семейством — см. `theme::bold`.
                                .font(theme::bold(15.0))
                                .color(pal.text_primary),
                        )
                        .truncate(),
                    );
                }
                if !self.meta_line.is_empty() {
                    ui.add(
                        egui::Label::new(
                            egui::RichText::new(&self.meta_line)
                                .small()
                                .color(pal.text_secondary),
                        )
                        .truncate(),
                    );
                }
            });
        });
    }

    fn format_selector(&mut self, ui: &mut egui::Ui) {
        let pal = self.palette;
        let items = [
            (Format::Mp4, Format::Mp4.label(self.lang)),
            (Format::Mp3, Format::Mp3.label(self.lang)),
        ];
        let picked = segment_track(
            ui,
            pal,
            egui::Id::new("track:format"),
            self.speed,
            self.format,
            &items,
            true,
        );

        if let Some(format) = picked {
            self.format = format;
            // Подписи сегментов качества и оговорки под ними зависят от
            // формата — пересобрать их надо здесь, а не в кадре отрисовки.
            // Субтитры в том же списке: в MP3 их класть некуда, и оговорка
            // про них при переключении на звук обязана исчезнуть — а с ней
            // и их язык из заголовка тонких настроек.
            self.rebuild_quality_note();
            self.rebuild_subtitles();
            self.rebuild_advanced_summary();
            self.remember();
        }
    }

    /// Переключатель качества: шесть ступеней в одной дорожке.
    ///
    /// Ширину сегмента считаем на каждом шаге заново, а не делим доступную
    /// один раз: шесть округлений до пиксельной сетки накопили бы ошибку,
    /// и дорожка либо не дотянулась бы до правого края, либо вылезла за него.
    /// Так каждому достаётся честная доля остатка, а последнему — ровно то,
    /// что осталось.
    fn quality_selector(&mut self, ui: &mut egui::Ui) {
        let pal = self.palette;
        let format = self.format;
        let lang = self.lang;
        // Массив на стеке, а не сборка списка: шесть пар «ступень + подпись»
        // ничего не выделяют, а подписи у `Quality` статические.
        let items = Quality::ALL.map(|quality| (quality, quality.label(format, lang)));

        let picked = segment_track(
            ui,
            pal,
            egui::Id::new("track:quality"),
            self.speed,
            self.quality,
            &items,
            true,
        );

        if let Some(quality) = picked {
            self.quality = quality;
            self.rebuild_quality_note();
            self.remember();
        }

        if !self.quality_note.is_empty() {
            ui.add_space(6.0);
            note(ui, &self.quality_note, pal.text_secondary);
        }
    }

    /// Два поля «с» и «до»: какой кусок ролика нужен.
    ///
    /// Разбирает набранное домен (`parse_section`), и только по правке текста:
    /// в кадре отрисовки здесь не считается ничего, включая сообщение об
    /// ошибке — оно статическое и лежит в `SectionError`.
    fn section_row(&mut self, ui: &mut egui::Ui) {
        let pal = self.palette;
        let error = self.section_error;
        let mut changed = false;
        let lang = self.lang;

        ui.horizontal(|ui| {
            // Ширину делим между двумя полями и тире между ними, а второму
            // отдаём весь остаток, а не такую же половину: два округления до
            // пиксельной сетки не дотянули бы ряд до правого края — та же
            // причина, что и в `quality_selector`.
            const DASH: f32 = 12.0;
            let spacing = ui.spacing().item_spacing.x;
            let width = ((ui.available_width() - DASH - spacing * 2.0) / 2.0).max(40.0);

            changed |= time_field(
                ui,
                pal,
                &mut self.section_start,
                i18n::t(lang, Key::UiSectionFrom),
                error.is_some_and(SectionError::at_start),
                width,
            );
            ui.add_sized(
                [DASH, theme::CONTROL_HEIGHT],
                egui::Label::new(egui::RichText::new("—").color(pal.text_muted)),
            );
            let rest = ui.available_width();
            changed |= time_field(
                ui,
                pal,
                &mut self.section_end,
                i18n::t(lang, Key::UiSectionTo),
                error.is_some_and(SectionError::at_end),
                rest,
            );
        });

        if changed {
            match parse_section(&self.section_start, &self.section_end) {
                Ok(section) => {
                    self.section = section;
                    self.section_error = None;
                }
                Err(err) => {
                    // Пока диапазон не разобран, не просим ничего. Кнопка всё
                    // равно выключена (`can_start`), но оставить здесь прошлое
                    // значение значило бы однажды вырезать не тот кусок.
                    self.section = Section::default();
                    self.section_error = Some(err);
                }
            }
            // Свёрнутая группа обязана сказать, что фрагмент задан, — иначе
            // обрезка становится невидимой настройкой.
            self.rebuild_advanced_summary();
        }

        // Оговорка есть всегда, как и у списка браузеров: у пустых полей она
        // объясняет, что писать, у заполненных — чем обрезка отличается от
        // обычной загрузки. Все строки статические.
        ui.add_space(6.0);
        if let Some(err) = self.section_error {
            note(ui, err.message(self.lang), pal.state_error);
        } else if !self.section.any() {
            note(ui, self.t(Key::UiSectionHint), pal.text_muted);
        } else if self.ffmpeg_missing {
            note(ui, self.t(Key::UiSectionNoFfmpeg), pal.state_warning);
        } else {
            note(ui, self.section_hint(), pal.text_muted);
        }
    }

    /// Чем обернётся заданный фрагмент: каким путём его возьмут и что при
    /// этом будет видно в окне.
    ///
    /// Путей два, и разница между ними человеку заметна — ждать минуты
    /// с неопределённой полосой или секунды с процентами, — так что молчать
    /// о выборе нельзя. Правило выбора живёт в домене
    /// ([`Section::plan`]), здесь только слова к нему.
    ///
    /// Считается прямо в кадре, и это не нарушение Правила 1: `plan` — это
    /// пара сравнений без единой аллокации, а обе строки статические. Поле
    /// с готовым текстом, как у `quality_note`, пришлось бы пересобирать
    /// в четырёх местах (правка полей, ответ предпросмотра, смена ссылки,
    /// очистка карточки), и первое же забытое показало бы путь от прошлой
    /// ссылки — при том что считать тут нечего.
    fn section_hint(&self) -> &'static str {
        let duration = self
            .preview
            .info
            .as_ref()
            .and_then(|info| info.duration_secs);

        match self.section.plan(duration) {
            // `Whole` сюда не попадает: выше уже спрошено `section.any()`,
            // а без границ плана «резать» не бывает. Ветка выписана вместе
            // со `Stream`, а не через `_`, чтобы новый вариант `SectionPlan`
            // компилятор потребовал разобрать и здесь.
            SectionPlan::Stream | SectionPlan::Whole => self.t(Key::UiSectionStreamNote),
            SectionPlan::CutAfter => self.t(Key::UiSectionCutAfterNote),
        }
    }

    /// Что вшить в файл: три независимых переключателя-«чипа» и подчинённый
    /// четвёртый.
    ///
    /// Чипы, а не галочки, — так в макете, и на трёх пунктах это выигрыш:
    /// подписи русские и длинные, столбик из трёх галочек занимал четверть
    /// карточки, а чипы переносятся по ширине сами
    /// (`horizontal_wrapped`) и в широком окне встают одной строкой.
    /// Состояние при этом сказано не только цветом: у включённого чипа
    /// нарисована галочка — см. [`chip`].
    fn embed_options(&mut self, ui: &mut egui::Ui) {
        let pal = self.palette;
        // Субтитры бывают только у видео: в MP3 их положить некуда. Чип
        // гасим, но причину говорим по наведению — молча выключенный элемент
        // выглядит поломкой, а не запретом.
        let subs_enabled = self.format == Format::Mp4;
        // Два флага, а не один, и разница не в экономии. `subs` пересобирает
        // подписи, и трогать их от «Метаданных» незачем; `any` запоминает
        // выбор, и вот его пропуск как раз ничем себя не выдаст — настройка
        // просто перестанет переживать перезапуск. Оба применяются **после**
        // отрисовки: `self` до конца замыкания занят.
        let mut subs_changed = false;
        let mut any_changed = false;
        // Копией, а не `self.speed` по месту: внутри замыкания `self` занят
        // изменяемо — там же правятся сами галочки.
        let speed = self.speed;
        let lang = self.lang;

        ui.horizontal_wrapped(|ui| {
            ui.spacing_mut().item_spacing = egui::vec2(8.0, 8.0);

            any_changed |= chip(
                ui,
                pal,
                &mut self.options.embed_metadata,
                i18n::t(lang, Key::UiEmbedMetadata),
                true,
                speed,
            )
            .on_hover_text(i18n::t(lang, Key::UiEmbedMetadataHint))
            .changed();
            any_changed |= chip(
                ui,
                pal,
                &mut self.options.embed_thumbnail,
                i18n::t(lang, Key::UiEmbedThumbnail),
                true,
                speed,
            )
            .on_hover_text(i18n::t(lang, Key::UiEmbedThumbnailHint))
            .changed();
            subs_changed |= chip(
                ui,
                pal,
                &mut self.options.embed_subs,
                i18n::t(lang, Key::UiEmbedSubs),
                subs_enabled,
                speed,
            )
            .on_disabled_hover_text(i18n::t(lang, Key::UiEmbedSubsDisabled))
            .changed();

            // Подчинённый чип появляется вместе с субтитрами, а не висит
            // выключенным рядом: без «Субтитров» он не значит ничего.
            if subs_enabled && self.options.embed_subs {
                subs_changed |= chip(
                    ui,
                    pal,
                    &mut self.options.auto_subs,
                    i18n::t(lang, Key::UiAutoSubs),
                    true,
                    speed,
                )
                .on_hover_text(i18n::t(lang, Key::UiAutoSubsHint))
                .changed();
            }
        });

        // Оговорка про ffmpeg — статическая строка: в кадре ничего не собирается.
        if self.ffmpeg_missing && self.options.any() {
            ui.add_space(8.0);
            note(ui, i18n::t(lang, Key::UiEmbedNoFfmpeg), pal.state_warning);
        }

        if subs_changed {
            self.rebuild_subtitles();
            // Язык субтитров показан в тонких настройках, и его строка
            // в их заголовке зависит от того, просят ли субтитры вообще.
            self.rebuild_advanced_summary();
        }

        if any_changed || subs_changed {
            self.remember();
        }
    }

    /// Тонкие настройки: фрагмент, вход на сайт, язык субтитров.
    ///
    /// Свёрнуты по умолчанию. Все трое нужны редко, а места занимали больше
    /// половины карточки: два поля времени с абзацем объяснения, список
    /// браузеров с абзацем и список из полутора сотен языков. Сводка в
    /// заголовке говорит, что из этого сейчас включено, — без неё свёрнутая
    /// группа прятала бы заданный фрагмент, и человек потом искал бы, почему
    /// ролик скачался куском.
    fn advanced_group(&mut self, ui: &mut egui::Ui) {
        let pal = self.palette;
        let open = self.advanced;
        let speed = self.speed;
        let lang = self.lang;
        let mut toggled = false;

        egui::Frame::new()
            .fill(pal.card_inner)
            .stroke(egui::Stroke::new(1.0, pal.border_subtle))
            .corner_radius(egui::CornerRadius::same(theme::RADIUS_INNER))
            .inner_margin(egui::Margin::same(4))
            .show(ui, |ui| {
                ui.set_width(ui.available_width());
                toggled = disclosure_row(
                    ui,
                    pal,
                    open,
                    i18n::t(lang, Key::UiAdvanced),
                    &self.advanced_summary,
                    speed,
                );

                collapsing_body(ui, egui::Id::new("advanced-body"), open, speed, |ui| {
                    egui::Frame::new()
                        .inner_margin(egui::Margin {
                            left: 12,
                            right: 12,
                            top: 4,
                            bottom: 12,
                        })
                        .show(ui, |ui| {
                            ui.set_width(ui.available_width());

                            field_label(ui, pal, i18n::t(lang, Key::UiSectionField));
                            self.section_row(ui);

                            ui.add_space(14.0);
                            field_label(ui, pal, i18n::t(lang, Key::UiSiteLogin));
                            self.cookie_selector(ui);

                            // Список языков нужен, только если субтитры просят:
                            // в остальное время он не значит ничего.
                            if self.subs_requested() {
                                ui.add_space(14.0);
                                field_label(ui, pal, i18n::t(lang, Key::UiSubtitleLanguage));
                                if self.sub_lang_selector(ui) {
                                    self.rebuild_subtitles();
                                    self.rebuild_advanced_summary();
                                }
                            }
                        });
                });
            });

        if toggled {
            self.advanced = !open;
        }
    }

    /// Выпадающий список языков субтитров.
    ///
    /// Возвращает `true`, когда выбор поменяли: пересобирать подпись и
    /// оговорку — работа обработчика, а не кадра отрисовки.
    ///
    /// Пункты берутся из ответа `probe`, то есть появляются через секунду
    /// после того, как в поле вставили ссылку (см. [`Preview`]). Пустого
    /// списка при этом не бывает — «Язык ролика» есть всегда, и он же
    /// значение по умолчанию, так что и до ответа выбор осмыслен.
    fn sub_lang_selector(&mut self, ui: &mut egui::Ui) -> bool {
        let pal = self.palette;
        // Ширину берём до `ComboBox`, как и у списка браузеров: внутри он
        // заводит свою горизонтальную раскладку.
        let width = ui.available_width();
        let allow_auto = self.options.auto_subs;
        let mut changed = false;
        // Подписи берём до замыкания: внутри `self` занят по частям, и позвать
        // `self.t` там уже нечем.
        let ui_lang = self.lang;
        let original = SubLang::original_label(ui_lang);
        let automatic = i18n::t(ui_lang, Key::UiSubsAutomatic);
        let own = i18n::t(ui_lang, Key::UiSubsOwn);

        ui.scope(|ui| {
            let v = ui.visuals_mut();
            // То же оформление, что у списка браузеров: это такое же поле
            // ввода, и разъехаться им нельзя.
            for state in [&mut v.widgets.inactive, &mut v.widgets.open] {
                state.weak_bg_fill = pal.input_fill;
            }
            v.widgets.hovered.weak_bg_fill = pal.input_fill;

            // Поля берём по отдельности: внутри замыкания `sub_lang` нужен
            // изменяемым, а `info` — нет, и целиком `self` там занять нельзя.
            let info = self.preview.info.as_ref();
            let lang = &mut self.sub_lang;

            egui::ComboBox::from_id_salt("savio-sub-lang")
                .selected_text(self.sub_lang_label.as_str())
                .width(width)
                .height(SUBLANG_LIST_HEIGHT)
                .show_ui(ui, |ui| {
                    let spacing = ui.spacing_mut();
                    spacing.interact_size.y = 26.0;
                    spacing.button_padding.y = 3.0;
                    spacing.item_spacing.y = 2.0;

                    // Первым — то, что нужно почти всегда, и единственный
                    // пункт, который есть до первого `probe`.
                    let selected = matches!(lang, SubLang::Original);
                    if ui
                        .selectable_label(selected, original)
                        .clicked()
                        && !selected
                    {
                        *lang = SubLang::Original;
                        changed = true;
                    }

                    // Заголовок раздела ставим на смене вида дорожек.
                    // Список приходит уже разделённым: сначала авторские,
                    // потом автоматические, — так что перелом ровно один.
                    let mut group: Option<bool> = None;
                    let tracks = info.map(|info| info.subtitle_tracks(allow_auto));
                    for track in tracks.into_iter().flatten() {
                        if group != Some(track.auto) {
                            group = Some(track.auto);
                            ui.label(
                                egui::RichText::new(if track.auto { automatic } else { own })
                                    .small()
                                    .color(pal.text_muted),
                            );
                        }

                        // `selectable_label`, а не `selectable_value`:
                        // последний берёт значение по значению, то есть
                        // требовал бы копии кода на каждый пункт в каждом
                        // кадре — а пунктов у YouTube полторы сотни.
                        let selected = matches!(lang, SubLang::Code(code) if *code == track.code);
                        if ui.selectable_label(selected, track.label.as_str()).clicked()
                            && !selected
                        {
                            *lang = SubLang::Code(track.code.clone());
                            changed = true;
                        }
                    }
                });
        });

        ui.add_space(6.0);
        if !self.subs_note.is_empty() {
            note(ui, &self.subs_note, pal.state_warning);
            ui.add_space(6.0);
        }
        // Обе строки статические, и обе нужны: про качество робота человек
        // должен узнать здесь, а не по готовому файлу.
        let hint = if allow_auto {
            Key::UiSubsAutomaticHint
        } else {
            Key::UiSubsOwnHint
        };
        note(ui, i18n::t(ui_lang, hint), pal.text_muted);

        changed
    }

    /// Выпадающий список «откуда взять вход на сайт»: браузер или файл.
    ///
    /// Список, а не поле ввода: имена браузеров принадлежат yt-dlp, их список
    /// закрытый, и опечатка в нём обернулась бы английской руганью вместо
    /// загрузки.
    ///
    /// Оговорка под ним меняется вместе с выбором и в каждом случае статична —
    /// в кадре отрисовки здесь ничего не собирается.
    fn cookie_selector(&mut self, ui: &mut egui::Ui) {
        let pal = self.palette;
        // Ширину берём до `ComboBox`: внутри он заводит свою горизонтальную
        // раскладку, и `available_width` там уже другая.
        let width = ui.available_width();
        // С каким входом спрашивали — часть вопроса: у YouTube ответ с cookies
        // и без них отличается вплоть до пустого списка дорожек. Сменили
        // браузер — прежнее превью уже не про этот запрос.
        let before = self.cookies;
        let lang = self.lang;

        ui.scope(|ui| {
            let v = ui.visuals_mut();
            // Список — такое же поле ввода, как ссылка и дорожки
            // переключателей, поэтому и «утоплен» глубже карточки. Иначе на
            // заливке `BG_SURFACE` он держался бы на одной тонкой рамке.
            // `open` в списке обязателен: пока раскрыт список, egui рисует
            // кнопку именно этим состоянием, и без него она бы перекрашивалась
            // в момент нажатия.
            for state in [&mut v.widgets.inactive, &mut v.widgets.open] {
                state.weak_bg_fill = pal.input_fill;
            }
            v.widgets.hovered.weak_bg_fill = pal.input_fill;

            egui::ComboBox::from_id_salt("savio-cookies")
                .selected_text(self.cookies.label(lang))
                .width(width)
                // Список обязан помещаться целиком. У egui потолок раскрытого
                // списка — `combo_height`, то есть 200 точек: при штатной
                // строке в 32 точки туда влезает пять пунктов из восьми,
                // а остальные три уезжают в прокрутку, полосы которой в покое
                // не видно. В окне минимального размера это выглядит так,
                // будто браузеров всего пять.
                .height(COOKIE_LIST_HEIGHT)
                .show_ui(ui, |ui| {
                    // Строки в списке плотнее, чем кнопки на экране: восемь
                    // штатных строк не поместились бы и в окно минимальной
                    // высоты (420), а для меню 26 точек — обычный размер.
                    let spacing = ui.spacing_mut();
                    spacing.interact_size.y = 26.0;
                    spacing.button_padding.y = 3.0;
                    spacing.item_spacing.y = 2.0;

                    for source in CookieSource::ALL {
                        ui.selectable_value(&mut self.cookies, source, source.label(lang));
                    }
                });
        });

        if self.cookies != before {
            // Пункт «Из файла…» без файла не значит ничего, поэтому диалог
            // открываем сразу, а не оставляем человека гадать, где выбрать
            // файл. Отказ от диалога возвращает прежний выбор: пустой «Из
            // файла…» выглядел бы включённым входом, а вход при нём не
            // передавался бы вовсе — ровно тот молчаливый отказ, которого
            // не должно быть.
            if self.cookies == CookieSource::File && self.cookie_file.is_none() {
                self.pick_cookie_file();
                if self.cookie_file.is_none() {
                    self.cookies = before;
                }
            }
            self.retarget_preview(ui.ctx());
            self.rebuild_advanced_summary();
            // После отката: если от диалога отказались, запомнить надо
            // прежний выбор, а не «Из файла…», которого уже нет.
            self.remember();
        }

        if self.cookies == CookieSource::File {
            ui.add_space(6.0);
            self.cookie_file_row(ui);
        }

        ui.add_space(6.0);
        match self.cookies {
            CookieSource::None => note(ui, i18n::t(lang, Key::UiCookiesWhy), pal.text_muted),
            CookieSource::File => note(
                ui,
                i18n::t(lang, Key::UiCookieFileWhy),
                pal.state_warning,
            ),
            _ => note(
                ui,
                i18n::t(lang, Key::UiCookieCloseBrowser),
                pal.state_warning,
            ),
        }
    }

    /// Строка с выбранным файлом cookies: кнопка во всю ширину с самим путём.
    ///
    /// Устроена как `folder_row`, и по той же причине: пара «подпись + кнопка»
    /// в узкой колонке разъезжается, а путь длинный почти всегда. Полный путь
    /// с кнопки, как и там, не посмотреть — `show_tooltip_when_elided` есть
    /// только у `Label` (дефект 48 реестра).
    ///
    /// Отдельного вида «файл не выбран» здесь нет, и это не упущение: щелчками
    /// в такое состояние не попасть — пункт «Из файла…» сам открывает диалог,
    /// а отказ от диалога возвращает прежний выбор (см. `cookie_selector`).
    /// Запуск с запомненным входом попасть может, если путь не выразился
    /// в UTF-8 и в `settings.json` не попал, и на этот случай на кнопке стоит
    /// [`PICK_COOKIE_FILE`] — приглашение сделать ровно то, что она и делает.
    fn cookie_file_row(&mut self, ui: &mut egui::Ui) {
        let pal = self.palette;
        let clicked = ui
            .add_sized(
                [ui.available_width(), theme::CONTROL_HEIGHT],
                egui::Button::new(
                    egui::RichText::new(&self.cookie_file_display)
                        .color(pal.text_secondary),
                )
                .truncate(),
            )
            .on_hover_text(self.t(Key::UiCookieSourceHint))
            .clicked();

        if clicked {
            self.pick_cookie_file();
            // Файл — часть вопроса к сайту наравне со ссылкой: сменили
            // файл, значит прежний ответ уже не про этот вход.
            self.retarget_preview(ui.ctx());
            self.remember();
        }
    }

    /// Спрашивает файл cookies. Отказ от диалога ничего не меняет: прежний
    /// выбор остаётся на месте.
    ///
    /// Диалог блокирует поток, то есть и кадр, — как и выбор папки
    /// сохранения. Это законно: пока открыт модальный диалог системы,
    /// рисовать окну всё равно нечего.
    fn pick_cookie_file(&mut self) {
        let Some(file) = rfd::FileDialog::new()
            // Фильтр по расширению, но не единственный: расширения у выгрузки
            // разные, и запереть человека в `*.txt` значило бы не дать
            // выбрать свой же файл.
            .add_filter(self.t(Key::FilterCookieFiles), &["txt"])
            .add_filter(self.t(Key::FilterAllFiles), &["*"])
            .pick_file()
        else {
            return;
        };

        self.cookie_file_display = display_cookie_file(Some(&file), self.lang);
        self.cookie_file = Some(file);
    }

    /// Куда класть готовые файлы: одна кнопка во всю ширину с самим путём.
    ///
    /// Путь на самой кнопке, а не подписью рядом: пары «кнопка + подпись»
    /// в узкой колонке разъезжаются, а путь длинный почти всегда. Длинный
    /// путь при этом обрезается, и целиком его сейчас взять негде:
    /// `show_tooltip_when_elided` есть только у `Label`, а на кнопке висит
    /// поясняющая подсказка (дефект 48 реестра).
    fn folder_row(&mut self, ui: &mut egui::Ui) {
        let pal = self.palette;
        // Папки нет — это не оговорка, а помеха работе: «Скачать» без неё
        // выключена. Поэтому предупреждающий тон, а не приглушённый.
        let color = if self.out_dir.is_some() {
            pal.text_secondary
        } else {
            pal.state_warning
        };

        let clicked = sized_with_touch(
            ui,
            egui::vec2(ui.available_width(), theme::CONTROL_HEIGHT),
            self.speed,
            |ui| {
                ui.add(
                    egui::Button::new(egui::RichText::new(&self.out_dir_display).color(color))
                        .truncate(),
                )
            },
        )
        .on_hover_text(self.t(Key::UiOutDirHint))
        .clicked();

        if clicked && let Some(dir) = rfd::FileDialog::new().pick_folder() {
            self.out_dir_display = display_dir(Some(&dir), self.lang);
            self.out_dir = Some(dir);
            self.remember();
        }
    }

    /// Ряд действий: «В очередь» слева, «Скачать» (или «Отмена») справа.
    ///
    /// Две кнопки в строку, а не одна во всю ширину, как было до очереди:
    /// докладывать ссылки нужно и во время загрузки, а второй ряд удлинил бы
    /// и без того длинную карточку. Ширины неравные — главное действие экрана
    /// остаётся заметно крупнее.
    fn action_button(&mut self, ui: &mut egui::Ui) {
        let pal = self.palette;
        // Подсказку выключенной кнопки выбираем по первой же причине, а не
        // по всем сразу: человеку нужно знать, что сделать сейчас.
        let add_hint = self.t(if self.queue.full {
            Key::UiQueueFull
        } else if self.url.trim().is_empty() {
            Key::UiPasteLinkForQueue
        } else if self.section_error.is_some() {
            Key::UiFixSection
        } else if self.out_dir.is_none() {
            Key::UiPickFolderFirst
        } else {
            Key::UiNeedYtdlp
        });
        let can_enqueue = self.can_enqueue();
        let lang = self.lang;

        let mut enqueue_clicked = false;
        let mut primary_clicked = false;

        ui.horizontal(|ui| {
            const GAP: f32 = 10.0;
            ui.spacing_mut().item_spacing.x = GAP;
            // Треть — «В очередь», остаток — главному действию. Остаток,
            // а не вторая доля от деления: два округления до пиксельной
            // сетки не дотянули бы ряд до правого края.
            let secondary = ((ui.available_width() - GAP) / 3.0).max(90.0);

            enqueue_clicked = ui
                .add_enabled(
                    can_enqueue,
                    // Подпись переносится: «Отложить в очередь» длиннее
                    // прежнего «В очередь», и в треть строки узкой карточки
                    // она в один ряд не встаёт ни на одном языке. Высота
                    // задана полом, так что на вторую строку кнопка растёт
                    // сама. Держит это `the_action_buttons_fit_the_card`.
                    egui::Button::new(i18n::t(lang, Key::UiEnqueue))
                        .wrap()
                        .min_size(egui::vec2(secondary, theme::CTA_HEIGHT)),
                )
                .on_hover_text(i18n::t(lang, Key::UiEnqueueHint))
                .on_disabled_hover_text(add_hint)
                .clicked();

            primary_clicked = self.primary_button(ui, ui.available_width());
        });

        // Подписи под кнопками, а не подсказки по наведению. Подсказка
        // требует догадаться, что наводить есть на что, — а вопрос «чем эти
        // две кнопки отличаются» возникает ровно у того, кто их видит
        // впервые. Под выключенной «Скачать» на месте подписи стоит причина,
        // и жёлтым: это не пояснение, а то, что мешает.
        ui.add_space(6.0);
        ui.horizontal(|ui| {
            const GAP: f32 = 10.0;
            ui.spacing_mut().item_spacing.x = GAP;
            let secondary = ((ui.available_width() - GAP) / 3.0).max(90.0);
            let rest = (ui.available_width() - secondary - GAP).max(90.0);
            // Ширина задаётся с обеих сторон, и это не перестраховка:
            // `allocate_ui_with_layout` двигает курсор на то, что занял
            // потомок, а не на запрошенное. Без нижней границы вторая
            // подпись прилипала к концу первой и стояла под чужой кнопкой —
            // проверено глазами, выглядело как случайно слипшаяся строка.
            let column = |ui: &mut egui::Ui, width: f32, text: &str, color| {
                ui.allocate_ui_with_layout(
                    egui::vec2(width, 0.0),
                    egui::Layout::top_down(egui::Align::Min),
                    |ui| {
                        ui.set_min_width(width);
                        ui.set_max_width(width);
                        note(ui, text, color);
                    },
                );
            };

            column(
                ui,
                secondary,
                i18n::t(lang, Key::UiQueueButtonNote),
                pal.text_muted,
            );
            let running = matches!(self.state, State::Running);
            let (text, color) = if running {
                (i18n::t(lang, Key::UiCancelHint), pal.text_muted)
            } else if self.url.trim().is_empty() && self.queue.next_waiting().is_none() {
                (i18n::t(lang, Key::UiDownloadNeedsLink), pal.state_warning)
            } else {
                (i18n::t(lang, Key::UiDownloadButtonNote), pal.text_muted)
            };
            column(ui, rest, text, color);
        });

        if enqueue_clicked && self.enqueue() {
            // Поле освобождаем сразу: «В очередь» затем и нажимают, чтобы
            // вставить следующую ссылку. У «Скачать» этого нет — там поле
            // остаётся, как оно оставалось и до появления очереди.
            self.url.clear();
            self.url_invalid = false;
        }
        if primary_clicked {
            let ctx = ui.ctx().clone();
            if matches!(self.state, State::Running) {
                self.cancel();
            } else {
                self.start(&ctx);
            }
        }

        if self.queue.full {
            ui.add_space(6.0);
            note(ui, i18n::t(lang, Key::UiQueueFullNote), pal.state_warning);
        }
    }

    /// Главная кнопка ряда: «Отмена» во время загрузки, «Скачать» в остальное
    /// время. Возвращает `true`, когда её нажали.
    ///
    /// Здесь решается только, что на ней показать; рисует её [`cta_button`].
    fn primary_button(&mut self, ui: &mut egui::Ui, width: f32) -> bool {
        let lang = self.lang;
        let cta = if matches!(self.state, State::Running) {
            Cta::Cancel
        } else {
            // Подсказка выключенной кнопке нужна не меньше, чем соседней: до
            // очереди она молча гасла, и понять почему было неоткуда.
            let hint = i18n::t(
                lang,
                if self.setup_error.is_some() {
                    Key::UiNeedYtdlp
                } else if self.section_error.is_some() {
                    Key::UiFixSection
                } else if self.out_dir.is_none() {
                    Key::UiPickFolderFirst
                } else {
                    Key::UiPasteOrQueue
                },
            );
            Cta::Download {
                enabled: self.can_start(),
                hint,
            }
        };
        cta_button(ui, self.palette, lang, width, cta, &mut self.swap_pause)
    }

    /// Карточка хода работы: что сейчас происходит с загрузкой.
    ///
    /// Название с обложкой отсюда переехали под поле ссылки: они про то,
    /// что собираются скачать, и известны ещё до нажатия «Скачать». Здесь
    /// остаётся только ход самой работы, а какой ролик качается — видно
    /// в строке очереди ниже, где название и так стоит и подсвечено.
    fn status_section(&mut self, ui: &mut egui::Ui) {
        let pal = self.palette;
        let (label, color) = self.status();
        let speed = self.speed;
        let lang = self.lang;
        // Куда открывать папку, решаем после карточки: внутри замыкания
        // `self` занят целиком, а `open_dir` запускает процесс.
        let mut open_at: Option<PathBuf> = None;

        theme::card_rising(ui, pal, self.appear(1), |ui| {
            ui.horizontal(|ui| {
                ui.spacing_mut().item_spacing.x = 9.0;
                // Точка — подсказка глазу, а не носитель смысла: то же
                // состояние сказано словом рядом.
                //
                // Дышит она ровно тогда, когда что-то вправду идёт (приём 14):
                // погасшая пульсация означает «кончилось», и это единственное,
                // что движется в покое. Цвет при этом переливается, а не
                // подменяется, — состояние меняется одним движением.
                let (dot, _) = ui.allocate_exact_size(egui::vec2(9.0, 9.0), egui::Sense::hover());
                let running = matches!(self.state, State::Running);
                let color = motion::tint(
                    ui.ctx(),
                    egui::Id::new("status-dot"),
                    color,
                    motion::MOVE * speed,
                );
                let color = if running {
                    color.gamma_multiply(motion::breath(ui.ctx(), speed))
                } else {
                    color
                };
                ui.painter().circle_filled(dot.center(), 4.5, color);
                ui.add(
                    egui::Label::new(
                        egui::RichText::new(label)
                            .font(theme::display(17.0))
                            .color(pal.text_primary),
                    )
                    .truncate(),
                );
            });

            ui.add_space(10.0);

            match &self.state {
                State::Running => {
                    ui.scope(|ui| {
                        // Жёлоб бара берётся из `extreme_bg_color`.
                        ui.visuals_mut().extreme_bg_color = pal.progress_track;

                        // Без явного скругления egui рисует бар «таблеткой» —
                        // ровно то, что нужно. Проценты не пишем внутрь бара:
                        // тёмный текст утонул бы в жёлобе, светлый — в заливке.
                        let bar = match self.progress.fraction() {
                            // yt-dlp отдаёт проценты рывками, поэтому полоса
                            // едет к присланному значению чуть дольше, чем
                            // приходит следующее (приём 09). Показываем при
                            // этом потолок, а не сам замер: см. `progress_peak`.
                            Some(_) => egui::ProgressBar::new(ui.ctx().animate_value_with_time(
                                egui::Id::new("progress-bar"),
                                self.progress_peak,
                                PROGRESS_CATCH_UP * speed,
                            )),
                            // Размер неизвестен — крутим неопределённый
                            // индикатор. Он у egui штатный и остаётся как был:
                            // это одна из трёх бесконечных анимаций набора, и
                            // живёт она ровно столько, сколько идёт загрузка.
                            None => egui::ProgressBar::new(0.0).animate(true),
                        };
                        ui.add(bar.fill(pal.accent).desired_height(8.0));
                    });

                    if !self.progress_line.is_empty() {
                        ui.add_space(8.0);
                        // Обрезаем, а не переносим: строка «стадия · проценты ·
                        // объём · скорость · остаток» в колонке шириной 340
                        // легла бы в две строки и дёргала бы высоту карточки
                        // на каждом кадре загрузки. Полную строку показывает
                        // подсказка самой обрезанной метки.
                        ui.add(
                            egui::Label::new(
                                egui::RichText::new(&self.progress_line)
                                    .small()
                                    .color(pal.text_secondary),
                            )
                            .truncate(),
                        );
                    }
                }
                State::Done(path) => {
                    if !self.done_path_display.is_empty() {
                        ui.add(
                            egui::Label::new(
                                egui::RichText::new(&self.done_path_display)
                                    .small()
                                    .color(pal.text_secondary),
                            )
                            .truncate(),
                        );
                        ui.add_space(10.0);
                    }
                    if let Some(dir) = path.parent()
                        && pill_button(ui, i18n::t(lang, Key::UiOpenFolder), speed).clicked()
                    {
                        open_at = Some(dir.to_path_buf());
                    }
                }
                State::Failed(err) => banner(ui, pal, err, pal.state_error),
                State::Cancelled => note(
                    ui,
                    i18n::t(lang, Key::UiCancelledNote),
                    pal.text_secondary,
                ),
                State::Queued => note(
                    ui,
                    i18n::t(lang, Key::UiQueuedNote),
                    pal.text_secondary,
                ),
                State::Idle => note(ui, i18n::t(lang, Key::UiIdleNote), pal.text_secondary),
            }
        });

        if let Some(dir) = open_at {
            open_dir(&dir);
        }
    }

    /// Правая колонка снизу: очередь или история, на выбор.
    ///
    /// Вместе, а не двумя карточками подряд: обе про одни и те же ссылки,
    /// только в разное время, и одновременно нужна ровно одна из них.
    /// История сюда переехала из собственной вкладки — там она отнимала
    /// место в дорожке разделов, а смотрят в неё как раз во время загрузки.
    fn rail_list(&mut self, ui: &mut egui::Ui) {
        let pal = self.palette;
        // Что нажали, решаем после отрисовки: менять список, пока по нему
        // идёт цикл, нельзя, а откладывать решение до следующего кадра —
        // значит терять его при быстром щелчке.
        let mut remove: Option<DownloadId> = None;
        let mut clear = false;
        let mut picked = None;
        let mut open_at: Option<PathBuf> = None;
        let speed = self.speed;
        let lang = self.lang;
        self.rebuild_rail_labels();
        // Копии ссылок, а не полей: внутри замыкания `self` занят целиком.
        let (queue_label, history_label) =
            (self.rail_labels.0.as_str(), self.rail_labels.1.as_str());

        theme::card_rising(ui, pal, self.appear(2), |ui| {
            ui.horizontal(|ui| {
                picked = segment_track(
                    ui,
                    pal,
                    egui::Id::new("track:rail"),
                    self.speed,
                    self.rail_tab,
                    &[
                        (RailTab::Queue, queue_label),
                        (RailTab::History, history_label),
                    ],
                    false,
                );

                // «Очистить» прижата к правому краю и есть только у очереди:
                // история за этот запуск — единственный след того, куда что
                // легло, и стирать её кнопкой рядом со списком опасно.
                ui.with_layout(egui::Layout::right_to_left(egui::Align::Center), |ui| {
                    if self.rail_tab == RailTab::Queue && !self.queue.items.is_empty() {
                        clear = pill_button(ui, i18n::t(lang, Key::UiClear), speed)
                            .on_hover_text(i18n::t(lang, Key::UiClearHint))
                            .clicked();
                    }
                });
            });

            ui.add_space(12.0);

            match self.rail_tab {
                RailTab::Queue => remove = self.queue_list(ui),
                RailTab::History => open_at = self.history_list(ui),
            }
        });

        if let Some(tab) = picked {
            self.rail_tab = tab;
        }
        if let Some(dir) = open_at {
            open_dir(&dir);
        }

        if let Some(id) = remove {
            // Не удаляем, а помечаем: строка складывается, а убирает её
            // `sweep_queue`, когда складывание доиграло (приём 10).
            let now = ui.ctx().input(|i| i.time);
            self.queue.mark_removing(id, now);
        }
        if clear {
            self.queue.clear();
        }
        let emptied = remove.is_some() || clear;

        // Экран не должен пережить очередь. Убрали последнее ожидающее — и
        // «В очереди» на плашке становится враньём, а совет под ней («нажмите
        // „Скачать“ — они пойдут по одной») указывает на кнопку, которую
        // `can_start()` к этому моменту уже погасил: ждать-то нечего. Сам
        // список при этом с экрана исчезает, так что человек читает про
        // очередь, которой не видит. Ни сборка, ни `clippy`, ни тесты этого
        // не ловят — только глаза.
        if emptied && matches!(self.state, State::Queued) && !self.queue.has_waiting() {
            self.state = State::Idle;
        }
    }

    /// Содержимое половины «Очередь». Возвращает строку, которую убрали.
    fn queue_list(&self, ui: &mut egui::Ui) -> Option<DownloadId> {
        let pal = self.palette;
        let speed = self.speed;
        let lang = self.lang;
        if self.queue.items.is_empty() {
            note(ui, i18n::t(lang, Key::UiQueueEmptyNote), pal.text_muted);
            return None;
        }

        let mut remove = None;

        // Подсказку с полной сводкой вешает сама обрезанная метка
        // (`show_tooltip_when_elided`) — свой `on_hover_text` рядом дал бы
        // вторую коробку с тем же текстом (дефект 22).
        ui.add(
            egui::Label::new(
                egui::RichText::new(&self.queue.summary)
                    .small()
                    .color(pal.text_muted),
            )
            .truncate(),
        );
        ui.add_space(10.0);

        // Строки лежат прямо в общей прокрутке, своей у списка нет — и это
        // не косметика. Вложенная вертикальная прокрутка берёт высоту из
        // `available_rect_before_wrap()`, а внутри другой прокрутки это не
        // «сколько влезет в окно», а «сколько осталось от её видимой части».
        // Карточка лежит низко, остаток к ней нулевой — и список схлопнулся
        // бы до `min_scrolled_size`, то есть до 64 точек (дефект 27).
        for (index, item) in self.queue.items.iter().enumerate() {
            if index > 0 {
                ui.add_space(8.0);
            }
            if queue_row(ui, pal, item, lang, speed) {
                remove = Some(item.id);
            }
        }

        ui.add_space(10.0);
        note(ui, i18n::t(lang, Key::UiQueueNote), pal.text_muted);

        remove
    }

    /// Содержимое половины «История». Возвращает папку, которую попросили
    /// открыть.
    fn history_list(&self, ui: &mut egui::Ui) -> Option<PathBuf> {
        let pal = self.palette;
        let Some((first, rest)) = self.history.entries.split_first() else {
            // Пустой экран без объяснения читается как поломка. Про то, что
            // список не переживает закрытие окна, говорим здесь же: иначе
            // после перезапуска пустая история выглядит потерянными данными.
            note(ui, self.t(Key::UiHistoryEmptyNote), pal.text_muted);
            return None;
        };

        let mut open_at = None;
        if let Some(dir) = self.history_card(ui, first) {
            open_at = Some(dir);
        }
        for entry in rest {
            ui.add_space(8.0);
            if let Some(dir) = self.history_card(ui, entry) {
                open_at = Some(dir);
            }
        }
        open_at
    }
}

/// Панель журнала внизу окна: кнопка «Скопировать» и сами строки.
///
/// Панелью, а не последней строкой прокрутки содержимого, и это важно:
/// вложенная прокрутка внутри другой схлопывается до 64 точек (дефект 27),
/// а своя прокрутка в своей панели законна.
///
/// Свободной функцией, а не методом, — ради проверки. Сколько места открытый
/// журнал оставляет разделу, видно только в кадре целиком, и мерить надо ту
/// самую панель, что рисует окно, а не её копию: копия разъехалась бы с ней
/// при первой же правке. `height` — высота тела, посчитанная от окна
/// ([`log_height`]).
fn log_panel(
    ui: &mut egui::Ui,
    pal: theme::Palette,
    lang: Lang,
    speed: f32,
    lines: &[String],
    copied_at: &mut Option<f64>,
    height: f32,
) {
    egui::Panel::bottom("savio-log")
        .resizable(false)
        .show_separator_line(false)
        .frame(
            egui::Frame::new()
                .fill(pal.rail_fill)
                .inner_margin(egui::Margin::symmetric(20, 12)),
        )
        .show(ui, |ui| {
            log_copy_row(ui, pal, lang, speed, lines, copied_at);
            ui.add_space(8.0);

            egui::Frame::new()
                .fill(pal.input_fill)
                .corner_radius(egui::CornerRadius::same(theme::RADIUS_INNER))
                .inner_margin(egui::Margin::same(12))
                .show(ui, |ui| {
                    ui.set_width(ui.available_width());
                    // Высота прибита с двух сторон — почему, объяснено
                    // у [`log_scroll`]. Коротко: панель сама растёт по
                    // содержимому, прокрутка внутри неё берёт остаток от
                    // прошлого кадра, и по кругу журнал застревал на
                    // 75 точках вместо 150, обрезаясь кромкой окна. Ровно тот
                    // же механизм, что в дефекте 27, только там роль панели
                    // играла внешняя прокрутка.
                    log_scroll(height).show(ui, |ui| {
                        for line in lines {
                            ui.label(
                                egui::RichText::new(line.as_str())
                                    .monospace()
                                    .color(pal.text_muted),
                            );
                        }
                    });
                });
        });
}

/// Кнопка «Скопировать» над телом журнала.
///
/// Строки журнала рисуются метками, а не полем ввода, и мышью не
/// выделяются: без кнопки просьба «пришлите журнал» упирается в то, что
/// переписывать его вручную никто не станет. Кнопка ничего не разбирает
/// и не запускает — берёт уже готовые строки, поэтому и работы с потоками
/// здесь нет.
fn log_copy_row(
    ui: &mut egui::Ui,
    pal: theme::Palette,
    lang: Lang,
    speed: f32,
    lines: &[String],
    copied_at: &mut Option<f64>,
) {
    ui.horizontal(|ui| {
        let now = ui.input(|i| i.time);

        let copied = pill_button(ui, i18n::t(lang, Key::UiCopy), speed)
            .on_hover_text(i18n::t(lang, Key::UiCopyHint))
            .clicked();

        if copied {
            // Единственная аллокация во всей кнопке, и происходит она по
            // нажатию, а не в кадре: `join` выделяет буфер один раз, сразу
            // нужного размера. Журнал уже ограничен `LOG_LIMIT`, так что
            // размер строки предсказуем.
            ui.ctx().copy_text(lines.join("\n"));
            *copied_at = Some(now);
        }

        if let Some(at) = *copied_at {
            let left = COPIED_NOTICE_SECS - (now - at);
            if left > 0.0 {
                // 10.7:1 на `BG_ROOT` — порог 4.5:1 проходит с запасом.
                ui.label(
                    egui::RichText::new(i18n::t(lang, Key::UiCopied))
                        .small()
                        .color(pal.state_success),
                );
                // Кадр к сроку приходится просить: без ввода egui окно не
                // перерисовывает, и подпись висела бы до первого движения
                // мыши — то есть заметно дольше положенного.
                ui.ctx()
                    .request_repaint_after(std::time::Duration::from_secs_f64(left));
            } else {
                *copied_at = None;
            }
        }
    });
}

// ---------------------------------------------------------------------------
// Вкладка «Метаданные»
// ---------------------------------------------------------------------------

impl SavioApp {
    /// Вкладка «Метаданные»: работа слева, объяснения справа.
    ///
    /// Две колонки по той же причине, что у загрузки: предупреждение о
    /// перезаписи и список поддерживаемых форматов — это то, что читают
    /// **до** нажатия «Стереть всё», и под самой кнопкой их не видно.
    fn metadata_tab(&mut self, ui: &mut egui::Ui) {
        let (pal, lang, speed) = (self.palette, self.lang, self.speed);
        const GAP: f32 = COLUMN_GAP;
        let mut to_download = false;

        if ui.available_width() < theme::TWO_COLUMN_MIN {
            self.metadata_main(ui);
            ui.add_space(GAP);
            to_download = metadata_rail(ui, pal, lang, speed, self.appear(1), self.appear(2));
        } else {
            let total = ui.available_width();
            let rail = theme::RAIL_WIDTH;
            let main = total - rail - GAP;

            ui.horizontal_top(|ui| {
                ui.spacing_mut().item_spacing.x = GAP;
                ui.allocate_ui_with_layout(
                    egui::vec2(main, 0.0),
                    egui::Layout::top_down(egui::Align::Min),
                    |ui| {
                        ui.set_min_width(main);
                        ui.set_max_width(main);
                        self.metadata_main(ui);
                    },
                );
                ui.allocate_ui_with_layout(
                    egui::vec2(rail, 0.0),
                    egui::Layout::top_down(egui::Align::Min),
                    |ui| {
                        ui.set_min_width(rail);
                        ui.set_max_width(rail);
                        to_download =
                            metadata_rail(ui, pal, lang, speed, self.appear(1), self.appear(2));
                    },
                );
            });
        }

        if to_download {
            self.switch_tab(Tab::Download, ui.ctx());
        }
    }

    /// Главная колонка вкладки: файл, прочитанное, кнопки и итог.
    fn metadata_main(&mut self, ui: &mut egui::Ui) {
        let pal = self.palette;
        let lang = self.lang;
        theme::card_rising(ui, pal, self.appear(0), |ui| {
            ui.label(
                egui::RichText::new(i18n::t(lang, Key::UiMetaTitle))
                    .font(theme::display(21.0))
                    .color(pal.text_primary),
            );
            ui.add_space(6.0);
            note(ui, i18n::t(lang, Key::UiMetaNote), pal.text_muted);

            ui.add_space(16.0);
            step_header(
                ui,
                pal,
                1,
                i18n::t(lang, Key::UiMetaFileStep),
                Some(i18n::t(lang, Key::UiMetaFileStepNote)),
                |_| {},
            );
            ui.add_space(8.0);
            self.meta_file_row(ui);

            ui.add_space(16.0);
            let personal = self
                .meta
                .summary
                .as_ref()
                .map_or("", |summary| summary.personal_line.as_str());
            findings_header(ui, pal, lang, personal);
            ui.add_space(8.0);
            self.meta_findings(ui);

            // TIFF читается, но не стирается, и место этой оговорки — у самих
            // кнопок: «Стереть всё» выключена, и причина нужна рядом с ней.
            // Нечитаемый файл объясняется выше, на месте таблицы.
            if self.meta.readable
                && let Some(blocked) = &self.meta.blocked
            {
                ui.add_space(12.0);
                banner(ui, pal, blocked, pal.state_warning);
            }

            ui.add_space(16.0);
            self.meta_buttons(ui);
            // Оговорка про перезапись — текстом, а не только в диалоге
            // подтверждения: до диалога ещё надо нажать, а решают, нажимать
            // ли, до него.
            ui.add_space(6.0);
            note(ui, i18n::t(lang, Key::UiMetaWipeNote), pal.text_muted);

            self.meta_status(ui);
        });
    }

    /// Какой файл разбираем: имя и размер в таблетке, кнопка выбора рядом.
    ///
    /// Таблетка — подпись, а не кнопка, и это не украшение: на путь, не
    /// похожий на кнопку, не нажимали, а у кнопки обрезанный текст целиком
    /// не показать вовсе (дефект 48 реестра).
    fn meta_file_row(&mut self, ui: &mut egui::Ui) {
        let (pal, lang, speed) = (self.palette, self.lang, self.speed);
        let busy = self.meta.busy();
        let file = self.meta.path.as_ref().map(|_| FilePill {
            name: &self.meta.file_name,
            facts: &self.meta.file_facts,
            path: &self.meta.path_display,
        });
        let clicked = file_row(ui, pal, lang, file, busy, speed);

        if clicked
            && let Some(path) = rfd::FileDialog::new()
                .add_filter(
                    self.t(Key::FilterSupported),
                    &["mp3", "jpg", "jpeg", "png", "webp", "gif", "tif", "tiff"],
                )
                .add_filter(self.t(Key::FilterAllFiles), &["*"])
                .pick_file()
        {
            let ctx = ui.ctx().clone();
            self.meta.select(path, self.lang, &ctx);
        }
    }

    /// Второй шаг: что в файле записано. Таблица, а пока её нет — то, что
    /// стоит на её месте.
    fn meta_findings(&mut self, ui: &mut egui::Ui) {
        let (pal, lang, speed) = (self.palette, self.lang, self.speed);
        let meta = &mut self.meta;

        if meta.path.is_none() {
            note(ui, i18n::t(lang, Key::UiMetaHowTo), pal.text_muted);
            return;
        }
        if !meta.readable {
            // Видео и незнакомые форматы: причина стоит там, где была бы
            // таблица, — на неё и смотрят, выбрав файл.
            if let Some(blocked) = &meta.blocked {
                banner(ui, pal, blocked, pal.state_warning);
            }
            return;
        }
        if let Some(summary) = &meta.summary {
            if summary.is_empty() {
                note(ui, i18n::t(lang, Key::UiMetaNothingFound), pal.text_secondary);
                return;
            }
            if meta_table(ui, pal, summary, lang, meta.service_open, meta.generation, speed) {
                meta.service_open = !meta.service_open;
            }
            ui.add_space(8.0);
            let what_yellow_means = if summary.personal > 0 {
                Key::UiMetaPersonalNote
            } else if meta.audio {
                Key::UiMetaTravelsNote
            } else {
                Key::UiMetaNoPersonalNote
            };
            note(ui, i18n::t(lang, what_yellow_means), pal.text_muted);
            return;
        }
        if let Some(error) = &meta.read_error {
            banner(ui, pal, error, pal.state_error);
            return;
        }
        // Файл читается впервые — или заново, сразу после очистки.
        working(ui, pal, &meta.stage);
    }

    fn meta_buttons(&mut self, ui: &mut egui::Ui) {
        let (pal, lang) = (self.palette, self.lang);
        let busy = self.meta.busy();
        // Почему кнопка выключена: пока файла нет — ровно это, а про
        // неподходящий формат — то же, что уже сказано баннером.
        let why_not = self
            .meta
            .blocked
            .as_deref()
            .unwrap_or(i18n::t(lang, Key::UiMetaPickFirst));
        let (read, wipe) = meta_actions(
            ui,
            pal,
            lang,
            self.meta.readable && !busy,
            self.meta.cleanable && !busy,
            why_not,
        );

        if read {
            let ctx = ui.ctx().clone();
            self.meta.start(MetaTask::Read, lang, &ctx);
        }
        if wipe {
            // Файл перезаписывается на месте, и вернуть метаданные будет
            // нельзя. Один вопрос дешевле безвозвратно очищенного оригинала.
            self.meta.confirming = true;
        }
    }

    /// Под кнопками: идёт очистка — индикатор, кончилась — её итог.
    ///
    /// Несостоявшееся чтение сюда не попадает: оно стоит на месте таблицы,
    /// куда и смотрят, выбрав файл.
    fn meta_status(&mut self, ui: &mut egui::Ui) {
        let pal = self.palette;
        if self.meta.running == Some(MetaTask::Clean) {
            ui.add_space(14.0);
            working(ui, pal, &self.meta.stage);
        } else if let Some((text, tone)) = &self.meta.outcome {
            ui.add_space(14.0);
            banner(ui, pal, text, tone.color(pal));
        }
    }

    /// Подтверждение перезаписи файла.
    fn confirm_modal(&mut self, ctx: &egui::Context, arrival: ModalArrival) {
        let pal = self.palette;
        arrival.veil(pal, ctx, "confirm");
        #[derive(PartialEq)]
        enum Answer {
            None,
            Yes,
            No,
        }

        let answer = egui::Modal::new(egui::Id::new("savio-confirm"))
            .backdrop_color(egui::Color32::TRANSPARENT)
            .frame(
                egui::Frame::new()
                    .fill(pal.modal_fill)
                    .stroke(egui::Stroke::new(1.0, pal.border_subtle))
                    .corner_radius(egui::CornerRadius::same(theme::RADIUS_CARD))
                    .inner_margin(egui::Margin::same(24)),
            )
            .show(ctx, |ui| {
                ui.set_width(400.0_f32.min(ctx.content_rect().width() - 48.0));

                ui.label(
                    egui::RichText::new(self.t(Key::UiMetaOverwriteTitle))
                        .heading()
                        .strong()
                        .color(pal.text_primary),
                );
                ui.add_space(8.0);
                ui.label(
                    egui::RichText::new(self.t(Key::UiMetaOverwriteText))
                        .color(pal.text_secondary),
                );
                ui.add_space(8.0);
                ui.add(
                    egui::Label::new(
                        egui::RichText::new(&self.meta.path_display)
                            .small()
                            .color(pal.text_muted),
                    )
                    .truncate(),
                );

                ui.add_space(18.0);
                ui.horizontal(|ui| {
                    const GAP: f32 = 10.0;
                    ui.spacing_mut().item_spacing.x = GAP;
                    let width = (ui.available_width() - GAP) / 2.0;

                    if ui
                        .add(
                            egui::Button::new(self.t(Key::UiCancel))
                                .min_size(egui::vec2(width, theme::CONTROL_HEIGHT)),
                        )
                        .clicked()
                    {
                        return Answer::No;
                    }
                    if ui
                        .add(
                            egui::Button::new(self.t(Key::UiDelete))
                                .min_size(egui::vec2(width, theme::CONTROL_HEIGHT)),
                        )
                        .clicked()
                    {
                        return Answer::Yes;
                    }
                    Answer::None
                })
                .inner
            });
        arrival.apply(ctx, &answer.response);

        // Esc и щелчок мимо — это отказ. Трактовать их как согласие на
        // необратимую операцию нельзя.
        let dismissed = answer.should_close();
        match answer.inner {
            Answer::Yes => {
                self.meta.confirming = false;
                self.meta.start(MetaTask::Clean, self.lang, ctx);
            }
            Answer::No => self.meta.confirming = false,
            Answer::None if dismissed => self.meta.confirming = false,
            Answer::None => {}
        }
    }

    /// Окно «О программе»: здесь то, что делают его кнопки, а само окно
    /// рисует [`about_window`].
    fn about_modal(&mut self, ctx: &egui::Context, arrival: ModalArrival) {
        let pal = self.palette;
        arrival.veil(pal, ctx, "about");

        // «Скопировано» гаснет само, как у журнала, и кадр к сроку так же
        // приходится просить: без ввода egui окно не перерисовывает, и
        // подпись висела бы до первого движения мыши.
        let now = ctx.input(|i| i.time);
        let copied_left = self
            .about_copied_at
            .map(|at| COPIED_NOTICE_SECS - (now - at))
            .filter(|left| *left > 0.0);
        match copied_left {
            Some(left) => ctx.request_repaint_after(std::time::Duration::from_secs_f64(left)),
            None => self.about_copied_at = None,
        }

        let window = about_window(pal, ctx, self.lang, self.speed, copied_left.is_some());
        arrival.apply(ctx, &window.response);

        // Как у списка метаданных: окно ничего не делает и запереть в нём
        // нечем, поэтому Esc и щелчок мимо закрывают его как обычно.
        let mut close = window.should_close();
        match window.inner {
            // Аллокация здесь — по нажатию, а не в кадре.
            Some(AboutAction::Write) => open_url(&feedback_mailto()),
            Some(AboutAction::Copy) => {
                ctx.copy_text(FEEDBACK_EMAIL.to_owned());
                self.about_copied_at = Some(now);
                // Этот кадр подпись уже не застал — нужен следующий.
                ctx.request_repaint();
            }
            Some(AboutAction::Project) => open_url(PROJECT_URL),
            Some(AboutAction::Changelog) => open_url(CHANGELOG_URL),
            // «О программе» при этом закрывается: два окна поверх завесы
            // выглядели бы стопкой, а второе из них — и вовсе загадкой.
            Some(AboutAction::Welcome) => {
                close = true;
                self.welcome_open = true;
            }
            Some(AboutAction::Close) => close = true,
            None => {}
        }
        if close {
            self.about_open = false;
            self.about_copied_at = None;
        }
    }
}

/// Что нажали в окне «О программе».
#[derive(Clone, Copy)]
enum AboutAction {
    Write,
    Copy,
    Project,
    Changelog,
    /// Открыть приветствие заново. Второй вход в него помимо кнопки «?»:
    /// человек, которому надо вспомнить, как всё устроено, идёт в
    /// «О программе» — там же и остальные объяснения.
    Welcome,
    Close,
}

/// Какое издание приветствия в этой версии программы.
///
/// Метка «показали» хранит номер издания (`binaries::welcome_seen`), и
/// приветствие с номером больше записанного при запуске показывается ещё
/// раз — тем, кто закрыл прежнее. Поднимать номер, когда приветствие
/// рассказывает о Savio заметно другое, а не при правке запятой: повторный
/// показ стоит человеку лишнего окна на запуске.
///
/// Первое издание — три шага загрузки (до 0.37.0), второе — обзор всех
/// разделов.
const WELCOME_EDITION: u32 = 2;

/// Что нажали в приветствии.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum WelcomeAction {
    /// «Начать»: закрыть и остаться там, где был.
    Start,
    /// Карточка раздела: закрыть и открыть его, у «Машины» — нужную половину.
    Open(Tab, Option<MachineTab>),
}

/// Промежуток между карточками разделов в приветствии — и по ширине, и по
/// высоте.
const WELCOME_GAP: f32 = 12.0;

/// Окно приветствия: что такое Savio и все его разделы по группам рельса.
///
/// Свободной функцией, как и `about_window`, ради проверок кадром без окна:
/// помещается ли оно в окно 520×420, назван ли в нём каждый пункт рельса
/// и открывает ли его карточка то, что обещает.
fn welcome_window(
    pal: theme::Palette,
    ctx: &egui::Context,
    lang: Lang,
    groups: &[String; 3],
    speed: f32,
) -> egui::ModalResponse<Option<WelcomeAction>> {
    let width = welcome_width(ctx.content_rect().width());

    egui::Modal::new(egui::Id::new("savio-welcome"))
        .backdrop_color(egui::Color32::TRANSPARENT)
        .frame(
            egui::Frame::new()
                .fill(pal.modal_fill)
                .stroke(egui::Stroke::new(1.0, pal.border_subtle))
                .corner_radius(egui::CornerRadius::same(theme::RADIUS_CARD))
                .inner_margin(egui::Margin::same(24)),
        )
        .show(ctx, |ui| {
            ui.set_width(width);
            let mut action = None;

            ui.horizontal(|ui| {
                ui.spacing_mut().item_spacing.x = 9.0;
                ui.label(
                    egui::RichText::new("Savio")
                        .font(theme::display(21.0))
                        .color(pal.text_primary),
                );
                let (dot, _) =
                    ui.allocate_exact_size(egui::vec2(9.0, 9.0), egui::Sense::hover());
                ui.painter().circle_filled(dot.center(), 4.5, pal.accent);
            });
            ui.add_space(10.0);
            ui.label(
                egui::RichText::new(i18n::t(lang, Key::WelcomeTitle))
                    .font(theme::display(22.0))
                    .color(pal.text_primary),
            );
            ui.add_space(6.0);
            note(ui, i18n::t(lang, Key::WelcomeNote), pal.text_secondary);
            ui.add_space(16.0);

            // Разделы — в прокрутке с потолком по высоте. В окне 420 точек
            // они в неё не помещаются, и без потолка окно вырастало выше
            // экрана: заголовок уходил за верхнюю кромку, «Начать» — за
            // нижнюю, и приветствие, которое нельзя ни дочитать, ни закрыть
            // кнопкой, превращалось из объяснения в препятствие. Числом, а не
            // остатком: прокрутка внутри растущего контейнера берёт высоту
            // от его прошлого кадра и схлопывается (дефект 27).
            // Потолок прокрутки считается от того, что уже занято, а не
            // выбирается числом на глаз: заголовок с пояснением занимает
            // разное место на разных языках и при разной ширине окна, и
            // зашитый запас разъехался бы с ними при первом же переводе.
            // `min_rect` здесь уже настоящий: шапка окна нарисована выше.
            const BUTTON_BLOCK: f32 = 16.0 + theme::CTA_HEIGHT + 6.0;
            let inner = (ctx.content_rect().height() - 56.0).max(200.0);
            let room = (inner - ui.min_rect().height() - BUTTON_BLOCK).max(80.0);
            ui.scope(|ui| {
                // Полоса прокрутки видна и в покое, когда разделы не
                // помещаются. У плавающей полосы egui в покое её нет вовсе,
                // а штатное затухание у кромки рисуется цветом фона — над
                // пустым промежутком между группами оно невидимо. Так и
                // вышло в окне 645×520: обрез пришёлся ровно между группами,
                // и «Рядом» с двумя разделами пропала без следа, а окно
                // выглядело законченным. Полоса плавающая, места не
                // занимает, и раскладку разделов это не трогает.
                ui.spacing_mut().scroll.dormant_handle_opacity = 0.6;
                egui::ScrollArea::vertical()
                    .auto_shrink([false, true])
                    .max_height(room)
                    .show(ui, |ui| {
                        ui.set_width(width);
                        if let Some((tab, half)) = welcome_sections(ui, pal, lang, groups, speed)
                        {
                            action = Some(WelcomeAction::Open(tab, half));
                        }
                    });
            });

            // «Начать» — под прокруткой, а не в ней, и это не для вида: оно
            // же и растит модалку. Примерочный проход берёт высоту окна из
            // `default_area_size` (400 точек), прокрутка в неё вписывается,
            // а не переполняет, — и модалка, у которой в прокрутке лежит
            // всё, так и осталась бы в 400 точек при окне любого размера
            // (задача 69: так прятало свои кнопки «О программе»).
            ui.add_space(16.0);
            ui.horizontal(|ui| {
                ui.spacing_mut().item_spacing.x = 14.0;
                if accent_button(
                    ui,
                    pal,
                    i18n::t(lang, Key::WelcomeStart),
                    140.0,
                    true,
                    "",
                ) {
                    action = Some(WelcomeAction::Start);
                }
                ui.add(
                    egui::Label::new(
                        egui::RichText::new(i18n::t(lang, Key::WelcomeOnce))
                            .small()
                            .color(pal.text_muted),
                    )
                    .wrap(),
                );
            });

            action
        })
}

/// Наибольшая ширина содержимого приветствия.
const WELCOME_WIDTH: f32 = 620.0;

/// Ширина содержимого приветствия в окне шириной `window`.
///
/// От окна, как у «О программе»: фиксированная вылезла бы за кромку окна
/// минимального размера. Вычитаются и поля рамки (24 с каждой стороны), и
/// её кромка: без последней модалка выходила за кромку окна ровно на два
/// пикселя — незаметно глазом, но проверка размера это ловит, и правильно
/// делает.
fn welcome_width(window: f32) -> f32 {
    WELCOME_WIDTH.min(window - 52.0)
}

/// Сколько места нужно строке «что это даёт» в карточке раздела.
///
/// Снято замером, а не выбрано на глаз: при 160 точках самая длинная из
/// строк на любом из трёх языков укладывается в четыре строки, при 150
/// армянская «Сейчас» занимает уже пять (замер 2026-09-24). Уже этого
/// карточка не бывает ни в одной из раскладок: по нему выбирается, стоять
/// ли группам колонками (`welcome_sections`), а в строках по две карточка
/// и в самом узком окне шире. Правка перевода сдвигает число, и держит его
/// `the_welcome_cards_stay_readable`.
const PITCH_MIN_WIDTH: f32 = 160.0;

/// Кружок со значком раздела в карточке приветствия.
const WELCOME_BADGE: f32 = 26.0;
/// Промежуток между кружком и названием раздела.
const WELCOME_BADGE_GAP: f32 = 10.0;

/// Шрифт названия раздела в карточке приветствия.
///
/// Функцией, а не на месте: по нему же меряет название проверка
/// `the_welcome_cards_stay_readable`, и своя копия в ней разъехалась бы
/// с карточкой при первой правке.
fn welcome_title_font() -> egui::FontId {
    theme::bold(14.0)
}

/// Разделы в приветствии: группы рельса и по карточке на каждый пункт.
///
/// Состав и порядок берутся у самого рельса (`NAV`), а не своим списком:
/// раздел, появившийся в рельсе, появляется и здесь. Раскладок две. В
/// широком окне группа — колонка, и три колонки стоят рядом: так
/// приветствие ниже и помещается без прокрутки в окно по умолчанию.
/// Когда карточке в колонке не остаётся [`PITCH_MIN_WIDTH`] под текст,
/// группа становится строкой: подпись, под ней карточки по две в ряд.
///
/// Возвращает раздел, по карточке которого щёлкнули.
fn welcome_sections(
    ui: &mut egui::Ui,
    pal: theme::Palette,
    lang: Lang,
    groups: &[String; 3],
    speed: f32,
) -> Option<(Tab, Option<MachineTab>)> {
    // Промежутки здесь все заданы явно: у темы они по 9 точек на всё
    // подряд, а подписи группы положено стоять ближе к своим карточкам,
    // чем к чужим.
    ui.spacing_mut().item_spacing.y = 0.0;
    let mut picked = None;

    let margin = theme::inner_frame(pal).total_margin().sum().x;
    let columns =
        welcome_cell_width(ui.available_width(), NAV.len()) - margin >= PITCH_MIN_WIDTH;
    if columns {
        welcome_cells::<{ NAV.len() }>(ui, |ui, g| nav_group_label(ui, pal, &groups[g]));
        let rows = NAV.iter().map(|(_, items)| items.len()).max().unwrap_or(0);
        for row in 0..rows {
            ui.add_space(if row == 0 { 6.0 } else { WELCOME_GAP });
            let cells = std::array::from_fn::<_, { NAV.len() }, _>(|g| NAV[g].1.get(row));
            picked = picked.or(welcome_row(ui, pal, lang, cells, speed));
        }
    } else {
        for (g, (group, (_, items))) in groups.iter().zip(NAV).enumerate() {
            if g > 0 {
                ui.add_space(18.0);
            }
            nav_group_label(ui, pal, group);
            for (row, chunk) in items.chunks(WELCOME_PER_ROW).enumerate() {
                ui.add_space(if row == 0 { 6.0 } else { WELCOME_GAP });
                let cells = std::array::from_fn::<_, WELCOME_PER_ROW, _>(|i| chunk.get(i));
                picked = picked.or(welcome_row(ui, pal, lang, cells, speed));
            }
        }
    }
    picked
}

/// Сколько карточек в ряду, когда группы разделов стоят строками.
///
/// Две, и третьей раскладки «по одной» нет: даже в самом узком окне
/// (520 точек) у карточки из пары под текст остаётся больше
/// [`PITCH_MIN_WIDTH`] — это проверяет `the_welcome_cards_stay_readable`.
const WELCOME_PER_ROW: usize = 2;

/// Ряд карточек разделов: равной ширины и равной высоты.
///
/// Высота — по самой длинной строке «что это даёт» в ряду: строки разной
/// длины, и без выравнивания низ ряда шёл бы лесенкой. Поэтому строки
/// раскладываются заранее, до первой карточки, и рисуются потом ровно
/// теми же раскладками — мерить одно, а рисовать другое значило бы
/// разъехаться на пиксель при первой же правке шрифта.
///
/// Пустая ячейка (`None`) оставляет своё место пустым: карточки соседних
/// рядов обязаны стоять друг под другом.
fn welcome_row<const N: usize>(
    ui: &mut egui::Ui,
    pal: theme::Palette,
    lang: Lang,
    cells: [Option<&NavItem>; N],
    speed: f32,
) -> Option<(Tab, Option<MachineTab>)> {
    let text = welcome_cell_width(ui.available_width(), N)
        - theme::inner_frame(pal).total_margin().sum().x;
    let font = egui::TextStyle::Small.resolve(ui.style());
    // Строку egui берёт во владение, как у любой подписи, — а раскладка
    // кэшируется по самой строке, так что в покое кадр считает только хеш.
    // Приветствие к тому же на экране редко и недолго.
    let mut pitches = cells.map(|item| {
        item.map(|item| {
            ui.painter().layout(
                i18n::t(lang, item.pitch).to_owned(),
                font.clone(),
                pal.text_muted,
                text,
            )
        })
    });
    let height = pitches
        .iter()
        .flatten()
        .map(|pitch| pitch.size().y)
        .fold(0.0, f32::max);

    let mut picked = None;
    welcome_cells::<N>(ui, |ui, i| {
        if let (Some(item), Some(pitch)) = (cells[i], pitches[i].take())
            && welcome_card(ui, pal, lang, item, pitch, height, speed)
        {
            picked = Some((item.tab, item.half));
        }
    });
    picked
}

/// Ширина одной из `n` ячеек ряда шириной `width`.
fn welcome_cell_width(width: f32, n: usize) -> f32 {
    (width - WELCOME_GAP * n.saturating_sub(1) as f32) / n as f32
}

/// Кладёт рядом `N` ячеек равной ширины и рисует в каждой своё.
///
/// Ширина задаётся ячейке с обеих сторон — по той же причине, что у колонок
/// `download_tab`: `allocate_ui_with_layout` двигает курсор на то, что занял
/// потомок, и без нижней границы короткая ячейка съехала бы к соседке.
///
/// Раскладка ячейки — `top_down(Min)`, и не `ui.columns`: тот отдаёт
/// колонкам `top_down_justified`, а `Label` переносит выключку раскладки
/// в выключку **текста** — абзац растягивается пробелами до кромки, и
/// посреди фразы зияет дыра в полслова (Правило 4).
fn welcome_cells<const N: usize>(ui: &mut egui::Ui, mut add: impl FnMut(&mut egui::Ui, usize)) {
    let cell = welcome_cell_width(ui.available_width(), N);
    ui.horizontal_top(|ui| {
        ui.spacing_mut().item_spacing.x = WELCOME_GAP;
        for i in 0..N {
            ui.allocate_ui_with_layout(
                egui::vec2(cell, 0.0),
                egui::Layout::top_down(egui::Align::Min),
                |ui| {
                    ui.set_min_width(cell);
                    ui.set_max_width(cell);
                    add(ui, i);
                },
            );
        }
    });
}

/// Карточка раздела в приветствии: значок, как в рельсе, название и строка
/// «что это даёт». Щёлкается целиком; возвращает `true`, если щёлкнули.
///
/// Вложенной карточкой, а не кнопкой, — как строка места в погоде: у
/// кнопки egui одна строка текста, а здесь их несколько. Отклик под
/// курсором — акцентная кромка: без него карточка читалась бы надписью,
/// а не переходом.
///
/// `pitch` — строка, уже разложенная по ширине карточки, а `height` —
/// высота самой длинной в ряду: до неё карточка добирается пустым местом.
fn welcome_card(
    ui: &mut egui::Ui,
    pal: theme::Palette,
    lang: Lang,
    item: &NavItem,
    pitch: Arc<egui::Galley>,
    height: f32,
    speed: f32,
) -> bool {
    let name = i18n::t(lang, item.label);

    let frame = theme::inner_frame(pal).show(ui, |ui| {
        ui.set_width(ui.available_width());
        // Выделяемые подписи съедали бы щелчок по карточке.
        ui.style_mut().interaction.selectable_labels = false;
        // Ряд значка с названием — высотой ровно в кружок, и задана она
        // явно: `ui.horizontal` берёт высоту элемента управления, и
        // название встало бы по её середине, а не по середине кружка.
        ui.allocate_ui_with_layout(
            egui::vec2(ui.available_width(), WELCOME_BADGE),
            egui::Layout::left_to_right(egui::Align::Center),
            |ui| {
                ui.spacing_mut().item_spacing.x = WELCOME_BADGE_GAP;
                let (badge, _) = ui.allocate_exact_size(
                    egui::vec2(WELCOME_BADGE, WELCOME_BADGE),
                    egui::Sense::hover(),
                );
                // Значок тот же, что у пункта рельса: по нему раздел потом
                // и находится в свёрнутом рельсе, где подписей нет.
                let painter = ui.painter();
                let radius = WELCOME_BADGE / 2.0;
                painter.circle_filled(badge.center(), radius, pal.accent_soft);
                painter.circle_stroke(badge.center(), radius, egui::Stroke::new(1.0, pal.accent));
                nav_icon(
                    painter,
                    egui::Rect::from_center_size(badge.center(), egui::vec2(14.0, 14.0)),
                    item.icon,
                    pal.accent_text,
                );
                ui.add(
                    egui::Label::new(
                        egui::RichText::new(name)
                            .font(welcome_title_font())
                            .color(pal.text_primary),
                    )
                    .truncate(),
                );
            },
        );
        ui.add_space(6.0);
        let short = height - pitch.size().y;
        ui.add(egui::Label::new(pitch));
        if short > 0.0 {
            ui.add_space(short);
        }
    });

    let rect = frame.response.rect;
    let response = ui
        .interact(rect, frame.response.id.with("open"), egui::Sense::click())
        .on_hover_cursor(egui::CursorIcon::PointingHand);
    // Карточка нарисована рамкой с подписями, и кнопкой для диктора она
    // становится только так. По этому же имени её находит и проверка.
    response.widget_info(|| egui::WidgetInfo::labeled(egui::WidgetType::Button, true, name));
    let touch =
        ui.ctx()
            .animate_bool_with_time(response.id, response.hovered(), motion::TOUCH * speed);
    if touch > 0.0 {
        ui.painter().rect_stroke(
            rect,
            egui::CornerRadius::same(theme::RADIUS_INNER),
            egui::Stroke::new(
                1.0,
                motion::mix(egui::Color32::TRANSPARENT, pal.accent, touch),
            ),
            egui::StrokeKind::Inside,
        );
    }
    response.clicked()
}

/// Окно «О программе»: что за приложение, кто сделал, куда писать.
///
/// Свободной функцией, а не методом, ради тестов раскладки
/// (`the_about_window_fits_the_smallest_window`,
/// `the_about_buttons_stay_in_sight`): `SavioApp` в тесте не собрать —
/// конструктор читает настройки с диска и спрашивает версии у внешних
/// программ, — а окну из всего состояния нужно одно: горит ли «Скопировано».
fn about_window(
    pal: theme::Palette,
    ctx: &egui::Context,
    lang: Lang,
    speed: f32,
    copied: bool,
) -> egui::ModalResponse<Option<AboutAction>> {
    // Ширина от окна, как у списка метаданных: фиксированная вылезла бы
    // за кромку окна минимального размера.
    let width = 440.0_f32.min(ctx.content_rect().width() - 48.0);

    egui::Modal::new(egui::Id::new("savio-about"))
        .backdrop_color(egui::Color32::TRANSPARENT)
        .frame(
            egui::Frame::new()
                .fill(pal.modal_fill)
                .stroke(egui::Stroke::new(1.0, pal.border_subtle))
                .corner_radius(egui::CornerRadius::same(theme::RADIUS_CARD))
                .inner_margin(egui::Margin::same(24)),
        )
        .show(ctx, |ui| {
            ui.set_width(width);
            let mut action = None;

            ui.label(
                egui::RichText::new(i18n::t(lang, Key::UiAbout))
                    .heading()
                    .strong()
                    .color(pal.text_primary),
            );
            ui.add_space(8.0);

            // Описание и сведения — в прокрутке, и потолок ей задаётся
            // числом, а не остатком. Без потолка `Modal` растёт по
            // содержимому, и в окне 420 точек высотой оно уходит за верхнюю
            // и нижнюю кромки разом, причём молча — модалка просто нарисована
            // больше экрана. Числом, а не `available_height()`, по той же
            // причине, что у журнала (дефект 27): прокрутка внутри растущего
            // контейнера берёт высоту от его прошлого кадра и схлопывается.
            // Считается потолок так же, как у приветствия: от уже занятого
            // заголовком и от рядов кнопок, которые встанут под прокруткой, —
            // теми же числами, какими ряды кладутся ниже. 56 — это рамка
            // модалки (поля и кромка, 50) и по три точки до краёв окна.
            const ABOVE_ROWS: f32 = 12.0;
            const BETWEEN_ROWS: f32 = 18.0;
            let step = ui.spacing().item_spacing.y;
            let rows = ABOVE_ROWS + BETWEEN_ROWS + 2.0 * (step + theme::CONTROL_HEIGHT);
            let inner = (ctx.content_rect().height() - 56.0).max(200.0);
            let room = (inner - ui.min_rect().height() - rows).max(80.0);
            ui.scope(|ui| {
                // Полоса прокрутки видна и в покое — по той же причине, что
                // у приветствия: в окне 520×420 под кромкой остаются целые
                // пункты («Показать приветствие» и подпись к кнопкам), а обрез,
                // пришедшийся на промежуток между строками, выглядел бы концом
                // окна.
                ui.spacing_mut().scroll.dormant_handle_opacity = 0.6;
                egui::ScrollArea::vertical()
                    .auto_shrink([false, true])
                    .max_height(room)
                    .show(ui, |ui| {
                        ui.set_width(width);
                        note(ui, i18n::t(lang, ABOUT_TEXT), pal.text_secondary);
                        ui.add_space(14.0);

                        // Строки те же, что в карточках «Машины»: одинаковые
                        // по смыслу таблицы должны и выглядеть одинаково.
                        stat_row(ui, pal, lang, i18n::t(lang, Key::UiVersion), Some(VERSION));
                        stat_row(
                            ui,
                            pal,
                            lang,
                            i18n::t(lang, Key::UiDeveloper),
                            Some(i18n::t(lang, AUTHOR)),
                        );
                        stat_row(ui, pal, lang, i18n::t(lang, Key::UiLicense), Some(LICENSE));
                        stat_row(
                            ui,
                            pal,
                            lang,
                            i18n::t(lang, Key::UiFeedback),
                            Some(FEEDBACK_EMAIL),
                        );

                        // «Показать приветствие» — своей строкой, а не пятой
                        // кнопкой в ряду: впятером они не помещаются в окно
                        // минимальной ширины (проверка
                        // `the_about_window_fits_the_smallest_window` поймала
                        // это сразу). Перенос ряда тут не годится —
                        // `pill_button` заворачивает кнопку в `ui.scope`, а тот
                        // сообщает занятое место задним числом, мимо всей
                        // логики переноса.
                        ui.add_space(12.0);
                        if accent_button(
                            ui,
                            pal,
                            i18n::t(lang, Key::UiShowWelcome),
                            ui.available_width(),
                            true,
                            "",
                        ) {
                            action = Some(AboutAction::Welcome);
                        }
                        ui.add_space(6.0);
                        note(ui, i18n::t(lang, Key::UiAboutButtonsNote), pal.text_muted);
                    });
            });

            // Ряды кнопок — под прокруткой, а не в ней, и это не только ради
            // того, чтобы «Написать» было видно в окне 520×420 без прокрутки.
            // Они же и растят модалку: примерочный проход берёт высоту окна
            // из `default_area_size` (400 точек), прокрутка в неё вписывается,
            // а не переполняет, — и пока кнопки лежали в прокрутке, модалка
            // так и оставалась в 400 точек в окне любого размера, а «Написать»
            // и «Закрыть» — под кромкой прокрутки даже во весь экран
            // (задача 69).
            ui.add_space(ABOVE_ROWS);
            ui.horizontal(|ui| {
                ui.spacing_mut().item_spacing.x = 10.0;
                // Копирование рядом с «Написать» обязательно, а не для
                // удобства. Без почтовой программы `mailto:` ошибки не даёт:
                // Windows в лучшем случае спрашивает, чем открыть адрес, а
                // `xdg-open` может и промолчать (Правило 6) — Savio об этом
                // не узнает. Скопированный адрес работает везде: в веб-почте,
                // на телефоне.
                if pill_button(ui, i18n::t(lang, Key::UiWrite), speed)
                    .on_hover_text(i18n::t(lang, Key::UiWriteHint))
                    .clicked()
                {
                    action = Some(AboutAction::Write);
                }
                if pill_button(ui, i18n::t(lang, Key::UiCopyAddress), speed).clicked() {
                    action = Some(AboutAction::Copy);
                }
                if copied {
                    ui.label(
                        egui::RichText::new(i18n::t(lang, Key::UiCopied))
                            .small()
                            .color(pal.state_success),
                    );
                }
            });

            ui.add_space(BETWEEN_ROWS);
            ui.horizontal(|ui| {
                ui.spacing_mut().item_spacing.x = 10.0;
                // Полный адрес — в подсказке: куда ведёт кнопка, лучше знать
                // до щелчка, а не по открывшемуся браузеру.
                if pill_button(ui, i18n::t(lang, Key::UiProjectPage), speed)
                    .on_hover_text(PROJECT_URL)
                    .clicked()
                {
                    action = Some(AboutAction::Project);
                }
                if pill_button(ui, i18n::t(lang, Key::UiWhatChanged), speed)
                    .on_hover_text(CHANGELOG_URL)
                    .clicked()
                {
                    action = Some(AboutAction::Changelog);
                }
                ui.with_layout(egui::Layout::right_to_left(egui::Align::Center), |ui| {
                    if pill_button(ui, i18n::t(lang, Key::UiClose), speed).clicked() {
                        action = Some(AboutAction::Close);
                    }
                });
            });

            action
        })
}

/// Адрес для кнопки «Написать»: почта для отзывов и версия в теме письма.
///
/// Версия в теме — ровно за тем же, за чем она стоит в заголовке раздела: жалобу
/// «не качает» без номера сборки воспроизводить нечем, а переспрашивать
/// его вторым письмом — терять половину ответов. Тема только из ASCII и
/// с `%20` вместо пробела: `mailto:` — это адрес, и сырой пробел в нём
/// почтовые программы понимают по-разному.
fn feedback_mailto() -> String {
    format!("mailto:{FEEDBACK_EMAIL}?subject=Savio%20{VERSION}")
}

// ---------------------------------------------------------------------------
// Вкладка «История»
// ---------------------------------------------------------------------------

impl SavioApp {
    /// Половина «Состав»: что за машина и в каком она состоянии.
    ///
    /// Опрос запускается сам при первом открытии вкладки. Кнопка с пустым
    /// экраном была бы лишним шагом: сюда заходят ровно за ответом, и
    /// нажимать «Проверить», чтобы его увидеть, незачем.
    fn system_tab(&mut self, ui: &mut egui::Ui) {
        if !self.system.asked {
            let ctx = ui.ctx().clone();
            let gpu = self.gpu.clone();
            self.system.start(gpu, self.lang, &ctx);
        }

        // Две колонки, как у остальных разделов: отчёт — в главной, два
        // пояснения — справа. Пояснения не про отдельный пункт, а про отчёт
        // целиком, и в общем потоке карточек их пролистывали бы вместе
        // с последним пунктом.
        const GAP: f32 = 18.0;
        if ui.available_width() < theme::TWO_COLUMN_MIN {
            self.system_main(ui);
            ui.add_space(GAP);
            system_rail(ui, self.palette, self.lang);
            return;
        }

        let total = ui.available_width();
        let rail = theme::RAIL_WIDTH;
        let main = total - rail - GAP;
        let (pal, lang) = (self.palette, self.lang);

        ui.horizontal_top(|ui| {
            ui.spacing_mut().item_spacing.x = GAP;
            for (width, which) in [(main, true), (rail, false)] {
                ui.allocate_ui_with_layout(
                    egui::vec2(width, 0.0),
                    egui::Layout::top_down(egui::Align::Min),
                    |ui| {
                        // Ширина с обеих сторон — по той же причине, что
                        // у колонок `download_tab`.
                        ui.set_min_width(width);
                        ui.set_max_width(width);
                        if which {
                            self.system_main(ui);
                        } else {
                            system_rail(ui, pal, lang);
                        }
                    },
                );
            }
        });
    }

    /// Главная колонка «Состава»: итог, кнопки и пункты отчёта.
    fn system_main(&mut self, ui: &mut egui::Ui) {
        let pal = self.palette;
        self.system_header(ui);
        ui.add_space(16.0);

        if self.system.busy {
            note(ui, &self.system.stage, pal.text_secondary);
            return;
        }

        // Язык снимаем до заимствования отчёта: `self.t` — это заём `self`
        // целиком, а он уже занят ссылкой на отчёт.
        let lang = self.lang;
        let Some(report) = &self.system.report else {
            // Приёмник умер, а отчёт не приехал: поток сорвался, не отправив
            // ничего. Показать «в порядке» тут нельзя — мы ничего не узнали.
            note(ui, i18n::t(lang, Key::UiSystemNoAnswer), pal.text_muted);
            return;
        };

        for check in &report.checks {
            check_card(ui, pal, check, lang);
            ui.add_space(8.0);
        }
    }

    /// Шапка вкладки: общий итог и две кнопки.
    fn system_header(&mut self, ui: &mut egui::Ui) {
        let pal = self.palette;
        let mut again = false;
        let mut save = false;
        let lang = self.lang;

        theme::card(ui, pal, |ui| {
            // Итог — обычной строкой с переносом: он длинный, а в
            // горизонтальной раскладке egui положил бы его в одну строку
            // любой длины и срезал кромкой окна.
            match &self.system.report {
                Some(report) => note(ui, &report.headline(lang), pal.text_secondary),
                None => note(ui, i18n::t(lang, Key::UiSystemAbout), pal.text_secondary),
            }

            ui.add_space(6.0);
            // Оговорка про то, чего в отчёте нет. Без неё «нет данных»
            // у половины пунктов выглядит поломкой Savio, а не отказом
            // системы: человеку неоткуда узнать, что температуры и SMART
            // без прав администратора недоступны в принципе.
            note(ui, i18n::t(lang, Key::UiSystemNote), pal.text_muted);

            ui.add_space(14.0);
            ui.horizontal(|ui| {
                ui.spacing_mut().item_spacing.x = 10.0;
                again = ui
                    .add_enabled(!self.system.busy, pill(i18n::t(lang, Key::UiCheckAgain)))
                    .clicked();
                save = ui
                    .add_enabled(
                        !self.system.busy && self.system.report.is_some(),
                        pill(i18n::t(lang, Key::UiSaveReport)),
                    )
                    .on_disabled_hover_text(i18n::t(lang, Key::UiWaitForPoll))
                    .clicked();
            });

            if let Some((text, tone)) = &self.system.saved {
                ui.add_space(10.0);
                note(ui, text, tone.color(pal));
            }
        });

        if again {
            let ctx = ui.ctx().clone();
            let gpu = self.gpu.clone();
            self.system.start(gpu, lang, &ctx);
        }
        if save {
            self.save_report();
        }
    }

    /// Кладёт отчёт в файл.
    ///
    /// Запись идёт прямо здесь, в кадре, и это тот редкий случай, когда так
    /// можно: диалог выбора файла всё равно останавливает всё окно на время
    /// своего показа, а сам отчёт — несколько килобайт текста. Заводить ради
    /// него поток значило бы усложнить код там, где выигрыша нет.
    fn save_report(&mut self) {
        let lang = self.lang;
        let Some(report) = &self.system.report else {
            return;
        };

        let Some(path) = rfd::FileDialog::new()
            .set_file_name(i18n::t(lang, Key::UiReportFileName))
            .add_filter(i18n::t(lang, Key::FilterTextFile), &["txt"])
            .save_file()
        else {
            // Диалог закрыли — это не отказ и не ошибка, говорить не о чем.
            return;
        };

        self.system.saved = Some(match std::fs::write(&path, report.to_text(lang)) {
            Ok(()) => (
                i18n::fill(
                    i18n::t(lang, Key::UiReportSaved),
                    &[&path.display().to_string()],
                ),
                Tone::Good,
            ),
            Err(err) => (
                i18n::fill(
                    i18n::t(lang, Key::UiReportSaveFailed),
                    &[&err.to_string()],
                ),
                Tone::Bad,
            ),
        });
    }

    /// Половина «Сейчас»: что происходит с машиной прямо сейчас.
    ///
    /// Две колонки, как у загрузки и «Телефона»: числа — в главной, оверлей
    /// и питание — справа. Прежде питание стояло над числами, и причина была
    /// честная: это единственный орган управления на всей половине, и ждать
    /// первого замера, чтобы его показать, незачем. Правая колонка сохраняет
    /// обе половины этой причины — питание видно сразу и без прокрутки, —
    /// а числа, ради которых половину и открывают, встают первыми.
    fn monitor_tab(&mut self, ui: &mut egui::Ui) {
        const GAP: f32 = 18.0;
        if ui.available_width() < theme::TWO_COLUMN_MIN {
            self.monitor_main(ui);
            ui.add_space(GAP);
            self.monitor_rail(ui);
            return;
        }

        let total = ui.available_width();
        let rail = theme::RAIL_WIDTH;
        let main = total - rail - GAP;

        ui.horizontal_top(|ui| {
            ui.spacing_mut().item_spacing.x = GAP;
            for (width, which) in [(main, true), (rail, false)] {
                ui.allocate_ui_with_layout(
                    egui::vec2(width, 0.0),
                    egui::Layout::top_down(egui::Align::Min),
                    |ui| {
                        // Ширина с обеих сторон — по той же причине, что
                        // у колонок `download_tab`.
                        ui.set_min_width(width);
                        ui.set_max_width(width);
                        if which {
                            self.monitor_main(ui);
                        } else {
                            self.monitor_rail(ui);
                        }
                    },
                );
            }
        });
    }

    /// Правая колонка «Сейчас»: оверлей и питание.
    ///
    /// Рисуется и тогда, когда первого замера ещё нет: главная колонка
    /// в это время показывает «жду замер», а переключатели от него
    /// не зависят вовсе.
    fn monitor_rail(&mut self, ui: &mut egui::Ui) {
        self.monitor_header(ui);
        ui.add_space(14.0);
        self.power_card(ui);
    }

    /// Главная колонка «Сейчас»: процессор, память, ввод-вывод, процессы.
    fn monitor_main(&mut self, ui: &mut egui::Ui) {
        let pal = self.palette;
        let speed = self.speed;
        let lang = self.lang;
        // Фаза считается один раз на вкладку: карточек с графиком две, и
        // разъехавшись на кадр они ехали бы вразнобой.
        let phase = self.monitor.trace_phase(ui.ctx(), speed);

        let Some(sample) = &self.monitor.sample else {
            note(
                ui,
                i18n::t(lang, Key::UiMonitorWarmingUp),
                pal.text_secondary,
            );
            return;
        };

        let cpu = i18n::t(lang, Key::HwCpu);
        let memory = i18n::t(lang, Key::HwMemory);

        // Процессор и память рядом, когда есть место: это два одинаковых по
        // устройству показателя, и читать их проще парой, чем лестницей.
        // Порог — по ширине главной колонки, а не окна: колонка теперь делит
        // строку с правой, и две карточки по 280 точек — наименьшее, при
        // котором число с подписью встают в ряд.
        const PAIR_MIN: f32 = 280.0 * 2.0 + 12.0;
        if ui.available_width() >= PAIR_MIN {
            ui.columns(2, |columns| {
                metric_card(
                    &mut columns[0],
                    pal,
                    cpu,
                    &sample.cpu,
                    Plot::new(&self.monitor.cpu_trace, pal.accent, phase),
                    speed,
                    Some(i18n::t(lang, Key::UiCpuWholeMachine)),
                );
                metric_card(
                    &mut columns[1],
                    pal,
                    memory,
                    &sample.mem,
                    Plot::new(&self.monitor.mem_trace, pal.state_success, phase),
                    speed,
                    None,
                );
            });
        } else {
            metric_card(
                ui,
                pal,
                cpu,
                &sample.cpu,
                Plot::new(&self.monitor.cpu_trace, pal.accent, phase),
                speed,
                Some(i18n::t(lang, Key::UiCpuWholeMachine)),
            );
            ui.add_space(12.0);
            metric_card(
                ui,
                pal,
                memory,
                &sample.mem,
                Plot::new(&self.monitor.mem_trace, pal.state_success, phase),
                speed,
                None,
            );
        }
        ui.add_space(12.0);

        io_card(ui, pal, sample, self.gpu.as_ref(), lang);
        ui.add_space(12.0);

        process_card(ui, pal, &sample.procs, lang);
    }

    /// Карточка «Питание»: чем машина питается сейчас и как это переключить.
    ///
    /// Нажатия не спрашивают подтверждения, и это решение: схема и режим
    /// питания меняются мгновенно и обратимо одним нажатием соседней кнопки.
    /// Переспрашивать Savio положено перед необратимым (так устроена чистка
    /// метаданных), а лишний вопрос там, где отменить можно тут же, только
    /// приучает жать «Да» не глядя.
    fn power_card(&mut self, ui: &mut egui::Ui) {
        let pal = self.palette;
        let busy = self.power.busy;
        let mut refresh = false;
        let mut change = None;
        let speed = self.speed;
        let lang = self.lang;

        theme::card(ui, pal, |ui| {
            // Ряду задаётся высота, и это не украшение вёрстки. `with_layout`
            // отдаёт потомку всю оставшуюся высоту карточки, а `Align::Center`
            // в горизонтальной раскладке «считает занятой» её целиком
            // (`Placer::advance_after_rects`: expand_to_include_rect(frame_rect)
            // «pretend we used whole frame»). Внутри прокрутки остаток — это
            // почти весь экран, поэтому строка заголовка уезжает в середину
            // карточки, а сама карточка вырастает во весь экран. Ровно так
            // сейчас и выглядят соседние `check_card` и `metric_card` —
            // это задача 42 реестра, и повторять её здесь незачем.
            // `ui.horizontal` этой беды лишён именно тем, что задаёт высоту
            // (`interact_size.y`).
            //
            // Кнопка при этом кладётся первой, справа налево: обрезаемый
            // заголовок иначе занял бы всю ширину и кнопка налезла бы на него.
            ui.allocate_ui_with_layout(
                egui::vec2(ui.available_width(), theme::CONTROL_HEIGHT),
                egui::Layout::right_to_left(egui::Align::Center),
                |ui| {
                    refresh = ui
                        .add_enabled(!busy, pill(i18n::t(lang, Key::UiRefresh)))
                        .on_disabled_hover_text(i18n::t(lang, Key::UiWaitForSystem))
                        .clicked();
                    ui.with_layout(egui::Layout::left_to_right(egui::Align::Center), |ui| {
                        ui.add(
                            egui::Label::new(
                                egui::RichText::new(i18n::t(lang, Key::UiPower))
                                    .font(theme::display(17.0))
                                    .color(pal.text_primary),
                            )
                            .truncate(),
                        );
                    });
                },
            );

            if let Some(trouble) = &self.power.state.trouble {
                ui.add_space(6.0);
                note(ui, trouble, pal.text_muted);
            }

            // Ответа ещё нет. Молчать здесь нельзя: пустая карточка с одним
            // заголовком выглядит поломкой, а не ожиданием.
            if self.power.state.is_blank() && self.power.state.trouble.is_none() {
                ui.add_space(6.0);
                note(ui, i18n::t(lang, Key::UiPowerAsking), pal.text_secondary);
            }

            if !self.power.state.plans.is_empty() {
                ui.add_space(14.0);
                field_label(ui, pal, i18n::t(lang, Key::UiPowerPlan));
                // Раскладка с переносом, а не дорожка сегментов: названий
                // бывает и шесть (вендорские схемы), длина у них любая, а
                // в окне шириной 520 даже три не встают в строку.
                //
                // Выключается ряд целиком, снаружи: `add_enabled_ui` на
                // каждой кнопке сломал бы перенос (см. `choice_pill`).
                ui.add_enabled_ui(!busy, |ui| {
                    ui.horizontal_wrapped(|ui| {
                        ui.spacing_mut().item_spacing = egui::vec2(8.0, 8.0);
                        for plan in &self.power.state.plans {
                            let on = self.power.state.active == Some(plan.id);
                            // Нажатие на уже активную ничего не значит:
                            // просить систему переключиться на то, что и так
                            // работает, — бодрый отчёт о безделье.
                            if choice_pill(ui, pal, &plan.name, on, speed).clicked() && !on {
                                change = Some(power::Change::Plan(plan.id));
                            }
                        }
                    });
                });
            }

            if let PowerModes::Known { effective, .. } = self.power.state.modes {
                ui.add_space(14.0);
                field_label(ui, pal, i18n::t(lang, Key::UiPowerMode));
                ui.add_enabled_ui(!busy, |ui| {
                    ui.horizontal_wrapped(|ui| {
                        ui.spacing_mut().item_spacing = egui::vec2(8.0, 8.0);
                        for mode in PowerMode::ALL {
                            // Четвёртый режим (ползунок Windows 10) рисуем,
                            // только если система в нём и есть: предложить
                            // пункт, которого нет в параметрах Windows 11,
                            // значит показать список, которого человек
                            // у себя не видел, а скрыть действующий —
                            // соврать о машине.
                            let on = effective == Some(mode);
                            if !mode.offered() && !on {
                                continue;
                            }
                            if choice_pill(ui, pal, mode.label(lang), on, speed).clicked() && !on {
                                change = Some(power::Change::Mode(mode));
                            }
                        }
                    });
                });

                // Ни одна кнопка не выбрана — это надо объяснить, иначе ряд
                // выглядит сломанным.
                if effective.is_none() {
                    ui.add_space(8.0);
                    note(ui, i18n::t(lang, Key::UiPowerUnknownMode), pal.text_muted);
                }

                if !self.power.hint.is_empty() {
                    ui.add_space(8.0);
                    note(ui, &self.power.hint, pal.state_warning);
                }
            }

            // Итог последнего нажатия — последней строкой карточки, у самых
            // кнопок: сказанное про переключение должно стоять там, где
            // переключали.
            if let Some((text, tone)) = &self.power.outcome {
                ui.add_space(12.0);
                note(ui, text, tone.color(pal));
            }
        });

        // Обе просьбы исполняем после карточки: внутри замыкания `self`
        // одолжен на чтение, и завести оттуда поток не выйдет.
        if refresh {
            let ctx = ui.ctx().clone();
            self.power.start(lang, &ctx);
        }
        if let Some(change) = change {
            let ctx = ui.ctx().clone();
            self.power.change(change, lang, &ctx);
        }
    }

    /// Шапка половины: чем монитор занят и как включить оверлей.
    fn monitor_header(&mut self, ui: &mut egui::Ui) {
        let pal = self.palette;
        let lang = self.lang;
        theme::card(ui, pal, |ui| {
            note(ui, i18n::t(lang, Key::UiMonitorNote), pal.text_secondary);

            ui.add_space(6.0);
            // Та же оговорка, что и в «Составе», и по той же причине: без неё
            // отсутствие видеокарты в списке выглядит недоделкой Savio,
            // а не отказом системы.
            note(ui, i18n::t(lang, Key::UiMonitorNoGpuLoad), pal.text_muted);

            ui.add_space(14.0);
            checkbox(
                ui,
                pal,
                &mut self.monitor.overlay,
                i18n::t(lang, Key::UiOverlay),
                true,
            );

            ui.add_space(6.0);
            let passthrough = checkbox(
                ui,
                pal,
                &mut self.monitor.passthrough,
                i18n::t(lang, Key::UiOverlayPassthrough),
                self.monitor.overlay,
            );
            passthrough.on_disabled_hover_text(i18n::t(lang, Key::UiOverlayFirst));

            ui.add_space(10.0);
            note(ui, i18n::t(lang, Key::UiOverlayNote), pal.text_muted);
        });
    }

    /// Одна строка истории.
    ///
    /// Карточка на каждую запись, а не одна на весь список: строки отделяются
    /// друг от друга сами, без разделителей, и список любой длины выглядит
    /// одинаково. Своей прокрутки здесь нет — вкладка целиком лежит в общей,
    /// и вложенная полоса рядом с внешней только мешала бы.
    fn history_card(&self, ui: &mut egui::Ui, entry: &HistoryEntry) -> Option<PathBuf> {
        let pal = self.palette;
        let mut open_at = None;

        theme::inner_frame(pal).show(ui, |ui| {
            // Без этого карточка сжалась бы по ширине имени файла: у
            // короткого имени получилась бы узкая полоска посреди окна.
            ui.set_width(ui.available_width());

            // Имя длинное почти всегда (yt-dlp кладёт в него название
            // ролика целиком) — обрезаем, полное показывается по наведению.
            //
            // `on_hover_text` для этого звать НЕ надо, хотя рука тянется:
            // у `Label` есть `show_tooltip_when_elided`, по умолчанию
            // включённый, и обрезанная метка сама вешает подсказку с
            // полным текстом. Свой вызов её не заменяет, а добавляет
            // вторую: egui считает подсказки на виджет и ставит их одна
            // под другой — выходит две коробки с одним и тем же именем.
            // Ни сборка, ни тесты этого не видят.
            ui.add(
                egui::Label::new(
                    egui::RichText::new(&entry.name)
                        .font(theme::bold(14.0))
                        .color(pal.text_primary),
                )
                .truncate(),
            );

            // Папки нет — значит, и открывать нечего: показываем только имя.
            let Some(dir) = &entry.dir else {
                return;
            };

            ui.add_space(8.0);
            // Раскладка справа налево: кнопка кладётся первой и занимает
            // ровно себя, а пути достаётся остаток строки. Слева направо
            // обрезаемая метка забирает всю ширину, и кнопка налезает на
            // неё — в колонке шириной 340 путь и «Открыть папку» вместе
            // не помещаются. Проверено глазами: текст уходил под кнопку.
            //
            // Высота ряда задаётся явно: `with_layout` отдал бы потомку весь
            // остаток высоты, а `Align::Center` считает его занятым целиком
            // (подробности — у `SavioApp::power_card`), и строка истории
            // растянулась бы до нижней кромки окна (дефект 42).
            ui.allocate_ui_with_layout(
                egui::vec2(ui.available_width(), theme::CONTROL_HEIGHT),
                egui::Layout::right_to_left(egui::Align::Center),
                |ui| {
                    ui.spacing_mut().item_spacing.x = 9.0;
                    // Лежит ли файл на месте, не спрашиваем: это обращение
                    // к диску, а `ui()` идёт 60 раз в секунду (Правило 1).
                    // Папку могли переименовать или унести вместе с флешкой —
                    // тогда об этом скажет проводник, и это честнее
                    // выключенной без объяснения кнопки.
                    if pill_button(ui, self.t(Key::UiOpenFolder), self.speed).clicked() {
                        open_at = Some(dir.clone());
                    }
                    // Вложенная раскладка обязательна: в `right_to_left` метка
                    // занимает ровно себя и прижимается к правому краю — без
                    // неё путь сползал бы к кнопке, а слева оставалось бы
                    // пустое место во всю ширину (та же грабля, что в
                    // `process_row`).
                    ui.with_layout(egui::Layout::left_to_right(egui::Align::Center), |ui| {
                        // Подсказку с полным путём, как и у имени выше, вешает
                        // сама обрезанная метка.
                        ui.add(
                            egui::Label::new(
                                egui::RichText::new(&entry.dir_display)
                                    .small()
                                    .color(pal.text_muted),
                            )
                            .truncate(),
                        );
                    });
                },
            );
        });

        open_at
    }
}

/// Правая колонка вкладки «Метаданные»: то, что читают до нажатия «Стереть».
///
/// Свободная функция, а не метод: обе карточки статические. Возвращает
/// `true`, когда нажали «Открыть «Загрузку»», — переход делает вызывающий.
fn metadata_rail(
    ui: &mut egui::Ui,
    pal: theme::Palette,
    lang: Lang,
    speed: f32,
    warning: Option<theme::Appear>,
    kinds: Option<theme::Appear>,
) -> bool {
    theme::card_rising(ui, pal, warning, |ui| {
        ui.horizontal(|ui| {
            ui.spacing_mut().item_spacing.x = 9.0;
            let (dot, _) = ui.allocate_exact_size(egui::vec2(9.0, 9.0), egui::Sense::hover());
            ui.painter()
                .circle_filled(dot.center(), 4.5, pal.state_warning);
            ui.add(
                egui::Label::new(
                    egui::RichText::new(i18n::t(lang, Key::UiMetaWillOverwrite))
                        .font(theme::display(17.0))
                        .color(pal.text_primary),
                )
                .truncate(),
            );
        });
        ui.add_space(8.0);
        note(
            ui,
            i18n::t(lang, Key::UiMetaWillOverwriteText),
            pal.text_secondary,
        );
        ui.add_space(6.0);
        note(ui, i18n::t(lang, Key::UiMetaKeepOriginal), pal.text_muted);
    });

    ui.add_space(14.0);

    theme::card_rising(ui, pal, kinds, |ui| {
        ui.label(
            egui::RichText::new(i18n::t(lang, Key::UiMetaSupported))
                .font(theme::display(17.0))
                .color(pal.text_primary),
        );
        ui.add_space(10.0);
        // Три строки с состоянием словами, а не ряд таблеток вперемешку:
        // в ряду «TIFF — только чтение» стояло между «GIF» и «видео», и что
        // из перечисленного умеет всё, приходилось выяснять по цвету.
        for (support, key) in [
            (Support::Full, Key::UiMetaSupportFull),
            (Support::ReadOnly, Key::UiMetaTiffReadOnly),
            (Support::NotYet, Key::UiMetaVideoNotYet),
        ] {
            support_row(ui, pal, support, i18n::t(lang, key));
            ui.add_space(4.0);
        }
        ui.add_space(8.0);
        // Чистить здесь, а вшивать — там: без указателя человек, пришедший
        // сюда за «добавить название в MP3», ушёл бы ни с чем.
        note(ui, i18n::t(lang, Key::UiMetaEmbedPointer), pal.text_muted);
        ui.add_space(10.0);
        pill_button(ui, i18n::t(lang, Key::UiMetaOpenDownload), speed).clicked()
    })
    .inner
}

/// Что Savio умеет с форматом.
#[derive(Clone, Copy)]
enum Support {
    /// Читает и стирает.
    Full,
    /// Только читает.
    ReadOnly,
    /// Пока не умеет.
    NotYet,
}

/// Строка списка форматов: кружок состояния и подпись.
///
/// Состояние сказано словами («только чтение», «пока нет»), а кружок лишь
/// повторяет его цветом: у полного — галочка, остальные пустые. Галочка
/// рисуется кистью по той же причине, что в [`chip`]: знака `✓` в наших
/// шрифтах нет, и вместо него вышел бы пустой прямоугольник.
fn support_row(ui: &mut egui::Ui, pal: theme::Palette, support: Support, text: &str) {
    const MARK: f32 = 14.0;
    let (ring, ink) = match support {
        Support::Full => (pal.state_success, pal.text_primary),
        Support::ReadOnly => (pal.state_warning, pal.text_secondary),
        Support::NotYet => (pal.border_strong, pal.text_muted),
    };

    ui.horizontal_top(|ui| {
        ui.spacing_mut().item_spacing.x = 9.0;
        // Кружок стоит против первой строки подписи, а не посередине абзаца:
        // в узкой колонке «чтение и очистка» переносится на вторую.
        let line = ui.text_style_height(&egui::TextStyle::Body);
        let (slot, _) = ui.allocate_exact_size(egui::vec2(MARK, line), egui::Sense::hover());
        let c = slot.center();
        let painter = ui.painter();
        painter.circle_stroke(c, MARK / 2.0 - 0.7, egui::Stroke::new(1.4, ring));
        if matches!(support, Support::Full) {
            let tick = egui::Stroke::new(1.4, ring);
            let at = |x: f32, y: f32| egui::pos2(c.x + (x - 0.5) * MARK, c.y + (y - 0.5) * MARK);
            painter.line_segment([at(0.3, 0.52), at(0.45, 0.67)], tick);
            painter.line_segment([at(0.45, 0.67), at(0.72, 0.36)], tick);
        }
        ui.add(egui::Label::new(egui::RichText::new(text).color(ink)).wrap());
    });
}

/// Заголовок второго шага и плашка с числом личных записей.
///
/// Число — словами, а не одним цветом: без различения цветов жёлтая строка
/// ничем не отличается от прочих. Плашка стоит справа от названия, если
/// помещается, а если нет — строкой ниже, но не поверх него (`step_fits`).
fn findings_header(ui: &mut egui::Ui, pal: theme::Palette, lang: Lang, personal: &str) {
    let title = i18n::t(lang, Key::UiMetaFileTags);
    let inline = personal.is_empty() || step_fits(ui, title, personal);
    step_header(ui, pal, 2, title, None, |ui| {
        if inline && !personal.is_empty() {
            soft_pill(ui, pal, personal, pal.state_warning, pal.warning_soft);
        }
    });
    if !inline {
        ui.add_space(6.0);
        soft_pill(ui, pal, personal, pal.state_warning, pal.warning_soft);
    }
}

/// Что показывает таблетка первого шага.
#[derive(Clone, Copy)]
struct FilePill<'a> {
    /// Имя файла без папок.
    name: &'a str,
    /// Размер и свойства с точкой впереди: «· 4.2 МБ · 3:25». Пусто, пока
    /// файл не прочитан.
    facts: &'a str,
    /// Полный путь — для подсказки.
    path: &'a str,
}

/// Первый шаг целиком: таблетка файла и кнопка выбора справа от неё.
/// Возвращает `true`, когда нажали кнопку выбора.
///
/// Кнопка кладётся первой справа налево, таблетка — после неё. Иначе
/// обрезаемая подпись занимает столько, сколько просит текст, и налезает
/// на кнопку.
fn file_row(
    ui: &mut egui::Ui,
    pal: theme::Palette,
    lang: Lang,
    file: Option<FilePill>,
    busy: bool,
    speed: f32,
) -> bool {
    let mut clicked = false;
    ui.allocate_ui_with_layout(
        egui::vec2(ui.available_width(), theme::CONTROL_HEIGHT),
        egui::Layout::right_to_left(egui::Align::Center),
        |ui| {
            // «Выбрать другой» — только когда выбирать уже есть из чего:
            // рядом с «файл не выбран» это слово звучит издёвкой, и человек
            // ищет, где же выбрать первый. Найдено глазами.
            let pick = if file.is_some() {
                Key::UiMetaPickAnother
            } else {
                Key::UiMetaPickFile
            };
            clicked = ui
                .add_enabled_ui(!busy, |ui| pill_button(ui, i18n::t(lang, pick), speed))
                .inner
                .on_hover_text(i18n::t(lang, Key::UiMetaPickHint))
                .clicked();

            file_pill(ui, pal, lang, file);
        },
    );
    clicked
}

/// Таблетка первого шага: имя файла и то, что о нём известно.
///
/// Места делятся так, чтобы имени досталась хотя бы половина: по нему
/// отвечают на вопрос, ради которого сюда смотрят, — «тот ли это файл».
/// Прежде место отмерялось сначала сведениям, и у MP3 хвост «· 4.2 МБ ·
/// 3:25 · 320 кбит/с» в окне 520 оставлял имени одну букву, а у записи на
/// час с лишним и вовсе выталкивал таблетку на кнопку (найдено ревью задачи
/// 65). Не влезают сведения — обрезаются они, а целиком они в подсказке.
///
/// Подсказка своя, а не штатная у обрезанных меток: в ней полный путь и
/// сведения, а не то же имя ещё раз, — и штатная выключена у обеих меток
/// (`show_tooltip_when_elided`), иначе коробок было бы две (дефект 22).
/// Висит подсказка на всей таблетке: рамка без собственного отклика
/// регистрируется после содержимого и потому получает наведение и над
/// подписью (`interaction.rs`, строки 286–297). Строки собраны при выборе
/// файла, а показываются лениво, через `on_hover_ui`: аргумент
/// `on_hover_text` вычислялся бы каждый кадр.
fn file_pill(ui: &mut egui::Ui, pal: theme::Palette, lang: Lang, file: Option<FilePill>) {
    let pill = egui::Frame::new()
        .stroke(egui::Stroke::new(1.0, pal.border_strong))
        .corner_radius(egui::CornerRadius::same(theme::RADIUS_PILL))
        .inner_margin(egui::Margin::symmetric(16, 7))
        .show(ui, |ui| {
            ui.with_layout(egui::Layout::left_to_right(egui::Align::Center), |ui| {
                ui.spacing_mut().item_spacing.x = 6.0;
                let Some(file) = file else {
                    ui.add(
                        egui::Label::new(
                            egui::RichText::new(i18n::t(lang, Key::UiNoFileChosen))
                                .color(pal.text_muted),
                        )
                        .truncate(),
                    );
                    return;
                };

                // Раскладка текста у egui кэшируется по самой строке, так
                // что в следующих кадрах это только хеш — как у `soft_pill`.
                let font = egui::TextStyle::Body.resolve(ui.style());
                let width = |text: &str| {
                    ui.painter()
                        .layout_no_wrap(text.to_owned(), font.clone(), egui::Color32::PLACEHOLDER)
                        .size()
                        .x
                };
                let room = ui.available_width();
                let name = width(file.name);
                let facts = if file.facts.is_empty() {
                    0.0
                } else {
                    width(file.facts) + ui.spacing().item_spacing.x
                };
                let name_room = if name + facts <= room {
                    name
                } else {
                    (room - facts).max(room * 0.5).min(name)
                };

                ui.scope(|ui| {
                    ui.set_max_width(name_room);
                    ui.add(
                        egui::Label::new(
                            egui::RichText::new(file.name).color(pal.text_secondary),
                        )
                        .truncate()
                        .show_tooltip_when_elided(false),
                    );
                });
                if !file.facts.is_empty() {
                    ui.add(
                        egui::Label::new(egui::RichText::new(file.facts).color(pal.text_muted))
                            .truncate()
                            .show_tooltip_when_elided(false),
                    );
                }
            });
        });

    if let Some(file) = file {
        pill.response.on_hover_ui(|ui| {
            ui.label(file.path);
            // Сведения — без точки-разделителя: в подсказке они стоят своей
            // строкой, а не продолжают имя.
            let facts = file.facts.trim_start_matches("· ");
            if !facts.is_empty() {
                ui.label(egui::RichText::new(facts).small().color(pal.text_muted));
            }
        });
    }
}

/// Кнопки раздела: «Прочитать снова» — на треть ширины, «Стереть всё» — на
/// остаток. Возвращает, какую нажали.
///
/// Треть, а не половина, как прежде: файл читается сам, и первая кнопка нужна
/// только проверить его ещё раз, — главное действие раздела — очистка. Треть
/// при этом — пол, а не потолок: подпись шире трети (армянская в окне 520)
/// раздвигает свою кнопку, и очистке достаётся остаток. Делить ширину заранее
/// поровну нельзя: `min_size` — лишь нижняя граница, и вторая кнопка уехала бы
/// за кромку карточки.
fn meta_actions(
    ui: &mut egui::Ui,
    pal: theme::Palette,
    lang: Lang,
    read_on: bool,
    clean_on: bool,
    why_not: &str,
) -> (bool, bool) {
    const GAP: f32 = 10.0;
    ui.horizontal(|ui| {
        ui.spacing_mut().item_spacing.x = GAP;
        let room = ui.available_width() - GAP;
        let read_width = (room / 3.0).max(meta_read_label_width(ui, lang));

        let read = ui
            .add_enabled(
                read_on,
                egui::Button::new(i18n::t(lang, Key::UiMetaReadAgain))
                    .min_size(egui::vec2(read_width, theme::CTA_HEIGHT)),
            )
            .on_disabled_hover_text(why_not)
            .clicked();
        // Акцентная заливка: это главное действие раздела. Выключенный вид
        // задан у `accent_button` явно — `ui.disable()` только глушит
        // прозрачность, и выключенная кнопка стала бы неотличима от включённой.
        let wipe = accent_button(
            ui,
            pal,
            i18n::t(lang, Key::UiMetaWipe),
            room - read_width,
            clean_on,
            why_not,
        );
        (read, wipe)
    })
    .inner
}

/// Сколько просит подпись «Прочитать снова» вместе с полями кнопки.
fn meta_read_label_width(ui: &egui::Ui, lang: Lang) -> f32 {
    let font = egui::TextStyle::Button.resolve(ui.style());
    let text = ui.painter().layout_no_wrap(
        i18n::t(lang, Key::UiMetaReadAgain).to_owned(),
        font,
        egui::Color32::PLACEHOLDER,
    );
    text.size().x + ui.spacing().button_padding.x * 2.0
}

/// Неопределённый индикатор и строка стадии под ним.
///
/// Сколько осталось, здесь неизвестно и не нужно: и чтение, и очистка
/// укладываются в доли секунды.
fn working(ui: &mut egui::Ui, pal: theme::Palette, stage: &str) {
    ui.scope(|ui| {
        ui.visuals_mut().extreme_bg_color = pal.progress_track;
        ui.add(
            egui::ProgressBar::new(0.0)
                .animate(true)
                .fill(pal.accent)
                .desired_height(8.0),
        );
    });
    if !stage.is_empty() {
        ui.add_space(8.0);
        ui.label(egui::RichText::new(stage).small().color(pal.text_secondary));
    }
}

/// Зазор между главной и правой колонками «Метаданных».
///
/// Константой, а не числом у раскладки, ради проверок ширины: самая узкая
/// главная колонка — не в окне 520, а сразу за порогом двух колонок
/// (`TWO_COLUMN_MIN` минус правая колонка и этот зазор), и тест обязан
/// считать её по тому же числу, что и раскладка.
const COLUMN_GAP: f32 = 18.0;

/// Ширина колонки подписей в таблице метаданных — как в макете.
///
/// Константой рядом с раскладкой, а не числом в вызове: по ней считает
/// проверка `the_metadata_table_fits_the_smallest_window`, а копия в тесте
/// разъехалась бы с раскладкой при первой же правке и перестала бы
/// что-либо ловить.
const META_LABEL_COLUMN: f32 = 180.0;

/// Зазор между подписью и значением в строке таблицы.
const META_COLUMN_GAP: f32 = 12.0;

/// Шрифт значения в таблице — на ступень крупнее подписи, как в макете:
/// читают значение, а подпись его только называет.
fn meta_value_font() -> egui::FontId {
    egui::FontId::new(14.0, egui::FontFamily::Proportional)
}

/// Таблица «Метаданные файла»: личное сверху и жёлтым, служебное — свёрнутой
/// строкой в конце. Возвращает `true`, когда щёлкнули по свёрнутой строке.
///
/// Жёлтый здесь не единственный признак, и это обязательно: без различения
/// цветов личная строка неотличима от прочих. Сколько их, сказано словами
/// в плашке над таблицей, а что значит жёлтый — строкой под ней.
///
/// Строки разделены зазором в точку, сквозь который видна карточка, — так
/// в макете. Скругление есть только у крайних строк, иначе в зазорах
/// проступали бы уголки.
///
/// `key` — номер выбранного файла (`MetaPanel::generation`): из него
/// строятся идентификаторы анимаций хвоста, чтобы у нового файла они
/// начинались с нуля, а не доезжали прежние.
fn meta_table(
    ui: &mut egui::Ui,
    pal: theme::Palette,
    summary: &MetaSummary,
    lang: Lang,
    open: bool,
    key: u64,
    speed: f32,
) -> bool {
    let folded = !summary.service.is_empty();
    let count = summary.rows.len();
    let tail = egui::Id::new("meta-service").with(key);
    let mut toggled = false;

    let table = ui.scope(|ui| {
        ui.spacing_mut().item_spacing.y = 1.0;
        for (i, row) in summary.rows.iter().enumerate() {
            let last = i + 1 == count && !folded;
            meta_row(
                ui,
                pal,
                &row.label,
                &row.value,
                row.personal,
                row_corners(i == 0, last),
            );
        }
        if folded {
            let fold = Fold {
                line: &summary.service_line,
                open,
                corners: row_corners(count == 0, !open),
                id: tail.with("row"),
            };
            toggled = service_row(ui, pal, lang, fold, speed);
            // Число строк — тоже в имени: перечитанный файл (после очистки
            // или смены языка) сохраняет номер, а хвост у него бывает другой
            // высоты, и раскрытие, помнящее высоту с прошлого раза, поехало
            // бы по чужой мерке.
            let id = tail.with(summary.service.len());
            collapsing_body(ui, id, open, speed, |ui| {
                ui.spacing_mut().item_spacing.y = 1.0;
                let tail = summary.service.len();
                for (i, row) in summary.service.iter().enumerate() {
                    meta_row(
                        ui,
                        pal,
                        &row.label,
                        &row.value,
                        false,
                        row_corners(false, i + 1 == tail),
                    );
                }
            });
        }
    });

    ui.painter().rect_stroke(
        table.response.rect,
        egui::CornerRadius::same(theme::RADIUS_INNER),
        egui::Stroke::new(1.0, pal.border_subtle),
        egui::StrokeKind::Inside,
    );
    toggled
}

/// Скругление строки таблицы: сверху — у первой, снизу — у последней.
fn row_corners(first: bool, last: bool) -> egui::CornerRadius {
    let (top, bottom) = (
        if first { theme::RADIUS_INNER } else { 0 },
        if last { theme::RADIUS_INNER } else { 0 },
    );
    egui::CornerRadius {
        nw: top,
        ne: top,
        sw: bottom,
        se: bottom,
    }
}

/// Строка таблицы: подпись в колонке слева, значение справа.
///
/// Значению `wrap()` обязателен: в горизонтальной раскладке egui кладёт
/// текст в одну строку любой длины, а XMP и комментарии длинные — строка
/// растянула бы карточку за кромку окна.
fn meta_row(
    ui: &mut egui::Ui,
    pal: theme::Palette,
    label: &str,
    value: &str,
    personal: bool,
    corners: egui::CornerRadius,
) {
    let (fill, ink) = if personal {
        (pal.warning_soft, pal.state_warning)
    } else {
        (pal.card_inner, pal.text_muted)
    };
    egui::Frame::new()
        .fill(fill)
        .corner_radius(corners)
        .inner_margin(egui::Margin::symmetric(14, 10))
        .show(ui, |ui| {
            ui.set_width(ui.available_width());
            ui.horizontal_top(|ui| {
                ui.spacing_mut().item_spacing.x = META_COLUMN_GAP;
                meta_label_cell(ui, label, ink);
                ui.add(
                    egui::Label::new(
                        egui::RichText::new(value)
                            .font(meta_value_font())
                            .color(pal.text_primary),
                    )
                    .wrap(),
                );
            });
        });
}

/// Подпись строки таблицы в колонке своей ширины.
///
/// Подпись переносится, а не обрезается: армянская «Օբյեկտիվի սերիական
/// համար» в колонку не влезает, и обрезанную её пришлось бы читать по
/// подсказке. `set_min_width` обязателен, хотя ширина уже запрошена, — та же
/// грабля, что у `stat_row_with`: без него значения начинались бы сразу за
/// подписью, каждое на своём месте, и колонки не вышло бы.
fn meta_label_cell(ui: &mut egui::Ui, label: &str, ink: egui::Color32) {
    ui.allocate_ui_with_layout(
        egui::vec2(META_LABEL_COLUMN, 0.0),
        egui::Layout::top_down(egui::Align::Min),
        |ui| {
            ui.set_min_width(META_LABEL_COLUMN);
            ui.set_max_width(META_LABEL_COLUMN);
            ui.add(egui::Label::new(egui::RichText::new(label).small().color(ink)).wrap());
        },
    );
}

/// Свёрнутая строка таблицы: что на ней написано и в каком она состоянии.
struct Fold<'a> {
    /// «ещё 7 — ориентация, размер кадра, XMP…».
    line: &'a str,
    open: bool,
    corners: egui::CornerRadius,
    /// Идентификатор строки — от номера выбранного файла (см. `meta_table`).
    id: egui::Id,
}

/// Свёрнутая строка служебных записей: сколько их и как называются первые.
/// Щелчок раскрывает их под ней; возвращает `true`, когда щёлкнули.
///
/// Для диктора строка — кнопка со своим именем (`widget_info`): нарисованное
/// кистью без имени не нашёл бы ни он, ни проверка кадра.
fn service_row(ui: &mut egui::Ui, pal: theme::Palette, lang: Lang, fold: Fold, speed: f32) -> bool {
    let Fold {
        line,
        open,
        corners,
        id,
    } = fold;
    const MARK: f32 = 11.0;
    const PAD_X: f32 = 14.0;
    const PAD_Y: f32 = 10.0;
    let label = i18n::t(lang, Key::UiMetaServiceRecords);

    let frame = egui::Frame::new()
        .fill(pal.card_inner)
        .corner_radius(corners)
        .inner_margin(egui::Margin::symmetric(PAD_X as i8, PAD_Y as i8))
        .show(ui, |ui| {
            ui.set_width(ui.available_width());
            // Выделяемые подписи съедали бы щелчок по строке.
            ui.style_mut().interaction.selectable_labels = false;
            ui.horizontal_top(|ui| {
                ui.spacing_mut().item_spacing.x = META_COLUMN_GAP;
                meta_label_cell(ui, label, pal.text_muted);
                // Значению — всё, кроме места под треугольник у правой кромки.
                ui.scope(|ui| {
                    ui.set_max_width((ui.available_width() - MARK - META_COLUMN_GAP).max(0.0));
                    ui.add(
                        egui::Label::new(
                            egui::RichText::new(line)
                                .font(meta_value_font())
                                .color(pal.text_secondary),
                        )
                        .wrap(),
                    );
                });
            });
        });

    let rect = frame.response.rect;
    let response = ui
        .interact(rect, id, egui::Sense::click())
        .on_hover_cursor(egui::CursorIcon::PointingHand);
    response.widget_info(|| egui::WidgetInfo::labeled(egui::WidgetType::Button, true, label));

    // Отклик под курсором — кромка, как у строки места в погоде: заливку
    // строка уже несёт, и её усиление читалось бы как выбор.
    let touch =
        ui.ctx()
            .animate_bool_with_time(response.id, response.hovered(), motion::TOUCH * speed);
    if touch > 0.0 {
        ui.painter().rect_stroke(
            rect,
            corners,
            egui::Stroke::new(
                1.0,
                motion::mix(egui::Color32::TRANSPARENT, pal.border_hover, touch),
            ),
            egui::StrokeKind::Inside,
        );
    }

    // Треугольник — кистью и тем же доворотом, что у `disclosure_row`:
    // стрелок в наших шрифтах нет. Стоит против первой строки значения.
    let line_height = ui
        .painter()
        .fonts_mut(|fonts| fonts.row_height(&meta_value_font()));
    let c = egui::pos2(
        rect.right() - PAD_X - MARK / 2.0,
        rect.top() + PAD_Y + line_height / 2.0,
    );
    let turn = motion::liquid(ui.ctx().animate_bool_with_time(
        response.id.with("turn"),
        open,
        motion::MOVE * speed,
    ));
    let (sin, cos) = (turn * std::f32::consts::FRAC_PI_2).sin_cos();
    let points = [(-2.5, -5.0), (-2.5, 5.0), (3.5, 0.0)]
        .into_iter()
        .map(|(x, y)| egui::pos2(c.x + x * cos - y * sin, c.y + x * sin + y * cos))
        .collect();
    ui.painter().add(egui::Shape::convex_polygon(
        points,
        pal.accent,
        egui::Stroke::NONE,
    ));

    response.clicked()
}

// ---------------------------------------------------------------------------
// Вкладка «Погода»
// ---------------------------------------------------------------------------

/// Ширина столбика почасового прогноза.
///
/// Под самую широкую подпись — «Сейчас» и «−12°»: уже неё столбики налезали
/// бы подписями друг на друга, а шире — на экран влезало бы меньше часов.
const HOUR_SLOT_WIDTH: f32 = 60.0;

/// Высота столбика: время, значок, температура и вероятность осадков.
const HOUR_SLOT_HEIGHT: f32 = 104.0;

/// Сторона значка погоды в столбике и в строке дня.
const SMALL_ICON: f32 = 30.0;

/// Сторона значка погоды рядом с крупной температурой.
const BIG_ICON: f32 = 64.0;

impl SavioApp {
    /// Вкладка «Погода»: место и «сейчас» слева, неделя и единицы справа.
    ///
    /// Две колонки по той же причине, что у загрузки: на неделю смотрят рядом
    /// с сегодняшней погодой, а не под ней, прокрутив экран. Ниже
    /// [`theme::TWO_COLUMN_MIN`] колонки встают друг под друга.
    fn weather_tab(&mut self, ui: &mut egui::Ui) {
        const GAP: f32 = 18.0;
        if ui.available_width() < theme::TWO_COLUMN_MIN {
            self.weather_main(ui);
            ui.add_space(GAP);
            self.weather_rail(ui);
            return;
        }

        let total = ui.available_width();
        let rail = theme::RAIL_WIDTH;
        let main = total - rail - GAP;

        ui.horizontal_top(|ui| {
            ui.spacing_mut().item_spacing.x = GAP;
            for (width, which) in [(main, true), (rail, false)] {
                ui.allocate_ui_with_layout(
                    egui::vec2(width, 0.0),
                    egui::Layout::top_down(egui::Align::Min),
                    |ui| {
                        // Ширина с обеих сторон — по той же причине, что
                        // у колонок `download_tab`.
                        ui.set_min_width(width);
                        ui.set_max_width(width);
                        if which {
                            self.weather_main(ui);
                        } else {
                            self.weather_rail(ui);
                        }
                    },
                );
            }
        });
    }

    /// Главная колонка: место, сейчас и ближайшие часы.
    fn weather_main(&mut self, ui: &mut egui::Ui) {
        self.weather_place_card(ui);
        // Пока прогноза нет, карточек под числа нет вовсе: пустые рамки
        // с прочерками читались бы как «сервер ответил пустотой», а о том,
        // что происходит на самом деле, говорит карточка места.
        if self.weather.view.is_some() {
            ui.add_space(14.0);
            self.weather_now_card(ui);
            ui.add_space(14.0);
            self.weather_hours_card(ui);
        }
    }

    /// Правая колонка: неделя, избранное и единицы.
    fn weather_rail(&mut self, ui: &mut egui::Ui) {
        if self.weather.view.is_some() {
            self.weather_days_card(ui);
            ui.add_space(14.0);
        }
        if !self.weather.favorites.is_empty() {
            self.weather_favorites_card(ui);
            ui.add_space(14.0);
        }
        self.weather_units_card(ui);
    }

    /// Карточка избранных мест.
    ///
    /// Своей карточкой справа, а не хвостом карточки места: избранное —
    /// это то, между чем переключаются, а не часть поиска, и в карточке
    /// места оно отодвигало поиск вниз на высоту своего списка.
    fn weather_favorites_card(&mut self, ui: &mut egui::Ui) {
        let pal = self.palette;
        let speed = self.speed;
        let lang = self.lang;
        let mut picked: Option<Place> = None;

        theme::card(ui, pal, |ui| {
            let panel = &self.weather;
            ui.label(
                egui::RichText::new(i18n::t(lang, Key::UiWeatherFavorites))
                    .font(theme::display(17.0))
                    .color(pal.text_primary),
            );
            ui.add_space(8.0);
            // Своими таблетками с переносом, а не дорожкой: названий бывает
            // десяток, и в колонку шириной 340 не встают даже три (см.
            // `choice_pill` про перенос).
            ui.horizontal_wrapped(|ui| {
                ui.spacing_mut().item_spacing = egui::vec2(8.0, 8.0);
                for place in &panel.favorites {
                    let on = panel
                        .place
                        .as_ref()
                        .is_some_and(|current| current.same_as(place));
                    if choice_pill(ui, pal, &place.name, on, speed).clicked() && !on {
                        picked = Some(place.clone());
                    }
                }
            });
            ui.add_space(8.0);
            note(ui, i18n::t(lang, Key::UiWeatherFavoritesNote), pal.text_muted);
        });

        if let Some(place) = picked {
            let ctx = ui.ctx().clone();
            self.weather.pick(Some(place), lang, &ctx);
            self.remember();
        }
    }

    /// Карточка места: где, когда обновлено, поиск и избранное.
    fn weather_place_card(&mut self, ui: &mut egui::Ui) {
        let pal = self.palette;
        let speed = self.speed;
        let mut refresh = false;
        let mut locate = false;
        let mut search = false;
        let mut favorite = false;
        let mut picked: Option<Place> = None;
        let lang = self.lang;

        theme::card_rising(ui, pal, self.appear(0), |ui| {
            let panel = &mut self.weather;

            // Высота ряду задаётся явно, а кнопка кладётся первой справа
            // налево — обе грабли разобраны у `SavioApp::power_card`.
            ui.allocate_ui_with_layout(
                egui::vec2(ui.available_width(), theme::CONTROL_HEIGHT),
                egui::Layout::right_to_left(egui::Align::Center),
                |ui| {
                    // «В избранном» — рядом с «Обновить», у названия места:
                    // обе кнопки про это место, а не про поиск ниже.
                    let on = panel.is_favorite();
                    let full = !on && panel.favorites.len() >= FAVORITES_LIMIT;
                    let response = ui.add_enabled_ui(panel.place.is_some() && !full, |ui| {
                        toggle_pill(
                            ui,
                            pal,
                            i18n::t(
                                lang,
                                if on {
                                    Key::UiWeatherInFavorites
                                } else {
                                    Key::UiWeatherToFavorites
                                },
                            ),
                            on,
                            speed,
                        )
                    });
                    favorite = response.inner.clicked();
                    let hint = i18n::t(
                        lang,
                        if full {
                            Key::UiWeatherFavoritesFull
                        } else if on {
                            Key::UiWeatherRemoveFavorite
                        } else {
                            Key::UiWeatherAddFavorite
                        },
                    );
                    response.response.on_hover_text(hint);

                    refresh = ui
                        .add_enabled(
                            panel.place.is_some() && !panel.busy,
                            pill(i18n::t(lang, Key::UiRefresh)),
                        )
                        .on_disabled_hover_text(i18n::t(
                            lang,
                            if panel.busy {
                                Key::UiWaitForAnswer
                            } else {
                                Key::UiPickPlaceFirst
                            },
                        ))
                        .clicked();
                    ui.with_layout(egui::Layout::left_to_right(egui::Align::Center), |ui| {
                        // Полное название показывает сама обрезанная метка
                        // (`show_tooltip_when_elided`) — своя подсказка стала
                        // бы второй коробкой (дефект 22).
                        let title = if panel.place_title.is_empty() {
                            i18n::t(lang, Key::UiWeatherNoPlace)
                        } else {
                            panel.place_title.as_str()
                        };
                        ui.add(
                            egui::Label::new(
                                egui::RichText::new(title)
                                    .font(theme::display(21.0))
                                    .color(pal.text_primary),
                            )
                            .truncate(),
                        );
                    });
                },
            );

            ui.add_space(4.0);
            // Когда получены числа — всегда, если они есть: без этой строки не
            // понять, свежий прогноз на экране или вчерашний.
            if let Some(view) = &panel.view {
                note(ui, &view.updated, pal.text_muted);
            }
            if panel.busy {
                note(ui, &panel.stage, pal.text_secondary);
            } else if panel.place.is_none() && panel.error.is_none() {
                note(
                    ui,
                    i18n::t(lang, Key::UiWeatherNoPlaceNote),
                    pal.text_muted,
                );
            }
            if panel.located {
                // Молча подставленный чужой город хуже отсутствия функции:
                // цифры правдоподобны, и им верят. Поэтому откуда место
                // взялось, сказано прямо — и там же, под названием, а не
                // ниже у кнопки: читают его, глядя на чужой город.
                //
                // Одной строкой, а не прежним абзацем: макет v2 просил
                // короче, и просьба честная — абзац пролистывали. Но
                // показывается строка по-прежнему только тогда, когда место
                // вправду взято по IP: постоянная оговорка у кнопки стала бы
                // шумом и перестала бы читаться ровно тогда, когда нужна.
                note(ui, i18n::t(lang, Key::UiWeatherVpnShort), pal.text_muted);
            }
            if let Some(error) = &panel.error {
                ui.add_space(10.0);
                // Старые числа при этом остаются на экране — жёлтым, а не
                // красным: работать с ними можно, просто они не свежие, и
                // строка «Обновлено в …» выше говорит, насколько.
                let color = if panel.view.is_some() {
                    pal.state_warning
                } else {
                    pal.state_error
                };
                banner(ui, pal, error, color);
            }

            ui.add_space(14.0);
            field_label(ui, pal, i18n::t(lang, Key::UiWeatherFindCity));
            ui.allocate_ui_with_layout(
                egui::vec2(ui.available_width(), theme::CONTROL_HEIGHT),
                egui::Layout::right_to_left(egui::Align::Center),
                |ui| {
                    // Обе кнопки кладутся первыми справа налево, поле — в
                    // остаток: «Найти» и «Определить по IP» — два способа
                    // сказать одно и то же «где я», и стоят они одной строкой.
                    locate = ui
                        .add_enabled(!panel.busy, pill(i18n::t(lang, Key::UiWeatherLocateByIp)))
                        .on_hover_text(i18n::t(lang, Key::UiWeatherLocateHint))
                        .on_disabled_hover_text(i18n::t(lang, Key::UiWaitForAnswer))
                        .clicked();
                    search |= ui
                        .add_enabled(!panel.searching, pill(i18n::t(lang, Key::UiWeatherFind)))
                        .clicked();
                    let field = ui.add_sized(
                        [ui.available_width(), theme::CONTROL_HEIGHT],
                        egui::TextEdit::singleline(&mut panel.query)
                            .hint_text(i18n::t(lang, Key::UiWeatherSearchHint))
                            .text_color(pal.text_primary)
                            .margin(egui::Margin::symmetric(14, 6)),
                    );
                    // Enter в поле — то же, что «Найти»: руки уже на клавиатуре.
                    if field.lost_focus() && ui.input(|i| i.key_pressed(egui::Key::Enter)) {
                        search = true;
                    }
                },
            );

            if panel.searching {
                ui.add_space(8.0);
                note(ui, i18n::t(lang, Key::UiWeatherSearching), pal.text_secondary);
            }
            if let Some((text, tone)) = &panel.search_note {
                ui.add_space(8.0);
                note(ui, text, tone.color(pal));
            }
            if let Some(results) = &panel.results {
                ui.add_space(8.0);
                for (place, detail) in results.iter().zip(&panel.result_details) {
                    if place_row(ui, pal, &place.name, detail, speed) {
                        picked = Some(place.clone());
                    }
                    ui.add_space(6.0);
                }
            }

        });

        // Всё исполняем после карточки: внутри замыкания `self` одолжен,
        // и завести оттуда поток или записать настройки не выйдет.
        let ctx = ui.ctx().clone();
        let lang = self.lang;
        if refresh {
            let place = self.weather.place.clone();
            self.weather.start(place, false, lang, &ctx);
        }
        if locate {
            self.weather.pick(None, lang, &ctx);
        }
        if search {
            self.weather.search(lang, &ctx);
        }
        if let Some(place) = picked {
            self.weather.pick(Some(place), lang, &ctx);
            self.remember();
        }
        if favorite && self.weather.toggle_favorite() {
            self.remember();
        }
    }

    /// Карточка «сейчас»: значок, температура и подробности.
    fn weather_now_card(&self, ui: &mut egui::Ui) {
        let pal = self.palette;
        let lang = self.lang;
        let missing = i18n::t(lang, WEATHER_MISSING);
        let Some(view) = &self.weather.view else {
            return;
        };

        theme::card_rising(ui, pal, self.appear(1), |ui| {
            // Температура с описанием — слева, подробности — справа через
            // разделитель, когда карточке хватает ширины. Списком под
            // температурой они оставляли пустой всю правую половину широкой
            // карточки, а глаз, дочитав «пасмурно», упирался в пустоту и
            // спускался за влажностью на строку ниже. В узком окне порядок
            // прежний: колонкой.
            const SIDE: f32 = 280.0;
            const BESIDE_MIN: f32 = SIDE + 320.0;
            let beside = ui.available_width() >= BESIDE_MIN;

            let headline = |ui: &mut egui::Ui| {
                ui.horizontal(|ui| {
                    ui.spacing_mut().item_spacing.x = 14.0;
                    let (icon, _) = ui.allocate_exact_size(
                        egui::vec2(BIG_ICON, BIG_ICON),
                        egui::Sense::hover(),
                    );
                    weather_icon(pal, ui.painter(), icon, view.sky, view.night);

                    // Своя вертикальная раскладка: в горизонтальной egui вытянул
                    // бы описание в одну строку за кромку окна (см. `preview_row`).
                    ui.vertical(|ui| {
                        ui.spacing_mut().item_spacing.y = 2.0;
                        ui.label(
                            egui::RichText::new(&view.temperature)
                                .font(theme::display(56.0))
                                .color(pal.text_primary),
                        );
                        if let Some(description) = view.description {
                            ui.add(
                                egui::Label::new(
                                    egui::RichText::new(description).color(pal.text_primary),
                                )
                                .truncate(),
                            );
                        }
                        if let Some(feels) = &view.feels_like {
                            ui.add(
                                egui::Label::new(
                                    egui::RichText::new(feels)
                                        .small()
                                        .color(pal.text_secondary),
                                )
                                .truncate(),
                            );
                        }
                    });
                });
            };
            // Воздух — продолжение той же таблицы, а не отдельный блок под
            // карточкой: положенный под весь ряд, он начинал свою колонку
            // значений от левого края, и в одной карточке стояли две таблицы
            // с разными отступами.
            let details = |ui: &mut egui::Ui| {
                for (label, value) in &view.rows {
                    stat_row_with(ui, pal, label, value.as_deref(), missing);
                }
                ui.add_space(10.0);
                if view.air.is_empty() {
                    // Частичный успех говорит о себе сам: пропавшие строки без
                    // объяснения выглядели бы недоделкой вкладки.
                    note(ui, i18n::t(lang, Key::UiWeatherNoAir), pal.text_muted);
                } else {
                    field_label(ui, pal, i18n::t(lang, Key::UiWeatherAirQuality));
                    for (label, value) in &view.air {
                        stat_row_with(ui, pal, label, value.as_deref(), missing);
                    }
                }
            };

            if beside {
                ui.horizontal_top(|ui| {
                    ui.spacing_mut().item_spacing.x = 18.0;
                    ui.allocate_ui_with_layout(
                        egui::vec2(SIDE, 0.0),
                        egui::Layout::top_down(egui::Align::Min),
                        |ui| {
                            ui.set_min_width(SIDE);
                            ui.set_max_width(SIDE);
                            headline(ui);
                        },
                    );
                    // Разделитель рисуется после колонки подробностей, а не
                    // `ui.separator()` на своём месте: ряд растёт по ходу
                    // раскладки, и в ту минуту его высота — высота одной
                    // температуры. Черта обрывалась у «ощущается как», хотя
                    // таблица справа шла ещё вдвое ниже.
                    let (gap, _) =
                        ui.allocate_exact_size(egui::vec2(1.0, 0.0), egui::Sense::hover());
                    let column = ui.vertical(|ui| details(ui)).response.rect;
                    ui.painter().vline(
                        gap.center().x,
                        column.y_range(),
                        ui.visuals().widgets.noninteractive.bg_stroke,
                    );
                });
            } else {
                headline(ui);
                ui.add_space(12.0);
                details(ui);
            }
        });
    }

    /// Карточка почасового прогноза.
    fn weather_hours_card(&self, ui: &mut egui::Ui) {
        let pal = self.palette;
        let lang = self.lang;
        let Some(view) = &self.weather.view else {
            return;
        };

        theme::card_rising(ui, pal, self.appear(2), |ui| {
            ui.label(
                egui::RichText::new(i18n::t(lang, Key::UiWeatherTwoDays))
                    .font(theme::display(17.0))
                    .color(pal.text_primary),
            );
            ui.add_space(10.0);

            if view.hours.is_empty() {
                note(ui, i18n::t(lang, Key::UiWeatherNoHours), pal.text_muted);
                return;
            }

            // Только горизонтальная прокрутка: сорок восемь столбиков в ряд
            // иначе растянули бы содержимое за кромку окна и утащили за собой
            // соседние подписи. Вертикальной прокрутки у неё нет, так что
            // колесо мыши по-прежнему листает саму вкладку, а внутренней
            // высоты, которая схлопывалась бы (дефект 27), здесь не заводится.
            egui::ScrollArea::horizontal()
                .id_salt("weather-hours")
                .show(ui, |ui| {
                    ui.horizontal(|ui| {
                        ui.spacing_mut().item_spacing.x = 6.0;
                        for hour in &view.hours {
                            hour_slot(ui, pal, hour);
                        }
                    });
                });

            // Рамка вокруг текущего часа и синее число под столбиком —
            // два условных знака подряд, и ни один из них не подписан.
            // Одна строка снимает оба вопроса разом.
            ui.add_space(8.0);
            note(ui, i18n::t(lang, Key::UiWeatherHoursLegend), pal.text_muted);
        });
    }

    /// Карточка недельного прогноза.
    fn weather_days_card(&self, ui: &mut egui::Ui) {
        let pal = self.palette;
        let lang = self.lang;
        let Some(view) = &self.weather.view else {
            return;
        };

        theme::card_rising(ui, pal, self.appear(1), |ui| {
            ui.label(
                egui::RichText::new(i18n::t(lang, Key::UiWeatherWeek))
                    .font(theme::display(17.0))
                    .color(pal.text_primary),
            );
            ui.add_space(8.0);

            if view.days.is_empty() {
                note(ui, i18n::t(lang, Key::UiWeatherNoDays), pal.text_muted);
                return;
            }
            for day in &view.days {
                day_row(ui, pal, day);
            }
            // Что значок под курсором рассказывает погоду словами, из самого
            // значка не следует: подсказку ищут только у того, что выглядит
            // недосказанным, а ряд дней выглядит законченным.
            ui.add_space(8.0);
            note(ui, i18n::t(lang, Key::UiWeatherDaysLegend), pal.text_muted);
        });
    }

    /// Карточка единиц.
    ///
    /// Видна без единого щелчка, хотя единицы запоминаются между запусками, —
    /// но и прятать тут нечего: выбранная единица стоит у каждого числа
    /// вкладки, и забытым выбором она не станет.
    fn weather_units_card(&mut self, ui: &mut egui::Ui) {
        let pal = self.palette;
        let speed = self.speed;
        let mut units = self.weather.units;
        let step = if self.weather.view.is_some() { 2 } else { 1 };
        let lang = self.lang;

        theme::card_rising(ui, pal, self.appear(step), |ui| {
            ui.label(
                egui::RichText::new(i18n::t(lang, Key::UiWeatherUnits))
                    .font(theme::display(17.0))
                    .color(pal.text_primary),
            );
            ui.add_space(10.0);

            // Подписи сегментов берутся у домена: две копии «мм рт. ст.»
            // разъехались бы. `map` у массива не выделяет памяти.
            labelled_row(ui, pal, i18n::t(lang, Key::UiWeatherTemperature), |ui| {
                if let Some(temp) = segment_track(
                    ui,
                    pal,
                    egui::Id::new("track:weather-temp"),
                    speed,
                    units.temp,
                    &TempUnit::ALL.map(|unit| (unit, unit.label())),
                    false,
                ) {
                    units.temp = temp;
                }
            });
            ui.add_space(10.0);
            labelled_row(ui, pal, i18n::t(lang, Key::WeatherWind), |ui| {
                if let Some(wind) = segment_track(
                    ui,
                    pal,
                    egui::Id::new("track:weather-wind"),
                    speed,
                    units.wind,
                    &WindUnit::ALL.map(|unit| (unit, unit.label(lang))),
                    false,
                ) {
                    units.wind = wind;
                }
            });
            ui.add_space(10.0);
            labelled_row(ui, pal, i18n::t(lang, Key::WeatherPressure), |ui| {
                if let Some(pressure) = segment_track(
                    ui,
                    pal,
                    egui::Id::new("track:weather-pressure"),
                    speed,
                    units.pressure,
                    &PressureUnit::ALL.map(|unit| (unit, unit.label(lang))),
                    false,
                ) {
                    units.pressure = pressure;
                }
            });
        });

        if self.weather.set_units(units, lang) {
            self.remember();
        }
    }
}

impl SavioApp {
    /// Экран «Телефон»: раздача слева, передачи справа.
    ///
    /// Колонки по той же причине, что у погоды: на список передач смотрят
    /// рядом с адресом, пока телефон отправляет, а не под ним, прокрутив
    /// экран. Ниже [`theme::TWO_COLUMN_MIN`] колонки встают друг под друга.
    fn phone_tab(&mut self, ui: &mut egui::Ui) {
        const GAP: f32 = 18.0;

        // Пока раздача идёт, над обеими колонками стоит полоса: папка
        // открыта для сети. Постоянная, а не баннер об ошибке, — это не
        // беда, а то, о чём человек обязан знать всё время, пока это верно.
        // Над колонками, а не внутри карточки: она про экран целиком, и в
        // узкой колонке читалась бы по три слова в строке.
        if self.share.running() {
            let pal = self.palette;
            banner(
                ui,
                pal,
                i18n::t(self.lang, Key::UiShareOpenWarning),
                pal.state_warning,
            );
            ui.add_space(GAP);
        }

        if ui.available_width() < theme::TWO_COLUMN_MIN {
            self.share_card(ui);
            ui.add_space(GAP);
            self.transfers_card(ui);
            return;
        }

        let total = ui.available_width();
        let rail = theme::RAIL_WIDTH;
        let main = total - rail - GAP;

        ui.horizontal_top(|ui| {
            ui.spacing_mut().item_spacing.x = GAP;
            for (width, which) in [(main, true), (rail, false)] {
                ui.allocate_ui_with_layout(
                    egui::vec2(width, 0.0),
                    egui::Layout::top_down(egui::Align::Min),
                    |ui| {
                        // Ширина с обеих сторон — по той же причине, что
                        // у колонок `download_tab`.
                        ui.set_min_width(width);
                        ui.set_max_width(width);
                        if which {
                            self.share_card(ui);
                        } else {
                            self.transfers_card(ui);
                        }
                    },
                );
            }
        });
    }

    /// Карточка раздачи: папка, кнопка, адрес с QR-кодом и кто подключился.
    fn share_card(&mut self, ui: &mut egui::Ui) {
        let pal = self.palette;
        let speed = self.speed;
        let now = ui.ctx().input(|i| i.time);
        let mut toggle = false;
        let mut choose_dir = false;
        let mut open_dir_clicked = false;
        let mut picked: Option<usize> = None;
        let mut copy = false;
        let lang = self.lang;

        // Какая папка будет раздана, если нажать сейчас.
        let dir = self.share.own_dir.clone().or_else(|| self.out_dir.clone());

        theme::card_rising(ui, pal, self.appear(0), |ui| {
            let panel = &self.share;
            let running = panel.running();

            // Высота ряду задаётся явно, а плашка кладётся первой справа
            // налево — обе грабли разобраны у `SavioApp::power_card`.
            ui.allocate_ui_with_layout(
                egui::vec2(ui.available_width(), theme::CONTROL_HEIGHT),
                egui::Layout::right_to_left(egui::Align::Center),
                |ui| {
                    let (key, color) = match panel.state {
                        ShareState::Off => (Key::UiShareOff, pal.text_muted),
                        ShareState::Starting => (Key::UiShareStarting, pal.text_secondary),
                        ShareState::On => (Key::UiShareOn, pal.state_success),
                    };
                    status_pill(ui, pal, i18n::t(lang, key), color);
                    ui.with_layout(egui::Layout::left_to_right(egui::Align::Center), |ui| {
                        ui.add(
                            egui::Label::new(
                                egui::RichText::new(i18n::t(lang, Key::TabPhone))
                                    .font(theme::display(21.0))
                                    .color(pal.text_primary),
                            )
                            .truncate(),
                        );
                    });
                },
            );
            ui.add_space(4.0);
            note(ui, i18n::t(lang, Key::UiShareNote), pal.text_secondary);

            // Два направления словами и стрелками. Из одного абзаца выше не
            // видно, что передача идёт в обе стороны: половина людей так и
            // не догадывалась, что с телефона можно отправить на компьютер.
            //
            // Стрелки «→» и «←» есть в Figtree, первом шрифте семейства, —
            // проверено по таблице `cmap`, а не на глаз: отсутствующий знак
            // рисуется пустым прямоугольником молча.
            ui.add_space(12.0);
            direction_cards(
                ui,
                pal,
                lang,
                [
                    (Key::UiShareToPhone, Key::UiShareToPhoneNote),
                    (Key::UiShareToComputer, Key::UiShareToComputerNote),
                ],
            );

            ui.add_space(16.0);
            step_header(ui, pal, 1, i18n::t(lang, Key::UiShareFolder), None, |_| {});
            ui.add_space(8.0);
            ui.allocate_ui_with_layout(
                egui::vec2(ui.available_width(), theme::CONTROL_HEIGHT),
                egui::Layout::right_to_left(egui::Align::Center),
                |ui| {
                    // Обе кнопки кладутся первыми в раскладке справа налево,
                    // а путь — во вложенную раскладку слева направо: иначе
                    // обрезаемая подпись занимает столько, сколько просит
                    // текст, и налезает на соседа справа.
                    open_dir_clicked = ui
                        .add_enabled(dir.is_some(), pill(i18n::t(lang, Key::UiOpen)))
                        .on_hover_text(i18n::t(lang, Key::UiShareOpenFolderHint))
                        .clicked();
                    choose_dir = ui
                        .add_enabled_ui(!running, |ui| {
                            pill_button(ui, i18n::t(lang, Key::UiShareChangeFolder), speed)
                        })
                        .inner
                        .on_hover_text(i18n::t(lang, Key::UiSharePickFolderHint))
                        .on_disabled_hover_text(i18n::t(lang, Key::UiShareFolderLocked))
                        .clicked();

                    let display = if running {
                        panel.serving_display.as_str()
                    } else if panel.own_dir.is_some() {
                        panel.own_dir_display.as_str()
                    } else {
                        self.out_dir_display.as_str()
                    };
                    let color = if dir.is_some() {
                        pal.text_secondary
                    } else {
                        pal.state_warning
                    };
                    // Путь — подпись, а не кнопка, и это не украшение.
                    // У `Label` есть `show_tooltip_when_elided`: обрезанный
                    // путь сам показывает себя целиком по наведению. У
                    // `Button` такого свойства нет вовсе, и пока путь жил
                    // на кнопке, полного пути не показывал никто — узнать
                    // его можно было только заново открыв диалог выбора
                    // (дефект 48 реестра). Заодно кнопка выбора перестала
                    // быть невидимой: на путь, не похожий на кнопку, не
                    // нажимали.
                    // Таблетка вокруг пути — из макета, и она же отделяет
                    // значение от подписей вокруг. Растягивается на остаток
                    // строки, и это ровно то, что нужно: вложенная раскладка
                    // слева направо внутри раскладки справа налево занимает
                    // всё между ними (см. Правило 4 про `status_pill`) —
                    // здесь эта особенность работает на нас, а не против.
                    egui::Frame::new()
                        .stroke(egui::Stroke::new(1.0, pal.border_strong))
                        .corner_radius(egui::CornerRadius::same(theme::RADIUS_PILL))
                        .inner_margin(egui::Margin::symmetric(16, 7))
                        .show(ui, |ui| {
                            ui.with_layout(
                                egui::Layout::left_to_right(egui::Align::Center),
                                |ui| {
                                    ui.add(
                                        egui::Label::new(
                                            egui::RichText::new(display).color(color),
                                        )
                                        .truncate(),
                                    );
                                },
                            );
                        });
                },
            );
            ui.add_space(6.0);
            note(
                ui,
                i18n::t(
                    lang,
                    if panel.own_dir.is_some() || running {
                        Key::UiShareOwnFolderNote
                    } else {
                        Key::UiShareDefaultFolderNote
                    },
                ),
                pal.text_muted,
            );

            // Список проверок — до старта, а не баннером после полуминуты
            // тишины: то же самое, сказанное вовремя. Третья строка жёлтая
            // не для порядка — это поведение, о которое спотыкаются: уйдёшь
            // с экрана, и раздача кончится.
            if !running {
                ui.add_space(16.0);
                step_header(
                    ui,
                    pal,
                    2,
                    i18n::t(lang, Key::UiShareChecklist),
                    Some(i18n::t(lang, Key::UiShareChecklistWhy)),
                    |_| {},
                );
                ui.add_space(8.0);
                for (ok, title, text) in [
                    (
                        true,
                        Key::UiShareCheckNetwork,
                        Some(Key::UiShareCheckNetworkNote),
                    ),
                    (
                        true,
                        Key::UiShareCheckFirewall,
                        Some(Key::UiShareCheckFirewallNote),
                    ),
                    (false, Key::UiShareCheckScreen, None),
                ] {
                    checklist_row(
                        ui,
                        pal,
                        ok,
                        i18n::t(lang, title),
                        text.map(|key| i18n::t(lang, key)),
                    );
                    ui.add_space(6.0);
                }
            }

            ui.add_space(14.0);
            let width = ui.available_width();
            if running {
                toggle = ui
                    .add_sized(
                        [width, theme::CTA_HEIGHT],
                        egui::Button::new(i18n::t(lang, Key::UiShareStop)),
                    )
                    .on_hover_text(i18n::t(lang, Key::UiShareStopHint))
                    .clicked();
            } else {
                toggle = accent_button(
                    ui,
                    pal,
                    i18n::t(lang, Key::UiShareStart),
                    width,
                    dir.is_some(),
                    i18n::t(lang, Key::UiSharePickFolderFirst),
                );
            }
            ui.add_space(6.0);
            // Пока раздача выключена — про то, что случится после нажатия;
            // когда идёт — про то, что её остановит. Видно без единого
            // щелчка: и то и другое — поведение, о которое спотыкаются.
            note(
                ui,
                i18n::t(
                    lang,
                    if running {
                        Key::UiShareAutoStop
                    } else {
                        Key::UiShareStartNote
                    },
                ),
                pal.text_muted,
            );

            if let Some((text, tone)) = &panel.note {
                ui.add_space(10.0);
                banner(ui, pal, text, tone.color(pal));
            }

            if panel.state == ShareState::Starting {
                ui.add_space(12.0);
                note(ui, i18n::t(lang, Key::UiShareOpening), pal.text_secondary);
            }

            let Some(address) = panel.addresses.get(panel.picked) else {
                return;
            };

            ui.add_space(16.0);
            // Код и адрес рядом, пока ширины хватает, и друг под другом — когда
            // нет. Порог по адресу, а не по подсказке: адрес — сорок знаков
            // полужирным, около 330 точек, и в колонке уже этого он рвётся
            // посередине (`…8080/?` на одной строке, `k=…` на другой). Так
            // и было при пороге в 240 — проверено глазами в окне 520.
            let beside = ui.available_width() >= QR_SIDE + 350.0;
            let address_block = |ui: &mut egui::Ui, copy: &mut bool| {
                field_label(ui, pal, i18n::t(lang, Key::UiShareAddressForPhone));
                ui.add(
                    egui::Label::new(
                        egui::RichText::new(&address.url)
                            .font(theme::bold(17.0))
                            .color(pal.text_primary),
                    )
                    .wrap(),
                );
                ui.add_space(6.0);
                note(ui, i18n::t(lang, Key::UiShareQrHint), pal.text_muted);
                ui.add_space(8.0);
                ui.horizontal(|ui| {
                    ui.spacing_mut().item_spacing.x = 10.0;
                    *copy = pill_button(ui, i18n::t(lang, Key::UiCopyAddress), speed).clicked();
                    if let Some(at) = panel.copied_at {
                        let left = COPIED_NOTICE_SECS - (now - at);
                        if left > 0.0 {
                            ui.label(
                                egui::RichText::new(i18n::t(lang, Key::UiCopied))
                                    .small()
                                    .color(pal.state_success),
                            );
                            ui.ctx()
                                .request_repaint_after(std::time::Duration::from_secs_f64(left));
                        }
                    }
                });
            };

            if beside {
                ui.horizontal_top(|ui| {
                    ui.spacing_mut().item_spacing.x = 18.0;
                    qr_image(ui, panel.qr.as_ref());
                    ui.vertical(|ui| address_block(ui, &mut copy));
                });
            } else {
                qr_image(ui, panel.qr.as_ref());
                ui.add_space(12.0);
                address_block(ui, &mut copy);
            }

            if panel.addresses.len() > 1 {
                ui.add_space(14.0);
                field_label(ui, pal, i18n::t(lang, Key::UiShareComputerAddress));
                // Таблетки с переносом, а не дорожка: подписи с именем сети
                // длинные, и в строку окна 520 не встают и две.
                ui.horizontal_wrapped(|ui| {
                    ui.spacing_mut().item_spacing = egui::vec2(8.0, 8.0);
                    for (index, other) in panel.addresses.iter().enumerate() {
                        let chosen = index == panel.picked;
                        if choice_pill(ui, pal, &other.label, chosen, speed).clicked() {
                            picked = Some(index);
                        }
                    }
                });
                ui.add_space(6.0);
                note(ui, i18n::t(lang, Key::UiShareAddressesHint), pal.text_muted);
            }

            ui.add_space(14.0);
            if panel.visitors.is_empty() {
                if now - panel.started_at < SHARE_QUIET_SECS {
                    note(ui, i18n::t(lang, Key::UiShareWaiting), pal.text_secondary);
                    ui.add_space(6.0);
                    note(ui, i18n::t(lang, SHARE_HELP), pal.text_muted);
                } else {
                    // Та же подсказка, но жёлтым: полминуты тишины — уже повод.
                    banner(ui, pal, i18n::t(lang, SHARE_HELP), pal.state_warning);
                }
            } else {
                field_label(ui, pal, i18n::t(lang, Key::UiShareVisitors));
                note(ui, &panel.visitors_line, pal.state_success);
            }
        });

        // Всё исполняем после карточки: внутри замыкания `self` одолжен.
        let ctx = ui.ctx().clone();
        if open_dir_clicked && let Some(dir) = &dir {
            open_dir(dir);
        }
        if choose_dir && let Some(picked_dir) = rfd::FileDialog::new().pick_folder() {
            self.share.own_dir_display = display_dir(Some(&picked_dir), self.lang);
            self.share.own_dir = Some(picked_dir);
        }
        if toggle {
            if self.share.running() {
                self.share.stop(None, lang);
            } else if let Some(dir) = dir {
                self.share.start(dir, lang, &ctx);
            }
        }
        if let Some(index) = picked {
            self.share.pick(index, &ctx);
        }
        if copy && let Some(address) = self.share.addresses.get(self.share.picked) {
            ctx.copy_text(address.url.clone());
            self.share.copied_at = Some(now);
        }
    }

    /// Карточка передач: что идёт, что дошло, что оборвалось.
    fn transfers_card(&self, ui: &mut egui::Ui) {
        let pal = self.palette;
        let lang = self.lang;
        theme::card_rising(ui, pal, self.appear(1), |ui| {
            ui.label(
                egui::RichText::new(i18n::t(lang, Key::UiShareTransfers))
                    .font(theme::display(17.0))
                    .color(pal.text_primary),
            );
            ui.add_space(8.0);

            if self.share.transfers.is_empty() {
                note(ui, i18n::t(lang, Key::UiShareNoTransfers), pal.text_muted);
                return;
            }

            for row in self.share.transfers.iter().rev() {
                ui.add(
                    egui::Label::new(egui::RichText::new(&row.name).color(pal.text_primary))
                        .truncate(),
                );
                let color = match row.outcome {
                    TransferOutcome::Going => pal.text_secondary,
                    TransferOutcome::Done => pal.state_success,
                    TransferOutcome::Failed(_) => pal.text_muted,
                };
                note(ui, &row.line, color);
                match &row.outcome {
                    TransferOutcome::Going => {
                        ui.add_space(4.0);
                        let bar = match row.fraction {
                            Some(fraction) => egui::ProgressBar::new(fraction),
                            None => egui::ProgressBar::new(0.0).animate(true),
                        };
                        ui.add(bar.fill(pal.accent).desired_height(6.0));
                    }
                    TransferOutcome::Done => {}
                    TransferOutcome::Failed(message) => note(ui, message, pal.state_error),
                }
                ui.add_space(12.0);
            }
        });
    }
}

/// QR-код адреса. Пока текстуры нет (строка не влезла в код — у адреса так
/// не бывает), место под код остаётся пустым, а не прыгает.
fn qr_image(ui: &mut egui::Ui, texture: Option<&egui::TextureHandle>) {
    let size = egui::vec2(QR_SIDE, QR_SIDE);
    match texture {
        Some(texture) => {
            ui.add(
                egui::Image::new(texture)
                    .fit_to_exact_size(size)
                    .corner_radius(egui::CornerRadius::same(theme::RADIUS_TINY)),
            );
        }
        None => {
            ui.allocate_exact_size(size, egui::Sense::hover());
        }
    }
}

/// Сколько секунд главная кнопка ряда загрузки не принимает щелчков после
/// того, как сменила смысл (см. [`SwapPause`]).
///
/// Полсекунды — это окно двойного щелчка в Windows по умолчанию и с запасом
/// то, за что долетает щелчок, задуманный ещё до смены: дефект
/// воспроизводили двумя щелчками с промежутком в 250 мс. Дольше держать
/// незачем: кнопка, которая не отвечает, когда её уже видно, — та же
/// поломка, только с другой стороны.
///
/// На `speed` не умножается: это не движение, а защита, и выключенные
/// переходы её не отменяют.
const SWAP_PAUSE_SECS: f64 = 0.5;

/// Пауза главной кнопки после смены смысла (задача 54).
///
/// «Скачать» и «Отмена» — одна кнопка на одном месте, и после щелчка под
/// неподвижным курсором тут же стоит кнопка с противоположным смыслом.
/// egui засчитывает оба щелчка двойного нажатия — `clicked()` приходит на
/// каждом отпускании, — так что второй щелчок, по привычке или от
/// нетерпения (снятие мгновенное и ничем не подтверждается), попадал уже
/// в неё: две «Отмены» подряд снимали 4K-ролик и тут же качали его заново,
/// а двойной щелчок по «Скачать» снимал только что начатую загрузку.
///
/// Щелчок, нажатый в паузе и отпущенный после неё, не пройдёт тоже:
/// выключенная кнопка egui нажатия не ловит (`hit_test.rs`), а без нажатия
/// отпускание щелчком не считается.
#[derive(Default)]
struct SwapPause {
    /// Смысл кнопки на прошлом проходе: `true` — «Отмена».
    cancels: bool,
    /// Когда смысл сменился у кнопки на экране, по часам egui. `None` —
    /// не менялся вовсе или сменился, пока кнопку не рисовали.
    since: Option<f64>,
    /// Номер прохода egui, на котором кнопку рисовали в последний раз.
    pass: u64,
}

impl SwapPause {
    /// Отмечает смысл кнопки на этом проходе и отвечает, сколько секунд
    /// ей ещё не принимать щелчков. `None` — нажимать можно.
    fn left(&mut self, cancels: bool, now: f64, pass: u64) -> Option<f64> {
        // Смена у кнопки, которую на прошлом проходе не рисовали, паузы не
        // заводит: человек был в другом разделе, и под курсором её не было.
        // Иначе загрузка, кончившаяся у него за спиной, встретила бы его
        // выключенной «Скачать» ни с того ни с сего.
        let shown = self.pass + 1 == pass;
        self.pass = pass;
        if cancels != self.cancels {
            self.cancels = cancels;
            self.since = shown.then_some(now);
        }
        let left = SWAP_PAUSE_SECS - (now - self.since?);
        (left > 0.0).then_some(left)
    }
}

/// Что стоит на главной кнопке ряда загрузки.
enum Cta<'a> {
    /// Идёт загрузка — «Отмена».
    Cancel,
    /// Всё остальное время — «Скачать»: можно ли нажать и, если нельзя,
    /// почему.
    Download { enabled: bool, hint: &'a str },
}

/// Главная кнопка ряда загрузки: «Отмена» во время загрузки, «Скачать»
/// в остальное время. Возвращает `true`, когда её нажали.
///
/// Свободной функцией, а не методом `SavioApp`, ради проверки кадром без
/// окна: щелчок сквозь смену смысла виден только на живой кнопке, а
/// `SavioApp` в тесте не собрать. Что на ней показать, решает
/// `SavioApp::primary_button`.
fn cta_button(
    ui: &mut egui::Ui,
    pal: theme::Palette,
    lang: Lang,
    width: f32,
    cta: Cta<'_>,
    pause: &mut SwapPause,
) -> bool {
    let now = ui.input(|i| i.time);
    let pass = ui.ctx().cumulative_pass_nr();
    let left = pause.left(matches!(cta, Cta::Cancel), now, pass);
    if let Some(left) = left {
        // Оживает кнопка только на кадре, а кадр без ввода egui не рисует:
        // без этой строки она ожила бы при первом движении мыши, а если
        // руки убрали — не ожила бы вовсе.
        ui.ctx()
            .request_repaint_after(std::time::Duration::from_secs_f64(left));
    }
    let settled = left.is_none();

    let (enabled, hint) = match cta {
        Cta::Cancel => {
            // Выключенный вид у «Отмены» штатный, тот же, что у выключенной
            // «В очередь»: контурная таблетка, приглушённая прозрачностью.
            // Свой понадобился только акцентной заливке ниже.
            return ui
                .add_enabled_ui(settled, |ui| {
                    ui.add_sized(
                        [width, theme::CTA_HEIGHT],
                        egui::Button::new(i18n::t(lang, Key::UiCancel)),
                    )
                    .on_hover_text(i18n::t(lang, Key::UiCancelHint))
                    .clicked()
                })
                .inner;
        }
        Cta::Download { enabled, hint } => (enabled && settled, hint),
    };

    ui.scope(|ui| {
        let v = ui.visuals_mut();
        // `ui.disable()` не переключает виджет на `noninteractive`,
        // а только глушит прозрачность. Поэтому выключенный вид
        // задаём сами: все три состояния красим приглушённым жёлтым,
        // навести на выключенную кнопку всё равно нельзя.
        // Подпись выключенной кнопки берётся отдельным полем палитры.
        // В тёмной теме она совпадает с обычной, и это сбивает с толку;
        // в светлой включённая кнопка тёмная и подписана белым, а
        // выключенная — пастельная, и белым по ней выходит 1.9:1.
        let (rest, hover, press, ink) = if enabled {
            (
                pal.accent,
                pal.accent_hover,
                pal.accent_active,
                pal.text_on_accent,
            )
        } else {
            (
                pal.accent_disabled,
                pal.accent_disabled,
                pal.accent_disabled,
                pal.text_on_accent_disabled,
            )
        };

        // Нажатие у кнопки из egui задаётся не своим прямоугольником,
        // а `expansion` (приём 02): рисует её `Button`, и подменить ему
        // рамку нечем. Полтора процента ширины на CTA — это около трёх
        // точек; берём их отрицательным полем, так что раскладка не едет.
        let squeeze = -width * motion::PRESS;

        for (state, fill, expansion) in [
            (&mut v.widgets.inactive, rest, 0.0),
            (&mut v.widgets.hovered, hover, 0.0),
            (&mut v.widgets.active, press, squeeze),
        ] {
            state.weak_bg_fill = fill;
            state.bg_stroke = egui::Stroke::NONE;
            state.fg_stroke = egui::Stroke::new(1.0, ink);
            state.corner_radius = egui::CornerRadius::same(theme::RADIUS_PILL);
            state.expansion = expansion;
        }
        // Двойное ослабление не нужно: приглушённый оранжевый уже задан
        // явно, а поверх него прозрачность съела бы кнопку целиком.
        v.disabled_alpha = 1.0;

        let response = ui.add_enabled(
            enabled,
            egui::Button::new(
                egui::RichText::new(i18n::t(lang, Key::UiDownload))
                    .font(theme::display(17.0))
                    .color(ink),
            )
            .min_size(egui::vec2(width, theme::CTA_HEIGHT)),
        );
        // В паузе кнопку держит не ссылка и не папка, и подсказка о них
        // соврала бы.
        if settled {
            response.on_disabled_hover_text(hint).clicked()
        } else {
            response.clicked()
        }
    })
    .inner
}

/// Главная кнопка экрана в акцентной заливке. Возвращает `true`, когда нажали.
///
/// Вид тот же, что у «Скачать» ([`cta_button`]): состояния заданы
/// через `visuals`, выключенная — приглушённым оранжевым явно, потому что
/// `ui.disable()` сам её от включённой не отличает (Правило 4).
fn accent_button(
    ui: &mut egui::Ui,
    pal: theme::Palette,
    label: &str,
    width: f32,
    enabled: bool,
    hint: &str,
) -> bool {
    ui.scope(|ui| {
        let v = ui.visuals_mut();
        // У выключенной кнопки своя подпись, а не та же самая. В тёмной теме
        // они совпадают, и это сбивает с толку: там обе тёмные. В светлой
        // включённая кнопка тёмная и подписана белым, а выключенная —
        // пастельная, и белым по ней выходит 1.9:1. Проверено глазами:
        // «Скачать» в светлой теме читался как пустая таблетка.
        let (rest, hover, press, ink) = if enabled {
            (
                pal.accent,
                pal.accent_hover,
                pal.accent_active,
                pal.text_on_accent,
            )
        } else {
            (
                pal.accent_disabled,
                pal.accent_disabled,
                pal.accent_disabled,
                pal.text_on_accent_disabled,
            )
        };
        let squeeze = -width * motion::PRESS;
        for (state, fill, expansion) in [
            (&mut v.widgets.inactive, rest, 0.0),
            (&mut v.widgets.hovered, hover, 0.0),
            (&mut v.widgets.active, press, squeeze),
        ] {
            state.weak_bg_fill = fill;
            state.bg_stroke = egui::Stroke::NONE;
            state.fg_stroke = egui::Stroke::new(1.0, ink);
            state.corner_radius = egui::CornerRadius::same(theme::RADIUS_PILL);
            state.expansion = expansion;
        }
        v.disabled_alpha = 1.0;

        // В горизонтальном ряду, а не прямо в колонке: растянутая `min_size`
        // кнопка кладёт подпись по выравниванию раскладки, и в колонке
        // `top_down(Min)` «Раздать файлы» уезжала к левому краю. «Скачать»
        // стоит в ряду с «В очередь» и этого не знает. Проверено глазами.
        ui.horizontal(|ui| {
            ui.add_enabled(
                enabled,
                egui::Button::new(
                    egui::RichText::new(label)
                        .font(theme::display(17.0))
                        .color(ink),
                )
                .min_size(egui::vec2(width, theme::CTA_HEIGHT)),
            )
            .on_disabled_hover_text(hint)
            .clicked()
        })
        .inner
    })
    .inner
}

/// Что сказать под прочерком в карточках погоды.
///
/// Своя строка, а не общая «Система не сообщила»: числа здесь присылает
/// не система, а сервер погоды, и отправить человека искать беду в своём
/// компьютере значило бы соврать.
const WEATHER_MISSING: Key = Key::UiWeatherValueMissing;

/// Строка найденного места: название и «область, страна». Щелчок выбирает.
///
/// Вложенной карточкой, а не кнопкой: у места две строки текста, а у кнопки
/// egui одна. Отклик под курсором — акцентная кромка: без него строка
/// выглядела бы надписью, а не выбором.
fn place_row(ui: &mut egui::Ui, pal: theme::Palette, name: &str, detail: &str, speed: f32) -> bool {
    let frame = theme::inner_frame(pal).show(ui, |ui| {
        ui.set_width(ui.available_width());
        // Выделяемые подписи съедали бы щелчок по строке.
        ui.style_mut().interaction.selectable_labels = false;
        ui.add(
            egui::Label::new(
                egui::RichText::new(name)
                    .font(theme::bold(14.0))
                    .color(pal.text_primary),
            )
            .truncate(),
        );
        if !detail.is_empty() {
            ui.add(
                egui::Label::new(egui::RichText::new(detail).small().color(pal.text_muted))
                    .truncate(),
            );
        }
    });

    let rect = frame.response.rect;
    let response = ui
        .interact(rect, frame.response.id.with("pick"), egui::Sense::click())
        .on_hover_cursor(egui::CursorIcon::PointingHand);
    let touch =
        ui.ctx()
            .animate_bool_with_time(response.id, response.hovered(), motion::TOUCH * speed);
    if touch > 0.0 {
        ui.painter().rect_stroke(
            rect,
            egui::CornerRadius::same(theme::RADIUS_INNER),
            egui::Stroke::new(
                1.0,
                motion::mix(egui::Color32::TRANSPARENT, pal.accent, touch),
            ),
            egui::StrokeKind::Inside,
        );
    }
    response.clicked()
}

/// Один столбик почасового прогноза.
///
/// Кистью в прямоугольнике постоянного размера, а не раскладкой из меток:
/// столбики обязаны стоять ровно, а у меток ширина своя у каждого числа.
fn hour_slot(ui: &mut egui::Ui, pal: theme::Palette, hour: &crate::model::HourView) {
    let (rect, _) = ui.allocate_exact_size(
        egui::vec2(HOUR_SLOT_WIDTH, HOUR_SLOT_HEIGHT),
        egui::Sense::hover(),
    );
    if !ui.is_rect_visible(rect) {
        return;
    }

    let painter = ui.painter();
    // Текущий час отмечен рамкой, а не одним цветом подписи: в прокрученном
    // ряду его ищут глазами, и цвета мелкой подписи для этого мало.
    if hour.now {
        painter.rect(
            rect,
            egui::CornerRadius::same(theme::RADIUS_INNER),
            pal.accent_soft,
            egui::Stroke::new(1.0, pal.accent),
            egui::StrokeKind::Inside,
        );
    }

    let small = egui::TextStyle::Small.resolve(ui.style());
    let x = rect.center().x;
    painter.text(
        egui::pos2(x, rect.top() + 8.0),
        egui::Align2::CENTER_TOP,
        &hour.time,
        small.clone(),
        if hour.now {
            pal.accent_hover
        } else {
            pal.text_muted
        },
    );
    let icon = egui::Rect::from_center_size(
        egui::pos2(x, rect.top() + 28.0 + SMALL_ICON / 2.0),
        egui::vec2(SMALL_ICON, SMALL_ICON),
    );
    weather_icon(pal, painter, icon, hour.sky, hour.night);
    painter.text(
        egui::pos2(x, rect.top() + 62.0),
        egui::Align2::CENTER_TOP,
        &hour.temperature,
        theme::bold(14.0),
        pal.text_primary,
    );
    if let Some(chance) = &hour.chance {
        painter.text(
            egui::pos2(x, rect.top() + 82.0),
            egui::Align2::CENTER_TOP,
            chance,
            small,
            pal.sky_water,
        );
    }
}

/// Строка недельного прогноза: день, значок, температуры, осадки.
fn day_row(ui: &mut egui::Ui, pal: theme::Palette, day: &crate::model::DayView) {
    /// Колонка вероятности осадков — постоянной ширины, иначе температуры
    /// разных дней не встали бы одна под другой.
    const CHANCE_WIDTH: f32 = 40.0;
    /// Колонка температур — под «−12° … −3°».
    const TEMPS_WIDTH: f32 = 92.0;

    // Высота ряда задаётся явно: `with_layout` отдал бы строке весь остаток
    // экрана (дефект 42, подробности у `SavioApp::power_card`). Колонки справа
    // кладутся первыми, справа налево, а название дня — во вложенную
    // `left_to_right`: так обрезаемая метка получает остаток и не налезает
    // на числа (Правило 4).
    ui.allocate_ui_with_layout(
        egui::vec2(ui.available_width(), SMALL_ICON + 6.0),
        egui::Layout::right_to_left(egui::Align::Center),
        |ui| {
            ui.spacing_mut().item_spacing.x = 8.0;

            let (chance, _) =
                ui.allocate_exact_size(egui::vec2(CHANCE_WIDTH, 20.0), egui::Sense::hover());
            if let Some(text) = &day.chance {
                ui.painter().text(
                    chance.right_center(),
                    egui::Align2::RIGHT_CENTER,
                    text,
                    egui::TextStyle::Small.resolve(ui.style()),
                    pal.sky_water,
                );
            }

            let (temps, _) =
                ui.allocate_exact_size(egui::vec2(TEMPS_WIDTH, 20.0), egui::Sense::hover());
            ui.painter().text(
                temps.right_center(),
                egui::Align2::RIGHT_CENTER,
                &day.temperatures,
                egui::TextStyle::Body.resolve(ui.style()),
                pal.text_primary,
            );

            let (icon, response) =
                ui.allocate_exact_size(egui::vec2(SMALL_ICON, SMALL_ICON), egui::Sense::hover());
            weather_icon(pal, ui.painter(), icon, day.sky, false);
            // Описание словами — по наведению: в узкой колонке ему нет места,
            // а значок «дождь» не различает морось и ливень.
            response.on_hover_text(day.description);

            ui.with_layout(egui::Layout::left_to_right(egui::Align::Center), |ui| {
                ui.add(
                    egui::Label::new(egui::RichText::new(&day.label).color(pal.text_primary))
                        .truncate(),
                );
            });
        },
    );
}

/// Значок погоды кистью.
///
/// Кистью, а не знаком шрифта, и это не вкусовщина. Ни дождевого облака, ни
/// солнца за облаком, ни тумана, ни грозы с дождём в шрифтах eframe нет
/// (проверено разбором cmap при постановке задачи 29), а уцелевшие ☀ и ☁
/// приезжают из разных файлов с разным масштабом — рядом они вышли бы разного
/// размера. Пустой прямоугольник на месте погоды не видят ни сборка, ни тесты
/// (Правило 4).
///
/// Рисуется в квадрате, вписанном в `rect`, в долях его стороны: один и тот
/// же значок годится и для крупного «сейчас», и для столбика часа.
fn weather_icon(
    pal: theme::Palette,
    painter: &egui::Painter,
    rect: egui::Rect,
    sky: Sky,
    night: bool,
) {
    let side = rect.width().min(rect.height());
    let origin = rect.center() - egui::vec2(side, side) / 2.0;
    let at = |x: f32, y: f32| origin + egui::vec2(x * side, y * side);

    let body = |center: egui::Pos2, radius: f32| {
        if night {
            // Месяц крупнее солнца: у серпа нет лучей, и того же радиуса ему
            // мало, чтобы в столбике часа читаться формой, а не точкой.
            crescent(painter, center, radius * 1.5, pal.sky_moon());
        } else {
            painter.circle_filled(center, radius, pal.sky_sun());
            let stroke = egui::Stroke::new((side * 0.06).max(1.2), pal.sky_sun());
            for ray in 0..8 {
                let angle = ray as f32 * std::f32::consts::FRAC_PI_4;
                let direction = egui::vec2(angle.cos(), angle.sin());
                painter.line_segment(
                    [
                        center + direction * radius * 1.45,
                        center + direction * radius * 1.95,
                    ],
                    stroke,
                );
            }
        }
    };

    // Облако: три круга и скруглённое основание. Нижние края кругов и
    // основания совпадают, поэтому вместе они дают одну ровную фигуру.
    // `dx`, `dy` — сдвиг в долях стороны, `scale` — масштаб вокруг середины.
    let cloud = |dx: f32, dy: f32, scale: f32, color: egui::Color32| {
        let point = |x: f32, y: f32| at(0.5 + (x - 0.5) * scale + dx, 0.5 + (y - 0.5) * scale + dy);
        let radius = |r: f32| r * scale * side;
        painter.circle_filled(point(0.36, 0.56), radius(0.17), color);
        painter.circle_filled(point(0.54, 0.45), radius(0.21), color);
        painter.circle_filled(point(0.70, 0.58), radius(0.15), color);
        painter.rect_filled(
            egui::Rect::from_min_max(point(0.20, 0.56), point(0.84, 0.73)),
            egui::CornerRadius::same(radius(0.085).clamp(1.0, 255.0) as u8),
            color,
        );
    };
    // Облако над осадками: поднято, чтобы под ним осталось место.
    let raised = || cloud(0.0, -0.12, 0.9, pal.sky_cloud());

    match sky {
        Sky::Clear => body(at(0.5, 0.5), 0.2 * side),
        Sky::PartlyCloudy => {
            body(at(0.36, 0.36), 0.15 * side);
            cloud(0.08, 0.08, 0.85, pal.sky_cloud());
        }
        // Незнакомый код — облако: это ни «ясно», ни осадки, и соврать
        // в какую-то сторону значком хуже, чем нарисовать нейтральное.
        Sky::Cloudy | Sky::Unknown => {
            cloud(0.1, -0.1, 0.75, pal.sky_cloud_far());
            cloud(-0.04, 0.06, 0.95, pal.sky_cloud());
        }
        Sky::Fog => {
            cloud(0.0, -0.12, 0.9, pal.sky_cloud_far());
            let stroke = egui::Stroke::new((side * 0.06).max(1.2), pal.sky_cloud());
            for (y, left, right) in [(0.72, 0.18, 0.74), (0.86, 0.28, 0.84)] {
                painter.line_segment([at(left, y), at(right, y)], stroke);
            }
        }
        Sky::Drizzle => {
            raised();
            for x in [0.34, 0.52, 0.70] {
                painter.circle_filled(at(x, 0.8), side * 0.04, pal.sky_water);
            }
        }
        Sky::Rain => {
            raised();
            let stroke = egui::Stroke::new((side * 0.055).max(1.2), pal.sky_water);
            for x in [0.38, 0.54, 0.70] {
                painter.line_segment([at(x, 0.68), at(x - 0.07, 0.9)], stroke);
            }
        }
        Sky::Snow => {
            raised();
            let stroke = egui::Stroke::new((side * 0.04).max(1.0), pal.sky_snow());
            for x in [0.34, 0.52, 0.70] {
                let center = at(x, 0.8);
                let reach = side * 0.06;
                for ray in 0..3 {
                    let angle = ray as f32 * std::f32::consts::FRAC_PI_3;
                    let direction = egui::vec2(angle.cos(), angle.sin()) * reach;
                    painter.line_segment([center - direction, center + direction], stroke);
                }
            }
        }
        Sky::Thunder => {
            raised();
            let stroke = egui::Stroke::new((side * 0.06).max(1.2), pal.sky_bolt());
            let zigzag = [at(0.56, 0.62), at(0.44, 0.78), at(0.58, 0.78), at(0.46, 0.95)];
            for pair in zigzag.windows(2) {
                painter.line_segment([pair[0], pair[1]], stroke);
            }
        }
    }
}

/// Месяц: полоса между двумя дугами — краем луны и краем тени на ней.
///
/// Сеткой, а не многоугольником: месяц невыпуклый, а `convex_polygon`
/// заливает только выпуклое — вышел бы кружок со срезанным краем. Тень —
/// круг размером с луну, сдвинутый вверх и вправо на полрадиуса.
///
/// Числа проверены глазами дважды. С тенью меньше луны серп выходил толщиной
/// в три четверти радиуса, и в столбике почасового прогноза (30 точек) месяц
/// читался пятном — ночь от дня отличалась только цветом. Кромка тонкой
/// линией нужна по второй причине: у сетки egui нет сглаживания, и на такой
/// величине края рассыпаются ступеньками.
fn crescent(painter: &egui::Painter, center: egui::Pos2, radius: f32, color: egui::Color32) {
    let (outer, inner) = crescent_arcs(center, radius);

    let mut mesh = egui::Mesh::default();
    for (edge, hollow) in outer.iter().zip(&inner) {
        mesh.colored_vertex(*edge, color);
        mesh.colored_vertex(*hollow, color);
    }
    for step in 0..CRESCENT_STEPS as u32 {
        let k = step * 2;
        mesh.add_triangle(k, k + 1, k + 2);
        mesh.add_triangle(k + 1, k + 3, k + 2);
    }
    painter.add(egui::Shape::Mesh(Arc::new(mesh)));

    // Сглаженная кромка по всему контуру: рог к рогу по луне и обратно по тени.
    let outline: Vec<egui::Pos2> = outer.iter().chain(inner.iter().rev()).copied().collect();
    painter.add(egui::Shape::closed_line(outline, egui::Stroke::new(1.0, color)));
}

/// Сколько отрезков в каждой дуге месяца.
const CRESCENT_STEPS: usize = 16;

/// Обе дуги месяца, от рога к рогу: край луны и край тени на ней.
///
/// Отдельно от рисования ради теста `the_crescent_stays_inside_the_moon`:
/// промах в выборе дуги тени ничего не роняет, а тихо заливает серп в круг.
/// Ровно так и было — и видно это было только глазами.
fn crescent_arcs(
    center: egui::Pos2,
    radius: f32,
) -> ([egui::Pos2; CRESCENT_STEPS + 1], [egui::Pos2; CRESCENT_STEPS + 1]) {
    use std::f32::consts::{PI, TAU};
    const STEPS: usize = CRESCENT_STEPS;

    let shift = egui::vec2(0.79, -0.61) * (0.5 * radius);
    let shade_radius = radius;
    let shade = center + shift;
    let distance = shift.length();
    let toward_shade = shift.y.atan2(shift.x);
    // Половина угла между рогами месяца, от центра луны: теорема косинусов
    // для треугольника «центр луны — центр тени — рог».
    let half = ((distance * distance + radius * radius - shade_radius * shade_radius)
        / (2.0 * distance * radius))
        .clamp(-1.0, 1.0)
        .acos();

    let on_moon = |angle: f32| center + egui::vec2(angle.cos(), angle.sin()) * radius;
    let horn_a = on_moon(toward_shade + half);
    let horn_b = on_moon(toward_shade - half);
    let angle_from_shade = |point: egui::Pos2| {
        let v = point - shade;
        v.y.atan2(v.x)
    };
    let start = angle_from_shade(horn_a);
    // Дуга тени идёт внутри луны, то есть через сторону, обращённую к её
    // центру. Из двух путей между рогами берём тот, чья середина ближе к ней.
    let forward = (angle_from_shade(horn_b) - start).rem_euclid(TAU);
    let middle = start + forward / 2.0;
    // Угловое расстояние до направления «к центру луны», свёрнутое в [0, π].
    // Сворачивается разность с направлением на тень, а не с противоположным:
    // `(x).rem_euclid(TAU) - PI` переводит совпадение не в ноль, а в ±π, и
    // выбирался внешний путь — серп заливался в круг (дефект задачи 29).
    let off = ((middle - toward_shade).rem_euclid(TAU) - PI).abs();
    let inner_span = if off < PI / 2.0 { forward } else { forward - TAU };

    // Точки обеих дуг — на стеке: они нужны дважды, сетке и кромке.
    let mut outer = [egui::Pos2::ZERO; STEPS + 1];
    let mut inner = [egui::Pos2::ZERO; STEPS + 1];
    for step in 0..=STEPS {
        let t = step as f32 / STEPS as f32;
        // Край луны — длинным путём от рога к рогу, в сторону от тени.
        outer[step] = on_moon(toward_shade + half + t * (TAU - 2.0 * half));
        let angle = start + t * inner_span;
        inner[step] = shade + egui::vec2(angle.cos(), angle.sin()) * shade_radius;
    }
    (outer, inner)
}

// ---------------------------------------------------------------------------
// Мелкие элементы
// ---------------------------------------------------------------------------

/// Насколько виджет сейчас под курсором: 0 — совсем нет, 1 — полностью.
///
/// Спрашиваем **до** того, как виджет нарисован, и это не хитрость: egui
/// решает, кто под курсором, в начале прохода — по прямоугольникам прошлого
/// кадра, — так что ответ на этот момент уже готов. Ровно так же и ровно тем
/// же `read_response` берёт свой вид сам `Button` в egui 0.36, поэтому
/// заливка, кромка и подпись едут одним коэффициентом и не расходятся
/// (приём 01).
///
/// Идентификатор виджета, которого ещё нет, даёт `ui.next_auto_id()`: он
/// подглядывает следующий, а не выдаёт его, — и первый же добавленный после
/// него виджет получает именно этот.
fn touch_at(ui: &egui::Ui, id: egui::Id, speed: f32) -> f32 {
    let hovered = ui.ctx().read_response(id).is_some_and(|r| r.hovered());
    ui.ctx()
        .animate_bool_with_time(id, hovered, motion::TOUCH * speed)
}

/// Ставит виджетам штатных состояний темы плавный отклик под курсором.
///
/// Красит `inactive` и `hovered` одинаково — тем, что получилось из `t`:
/// какое из двух состояний возьмёт egui, зависит от того же самого наведения,
/// и держать их разными нечем. Нажатие (`active`) остаётся мгновенным: это
/// не отклик на приближение, а подтверждение действия.
///
/// `expansion` едет вместе с цветом намеренно. Раскладку это не двигает —
/// у кнопки `outer_margin` ровно на столько же отрицательный, — но без него
/// кромка прыгала бы на месте, пока цвет переливается.
fn touch_visuals(ui: &mut egui::Ui, t: f32) {
    let v = ui.visuals_mut();
    let (rest, hover) = (v.widgets.inactive, v.widgets.hovered);
    let weak = motion::mix(rest.weak_bg_fill, hover.weak_bg_fill, t);
    let solid = motion::mix(rest.bg_fill, hover.bg_fill, t);
    let border = motion::mix(rest.bg_stroke.color, hover.bg_stroke.color, t);
    let text = motion::mix(rest.fg_stroke.color, hover.fg_stroke.color, t);
    let expansion = rest.expansion + (hover.expansion - rest.expansion) * t;

    for state in [&mut v.widgets.inactive, &mut v.widgets.hovered] {
        state.weak_bg_fill = weak;
        state.bg_fill = solid;
        state.bg_stroke.color = border;
        state.fg_stroke.color = text;
        state.expansion = expansion;
    }
}

/// Что осталось от сегмента после отрисовки.
///
/// Прямоугольник нужен дорожке: перетекающая таблетка (приём 03) едет к
/// выбранному сегменту, а где он лёг, известно только после раскладки.
struct Segment {
    clicked: bool,
    rect: egui::Rect,
    touch: f32,
}

/// Один сегмент переключателя: подпись и отклик, но **без** заливки выбранного.
///
/// Цвета задаём через `visuals`, а не через `Button::fill`: последний,
/// по документации egui, отключает реакцию на наведение — кнопка выглядела бы
/// мёртвой. Одна функция на все дорожки сразу — половины «Машины», формат,
/// качество, половины «Машины», очередь с историей: разъехавшись, одинаковые
/// на вид элементы смотрелись бы досадной небрежностью.
///
/// Оранжевого у выбранного сегмента здесь нет намеренно, и это половина
/// приёма 03: заливку рисует одна на всю дорожку таблетка в [`segment_track`],
/// которая к выбранному **едет**, а не зажигается на месте. Покрасить сегмент
/// ещё и тут тянет при первом же взгляде на функцию — и тогда таблетка
/// поедет по уже зажжённому месту, то есть весь приём пропадёт, а сборка,
/// `clippy` и тесты этого не заметят.
///
/// `width` — это **минимум**, а не потолок: egui не сжимает кнопку под
/// доступное место, а раздвигает раскладку. Ноль означает «по ширине текста»
/// и нужен там, где дорожка стоит посреди строки, а не растянута на всё окно.
fn segment_button(
    ui: &mut egui::Ui,
    pal: theme::Palette,
    label: &str,
    selected: bool,
    width: f32,
    speed: f32,
) -> Segment {
    ui.scope(|ui| {
        // Поля сегмента урезаем против штатных 16: шесть ступеней качества
        // («2160p») в окне шириной 520 иначе вылезли бы за кромку. Число —
        // в теме, чтобы проверка ширины считала по тому же.
        ui.spacing_mut().button_padding.x = theme::SEGMENT_PADDING;

        let id = ui.next_auto_id();
        let touch = touch_at(ui, id, speed);
        // Выбранность едет отдельно и дольше отклика: подпись перекрашивается
        // ровно за то время, что таблетка добирается до сегмента.
        let chosen =
            ui.ctx()
                .animate_bool_with_time(id.with("chosen"), selected, motion::MOVE * speed);

        // Под выбранным сегментом лежит таблетка, и своей заливки ему не
        // нужно ни в покое, ни под курсором, ни под нажатием: серая подсветка
        // легла бы поверх оранжевого.
        let (rest, press) = if selected {
            (egui::Color32::TRANSPARENT, egui::Color32::TRANSPARENT)
        } else {
            (
                motion::mix(egui::Color32::TRANSPARENT, pal.card_inner, touch),
                pal.card_fill,
            )
        };
        // Подпись выбранного тёмная — на оранжевом светлая даёт 1.9:1.
        // У невыбранного она приглушена в покое и светлеет под курсором:
        // это и есть отклик, заливки там почти нет.
        let text = motion::mix(
            motion::mix(pal.text_secondary, pal.text_primary, touch),
            pal.text_on_accent,
            chosen,
        );

        let v = ui.visuals_mut();
        for (state, fill) in [
            (&mut v.widgets.inactive, rest),
            (&mut v.widgets.hovered, rest),
            (&mut v.widgets.active, press),
        ] {
            state.weak_bg_fill = fill;
            state.bg_stroke = egui::Stroke::NONE;
            state.fg_stroke = egui::Stroke::new(1.0, text);
            state.corner_radius = egui::CornerRadius::same(theme::RADIUS_PILL);
            // Сегмент не должен «распухать» — он зажат в дорожке.
            state.expansion = 0.0;
        }

        let response =
            ui.add(egui::Button::new(label).min_size(egui::vec2(width, theme::SEGMENT_HEIGHT)));
        Segment {
            clicked: response.clicked(),
            rect: response.rect,
            touch,
        }
    })
    .inner
}

/// Дорожка переключателя целиком: контурная «таблетка», сегменты внутри и
/// одна оранжевая таблетка, перетекающая к выбранному (приём 03).
///
/// Возвращает то, по чему щёлкнули. Применять выбор надо снаружи: внутри
/// замыкания `self` занят целиком, и присвоить поле оттуда нельзя.
///
/// Одна функция на все пять дорожек окна. Место под таблетку занимается
/// **до** цикла: где она ляжет, известно только после раскладки, а лежать
/// она обязана под подписями. `Shape::Noop` в резерве не стоит видеокарте
/// ничего, если выбранного сегмента вдруг не окажется.
///
/// `stretch` растягивает сегменты на всю ширину поровну (формат, качество);
/// без него каждый берёт ширину своей подписи — так дорожка стоит посреди
/// строки, а не растянута на всё окно. Доля считается на каждом шаге заново,
/// а не делится один раз: округления до пиксельной сетки накопили бы ошибку,
/// и дорожка либо не дотянулась бы до правого края, либо вылезла за него.
fn segment_track<T: Copy + PartialEq>(
    ui: &mut egui::Ui,
    pal: theme::Palette,
    id: egui::Id,
    speed: f32,
    current: T,
    items: &[(T, &str)],
    stretch: bool,
) -> Option<T> {
    const GAP: f32 = theme::SEGMENT_GAP;

    let mut picked = None;
    theme::track_frame(pal).show(ui, |ui| {
        ui.horizontal(|ui| {
            ui.spacing_mut().item_spacing.x = GAP;

            // `ui.horizontal` не «начинает слева направо», а продолжает то
            // направление, что задано снаружи, — и в раскладке справа налево
            // самым правым оказывается тот сегмент, который положили первым.
            // Проверено глазами: переключатель темы в подвале вышел
            // «Светлая | Тёмная» при списке `[Тёмная, Светлая]`, то есть
            // подсветка стояла не под той подписью, под которой её искали.
            //
            // Поэтому список проходится задом наперёд, а направление остаётся
            // родительским. Развернуть вместо этого саму раскладку —
            // соблазнительно и неверно: вложенный `left_to_right` кладёт
            // содержимое от левого края, `min_rect` справа налево растёт
            // от правого, и между ними оказывается вся строка. Проверено
            // глазами обе попытки: с `available_size_before_wrap` дорожка
            // растянулась на весь подвал и вытеснила строку версий, с нулевой
            // шириной — налезла на соседнюю галочку.
            let backwards = ui.layout().prefer_right_to_left();

            let slot = ui.painter().add(egui::Shape::Noop);
            let mut chosen: Option<Segment> = None;
            let mut left = items.len() as f32;

            for step in 0..items.len() {
                let (item, label) = if backwards {
                    &items[items.len() - 1 - step]
                } else {
                    &items[step]
                };
                let width = if stretch {
                    let width = (ui.available_width() - GAP * (left - 1.0)) / left;
                    left -= 1.0;
                    width
                } else {
                    0.0
                };

                let segment = segment_button(ui, pal, label, *item == current, width, speed);
                if segment.clicked {
                    picked = Some(*item);
                }
                if *item == current {
                    chosen = Some(segment);
                }
            }

            if let Some(chosen) = chosen {
                let shown = motion::pill(ui.ctx(), id, chosen.rect, motion::MOVE * speed);
                ui.painter().set(
                    slot,
                    egui::Shape::rect_filled(
                        shown,
                        egui::CornerRadius::same(theme::RADIUS_PILL),
                        // Наведение на уже выбранный сегмент светлит саму
                        // таблетку: до приёма 03 это делала его собственная
                        // заливка, и терять отклик вместе с ней незачем.
                        motion::mix(pal.accent, pal.accent_hover, chosen.touch),
                    ),
                );
            }
        });
    });
    picked
}

/// Заготовка вторичной кнопки: контурная «таблетка» штатной высоты.
///
/// Отдельно от [`pill_button`], потому что нужна и выключенной: у
/// `ui.add_enabled` первым аргументом идёт условие, а вторым — сам виджет.
fn pill(label: &str) -> egui::Button<'_> {
    egui::Button::new(label).min_size(egui::vec2(0.0, theme::CONTROL_HEIGHT))
}

/// Даёт плавный отклик тому виджету, который добавят следующим.
///
/// Подглядеть идентификатор и добавить виджет надо в **одном и том же** `Ui`:
/// у потомка своя нумерация, и `next_auto_id`, взятый снаружи, указал бы не
/// туда. Отсюда три обёртки ниже вместо одной — они отличаются ровно тем,
/// какой `Ui` создают вокруг.
///
/// Правит `visuals` без возврата — значит, звать её можно только там, где
/// правка и так не переживёт кадра: внутри `scope`, `add_enabled_ui` или
/// `allocate_ui_*`.
fn with_touch<R>(ui: &mut egui::Ui, speed: f32, add: impl FnOnce(&mut egui::Ui) -> R) -> R {
    let t = touch_at(ui, ui.next_auto_id(), speed);
    touch_visuals(ui, t);
    add(ui)
}

/// Названия групп рельса прописными, на выбранном языке.
fn nav_groups(lang: Lang) -> [String; 3] {
    let mut out = [const { String::new() }; 3];
    for (slot, (key, _)) in out.iter_mut().zip(NAV) {
        *slot = i18n::t(lang, key).to_uppercase();
    }
    out
}

/// Содержимое рельса без `self`.
///
/// Свободной функцией ради проверки: рельс — единственная навигация окна,
/// и его ширину на трёх языках надо мерить кадром без окна, а собрать
/// [`RailState`] для этого дешевле, чем целый `SavioApp`.
fn rail_body(ui: &mut egui::Ui, state: &RailState<'_>, layout: RailLayout) -> RailPicks {
    let mut picks = RailPicks {
        more_open: state.more_open,
        ..RailPicks::default()
    };
    let pal = state.pal;
    let wide = layout.labels();

    // Нижний блок кладём панелью, а не после распорки: панель сама прижмётся
    // к нижней кромке рельса, а распорке пришлось бы отмерять остаток высоты
    // руками — и промахиваться на кадр при каждой смене содержимого.
    egui::Panel::bottom("savio-rail-bottom")
        .resizable(false)
        .show_separator_line(false)
        .frame(egui::Frame::new().outer_margin(egui::Margin {
            top: theme::NAV_BLOCK_GAP as i8,
            ..egui::Margin::ZERO
        }))
        .show(ui, |ui| {
            if layout == RailLayout::Full {
                theme::rail_block_frame(pal).show(ui, |ui| {
                    ui.set_width(ui.available_width());
                    rail_block(ui, state, &mut picks);
                });
            } else {
                rail_more_button(ui, state, &mut picks, wide);
            }
        });

    ui.vertical(|ui| {
        ui.spacing_mut().item_spacing.y = 2.0;

        // Имя программы и акцентная точка. В свёрнутом рельсе остаётся одна
        // точка: «Savio» туда не влезает, а обрезанное имя хуже его отсутствия.
        ui.horizontal(|ui| {
            if wide {
                ui.label(
                    egui::RichText::new("Savio")
                        .font(theme::display(21.0))
                        .color(pal.text_primary),
                );
            }
            let (dot, _) = ui.allocate_exact_size(egui::vec2(9.0, 9.0), egui::Sense::hover());
            ui.painter().circle_filled(dot.center(), 4.5, pal.accent);
        });
        ui.add_space(14.0);

        for (group, (_, items)) in state.groups.iter().zip(NAV) {
            if wide {
                ui.add_space(8.0);
                nav_group_label(ui, pal, group);
                ui.add_space(4.0);
            } else {
                ui.add_space(10.0);
            }

            for item in items {
                let open = item.is_open(state.tab, state.half);
                if rail_item(ui, state, item, open, wide) {
                    picks.section = Some((item.tab, item.half));
                }
            }
        }
    });

    picks
}

/// Название группы разделов: прописными, мелко и с разрядкой.
///
/// Общее у рельса и приветствия: приветствие повторяет группы рельса, и
/// выглядеть они обязаны одинаково — разъехавшись, одна и та же подпись
/// читалась бы двумя разными вещами.
///
/// Прописными строку готовят заранее ([`nav_groups`]): `to_uppercase`
/// в кадре — это аллокация на каждую группу, каждый кадр. Цвет `text_faint`
/// разрешён на фоне окна, рельсе, карточке и модалке, но не во вложенном
/// блоке — туда эту подпись не класть.
fn nav_group_label(ui: &mut egui::Ui, pal: theme::Palette, group: &str) {
    ui.label(
        egui::RichText::new(group)
            .font(egui::FontId::new(11.5, egui::FontFamily::Proportional))
            // Разрядка — из макета.
            .extra_letter_spacing(0.9)
            .color(pal.text_faint),
    );
}

/// Один пункт рельса.
///
/// Возвращает `true`, если по нему щёлкнули.
fn rail_item(
    ui: &mut egui::Ui,
    state: &RailState<'_>,
    item: &NavItem,
    open: bool,
    wide: bool,
) -> bool {
    let pal = state.pal;
    let label = i18n::t(state.lang, item.label);
    let (rect, response) = ui.allocate_exact_size(
        egui::vec2(ui.available_width(), theme::NAV_ITEM_HEIGHT),
        egui::Sense::click(),
    );
    // Пункт нарисован кистью, и для экранного диктора без этого безымянен,
    // а в свёрнутом рельсе у него нет даже видимой подписи — один значок.
    // Имя и «открыт ли» готовый `Button` сообщает сам; здесь их называют
    // явно (о цене — у `choice_pill`).
    response.widget_info(|| {
        egui::WidgetInfo::selected(egui::WidgetType::Button, true, open, label)
    });
    let id = response.id;

    let touch = touch_at(ui, id, state.speed);
    // Про появление спрашиваем на каждом кадре, включая те, когда пункт
    // закрыт: `animate_bool_with_time`, впервые увидев незнакомый
    // идентификатор, отдаёт сразу конечное значение — и подсветка возникала
    // бы целиком, без перехода.
    let shown = ui
        .ctx()
        .animate_bool_with_time(id.with("open"), open, motion::MOVE * state.speed);

    let painter = ui.painter();
    // Наведение — та же заливка на половинной прозрачности, как в макете.
    let fill = motion::mix(
        egui::Color32::TRANSPARENT,
        pal.accent_soft,
        shown.max(touch * 0.5),
    );
    painter.rect_filled(rect, egui::CornerRadius::same(theme::RADIUS_NAV), fill);

    // Полоса слева — единственное, что отличает открытый пункт от того,
    // на который просто навели: заливка у них одного цвета.
    if shown > 0.0 {
        let bar = egui::Rect::from_min_size(
            egui::pos2(rect.left(), rect.center().y - 9.0),
            egui::vec2(3.0, 18.0),
        );
        painter.rect_filled(
            bar,
            egui::CornerRadius::same(2),
            motion::mix(egui::Color32::TRANSPARENT, pal.accent, shown),
        );
    }

    let ink = motion::mix(
        motion::mix(pal.text_secondary, pal.text_primary, touch),
        pal.text_primary,
        shown,
    );
    if wide {
        let icon = egui::Rect::from_center_size(
            egui::pos2(rect.left() + NAV_ICON_CENTER, rect.center().y),
            egui::vec2(16.0, 16.0),
        );
        nav_icon(painter, icon, item.icon, ink);
        paint_rail_label(ui, rect, label, ink);
    } else {
        let icon = egui::Rect::from_center_size(rect.center(), egui::vec2(18.0, 18.0));
        nav_icon(painter, icon, item.icon, ink);
    }

    // В свёрнутом рельсе подпись прячется, и без подсказки пункт превратился
    // бы в загадку: значок один, слов никаких.
    let response = if wide {
        response
    } else {
        response.on_hover_text(label)
    };
    response.on_hover_cursor(egui::CursorIcon::PointingHand).clicked()
}

/// Середина значка пункта от левого края пункта.
const NAV_ICON_CENTER: f32 = 22.0;

/// Подпись пункта рельса — общая у пунктов и у кнопки «Настройки».
///
/// Раскладывается с потолком по ширине, а не рисуется как есть: не влезшая
/// в рельс уехала бы под кромку и наползла на содержимое — кисть о соседях
/// ничего не знает. С потолком она честно обрежется многоточием. Что до
/// этого не доходит ни на одном языке, держит `the_rail_labels_fit_their_width`.
fn paint_rail_label(ui: &egui::Ui, rect: egui::Rect, label: &str, ink: egui::Color32) {
    let galley = ui.ctx().fonts_mut(|fonts| {
        fonts.layout(
            label.to_owned(),
            egui::FontId::new(15.0, egui::FontFamily::Proportional),
            ink,
            theme::NAV_LABEL_WIDTH,
        )
    });
    let at = egui::pos2(
        rect.left() + theme::NAV_ICON_COLUMN,
        rect.center().y - galley.size().y / 2.0,
    );
    ui.painter().galley(at, galley, ink);
}

/// Значок раздела, нарисованный кистью.
///
/// Кистью, а не знаком из шрифта, и причина записана у [`NavIcon`]: нужных
/// знаков нет ни в одной из тринадцати доступных гарнитур, а отсутствующий
/// знак рисуется пустым прямоугольником молча.
fn nav_icon(painter: &egui::Painter, rect: egui::Rect, icon: NavIcon, color: egui::Color32) {
    let stroke = egui::Stroke::new(1.4, color);
    let (c, w, h) = (rect.center(), rect.width(), rect.height());

    match icon {
        NavIcon::Download => {
            // Стрелка вниз и поддон под ней.
            painter.line_segment(
                [
                    egui::pos2(c.x, rect.top()),
                    egui::pos2(c.x, rect.top() + h * 0.55),
                ],
                stroke,
            );
            for side in [-1.0, 1.0] {
                painter.line_segment(
                    [
                        egui::pos2(c.x + side * w * 0.22, rect.top() + h * 0.33),
                        egui::pos2(c.x, rect.top() + h * 0.57),
                    ],
                    stroke,
                );
            }
            painter.line_segment(
                [
                    egui::pos2(rect.left(), rect.bottom() - h * 0.08),
                    egui::pos2(rect.right(), rect.bottom() - h * 0.08),
                ],
                stroke,
            );
        }
        NavIcon::Metadata => {
            // Ярлык с отверстием.
            let tag = egui::Rect::from_min_max(
                egui::pos2(rect.left(), rect.top() + h * 0.15),
                egui::pos2(rect.right(), rect.bottom() - h * 0.15),
            );
            painter.rect_stroke(
                tag,
                egui::CornerRadius::same(3),
                stroke,
                egui::StrokeKind::Inside,
            );
            painter.circle_filled(
                egui::pos2(tag.left() + w * 0.22, tag.center().y),
                1.6,
                color,
            );
            for k in [0.35_f32, 0.62] {
                painter.line_segment(
                    [
                        egui::pos2(tag.left() + w * 0.42, tag.top() + h * k),
                        egui::pos2(tag.right() - w * 0.12, tag.top() + h * k),
                    ],
                    egui::Stroke::new(1.2, color),
                );
            }
        }
        NavIcon::Gauge => {
            // Полукруг шкалы и стрелка на нём.
            let r = w * 0.44;
            let arc: Vec<egui::Pos2> = (0..=16)
                .map(|i| {
                    let a = std::f32::consts::PI * (1.0 + i as f32 / 16.0);
                    egui::pos2(
                        c.x + r * a.cos(),
                        c.y + h * 0.18 + r * a.sin(),
                    )
                })
                .collect();
            painter.add(egui::Shape::line(arc, stroke));
            painter.line_segment(
                [
                    egui::pos2(c.x, c.y + h * 0.18),
                    egui::pos2(c.x + r * 0.62, c.y + h * 0.18 - r * 0.62),
                ],
                stroke,
            );
        }
        NavIcon::Chip => {
            // Кристалл с ножками.
            let body = egui::Rect::from_center_size(c, egui::vec2(w * 0.58, h * 0.58));
            painter.rect_stroke(
                body,
                egui::CornerRadius::same(2),
                stroke,
                egui::StrokeKind::Inside,
            );
            let leg = egui::Stroke::new(1.2, color);
            for k in [0.3_f32, 0.7] {
                painter.line_segment(
                    [
                        egui::pos2(body.left() + body.width() * k, rect.top()),
                        egui::pos2(body.left() + body.width() * k, body.top()),
                    ],
                    leg,
                );
                painter.line_segment(
                    [
                        egui::pos2(body.left() + body.width() * k, body.bottom()),
                        egui::pos2(body.left() + body.width() * k, rect.bottom()),
                    ],
                    leg,
                );
                painter.line_segment(
                    [
                        egui::pos2(rect.left(), body.top() + body.height() * k),
                        egui::pos2(body.left(), body.top() + body.height() * k),
                    ],
                    leg,
                );
                painter.line_segment(
                    [
                        egui::pos2(body.right(), body.top() + body.height() * k),
                        egui::pos2(rect.right(), body.top() + body.height() * k),
                    ],
                    leg,
                );
            }
        }
        NavIcon::Sky => {
            // Солнце за облаком.
            painter.circle_stroke(
                egui::pos2(rect.left() + w * 0.34, rect.top() + h * 0.32),
                w * 0.19,
                egui::Stroke::new(1.2, color),
            );
            let cloud = egui::Rect::from_min_max(
                egui::pos2(rect.left() + w * 0.1, c.y),
                egui::pos2(rect.right() - w * 0.05, rect.bottom() - h * 0.12),
            );
            painter.rect_stroke(
                cloud,
                egui::CornerRadius::same(255),
                stroke,
                egui::StrokeKind::Inside,
            );
        }
        NavIcon::Phone => {
            // Корпус с кнопкой.
            let body = egui::Rect::from_center_size(c, egui::vec2(w * 0.56, h * 0.9));
            painter.rect_stroke(
                body,
                egui::CornerRadius::same(3),
                stroke,
                egui::StrokeKind::Inside,
            );
            painter.line_segment(
                [
                    egui::pos2(c.x - w * 0.1, body.bottom() - h * 0.14),
                    egui::pos2(c.x + w * 0.1, body.bottom() - h * 0.14),
                ],
                egui::Stroke::new(1.2, color),
            );
        }
    }
}

/// Кнопка, раскрывающая нижний блок, когда ему нет места в самом рельсе.
///
/// Три точки кистью, а не знак «⋯»: тот есть только в `Hack`, а `Hack` стоит
/// лишь в `Monospace`, куда запасной глиф egui не заглядывает, — получился бы
/// пустой прямоугольник, и молча.
///
/// `wide` — видны ли подписи пунктов (`RailLayout::Labels`): тогда и у этой
/// кнопки точки встают на место значка, а рядом подпись, как у соседей.
fn rail_more_button(
    ui: &mut egui::Ui,
    state: &RailState<'_>,
    picks: &mut RailPicks,
    wide: bool,
) {
    let pal = state.pal;
    let label = i18n::t(state.lang, Key::NavSettings);
    let (rect, response) = ui.allocate_exact_size(
        egui::vec2(ui.available_width(), theme::NAV_ITEM_HEIGHT),
        egui::Sense::click(),
    );
    // Три точки — картинка, и без имени диктору кнопку не назвать.
    response.widget_info(|| egui::WidgetInfo::labeled(egui::WidgetType::Button, true, label));
    let touch = touch_at(ui, response.id, state.speed);
    let painter = ui.painter();
    painter.rect_filled(
        rect,
        egui::CornerRadius::same(theme::RADIUS_NAV),
        motion::mix(egui::Color32::TRANSPARENT, pal.card_inner, touch),
    );
    let ink = motion::mix(pal.text_secondary, pal.text_primary, touch);
    let dots = if wide {
        egui::pos2(rect.left() + NAV_ICON_CENTER, rect.center().y)
    } else {
        rect.center()
    };
    for k in [-1.0_f32, 0.0, 1.0] {
        painter.circle_filled(egui::pos2(dots.x + k * 6.0, dots.y), 1.8, ink);
    }
    if wide {
        paint_rail_label(ui, rect, label, ink);
    }

    let response = response
        .on_hover_cursor(egui::CursorIcon::PointingHand)
        .on_hover_text(i18n::t(state.lang, Key::NavMoreHint));
    if response.clicked() {
        picks.more_open = !picks.more_open;
    }

    // Меню над кнопкой: рельс прижат к низу окна, и раскрывать его вниз
    // некуда. Закрывается щелчком мимо, клавишей Esc и действием, которое
    // открывает своё окно (`RailPicks::opens_something`).
    //
    // Щелчок **внутри** его не закрывает, и это не вкус. Умолчание `Popup` —
    // `CloseOnClick`, то есть любой щелчок, свой тоже, — и щелчок по кнопке
    // языка закрывал меню вместе с только что открытым списком языков: в
    // узком окне язык было не сменить вовсе. В широком всё работало, блок там
    // стоит без меню вокруг, так что заметить это можно было только сузив
    // окно. Держит `the_language_changes_from_the_narrow_rail`.
    let mut open = picks.more_open;
    egui::Popup::new(
        egui::Id::new("savio-rail-more"),
        ui.ctx().clone(),
        rect,
        ui.layer_id(),
    )
    .kind(egui::PopupKind::Menu)
    .close_behavior(egui::PopupCloseBehavior::CloseOnClickOutside)
    .layout(egui::Layout::top_down(egui::Align::Min))
    // Штатный стиль меню здесь не годится, и это видно только глазами:
    // `menu_style` снимает у виджетов кромку — кнопки «Обновить движок»
    // и «О программе» превращаются в строчки текста, неотличимые от
    // подписей рядом. Блок обязан выглядеть так же, как в развёрнутом
    // рельсе, — это один и тот же блок.
    .align(egui::RectAlign::RIGHT_END)
    .gap(6.0)
    .open_bool(&mut open)
    .show(|ui| {
        // Ширину задаём с обеих сторон: без потолка меню растягивается
        // по строке версий, а та длинная и в рельсе обрезается.
        ui.set_min_width(theme::NAV_BLOCK_WIDTH);
        ui.set_max_width(theme::NAV_BLOCK_WIDTH);
        rail_block(ui, state, picks);
    });
    if picks.opens_something() {
        open = false;
    }
    picks.more_open = open;
}

/// Зазор между кнопками в рядах нижнего блока рельса.
const RAIL_ROW_GAP: f32 = 6.0;

/// Нижний блок рельса: обслуживание и настройки окна.
///
/// Один и тот же и в развёрнутом рельсе, и во всплывающем меню свёрнутого:
/// две копии разъехались бы при первой же правке, и в узком окне пропала бы
/// как раз та настройка, которую добавили последней.
fn rail_block(ui: &mut egui::Ui, state: &RailState<'_>, picks: &mut RailPicks) {
    let pal = state.pal;
    let lang = state.lang;
    let speed = state.speed;

    // Точка зелёная, когда версии известны, и приглушённая, пока опрос идёт.
    // Цветом одним ничего не сказано — рядом текст.
    let known = !state.tools.is_empty();
    ui.horizontal(|ui| {
        ui.spacing_mut().item_spacing.x = 7.0;
        let (dot, _) = ui.allocate_exact_size(egui::vec2(7.0, 7.0), egui::Sense::hover());
        ui.painter().circle_filled(
            dot.center(),
            3.5,
            if known { pal.state_success } else { pal.text_muted },
        );
        ui.label(
            egui::RichText::new(i18n::t(lang, Key::UiAllInPlaceShort))
                .small()
                .color(pal.text_secondary),
        );
        // «?» — первый вход в приветствие — живёт в этой строке, справа,
        // маленьким кружком. Таблеткой в ряду языка и журнала он не
        // помещался уже по-русски (ряд в 197 точек при 168 доступных), а
        // по-армянски тем более: ряд вылезал за кромку блока и раздвигал за
        // собой соседей. Рядом с «О программе» — тоже нет: та от тесноты
        // переносилась на две строки. Держит `the_rail_labels_fit_their_width`.
        ui.with_layout(egui::Layout::right_to_left(egui::Align::Center), |ui| {
            if help_button(ui, pal, lang, speed).clicked() {
                picks.welcome = true;
            }
        });
    });

    // Строка версий. Подсказку с полным текстом вешает сама обрезанная метка
    // (`show_tooltip_when_elided`), поэтому своего `on_hover_text` здесь нет —
    // он дал бы вторую коробку с тем же текстом (дефект 22).
    //
    // `text_muted`, а не `text_faint`: блок — вложенная подложка, и там
    // `text_faint` даёт 4.23:1, ниже порога (см. поле палитры).
    if known {
        ui.add(
            egui::Label::new(
                egui::RichText::new(state.tools)
                    .small()
                    .color(pal.text_muted),
            )
            .truncate(),
        );
    }

    ui.add_space(8.0);
    ui.add_enabled_ui(!state.busy, |ui| {
        for (key, hint, what) in [
            (
                Key::UiUpdateEngine,
                Key::UiUpdateEngineHint,
                setup::Component::Ytdlp,
            ),
            (
                Key::UiUpdateFfmpeg,
                Key::UiUpdateFfmpegHint,
                setup::Component::Ffmpeg,
            ),
        ] {
            if wide_pill(ui, i18n::t(lang, key), speed)
                .on_hover_text(i18n::t(lang, hint))
                .clicked()
            {
                picks.update = Some(what);
            }
        }
    });

    ui.add_space(8.0);
    // Массивом, а не `Vec`: блок рисуется каждый кадр, и куча здесь ни к чему.
    let themes = Appearance::ALL.map(|choice| (choice, choice.label(lang)));
    let picked = segment_track(
        ui,
        pal,
        egui::Id::new("track:theme"),
        speed,
        state.appearance,
        &themes,
        true,
    );
    if let Some(choice) = picked {
        picks.appearance = Some(choice);
    }
    ui.add_space(2.0);

    ui.horizontal(|ui| {
        ui.spacing_mut().item_spacing.x = RAIL_ROW_GAP;
        // Язык — одной подписью с текущим выбором, список открывается меню.
        // Три подписи подряд в 216 точек не влезают ни на одном языке.
        //
        // Открытость меню живёт в `Context::data`, а не полем окна: она
        // нужна ровно здесь и ровно на время показа, а поле пришлось бы
        // тащить через `RailState` и `RailPicks` туда и обратно.
        let response = pill_button(ui, lang.label(), speed)
            .on_hover_text(i18n::t(lang, Key::UiLanguageHint));
        let mut open = ui
            .ctx()
            .data(|d| d.get_temp::<bool>(egui::Id::new("rail-lang")).unwrap_or(false));
        if response.clicked() {
            open = !open;
        }
        egui::Popup::new(
            egui::Id::new("savio-rail-lang"),
            ui.ctx().clone(),
            response.rect,
            ui.layer_id(),
        )
        .kind(egui::PopupKind::Menu)
        .layout(egui::Layout::top_down_justified(egui::Align::Min))
        .style(egui::containers::menu::menu_style)
        .align(egui::RectAlign::TOP_START)
        .gap(6.0)
        .open_bool(&mut open)
        .show(|ui| {
            for other in Lang::ALL {
                if choice_pill(ui, pal, other.label(), other == lang, speed).clicked() {
                    picks.lang = Some(other);
                }
            }
        });
        ui.ctx()
            .data_mut(|d| d.insert_temp(egui::Id::new("rail-lang"), open));

        let log = ui.add_enabled_ui(state.has_log, |ui| {
            toggle_pill(ui, pal, i18n::t(lang, Key::UiLog), state.log_open, speed)
        });
        if log.inner.clicked() {
            picks.toggle_log = true;
        }
        if !state.has_log {
            log.response.on_hover_text(i18n::t(lang, Key::UiLogEmpty));
        }
    });

    ui.add_space(2.0);
    if wide_pill(ui, i18n::t(lang, Key::UiAbout), speed)
        .on_hover_text(i18n::t(lang, Key::UiAboutHint))
        .clicked()
    {
        picks.about = true;
    }

    ui.add_space(4.0);
    let mut smooth = state.smooth;
    if checkbox(ui, pal, &mut smooth, i18n::t(lang, Key::UiSmooth), true)
        .on_hover_text(i18n::t(lang, Key::UiSmoothHint))
        .changed()
    {
        picks.smooth = Some(smooth);
    }
}

/// Круглая кнопка «?» в строке состояния рельса: вход в приветствие.
///
/// Нарисована кистью, а не таблеткой: в строку высотой с подпись таблетка
/// штатной высоты не встаёт, и строка раздулась бы ради одного знака. Кромка
/// и знак — те же роли, что у вторичной кнопки (`border_strong` и
/// `text_secondary`), так что контраст на подложке блока уже проверен.
fn help_button(ui: &mut egui::Ui, pal: theme::Palette, lang: Lang, speed: f32) -> egui::Response {
    const SIZE: f32 = 20.0;
    let hint = i18n::t(lang, Key::UiHelpButtonHint);
    let (rect, response) = ui.allocate_exact_size(egui::vec2(SIZE, SIZE), egui::Sense::click());
    // Знак вопроса — картинка, и назвать кнопку диктору нечем, кроме подсказки.
    response.widget_info(|| egui::WidgetInfo::labeled(egui::WidgetType::Button, true, hint));
    let touch = touch_at(ui, response.id, speed);
    let painter = ui.painter();
    painter.circle_stroke(
        rect.center(),
        SIZE / 2.0 - 0.5,
        egui::Stroke::new(1.0, motion::mix(pal.border_strong, pal.border_hover, touch)),
    );
    painter.text(
        rect.center(),
        egui::Align2::CENTER_CENTER,
        "?",
        egui::FontId::new(12.0, egui::FontFamily::Proportional),
        motion::mix(pal.text_secondary, pal.text_primary, touch),
    );
    response
        .on_hover_cursor(egui::CursorIcon::PointingHand)
        .on_hover_text(hint)
}

/// Две карточки направления в ряд: «На телефон» и «На компьютер».
///
/// Ряд разваливается в колонку, когда места мало: две карточки по два
/// предложения в каждой в колонке шириной 340 читались бы по три слова
/// в строке. Порог — из самой раскладки, а не на глаз: карточке нужно
/// около 200 точек, чтобы заголовок со стрелкой встал в одну строку.
fn direction_cards(ui: &mut egui::Ui, pal: theme::Palette, lang: Lang, pairs: [(Key, Key); 2]) {
    const SIDE_BY_SIDE: f32 = 200.0 * 2.0 + 12.0;
    const ARROWS: [&str; 2] = ["→", "←"];

    let card = |ui: &mut egui::Ui, arrow: &str, title: Key, text: Key| {
        // Раскладка задаётся явно: в колонках `ui.columns` выключка тянет
        // пробелы до кромки, и абзац набирается дырами.
        let width = ui.available_width();
        ui.with_layout(egui::Layout::top_down(egui::Align::Min), |ui| {
            ui.set_width(width);
            theme::inner_frame(pal).show(ui, |ui| {
                ui.set_width(ui.available_width());
                ui.horizontal(|ui| {
                    ui.spacing_mut().item_spacing.x = 8.0;
                    ui.label(
                        egui::RichText::new(arrow)
                            .font(theme::bold(15.0))
                            .color(pal.accent),
                    );
                    ui.label(
                        egui::RichText::new(i18n::t(lang, title))
                            .font(theme::bold(14.0))
                            .color(pal.text_primary),
                    );
                });
                ui.add_space(4.0);
                note(ui, i18n::t(lang, text), pal.text_muted);
            });
        });
    };

    if ui.available_width() >= SIDE_BY_SIDE {
        ui.columns(2, |columns| {
            for (column, (arrow, (title, text))) in
                columns.iter_mut().zip(ARROWS.into_iter().zip(pairs))
            {
                card(column, arrow, title, text);
            }
        });
    } else {
        for (arrow, (title, text)) in ARROWS.into_iter().zip(pairs) {
            card(ui, arrow, title, text);
            ui.add_space(8.0);
        }
    }
}

/// Строка списка проверок перед стартом: знак, заголовок и пояснение.
///
/// Не путать с `check_row` — та про строку отчёта о системе.
///
/// Знак рисуется кистью, а не берётся из шрифта. «✓» (U+2713) не нашлось
/// **ни в одной** из тринадцати доступных Savio гарнитур — ни в девяти
/// своих, ни в четырёх штатных у eframe, — и вышел бы пустой прямоугольник,
/// причём молча. Проверено разбором таблиц `cmap` у самих файлов.
fn checklist_row(
    ui: &mut egui::Ui,
    pal: theme::Palette,
    ok: bool,
    title: &str,
    text: Option<&str>,
) {
    let color = if ok { pal.state_success } else { pal.state_warning };
    theme::inner_frame(pal).show(ui, |ui| {
        ui.set_width(ui.available_width());
        ui.horizontal(|ui| {
            ui.spacing_mut().item_spacing.x = 10.0;
            let (mark, _) = ui.allocate_exact_size(egui::vec2(18.0, 18.0), egui::Sense::hover());
            check_mark(ui.painter(), mark, ok, color);

            // Подпись с пояснением — колонкой справа от знака, и ширину ей
            // задаём явно: без этого пояснение уходит под знак, а не под
            // заголовок.
            let width = ui.available_width();
            ui.with_layout(egui::Layout::top_down(egui::Align::Min), |ui| {
                ui.set_width(width);
                ui.label(
                    egui::RichText::new(title)
                        .font(theme::bold(14.0))
                        .color(pal.text_primary),
                );
                if let Some(text) = text {
                    ui.add_space(3.0);
                    note(ui, text, pal.text_muted);
                }
            });
        });
    });
}

/// Галочка в кружке или восклицательный знак в нём же.
fn check_mark(painter: &egui::Painter, rect: egui::Rect, ok: bool, color: egui::Color32) {
    let r = rect.width() / 2.0 - 1.0;
    painter.circle_stroke(rect.center(), r, egui::Stroke::new(1.2, color));
    let stroke = egui::Stroke::new(1.6, color);
    if ok {
        let c = rect.center();
        painter.line_segment(
            [
                egui::pos2(c.x - r * 0.45, c.y),
                egui::pos2(c.x - r * 0.1, c.y + r * 0.38),
            ],
            stroke,
        );
        painter.line_segment(
            [
                egui::pos2(c.x - r * 0.1, c.y + r * 0.38),
                egui::pos2(c.x + r * 0.48, c.y - r * 0.38),
            ],
            stroke,
        );
    } else {
        let c = rect.center();
        painter.line_segment(
            [
                egui::pos2(c.x, c.y - r * 0.5),
                egui::pos2(c.x, c.y + r * 0.12),
            ],
            stroke,
        );
        painter.circle_filled(egui::pos2(c.x, c.y + r * 0.45), 1.1, color);
    }
}

/// Что получилось из строки заголовка раздела за кадр.
struct SectionTitle {
    /// Щёлкнули по номеру версии.
    about: bool,
    /// Где лёг номер версии.
    version: egui::Rect,
    /// Где легло пояснение к разделу — то, что в него упирается.
    note: egui::Rect,
}

/// Зазор между строкой заголовка раздела и прокруткой под ней.
///
/// Именем, а не числом по месту, ради проверки высоты при открытом журнале:
/// она складывает раздел из тех же частей, что и окно, и своя копия зазора
/// разъехалась бы с раскладкой при первой же правке.
const SECTION_TITLE_GAP: f32 = 10.0;

/// Оболочка содержимого окна: поля вокруг раздела.
///
/// Функцией, а не рамкой по месту, по той же причине, что и
/// [`SECTION_TITLE_GAP`]: проверка высоты при открытом журнале рисует раздел
/// в этой же рамке.
fn content_frame() -> egui::Frame {
    egui::Frame::new().inner_margin(egui::Margin::symmetric(theme::CONTENT_MARGIN as i8, 16))
}

/// Строка заголовка раздела без `self`.
///
/// Отдельно от метода ради проверки: запас по ширине здесь — величина
/// переменная (пояснения у разделов разной длины, а переводов три), и
/// померить наложение можно только у того, что окно и тест берут из
/// одного места.
fn section_title_row(
    ui: &mut egui::Ui,
    pal: theme::Palette,
    lang: Lang,
    speed: f32,
    title: &str,
    note_key: Key,
) -> SectionTitle {
    let mut row = SectionTitle {
        about: false,
        version: egui::Rect::NOTHING,
        note: egui::Rect::NOTHING,
    };

    // Высоту ряду задаём явно: `with_layout` отдал бы потомку весь остаток
    // высоты, а центрирующая раскладка считает его занятым целиком — строка
    // заголовка уехала бы в середину экрана (дефект 42).
    ui.allocate_ui_with_layout(
        egui::vec2(ui.available_width(), theme::CONTROL_HEIGHT),
        // Справа налево, и номер версии кладётся **первым**. Иначе
        // обрезаемое пояснение занимает столько, сколько просит текст,
        // о соседе справа ничего не зная, — и в окне 520 оно наползало
        // на версию: «…over yo0.32.1». Проверено глазами.
        egui::Layout::right_to_left(egui::Align::Center),
        |ui| {
            ui.spacing_mut().item_spacing.x = 10.0;

            // Щелчок по версии открывает «О программе», и это не украшение,
            // а запасной вход: в узком окне нижний блок рельса свёрнут
            // в одну кнопку.
            let t = touch_at(ui, ui.next_auto_id(), speed);
            let version = ui
                .add(
                    egui::Label::new(
                        egui::RichText::new(VERSION)
                            .small()
                            .color(motion::mix(pal.text_faint, pal.text_primary, t)),
                    )
                    .selectable(false)
                    .sense(egui::Sense::click()),
                )
                .on_hover_cursor(egui::CursorIcon::PointingHand)
                .on_hover_text(i18n::t(lang, Key::UiAboutVersionHint));
            row.version = version.rect;
            row.about = version.clicked();

            ui.with_layout(egui::Layout::left_to_right(egui::Align::Center), |ui| {
                ui.spacing_mut().item_spacing.x = 10.0;
                ui.label(
                    egui::RichText::new(title)
                        .font(theme::display(24.0))
                        .color(pal.text_primary),
                );

                // Тире отдельной подписью, а не приклеенным к тексту через
                // `format!`: строка заголовка рисуется каждый кадр, и склейка
                // стоила бы аллокации шестьдесят раз в секунду ни за что.
                ui.label(egui::RichText::new("—").small().color(pal.text_muted));
                ui.spacing_mut().item_spacing.x = 5.0;
                // Пояснение обрезается, а не переносится: оно второстепенно,
                // а в узком окне места ему нет вовсе.
                row.note = ui
                    .add(
                        egui::Label::new(
                            egui::RichText::new(i18n::t(lang, note_key))
                                .small()
                                .color(pal.text_muted),
                        )
                        .truncate(),
                    )
                    .rect;
            });
        },
    );

    row
}

/// Правая колонка «Состава»: зачем раздел здесь и что значит прочерк.
///
/// Второе важнее первого. Прочерк на месте значения человек читает как
/// «железа нет» или «Savio сломался», хотя это молчание системы: без прав
/// администратора половина сведений недоступна в принципе (Правило 6 про
/// WMI). Сказать это надо рядом с отчётом, а не в справке.
fn system_rail(ui: &mut egui::Ui, pal: theme::Palette, lang: Lang) {
    for (title, text) in [
        (Key::UiMachineWhy, Key::UiMachineWhyNote),
        (Key::UiMachineDashTitle, Key::UiMachineDashNote),
    ] {
        theme::card(ui, pal, |ui| {
            ui.label(
                egui::RichText::new(i18n::t(lang, title))
                    .font(theme::display(17.0))
                    .color(pal.text_primary),
            );
            ui.add_space(8.0);
            note(ui, i18n::t(lang, text), pal.text_muted);
        });
        ui.add_space(14.0);
    }
}

/// Поперечник кружка с номером в заголовке шага.
///
/// Вынесен из `step_header` вместе с зазором и шрифтом названия ради
/// `step_fits`: проверка «поместится ли плашка рядом» обязана считать по тем
/// же числам, что и раскладка, — своя копия разъехалась бы при первой правке.
const STEP_CIRCLE: f32 = 26.0;
/// Зазор между частями заголовка шага.
const STEP_GAP: f32 = 10.0;

fn step_title_font() -> egui::FontId {
    theme::display(17.0)
}

/// Поместится ли плашка справа от названия шага, не налезая на него.
///
/// `step_header` кладёт правую часть от правой кромки, и если строки не
/// хватает, плашка уезжает влево — прямо поверх названия, а её заливка
/// прозрачна на девять десятых, так что буквы ложатся одни на другие.
/// По-армянски так и выходило: «Ֆայլի մետատվյալներ» и «4 անձնական
/// գրառում» вместе длиннее строки в карточке шириной 364 (найдено ревью
/// задачи 65). Не поместилась — вызывающий кладёт её строкой ниже.
fn step_fits(ui: &egui::Ui, title: &str, pill: &str) -> bool {
    let title = ui
        .painter()
        .layout_no_wrap(title.to_owned(), step_title_font(), egui::Color32::PLACEHOLDER)
        .size()
        .x;
    STEP_CIRCLE + STEP_GAP + title + STEP_GAP + soft_pill_width(ui, pill) <= ui.available_width()
}

/// Заголовок шага: номер в кружке и название дисплейным начертанием.
///
/// Номер отвечает на «с чего начинать» раньше, чем человек прочтёт подписи.
/// Без него экран загрузки читался списком равноправных настроек, в котором
/// непонятно, что обязательно, а что можно не трогать: поле ссылки, две
/// дорожки, три галочки и свёрнутая группа выглядели одинаково важными.
///
/// `note` — короткое пояснение **рядом с названием**, мелким приглушённым
/// шрифтом («— MP3 или изображение»). `right` — то, что встаёт у правого края
/// строки: плашка состояния шага. Это два разных места, и путать их нельзя:
/// первый вариант этой функции знал только `right`, и пояснение, переданное
/// туда, уезжало к правой кромке карточки — в полуметре от названия, к
/// которому относилось. Проверено глазами на «Метаданных».
///
/// `right` — замыкание, а не `Option`, чтобы вызывающему не приходилось
/// собирать виджет заранее: рисовать его надо внутри нужной раскладки.
///
/// Высота ряду задаётся явно. `with_layout` отдал бы потомку весь остаток
/// высоты карточки, а центрирующая раскладка считает его занятым целиком —
/// заголовок уехал бы в середину экрана (дефект 42).
fn step_header<R>(
    ui: &mut egui::Ui,
    pal: theme::Palette,
    number: usize,
    title: &str,
    note: Option<&str>,
    right: impl FnOnce(&mut egui::Ui) -> R,
) {
    const CIRCLE: f32 = STEP_CIRCLE;

    ui.allocate_ui_with_layout(
        egui::vec2(ui.available_width(), CIRCLE),
        egui::Layout::left_to_right(egui::Align::Center),
        |ui| {
            ui.spacing_mut().item_spacing.x = STEP_GAP;

            // Кружок с номером рисуется кистью: цифра в кружке — это не знак
            // из шрифта (кружкам с цифрами внутри в наших гарнитурах взяться
            // неоткуда), а две фигуры и текст поверх них.
            let (circle, _) =
                ui.allocate_exact_size(egui::vec2(CIRCLE, CIRCLE), egui::Sense::hover());
            let painter = ui.painter();
            painter.circle_filled(circle.center(), CIRCLE / 2.0, pal.accent_soft);
            painter.circle_stroke(
                circle.center(),
                CIRCLE / 2.0,
                egui::Stroke::new(1.0, pal.accent),
            );
            painter.text(
                circle.center(),
                egui::Align2::CENTER_CENTER,
                number,
                theme::display(13.0),
                pal.accent_text,
            );

            ui.label(
                egui::RichText::new(title)
                    .font(step_title_font())
                    .color(pal.text_primary),
            );

            // Правая часть кладётся **до** пояснения, и это не порядок ради
            // порядка: пояснение обрезается, а обрезаемая метка занимает
            // столько, сколько просит текст, и о соседе справа не знает.
            // Положи её первой — и плашка «Ролик найден» уехала бы под неё.
            ui.with_layout(egui::Layout::right_to_left(egui::Align::Center), |ui| {
                right(ui);
                if let Some(note) = note {
                    ui.with_layout(egui::Layout::left_to_right(egui::Align::Center), |ui| {
                        ui.add(
                            egui::Label::new(
                                egui::RichText::new(note).small().color(pal.text_muted),
                            )
                            .truncate(),
                        );
                    });
                }
            });
        },
    );
}

/// Кнопка-«таблетка» во всю ширину.
///
/// Нужна рельсу: там кнопки стоят колонкой, и разной ширины они выглядели
/// бы обрывками. Отдельной функцией, а не флагом у `pill_button`: тот стоит
/// в полусотне мест, и лишний аргумент там ничего не объясняет.
fn wide_pill(ui: &mut egui::Ui, label: &str, speed: f32) -> egui::Response {
    // Подпись **переносится**, и это не украшение. Рельс узкий, а переводы
    // длиннее русского: армянское «Обновить движок» — 175 точек при 168
    // доступных, и без переноса кнопка раздвинулась бы за кромку блока.
    // Высота задана полом, а не потолком, поэтому на вторую строку кнопка
    // вырастает сама. Что двух строк хватает на всех языках, держит
    // `the_rail_labels_fit_their_width`.
    let width = ui.available_width();
    with_touch(ui, speed, |ui| {
        ui.add(
            egui::Button::new(label)
                .wrap()
                .min_size(egui::vec2(width, theme::CONTROL_HEIGHT)),
        )
    })
}

/// Вторичная кнопка.
fn pill_button(ui: &mut egui::Ui, label: &str, speed: f32) -> egui::Response {
    ui.scope(|ui| with_touch(ui, speed, |ui| ui.add(pill(label))))
        .inner
}

/// `ui.add_sized`, но с откликом под курсором.
///
/// Раскладка та же самая: `add_sized` — это и есть `allocate_ui_with_layout`
/// с центрирующей раскладкой, здесь она просто выписана, чтобы внутрь
/// поместился [`with_touch`].
fn sized_with_touch<R>(
    ui: &mut egui::Ui,
    size: egui::Vec2,
    speed: f32,
    add: impl FnOnce(&mut egui::Ui) -> R,
) -> R {
    ui.allocate_ui_with_layout(
        size,
        egui::Layout::centered_and_justified(egui::Direction::TopDown),
        |ui| with_touch(ui, speed, add),
    )
    .inner
}

/// Кнопка-выключатель: нажатая заливается мягким акцентом.
///
/// Состояние сказано не только цветом — включённая ещё и обведена акцентной
/// границей, а рядом с ней всегда есть то, что она показывает.
fn toggle_pill(
    ui: &mut egui::Ui,
    pal: theme::Palette,
    label: &str,
    on: bool,
    speed: f32,
) -> egui::Response {
    ui.scope(|ui| {
        if on {
            let v = ui.visuals_mut();
            for state in [
                &mut v.widgets.inactive,
                &mut v.widgets.hovered,
                &mut v.widgets.active,
            ] {
                state.weak_bg_fill = pal.accent_soft;
                state.bg_stroke = egui::Stroke::new(1.0, pal.accent);
                state.fg_stroke = egui::Stroke::new(1.0, pal.accent_hover);
            }
        }
        // Отклик под курсором добавляет `pill_button`, и включённой кнопке
        // он ничего не меняет: покой и наведение у неё выше выставлены
        // одинаково, так что смешивать нечего.
        pill_button(ui, label, speed)
    })
    .inner
}

/// Поля плашки [`soft_pill`] по бокам от подписи.
const SOFT_PILL_PAD_X: f32 = 11.0;

/// Сколько места займёт плашка с этой подписью — по той же раскладке текста,
/// что у самой плашки.
fn soft_pill_width(ui: &egui::Ui, text: &str) -> f32 {
    let font = egui::TextStyle::Small.resolve(ui.style());
    let galley = ui
        .painter()
        .layout_no_wrap(text.to_owned(), font, egui::Color32::PLACEHOLDER);
    galley.size().x + SOFT_PILL_PAD_X * 2.0
}

/// Неинтерактивная плашка: подпись на мягкой подложке.
///
/// Ею сказаны «MP3», «JPG» и «Опрос идёт» — то, что читают, но не нажимают.
///
/// Рисуется своими руками, а не `Frame` с меткой внутри, и это не вкусовщина.
/// Внутри `horizontal_wrapped` контейнер не знает, сколько места осталось
/// в строке, поэтому берёт ширину по своему содержимому — и плашка вылезает
/// за кромку карточки, утаскивая за собой саму карточку. Проверено глазами:
/// «TIFF — только чтение» так и уехал за правый край окна. Здесь ширина
/// известна заранее, из разложенного текста, и `horizontal_wrapped`
/// переносит плашку сам.
fn soft_pill(
    ui: &mut egui::Ui,
    pal: theme::Palette,
    text: &str,
    color: egui::Color32,
    fill: egui::Color32,
) {
    const PAD_X: f32 = SOFT_PILL_PAD_X;
    const HEIGHT: f32 = 24.0;

    let font = egui::TextStyle::Small.resolve(ui.style());
    // Раскладка текста у egui кэшируется по самой строке, так что повторный
    // вызов с той же подписью считает только хеш.
    let galley = ui.painter().layout_no_wrap(
        text.to_owned(),
        font,
        egui::Color32::PLACEHOLDER,
    );

    let (rect, response) = ui.allocate_exact_size(
        egui::vec2(galley.size().x + PAD_X * 2.0, HEIGHT),
        egui::Sense::hover(),
    );
    // Плашку читают, а не нажимают, — значит, прочесть её должен и экранный
    // диктор. Нарисованное кистью без имени для него не существует, и
    // «2 личные записи» над таблицей сказаны были бы одним цветом строк.
    response.widget_info(|| egui::WidgetInfo::labeled(egui::WidgetType::Label, true, text));
    if !ui.is_rect_visible(rect) {
        return;
    }

    let painter = ui.painter();
    let stroke = if fill == egui::Color32::TRANSPARENT {
        egui::Stroke::new(1.0, pal.border_subtle)
    } else {
        egui::Stroke::NONE
    };
    painter.rect(
        rect,
        egui::CornerRadius::same(theme::RADIUS_PILL),
        fill,
        stroke,
        egui::StrokeKind::Inside,
    );
    painter.galley(
        egui::pos2(rect.left() + PAD_X, rect.center().y - galley.size().y / 2.0),
        galley,
        color,
    );
}

/// Переключатель-«чип»: галочка и подпись в одной «таблетке».
///
/// Своими руками, а не `Checkbox` в рамке, и рисуется здесь всё, включая
/// саму галочку. Причина у галочки та же, по которой в оверлее написано
/// «Закрыть», а не нарисован крестик: знака `✓` нет ни в одном из наших
/// шрифтов, и вместо него вышел бы пустой прямоугольник (Правило 4).
/// Две линии кистью надёжнее любого символа.
///
/// Галочка обязательна, а не украшение: без неё включённость чипа была бы
/// сказана одним цветом, а этого мало.
fn chip(
    ui: &mut egui::Ui,
    pal: theme::Palette,
    checked: &mut bool,
    label: &str,
    enabled: bool,
    speed: f32,
) -> egui::Response {
    const PAD: f32 = 14.0;
    const GAP: f32 = 8.0;
    const MARK: f32 = 14.0;

    ui.add_enabled_ui(enabled, |ui| {
        let font = egui::TextStyle::Button.resolve(ui.style());
        // Раскладка текста у egui кэшируется по самой строке, так что
        // повторный вызов с той же подписью считает только хеш.
        let galley =
            ui.painter()
                .layout_no_wrap(label.to_owned(), font, egui::Color32::PLACEHOLDER);

        let size = egui::vec2(
            PAD * 2.0 + MARK + GAP + galley.size().x,
            theme::CONTROL_HEIGHT,
        );
        let (rect, mut response) = ui.allocate_exact_size(size, egui::Sense::click());

        if response.clicked() {
            *checked = !*checked;
            response.mark_changed();
        }

        if !ui.is_rect_visible(rect) {
            return response;
        }

        let on = *checked;
        // Прямоугольник уже разложен, отклик получен — коэффициенты берутся
        // тем же кадром, без заглядывания в прошлый.
        let ctx = ui.ctx();
        let touch =
            ctx.animate_bool_with_time(response.id, response.hovered(), motion::TOUCH * speed);
        // Включённость едет отдельно и дольше: это смена состояния, а не
        // отклик на приближение курсора.
        let on_t = ctx.animate_bool_with_time(response.id.with("on"), on, motion::MOVE * speed);
        // Нажатие: приминаем на полтора процента ширины (приём 02). Кривая
        // `glide` — приходящее тормозит у цели; время короче отклика, иначе
        // кнопка залипает под пальцем.
        let press = motion::glide(ctx.animate_bool_with_time(
            response.id.with("press"),
            response.is_pointer_button_down_on(),
            motion::TOUCH * 0.75 * speed,
        ));
        let rect = motion::pressed(rect, press);

        // Невыбранный чип светлеет под курсором, выбранный переливается
        // в зелёный — и одно накладывается на другое, а не спорит с ним.
        let fill = motion::mix(
            motion::mix(egui::Color32::TRANSPARENT, pal.card_inner, touch),
            pal.success_soft,
            on_t,
        );
        let stroke = motion::mix(
            motion::mix(pal.border_strong, pal.border_hover, touch),
            pal.state_success,
            on_t,
        );
        let text_color = motion::mix(
            motion::mix(pal.text_secondary, pal.text_primary, touch),
            pal.text_primary,
            on_t,
        );

        let painter = ui.painter();
        painter.rect(
            rect,
            egui::CornerRadius::same(theme::RADIUS_PILL),
            fill,
            egui::Stroke::new(1.0, stroke),
            egui::StrokeKind::Inside,
        );

        // Коробка галочки: пустая у выключенного чипа, с птичкой у включённого.
        let mark = egui::Rect::from_center_size(
            egui::pos2(rect.left() + PAD + MARK / 2.0, rect.center().y),
            egui::vec2(MARK, MARK),
        );
        painter.rect(
            mark,
            egui::CornerRadius::same(theme::RADIUS_TINY),
            egui::Color32::TRANSPARENT,
            egui::Stroke::new(1.4, motion::mix(stroke, pal.state_success, on_t)),
            egui::StrokeKind::Inside,
        );
        // Птичка не возникает, а проявляется вместе с заливкой. Порог, а не
        // `if on`: на нуле рисовать нечего, а прозрачные линии всё равно
        // уехали бы в вершинный буфер.
        if on_t > 0.0 {
            let tick = egui::Stroke::new(
                1.8,
                motion::mix(egui::Color32::TRANSPARENT, pal.state_success, on_t),
            );
            let (l, t, w, h) = (mark.left(), mark.top(), mark.width(), mark.height());
            painter.line_segment(
                [
                    egui::pos2(l + w * 0.24, t + h * 0.52),
                    egui::pos2(l + w * 0.44, t + h * 0.72),
                ],
                tick,
            );
            painter.line_segment(
                [
                    egui::pos2(l + w * 0.44, t + h * 0.72),
                    egui::pos2(l + w * 0.78, t + h * 0.28),
                ],
                tick,
            );
        }

        painter.galley(
            egui::pos2(
                mark.right() + GAP,
                rect.center().y - galley.size().y / 2.0,
            ),
            galley,
            text_color,
        );

        response
    })
    .inner
}

/// Содержимое, показанное на долю `t` своей высоты.
///
/// Общая половина приёмов 08 и 10: и раскрытие группы, и строка очереди
/// раздвигают соседей, а не возникают на готовом месте. Полной высоты egui
/// заранее не знает — узнать её можно только нарисовав, — поэтому она берётся
/// с прошлого кадра и лежит в памяти контекста.
///
/// `opacity` отдельно от `t` не для гибкости: у группы содержимое проступает
/// на второй половине пути, у строки — вместе с высотой, и это разные вещи.
fn clipped(
    ui: &mut egui::Ui,
    id: egui::Id,
    t: f32,
    opacity: f32,
    add: impl FnOnce(&mut egui::Ui),
) {
    let height = id.with("height");
    if t >= 1.0 {
        // Показано целиком: рисуем как обычно и заодно перемеряем высоту.
        // Перемерять надо каждый раз — содержимое меняется само (список
        // языков появляется вместе с субтитрами), и запомненное однажды
        // число обрезало бы содержимое при следующем свёртывании.
        let taken = ui.scope(add).response.rect.height();
        ui.ctx().data_mut(|d| d.insert_temp(height, taken));
        return;
    }

    let Some(full) = ui.ctx().data(|d| d.get_temp::<f32>(height)) else {
        // Высоты ещё нет. Раскладываем содержимое за пределами видимого и
        // места не занимаем: обрезать нечем, а показать целиком — мигнуть.
        let at = ui.cursor().min;
        let mut probe = ui.new_child(
            egui::UiBuilder::new()
                .max_rect(egui::Rect::from_min_size(
                    at,
                    egui::vec2(ui.available_width(), 10_000.0),
                ))
                .layout(egui::Layout::top_down(egui::Align::Min)),
        );
        probe.set_clip_rect(egui::Rect::NOTHING);
        add(&mut probe);
        let taken = probe.min_rect().height();
        ui.ctx().data_mut(|d| d.insert_temp(height, taken));
        ui.ctx().request_repaint();
        return;
    };

    let (rect, _) =
        ui.allocate_exact_size(egui::vec2(ui.available_width(), full * t), egui::Sense::hover());
    if !ui.is_rect_visible(rect) {
        return;
    }

    // Содержимое рисуется во всю свою высоту, а видно из него столько,
    // сколько отвела раскладка: обрезкой заведует `clip_rect`, а не виджет.
    let mut body = ui.new_child(
        egui::UiBuilder::new()
            .max_rect(egui::Rect::from_min_size(
                rect.min,
                egui::vec2(rect.width(), full.max(1.0)),
            ))
            .layout(egui::Layout::top_down(egui::Align::Min)),
    );
    body.set_clip_rect(rect.intersect(ui.clip_rect()));
    body.multiply_opacity(opacity);
    add(&mut body);
}

/// Раскрывающееся тело группы: едет по высоте, содержимое проступает на
/// второй половине пути (приём 08).
///
/// Полной высоты egui заранее не знает — узнать её можно только нарисовав, —
/// поэтому она берётся с прошлого кадра и лежит в памяти контекста. Ровно так
/// же устроен и штатный `CollapsingState`; своя реализация нужна лишь затем,
/// чтобы длительность брать из `motion`, а не из общего `Style::animation_time`:
/// иначе раскрытие не подчинялось бы «Плавным переходам».
///
/// В первое в жизни раскрытие тело успевает попасть один раз **невидимым**:
/// высоты ещё нет, а показать его целиком, пока раскрытие только началось, —
/// это мигнуть содержимым на кадр. Кадр короткий, поймать его снимком не
/// вышло, но он настоящий: обмер стоит того, чтобы его не было.
fn collapsing_body(
    ui: &mut egui::Ui,
    id: egui::Id,
    open: bool,
    speed: f32,
    add: impl FnOnce(&mut egui::Ui),
) {
    let t = ui
        .ctx()
        .animate_bool_with_time(id, open, motion::MOVE * speed);
    if t <= 0.0 {
        return;
    }
    // Содержимое проступает на второй половине пути: на первой ещё нечему
    // проступать — из-под кромки видна пара строк.
    clipped(ui, id, t, ((t - 0.5) * 2.0).clamp(0.0, 1.0), add);
}

/// Заголовок раскрывающейся группы: треугольник, название и сводка справа.
///
/// Возвращает `true`, когда по нему щёлкнули.
///
/// Треугольник рисуется кистью по той же причине, что и галочка в [`chip`]:
/// стрелок и треугольников в наших шрифтах нет. Подписи внутри намеренно
/// невыделяемые — иначе выделение текста съедало бы щелчок по строке.
///
/// Сводка с меткой (см. [`GroupSummary`]) горит точкой и цветом метки. Это
/// тот же знак «точка плюс подпись», что у [`status_pill`], и тех же
/// размеров: два размера одного знака читались бы как два разных знака.
fn disclosure_row(
    ui: &mut egui::Ui,
    pal: theme::Palette,
    open: bool,
    title: &str,
    summary: &GroupSummary,
    speed: f32,
) -> bool {
    const DOT: f32 = 7.0;
    const GAP: f32 = 7.0;

    let inner = ui.horizontal(|ui| {
        ui.style_mut().interaction.selectable_labels = false;
        ui.spacing_mut().item_spacing.x = 10.0;
        ui.add_space(8.0);

        let (mark, _) = ui.allocate_exact_size(egui::vec2(11.0, 11.0), egui::Sense::hover());
        let c = mark.center();
        // Треугольник не подменяется другим, а доворачивается на 90° той же
        // `liquid`, что везёт таблетку выбора: раскрытие — это тоже выбор,
        // и лёгкий перелёт у стрелки читается как одно движение с группой.
        let turn = motion::liquid(ui.ctx().animate_bool_with_time(
            ui.id().with(title),
            open,
            motion::MOVE * speed,
        ));
        let (sin, cos) = (turn * std::f32::consts::FRAC_PI_2).sin_cos();
        // Вершины свёрнутого (стрелка вправо), повёрнутые вокруг середины.
        let points = [(-2.5, -5.0), (-2.5, 5.0), (3.5, 0.0)]
            .into_iter()
            .map(|(x, y)| egui::pos2(c.x + x * cos - y * sin, c.y + x * sin + y * cos))
            .collect();
        ui.painter().add(egui::Shape::convex_polygon(
            points,
            pal.accent,
            egui::Stroke::NONE,
        ));

        ui.add(
            egui::Label::new(egui::RichText::new(title).color(pal.text_primary)).truncate(),
        );

        // Сводка прижата к правому краю и обрезается сама: подсказку с
        // полным текстом вешает обрезанная метка (дефект 22 — своя стала бы
        // второй коробкой).
        ui.with_layout(egui::Layout::right_to_left(egui::Align::Center), |ui| {
            ui.add_space(8.0);
            ui.spacing_mut().item_spacing.x = GAP;

            // Цвет переливается, а точка проявляется, — и спрашивается это
            // на каждом кадре, а не только у горящей сводки: иначе первый
            // вопрос пришёлся бы на кадр, когда вход включили, и точка
            // возникла бы сразу целиком (Правило 6).
            let id = ui.id().with(title);
            let ink = motion::tint(
                ui.ctx(),
                id.with("ink"),
                summary.mark.map_or(pal.text_muted, |tone| tone.color(pal)),
                motion::MOVE * speed,
            );
            let lit = ui.ctx().animate_bool_with_time(
                id.with("lit"),
                summary.mark.is_some(),
                motion::MOVE * speed,
            );

            let label = egui::Label::new(
                egui::RichText::new(summary.text.as_str())
                    .small()
                    .color(ink),
            )
            .truncate();
            if lit <= 0.0 {
                ui.add(label);
                return;
            }

            // Точка стоит левее подписи, а кладётся после неё: справа налево
            // первым идёт то, что правее. Обрезаемая метка забрала бы весь
            // остаток строки, и точка легла бы поверх названия группы, —
            // поэтому её место вычитается заранее. Порядком, как у
            // `process_row`, тут не спастись: точке положено стоять слева.
            let room = (ui.available_width() - DOT - GAP).max(0.0);
            ui.allocate_ui_with_layout(
                egui::vec2(room, ui.available_height()),
                egui::Layout::right_to_left(egui::Align::Center),
                |ui| ui.add(label),
            );
            let (spot, _) = ui.allocate_exact_size(egui::vec2(DOT, DOT), egui::Sense::hover());
            ui.painter().circle_filled(
                spot.center(),
                DOT / 2.0,
                motion::mix(egui::Color32::TRANSPARENT, ink, lit),
            );
        });
    });

    let rect = inner.response.rect;
    ui.interact(rect, ui.id().with(title), egui::Sense::click())
        .on_hover_cursor(egui::CursorIcon::PointingHand)
        .clicked()
}

/// Ширина колонки подписей в [`labelled_row`].
///
/// Отдельной константой, а не числом внутри: по ней считает проверка
/// `the_field_labels_fit_their_column`, а своя копия в тесте разъехалась бы
/// с раскладкой при первой же правке и перестала бы что-либо ловить.
const LABEL_COLUMN: f32 = 96.0;

/// Подписи полей, которые кладутся в эту колонку.
///
/// Списком, а не «все ключи подряд»: в колонку попадают ровно эти, и
/// проверке ширины надо знать, какие именно. Забыть дописать сюда новую
/// подпись — та же беда, что и перевести её слишком длинно, так что список
/// стоит рядом с самой колонкой.
#[cfg(test)]
const LABEL_KEYS: [Key; 5] = [
    Key::UiFormat,
    Key::QualityFieldVideo,
    Key::QualityFieldAudio,
    Key::UiEmbed,
    Key::UiWeatherTemperature,
];

/// Ряд «подпись слева, элемент управления справа».
///
/// В узком окне подпись уезжает НАД элементом: колонка в 78 точек съела бы
/// пятую часть ширины, а переключателю качества из шести ступеней и без того
/// тесно. Порог — ширина, при которой ступени ещё помещаются в строку.
fn labelled_row<R>(
    ui: &mut egui::Ui,
    pal: theme::Palette,
    label: &str,
    add: impl FnOnce(&mut egui::Ui) -> R,
) -> R {
    // Ширина колонки подписи — под самую длинную из них, «Битрейт, кбит/с».
    // При 78 она обрезалась в «Битрейт, кб…», а обрезанная подпись у
    // переключателя — это ровно та частая беда, о которой Правило 2.
    //
    // Шире её сделать нельзя: колонка отнимает ширину у дорожки качества,
    // а у той шесть ступеней и запас в десяток точек. Поэтому подписи полей
    // на всех трёх языках обязаны укладываться в это число — держит это
    // `the_field_labels_fit_their_column`.
    const LABEL_WIDTH: f32 = LABEL_COLUMN;
    const GAP: f32 = 12.0;
    // Порог, ниже которого подпись уезжает НАД элементом. Считан от
    // переключателя качества: шесть ступеней («2160p» — самая широкая)
    // требуют около 360 точек, и колонка подписи с зазором отнимает ещё
    // 108. В окне минимальной ширины столько не набирается, и там подписи
    // встают сверху — иначе последняя ступень уехала бы за кромку.
    const INLINE_MIN: f32 = 470.0;

    if ui.available_width() < INLINE_MIN {
        field_label(ui, pal, label);
        return add(ui);
    }

    ui.horizontal_top(|ui| {
        ui.spacing_mut().item_spacing.x = GAP;
        let rest = (ui.available_width() - LABEL_WIDTH - GAP).max(120.0);

        ui.allocate_ui_with_layout(
            egui::vec2(LABEL_WIDTH, theme::CONTROL_HEIGHT),
            egui::Layout::left_to_right(egui::Align::Center),
            |ui| {
                // `set_min_width` тут обязателен, хотя ширина уже запрошена
                // выше: `allocate_ui_with_layout` двигает курсор не на
                // запрошенный размер, а на тот, что занял потомок. Без него
                // короткая подпись («Формат») прижала бы элемент к себе,
                // а длинная («Качество») — нет, и колонки бы не вышло.
                ui.set_min_width(LABEL_WIDTH);
                ui.add(
                    egui::Label::new(
                        egui::RichText::new(label)
                            .small()
                            .color(pal.text_muted),
                    )
                    .truncate(),
                );
            },
        );

        ui.allocate_ui_with_layout(
            egui::vec2(rest, 0.0),
            egui::Layout::top_down(egui::Align::Min),
            |ui| {
                ui.set_min_width(rest);
                ui.set_max_width(rest);
                add(ui)
            },
        )
        .inner
    })
    .inner
}

/// Прокрутка тела журнала: пол и потолок высоты в одном месте.
///
/// Отдельной функцией, а не строчками внутри [`log_panel`], — ради теста.
/// Высоту прокрутки не видят ни сборка, ни `clippy`, а в широком окне её
/// не видно и глазами: остатка там хватает, и место выглядит исправным при
/// любой настройке. Меряет её `the_log_body_keeps_its_height`, и померить
/// может только то, что окно и тест берут из одного места.
fn log_scroll(height: f32) -> egui::ScrollArea {
    egui::ScrollArea::vertical()
        // Потолок и пол вместе дают ровно `height`, и пол здесь не
        // перестраховка. `ScrollArea` берёт высоту из
        // `available_rect_before_wrap()`, а внутри чужой прокрутки или
        // растущей панели это не «сколько влезет в окно», а остаток от
        // них — нулевой или отрицательный. `max_height` тут не помогает:
        // он потолок, а не пол (дефект 27).
        //
        // Почему без пола выходило то 64, то 75, хотя причина одна: пол
        // сам по себе у egui есть — умолчание `min_scrolled_size` в 64
        // точки, — а панель растёт по содержимому. Значит устойчива любая
        // высота от 64 и выше, и журналу достаётся та, с которой он
        // пришёл в этот круг. Свой пол, равный потолку, делает неподвижную
        // точку единственной.
        .max_height(height)
        .min_scrolled_height(height)
        .stick_to_bottom(true)
        // Короткому журналу пол не мешает быть коротким: при `auto_shrink`
        // по вертикали egui всё равно сжимает окошко под содержимое, и
        // пустого поля под парой строк не остаётся.
        .auto_shrink([false, true])
}

/// Одна строка очереди. Возвращает `true`, если нажали «убрать».
///
/// Свободная функция, а не метод: строке нужен только сам элемент, и от
/// заимствования всего `SavioApp` внутри цикла по списку это избавляет.
fn queue_row(
    ui: &mut egui::Ui,
    pal: theme::Palette,
    item: &QueueItem,
    lang: Lang,
    speed: f32,
) -> bool {
    let mut remove = false;
    let id = egui::Id::new("queue-row").with(item.id);

    // Строка не возникает и не пропадает, а раздвигает соседей и складывается
    // обратно (приём 10). Вставка едет `MOVE`, удаление — чуть быстрее: уход
    // провожать взглядом незачем.
    let born = motion::since_first_seen(ui.ctx(), id.with("born"), motion::MOVE * speed);
    let leaving = item.removing_since.map_or(0.0, |at| {
        motion::elapsed(ui.ctx(), at, motion::MOVE * QUEUE_LEAVE * speed)
    });
    let t = born.min(1.0 - leaving);
    if t <= 0.0 {
        return false;
    }

    clipped(ui, id, t, t, |ui| {
        queue_row_body(ui, pal, item, lang, speed, &mut remove);
    });
    remove
}

/// Внутренность строки очереди, без оболочки появления.
fn queue_row_body(
    ui: &mut egui::Ui,
    pal: theme::Palette,
    item: &QueueItem,
    lang: Lang,
    speed: f32,
    remove: &mut bool,
) {
    theme::inner_frame(pal)
        .show(ui, |ui| {
            // Иначе строка сжалась бы по ширине своего названия: у короткого
            // получилась бы узкая полоска посреди списка.
            ui.set_width(ui.available_width());

            ui.horizontal(|ui| {
                const GAP: f32 = 8.0;
                const BUTTON: f32 = 24.0;
                ui.spacing_mut().item_spacing.x = GAP;

                // Точка — подсказка глазу, а не носитель смысла: то же
                // состояние сказано словом строкой ниже.
                let (dot, _) = ui.allocate_exact_size(egui::vec2(8.0, 8.0), egui::Sense::hover());
                // Цвет переливается, а не подменяется, и дышит только у той
                // строки, которая вправду идёт (приёмы 10 и 14).
                let color = motion::tint(
                    ui.ctx(),
                    egui::Id::new("queue-dot").with(item.id),
                    item.status.color(pal),
                    motion::MOVE * speed,
                );
                let color = if item.status == QueueStatus::Running {
                    color.gamma_multiply(motion::breath(ui.ctx(), speed))
                } else {
                    color
                };
                ui.painter().circle_filled(dot.center(), 4.0, color);

                // Убрать можно только то, что ещё не началось: у идущей
                // загрузки для этого есть «Отмена», а у отработавшей строка —
                // единственный след того, чем всё кончилось.
                let removable = item.status == QueueStatus::Waiting && item.removing_since.is_none();

                // Место под кнопку отмеряем сами, а не кладём её первой
                // в раскладке справа налево: там короткое название прижалось
                // бы к правому краю, а начинаться строка обязана слева.
                // Отдать же название под `truncate()` без запаса нельзя —
                // оно займёт всю ширину и выдавит кнопку за кромку.
                let trailing = if removable { BUTTON + GAP } else { 0.0 };
                let width = (ui.available_width() - trailing).max(40.0);
                ui.allocate_ui_with_layout(
                    egui::vec2(width, BUTTON),
                    egui::Layout::left_to_right(egui::Align::Center),
                    |ui| {
                        // `set_min_width` тут обязателен, хотя ширина уже
                        // запрошена выше: `allocate_ui_with_layout` двигает
                        // курсор не на запрошенный размер, а на тот, что занял
                        // потомок. Без него у короткого названия кнопка
                        // прилипала бы к нему вплотную посреди строки вместо
                        // правого края. Проверено глазами.
                        ui.set_min_width(width);
                        // Подсказку с полным названием вешает сама обрезанная
                        // метка — свой `on_hover_text` рядом её не заменил бы,
                        // а добавил вторую коробку с тем же текстом.
                        ui.add(
                            egui::Label::new(
                                egui::RichText::new(&item.title).color(pal.text_primary),
                            )
                            .truncate(),
                        );
                    },
                );

                if removable {
                    *remove = ui
                        .scope(|ui| {
                            // Поля кнопке урезаем, и это не косметика.
                            // `min_size` — только нижняя граница, а желаемую
                            // ширину `Button` считает как «текст плюс
                            // `button_padding.x` с двух сторон». При штатных
                            // 14 точках (theme.rs) крестик выходит 36.5 вместо
                            // отведённых ему 24, вылезает за `max_rect` строки
                            // и расширяет его — а следующая строка стартует уже
                            // от расширенной кромки и переполняет её снова.
                            // Перекос копится вниз по списку: к десятой строке
                            // это уже сотня точек за кромкой окна. Замерено на
                            // egui 0.35; ни сборка, ни `clippy`, ни тесты
                            // этого не видят.
                            ui.spacing_mut().button_padding.x = 6.0;
                            ui.add(egui::Button::new("×").min_size(egui::vec2(BUTTON, BUTTON)))
                                .on_hover_text(i18n::t(lang, Key::UiRemoveFromQueue))
                                .clicked()
                        })
                        .inner;
                }
            });

            ui.add_space(2.0);
            ui.label(
                egui::RichText::new(&item.detail).small().color(motion::tint(
                    ui.ctx(),
                    egui::Id::new("queue-detail").with(item.id),
                    item.status.color(pal),
                    motion::MOVE * speed,
                )),
            );

            // Причина отказа — то, ради чего в этот список потом смотрят:
            // журнал к тому времени очищен следующей загрузкой. Обрезаем,
            // а не переносим: объяснения длинные, и десяток абзацев подряд
            // превратил бы список в стену текста. Полный текст показывает
            // та же штатная подсказка обрезанной метки.
            if !item.error_line.is_empty() {
                ui.add_space(2.0);
                ui.add(
                    egui::Label::new(
                        egui::RichText::new(&item.error_line)
                            .small()
                            .color(pal.state_error),
                    )
                    .truncate(),
                );
            }
        });
}

/// Одна галочка.
///
/// Вид задан здесь, а не у места вызова, и это не вкусовщина. Коробка
/// у флажка всего 16 точек в поперечнике, а общее скругление темы — 8:
/// при нём она скругляется почти в кружок, то есть выглядит радиокнопкой —
/// элементом с другим смыслом («одно из»), хотя галочки независимы. Пока
/// эта настройка стояла у карточки «Вшить в файл», следующая галочка
/// в другом месте окна получала именно кружок; ровно так и вышло с первой
/// галочкой монитора. Ни сборка, ни `clippy`, ни тесты этого не видят.
fn checkbox(
    ui: &mut egui::Ui,
    pal: theme::Palette,
    checked: &mut bool,
    label: &'static str,
    enabled: bool,
) -> egui::Response {
    ui.scope(|ui| {
        // Штатная строка виджета — 32 точки (высота поля ввода). Для галочки
        // это много: три подряд съели бы четверть окна минимальной высоты.
        ui.spacing_mut().interact_size.y = 24.0;

        let v = ui.visuals_mut();
        // `noninteractive` в списке не для полноты: выключенную галочку
        // egui рисует именно им, и без него она осталась бы с чужим
        // скруглением, то есть тем самым кружком-радиокнопкой.
        for state in [
            &mut v.widgets.noninteractive,
            &mut v.widgets.inactive,
            &mut v.widgets.hovered,
            &mut v.widgets.active,
        ] {
            // Галочку egui рисует цветом `fg_stroke` — тем же, каким красит
            // подпись рядом. Акцент нужен только самой галочке (в покое
            // коробка пуста, и без цвета выбранное не отличить от
            // невыбранного), поэтому подписи цвет задаётся отдельно, через
            // `RichText`: он перебивает цвет по умолчанию.
            state.fg_stroke = egui::Stroke::new(1.6, pal.accent);
            state.corner_radius = egui::CornerRadius::same(theme::RADIUS_TINY);
            state.expansion = 0.0;
        }
        // Коробка «утоплена», как поле ввода и дорожка переключателя: на
        // заливке карточки она иначе держится на одной тонкой рамке.
        v.widgets.inactive.bg_fill = pal.input_fill;

        ui.add_enabled(
            enabled,
            egui::Checkbox::new(
                checked,
                egui::RichText::new(label).color(pal.text_primary),
            ),
        )
    })
    .inner
}

/// Красная рамка у поля, в котором ошиблись: в покое, при наведении и в фокусе.
///
/// `selection.stroke` в списке не для полноты — это и есть рамка поля, когда
/// в нём стоит курсор. Без неё поле краснеет ровно до того мгновения, когда
/// человек начинает его исправлять.
///
/// Одна функция на все поля ввода: разъехавшись, две одинаковые по смыслу
/// ошибки выглядели бы по-разному.
fn mark_invalid(pal: theme::Palette, ui: &mut egui::Ui) {
    let v = ui.visuals_mut();
    let error = egui::Stroke::new(1.0, pal.state_error);
    v.widgets.inactive.bg_stroke = error;
    v.widgets.hovered.bg_stroke = error;
    v.widgets.active.bg_stroke = error;
    v.selection.stroke = error;
}

/// Поле ввода времени: «1:30», «1:02:03» или число секунд.
///
/// Возвращает `true`, когда текст правили: разбирать строку в кадре отрисовки
/// незачем, это работа обработчика изменения.
fn time_field(
    ui: &mut egui::Ui,
    pal: theme::Palette,
    value: &mut String,
    hint: &'static str,
    invalid: bool,
    width: f32,
) -> bool {
    ui.scope(|ui| {
        if invalid {
            mark_invalid(pal, ui);
        }

        ui.add_sized(
            [width, theme::CONTROL_HEIGHT],
            egui::TextEdit::singleline(value)
                .hint_text(hint)
                .text_color(pal.text_primary)
                .margin(egui::Margin::symmetric(10, 6)),
        )
        .changed()
    })
    .inner
}

/// Кнопка выбора «одно из»: подпись в таблетке, выбранная — с акцентом.
///
/// Рисуется своими руками, и причина не в оформлении, а в переносе строки.
/// Готовый [`toggle_pill`] заводит внутри `ui.scope`, а тот сообщает
/// раскладке занятое место **задним числом**, минуя `next_space` — то есть
/// мимо всей логики переноса. В `horizontal_wrapped` такая кнопка на новую
/// строку не уезжает: она вылезает за кромку карточки и тянет карточку за
/// собой. По той же причине выключать ряд надо целиком, снаружи, а не
/// каждую кнопку через `add_enabled_ui`: это тот же `scope`.
///
/// Проверено глазами в окне 520×420: третья таблетка режима обрезалась
/// кромкой окна, а подпись второй заворачивалась в две строки внутри самой
/// таблетки. Ни сборка, ни `clippy`, ни тесты этого не видят.
///
/// Здесь ширина известна заранее, из разложенного текста, и место просится
/// через `allocate_exact_size` — то есть через ту самую логику переноса
/// (так же устроен `chip`).
fn choice_pill(
    ui: &mut egui::Ui,
    pal: theme::Palette,
    label: &str,
    on: bool,
    speed: f32,
) -> egui::Response {
    const PAD: f32 = 14.0;

    let font = egui::TextStyle::Button.resolve(ui.style());
    // Раскладка текста у egui кэшируется по самой строке, так что повторный
    // вызов с той же подписью считает только хеш.
    let galley = ui
        .painter()
        .layout_no_wrap(label.to_owned(), font, egui::Color32::PLACEHOLDER);

    let size = egui::vec2(PAD * 2.0 + galley.size().x, theme::CONTROL_HEIGHT);
    let (rect, response) = ui.allocate_exact_size(size, egui::Sense::click());
    // Подпись нарисована кистью, и для экранного диктора таблетка без этого
    // безымянна: имя и «выбрана ли» готовый `Button` сообщает сам, а здесь
    // их надо назвать явно. Замыкание зовётся, только когда дерево
    // доступности кто-то читает или по таблетке щёлкнули, так что в обычном
    // кадре аллокации нет.
    response.widget_info(|| {
        egui::WidgetInfo::selected(egui::WidgetType::Button, ui.is_enabled(), on, label)
    });
    if !ui.is_rect_visible(rect) {
        return response;
    }

    // Выбранная сказана не одним цветом: у неё и заливка, и акцентная
    // кромка, и подпись другого тона. Невыбранная в покое почти прозрачна
    // и светлеет под курсором — это и есть отклик.
    let ctx = ui.ctx();
    let touch = ctx.animate_bool_with_time(response.id, response.hovered(), motion::TOUCH * speed);
    let on_t = ctx.animate_bool_with_time(response.id.with("on"), on, motion::MOVE * speed);
    let press = motion::glide(ctx.animate_bool_with_time(
        response.id.with("press"),
        response.is_pointer_button_down_on(),
        motion::TOUCH * 0.75 * speed,
    ));
    let rect = motion::pressed(rect, press);

    let fill = motion::mix(
        motion::mix(egui::Color32::TRANSPARENT, pal.card_inner, touch),
        pal.accent_soft,
        on_t,
    );
    let stroke = motion::mix(
        motion::mix(pal.border_strong, pal.border_hover, touch),
        pal.accent,
        on_t,
    );
    let text = motion::mix(
        motion::mix(pal.text_secondary, pal.text_primary, touch),
        pal.accent_hover,
        on_t,
    );

    let painter = ui.painter();
    painter.rect(
        rect,
        egui::CornerRadius::same(theme::RADIUS_PILL),
        fill,
        egui::Stroke::new(1.0, stroke),
        egui::StrokeKind::Inside,
    );
    painter.galley(
        egui::pos2(rect.left() + PAD, rect.center().y - galley.size().y / 2.0),
        galley,
        text,
    );

    response
}

/// Мелкая оговорка под элементом управления.
///
/// `wrap()` обязателен: без него длинная строка ушла бы за кромку окна
/// и растянула бы содержимое прокрутки — см. комментарий в `banner`.
fn note(ui: &mut egui::Ui, text: &str, color: egui::Color32) {
    ui.add(egui::Label::new(egui::RichText::new(text).small().color(color)).wrap());
}

/// Цвет плашки статуса пункта отчёта.
///
/// «Нет данных» намеренно не красный и не зелёный, а приглушённый: это не
/// беда и не благополучие, а отсутствие сведений. Покрасить его зелёным
/// значило бы сказать «в порядке» про то, чего не смотрели, красным —
/// напугать штатным положением дел.
fn check_color(pal: theme::Palette, status: CheckStatus) -> egui::Color32 {
    match status {
        CheckStatus::Ok => pal.state_success,
        CheckStatus::Warning => pal.state_warning,
        CheckStatus::Failed => pal.state_error,
        CheckStatus::Unknown => pal.text_muted,
    }
}

/// Карточка одного пункта отчёта.
fn check_card(ui: &mut egui::Ui, pal: theme::Palette, check: &crate::model::Check, lang: Lang) {
    theme::card(ui, pal, |ui| {
            // Плашка прижата к правому краю: так статусы всех карточек
            // стоят в одну колонку и читаются сверху вниз, не завися от
            // длины заголовка. Кладём её первой, справа налево: обрезаемый
            // заголовок иначе занял бы всю ширину, и плашка налезла бы
            // на него.
            //
            // Высота ряда задаётся явно, и это не украшение вёрстки:
            // `with_layout` отдал бы потомку весь остаток высоты карточки,
            // а `Align::Center` считает его занятым целиком (подробности —
            // у `SavioApp::power_card`). Внутри прокрутки остаток — почти
            // весь экран, и карточка вырастала до нижней кромки, вытесняя
            // соседние пункты, а заголовок схлопывался в «…» (дефект 42).
            ui.allocate_ui_with_layout(
                egui::vec2(ui.available_width(), theme::CONTROL_HEIGHT),
                egui::Layout::right_to_left(egui::Align::Center),
                |ui| {
                    status_pill(ui, pal, check.status.label(lang), check_color(pal, check.status));
                    ui.with_layout(egui::Layout::left_to_right(egui::Align::Center), |ui| {
                        ui.add(
                            egui::Label::new(
                                egui::RichText::new(&check.name)
                                    .font(theme::display(17.0))
                                    .color(pal.text_primary),
                            )
                            .truncate(),
                        );
                    });
                },
            );

            ui.add_space(6.0);
            note(ui, &check.summary, pal.text_secondary);

            if !check.rows.is_empty() {
                ui.add_space(10.0);
                for row in &check.rows {
                    check_row(ui, pal, row, lang);
                }
            }

            if let Some(advice) = &check.advice {
                ui.add_space(10.0);
                banner(ui, pal, advice, pal.state_warning);
            }
        });
}

/// Строка «подпись — значение» внутри карточки.
fn check_row(ui: &mut egui::Ui, pal: theme::Palette, row: &crate::model::CheckRow, lang: Lang) {
    stat_row(ui, pal, lang, &row.label, row.value.as_deref());
}

/// Строка «подпись — значение» в колонку.
///
/// Отделена от `check_row` ради монитора: у него значения приезжают готовыми
/// строками внутри замера, и заворачивать их в `CheckRow` пришлось бы каждый
/// кадр — то есть заводить по аллокации на строку шестьдесят раз в секунду
/// ровно там, где Правило 1 этого и не велит. Вид у строк при этом обязан
/// остаться общим: две одинаковые на вид таблицы, разъехавшиеся по вёрстке,
/// выглядят небрежностью.
fn stat_row(ui: &mut egui::Ui, pal: theme::Palette, lang: Lang, label: &str, value: Option<&str>) {
    stat_row_with(ui, pal, label, value, i18n::t(lang, Key::UiSystemValueMissing));
}

/// Та же строка, но со своим объяснением прочерка.
///
/// Объяснение — часть смысла прочерка, а не украшение: у снимка системы
/// значение не сообщила система, у погоды — сервер, и одна общая фраза
/// соврала бы в одном из двух мест.
fn stat_row_with(
    ui: &mut egui::Ui,
    pal: theme::Palette,
    label: &str,
    value: Option<&str>,
    missing: &str,
) {
    ui.horizontal_top(|ui| {
        ui.spacing_mut().item_spacing.x = 8.0;

        // Подпись занимает фиксированную долю ширины, чтобы значения
        // выстроились в колонку. Доля, а не число точек: в окне 520 и в
        // развёрнутом на два монитора нужны разные ширины, а колонка нужна
        // в обеих.
        let label_width = (ui.available_width() * 0.42).clamp(40.0, 200.0);
        ui.allocate_ui_with_layout(
            egui::vec2(label_width, 0.0),
            egui::Layout::left_to_right(egui::Align::Min),
            |ui| {
                // `set_min_width` тут обязателен, хотя ширина уже запрошена
                // выше, и это ровно та же грабля, что в `queue_row`:
                // `allocate_ui_with_layout` двигает курсор не на запрошенный
                // размер, а на тот, что реально занял потомок. Без него
                // значения начинаются сразу за подписью, каждое на своём
                // месте, и обещанной колонки не получается — у «Ядро»
                // значение уезжает к левому краю, у «Точка монтирования»
                // почти к середине. Ни сборка, ни тесты этого не видят.
                ui.set_min_width(label_width);
                // Подсказку с полным текстом обрезанная метка вешает сама
                // (`show_tooltip_when_elided` включён по умолчанию). Свой
                // `on_hover_text` здесь добавил бы вторую коробку с тем же
                // текстом — это дефект 22, он уже случался.
                ui.add(
                    egui::Label::new(
                        egui::RichText::new(label)
                            .small()
                            .color(pal.text_muted),
                    )
                    .truncate(),
                );
            },
        );

        match value {
            // `wrap()` обязателен: в горизонтальной раскладке egui берёт
            // режим `Extend` и кладёт значение в одну строку любой длины —
            // длинное имя USB-устройства ушло бы за кромку окна.
            Some(value) => {
                ui.add(
                    egui::Label::new(
                        egui::RichText::new(value)
                            .small()
                            .color(pal.text_secondary),
                    )
                    .wrap(),
                );
            }
            // Вот ради чего значение — `Option`. Прочерк, а не ноль и не
            // пустое место: пустая строка выглядит недорисованной, а ноль
            // читается как измеренная величина. Тон приглушённый — «нет
            // данных» не должно спорить за внимание с настоящими числами.
            None => {
                ui.add(
                    egui::Label::new(
                        egui::RichText::new("—")
                            .small()
                            .color(pal.text_muted),
                    )
                    .wrap(),
                )
                .on_hover_text(missing);
            }
        }
    });
}

fn field_label(ui: &mut egui::Ui, pal: theme::Palette, text: &str) {
    ui.label(egui::RichText::new(text).small().color(pal.text_muted));
    ui.add_space(6.0);
}

/// Плашка состояния: цветная точка плюс подпись тем же цветом.
/// Цветом одним статус не передаём — рядом всегда есть текст.
///
/// Место плашка отмеряет себе сама и рисуется кистью — так же, как [`chip`]
/// и [`choice_pill`], и по той же причине, только тут она весомее. Оболочка
/// из `Frame` с раскладкой внутри выглядит проще, но растягивалась во всю
/// строку: плашку ставят в `right_to_left`, у такой области `min_rect`
/// растёт от **правого** края, а вложенная `left_to_right` кладёт своё
/// содержимое от левого — и между ними оказывается вся ширина карточки.
/// Раздувшаяся плашка забирала место у заголовка, и тот схлопывался в «…»
/// (дефект 42, вторая его половина). Померено: 884 точки против 99 при
/// ширине окна 900. Ни сборка, ни `clippy`, ни тесты этого не видели —
/// теперь видит `a_status_pill_asks_only_for_its_own_width`.
///
/// Отсюда же и отказ от `ui.horizontal` внутри: тот, оказавшись внутри уже
/// горизонтальной раскладки, наследует её направление, и точка с подписью
/// менялись местами. Кисти направление не указ.
fn status_pill(ui: &mut egui::Ui, pal: theme::Palette, label: &str, color: egui::Color32) {
    const PAD: f32 = 11.0;
    const GAP: f32 = 7.0;
    const DOT: f32 = 7.0;
    /// Поля сверху и снизу: плашка обязана быть ниже кнопки, иначе
    /// в ряду с заголовком она читалась бы как ещё одна кнопка.
    const RIM: f32 = 5.0;

    let font = egui::TextStyle::Small.resolve(ui.style());
    // Раскладка текста у egui кэшируется по самой строке, так что повторный
    // вызов с той же подписью считает только хеш.
    let galley = ui
        .painter()
        .layout_no_wrap(label.to_owned(), font, egui::Color32::PLACEHOLDER);

    let size = egui::vec2(
        PAD * 2.0 + DOT + GAP + galley.size().x,
        galley.size().y.max(DOT) + RIM * 2.0,
    );
    let (rect, _) = ui.allocate_exact_size(size, egui::Sense::hover());
    if !ui.is_rect_visible(rect) {
        return;
    }

    let painter = ui.painter();
    painter.rect_stroke(
        rect,
        egui::CornerRadius::same(theme::RADIUS_PILL),
        egui::Stroke::new(1.0, pal.border_subtle),
        egui::StrokeKind::Inside,
    );
    painter.circle_filled(
        egui::pos2(rect.left() + PAD + DOT / 2.0, rect.center().y),
        DOT / 2.0,
        color,
    );
    painter.galley(
        egui::pos2(
            rect.left() + PAD + DOT + GAP,
            rect.center().y - galley.size().y / 2.0,
        ),
        galley,
        color,
    );
}

// ---------------------------------------------------------------------------
// Монитор: карточки, графики, оверлей
// ---------------------------------------------------------------------------

/// Прочерк на месте отсутствующего значения.
///
/// Одной константой, а не литералом по месту: прочерк здесь — не украшение,
/// а способ сказать «нет данных», и он обязан выглядеть одинаково везде.
const DASH: &str = "—";

/// Ползущий график показателя: сами замеры, цвет и фаза сдвига.
///
/// Группой, а не тремя аргументами подряд: с палитрой у `metric_card` их
/// стало восемь, и `clippy` тут прав не только формально — восемь
/// позиционных аргументов, из которых три подряд про одно и то же,
/// на месте вызова читаются загадкой. Дальше эта же тройка целиком уезжает
/// в `trace_plot`, то есть группа не выдумана под счётчик, а была и так.
#[derive(Clone, Copy)]
struct Plot<'a> {
    trace: &'a Trace,
    color: egui::Color32,
    /// Фаза ползущего графика: доля шага, на которую он уже сдвинулся.
    phase: f32,
}

impl<'a> Plot<'a> {
    fn new(trace: &'a Trace, color: egui::Color32, phase: f32) -> Self {
        Self { trace, color, phase }
    }
}

/// Карточка показателя: крупное число, график и подпись.
fn metric_card(
    ui: &mut egui::Ui,
    pal: theme::Palette,
    title: &str,
    metric: &Metric,
    plot: Plot<'_>,
    speed: f32,
    means: Option<&str>,
) {
    // Шрифт числа заведён именем, а не выписан по месту дважды: высоту ряда
    // считаем по нему же, и разъехавшись, эти двое обрезали бы число сверху.
    let number = theme::display(30.0);
    // Высота ряда задаётся явно, и это не украшение вёрстки: `with_layout`
    // отдал бы потомку весь остаток высоты карточки, а `Align::Center`
    // считает его занятым целиком (подробности — у `SavioApp::power_card`).
    // Внутри прокрутки остаток — почти весь экран, и карточка вырастала до
    // нижней кромки, а число с подписью висели в её середине (дефект 42).
    //
    // Число выше кнопки, поэтому `CONTROL_HEIGHT` тут не потолок, а пол:
    // спрашиваем настоящую высоту строки у шрифта, а не берём её на глаз —
    // заниженная обрезала бы число, и увидеть это можно только глазами.
    let row = ui
        .fonts_mut(|fonts| fonts.row_height(&number))
        .max(theme::CONTROL_HEIGHT);

    theme::card(ui, pal, |ui| {
            // Число прижато к правому краю: так проценты всех карточек
            // стоят в одну колонку и читаются сверху вниз. Кладём его
            // первым, справа налево, — обрезаемый заголовок иначе забрал бы
            // всю ширину и число ушло бы под него.
            ui.allocate_ui_with_layout(
                egui::vec2(ui.available_width(), row),
                egui::Layout::right_to_left(egui::Align::Center),
                |ui| {
                    // Замер приходит раз в секунду и прыгает с 12% на 61%.
                    // Лерпится само число, а строка собирается уже из него
                    // (приём 12). `format!` в кадре здесь законен: числа
                    // монитора и так пересобираются каждый замер, а без этого
                    // на экране дребезг, за которым не видно тенденции.
                    //
                    // Готовая `percent_text` при этом остаётся хозяйкой
                    // формата: нет её — нет и показания, и рисуется прочерк.
                    // Подставить на месте «нет значения» ноль было бы враньём
                    // о машине (Правило 6).
                    let shown = metric.percent.map(|percent| {
                        ui.ctx().animate_value_with_time(
                            egui::Id::new("metric").with(title),
                            percent,
                            motion::MOVE * speed,
                        )
                    });
                    let text = match (shown, metric.percent_text.as_deref()) {
                        (Some(shown), Some(_)) => format!("{}%", shown.round() as i32),
                        _ => DASH.to_owned(),
                    };
                    ui.label(egui::RichText::new(text).font(number).color(plot.color));
                    ui.with_layout(egui::Layout::left_to_right(egui::Align::Center), |ui| {
                        ui.add(
                            egui::Label::new(
                                egui::RichText::new(title)
                                    .small()
                                    .color(pal.text_muted),
                            )
                            .truncate(),
                        );
                    });
                },
            );

            ui.add_space(8.0);
            trace_plot(ui, pal, plot);

            if let Some(detail) = &metric.detail {
                ui.add_space(6.0);
                note(ui, detail, pal.text_secondary);
            }

            // Одна строка о том, что число значит. Без неё «57%» у процессора
            // читают как долю одного ядра и удивляются, почему при полной
            // загрузке там не 400: доля уже поделена на число ядер.
            if let Some(means) = means {
                ui.add_space(6.0);
                // Явная раскладка: карточка часто стоит в колонке
                // `ui.columns`, а там абзац, ушедший на вторую строку,
                // выключается по ширине и набирается дырами.
                ui.with_layout(egui::Layout::top_down(egui::Align::Min), |ui| {
                    note(ui, means, pal.text_muted);
                });
            }
        });
}

/// Полоска-график: последние замеры, слева самый старый.
///
/// Шкала жёстко от нуля до ста, а не «по максимуму в окне». Автомасштаб
/// нарисовал бы у простаивающей машины ту же гору, что у загруженной, —
/// график, который врёт ровно в ту сторону, в какую на него смотрят.
fn trace_plot(ui: &mut egui::Ui, pal: theme::Palette, plot: Plot<'_>) {
    const HEIGHT: f32 = 56.0;

    let Plot {
        trace,
        color,
        phase,
    } = plot;

    let (rect, _) = ui.allocate_exact_size(
        egui::vec2(ui.available_width(), HEIGHT),
        egui::Sense::hover(),
    );
    let painter = ui.painter();
    painter.rect_filled(
        rect,
        egui::CornerRadius::same(theme::RADIUS_INNER),
        pal.input_fill,
    );
    // Одна линия сетки, на половине шкалы. Пять линий на сорока четырёх
    // точках высоты слились бы в серый прямоугольник.
    painter.line_segment(
        [
            egui::pos2(rect.left(), rect.center().y),
            egui::pos2(rect.right(), rect.center().y),
        ],
        egui::Stroke::new(1.0, pal.border_subtle),
    );

    // Одной точке рисовать нечего: линия начинается с отрезка.
    let filled = trace.iter().len();
    if filled < 2 {
        return;
    }

    // Шаг считаем по потолку буфера, а не по числу набранных точек: иначе
    // первые секунды график растягивался бы на всю ширину и «сжимался» по
    // мере наполнения — движение, которого на самом деле не было.
    let step = rect.width() / (TRACE_LIMIT - 1) as f32;
    let newest = filled - 1;

    // Кадры для сдвига просит сам график, и по своему шагу сетки.
    //
    // Соблазн поставить тут круглые «тридцать кадров в секунду» велик, и
    // цена ему замерена: 7,1 с процессорного времени за 10 с работы вместо
    // 0,6 с — в двенадцать раз больше на ровном месте (отладочная сборка,
    // окно 1100×780). А ехать ломаной за такт всего один шаг, то есть около
    // четырёх точек на широкой карточке: тридцати кадров хватило бы на
    // сдвиг в **одну восьмую точки** за кадр — движение, которого не видит
    // никто. Поэтому интервал считается от шага, а не выбирается на глаз:
    // просим кадр на каждые полточки пути. В узком окне шаг вдвое меньше —
    // и кадров там нужно вдвое меньше, само собой.
    if phase < 1.0 && step > 0.0 {
        let seconds = (0.5 / step * motion::SAMPLE).clamp(1.0 / 60.0, 0.5);
        ui.ctx()
            .request_repaint_after(std::time::Duration::from_secs_f32(seconds));
    }

    // Одна ломаная, а не сто девятнадцать отрезков: `Shape::line` кладёт
    // в список отрисовки один объект, отдельные `line_segment` — по одному
    // на каждую пару точек.
    let points: Vec<egui::Pos2> = trace
        .iter()
        .enumerate()
        .map(|(i, value)| motion::trace_point(rect, value, i, newest, step, phase))
        .collect();
    painter.add(egui::Shape::line(
        points,
        egui::Stroke::new(1.5, color),
    ));
}

/// Карточка «Ввод-вывод»: сеть, диски и видеокарта.
///
/// Втроём в одной карточке, потому что у всех троих одна беда: показать
/// про них можно строку, а не график. Своя карточка на строку превратила бы
/// вкладку в лестницу из рамок.
fn io_card(
    ui: &mut egui::Ui,
    pal: theme::Palette,
    sample: &PerfSample,
    gpu: Option<&GpuInfo>,
    lang: Lang,
) {
    theme::card(ui, pal, |ui| {
            ui.add(
                egui::Label::new(
                    egui::RichText::new(i18n::t(lang, Key::UiIo))
                        .small()
                        .color(pal.text_muted),
                )
                .truncate(),
            );

            ui.add_space(8.0);
            stat_row(ui, pal, lang, i18n::t(lang, Key::UiNetwork), sample.net.as_deref());
            stat_row(ui, pal, lang, i18n::t(lang, Key::UiDisks), sample.disk.as_deref());
            stat_row(
                ui,
                pal,
                lang,
                i18n::t(lang, Key::HwSwap),
                sample.swap.detail.as_deref(),
            );
            // Видеокарта здесь только именем: загрузку у неё не спросить,
            // а имя уже снято с адаптера, которым eframe рисует окно.
            stat_row(
                ui,
                pal,
                lang,
                i18n::t(lang, Key::HwGpu),
                gpu.map(|gpu| gpu.name.as_str()),
            );

            // Пояснение — под всеми строками, а не после первой: оно про
            // карточку целиком. Поставленное за «Сетью», оно разрывало
            // таблицу и читалось подписью к одной строке. Найдено глазами.
            ui.add_space(6.0);
            note(ui, i18n::t(lang, Key::UiIoNote), pal.text_muted);
        });
}

/// Карточка со списком процессов.
fn process_card(
    ui: &mut egui::Ui,
    pal: theme::Palette,
    procs: &[crate::model::ProcRow],
    lang: Lang,
) {
    theme::card(ui, pal, |ui| {
            ui.add(
                egui::Label::new(
                    egui::RichText::new(i18n::t(lang, Key::UiProcesses))
                        .small()
                        .color(pal.text_muted),
                )
                .truncate(),
            );

            ui.add_space(4.0);
            if procs.is_empty() {
                note(ui, i18n::t(lang, Key::UiNoProcesses), pal.text_muted);
                return;
            }

            note(ui, i18n::t(lang, Key::UiProcessesNote), pal.text_muted);
            ui.add_space(8.0);

            // Своей прокрутки здесь нет: вкладка целиком лежит в общей, а
            // вложенная полоса рядом с внешней схлопывает содержимое (это
            // дефект 27, он уже случался с журналом). Список короткий —
            // `PROC_LIMIT` строк, — и в общей прокрутке помещается весь.
            for row in procs {
                process_row(ui, pal, row);
            }
        });
}

/// Одна строка списка процессов.
fn process_row(ui: &mut egui::Ui, pal: theme::Palette, row: &crate::model::ProcRow) {
    ui.horizontal(|ui| {
        ui.spacing_mut().item_spacing.x = 8.0;
        // Раскладка справа налево: числа кладутся первыми и занимают
        // ровно себя, а имени достаётся остаток строки. Слева направо
        // длинное имя процесса вытолкнуло бы за кромку окна как раз то,
        // ради чего в список и смотрят.
        ui.with_layout(egui::Layout::right_to_left(egui::Align::Center), |ui| {
            ui.add(
                egui::Label::new(
                    egui::RichText::new(&row.mem_text)
                        .small()
                        .color(pal.text_secondary),
                )
                .truncate(),
            );
            ui.add(
                egui::Label::new(
                    egui::RichText::new(&row.cpu_text)
                        .small()
                        .color(pal.text_primary),
                )
                .truncate(),
            );
            // Имени достаётся весь остаток строки, и вложенная раскладка
            // здесь обязательна: в `right_to_left` метка занимает ровно
            // себя и прижимается к правому краю — без неё вся строка
            // сползает вправо, а слева остаётся пустое поле во всю ширину
            // окна. Проверено глазами: ни сборка, ни тесты этого не видят.
            //
            // Подсказку с полным именем обрезанная метка вешает сама —
            // свой `on_hover_text` добавил бы вторую (дефект 22).
            ui.with_layout(egui::Layout::left_to_right(egui::Align::Center), |ui| {
                ui.add(
                    egui::Label::new(
                        egui::RichText::new(&row.name)
                            .small()
                            .color(pal.text_secondary),
                    )
                    .truncate(),
                );
            });
        });
    });

    // Полоска под строкой: список читается глазами по ней, а не по числам.
    let (bar, _) = ui.allocate_exact_size(
        egui::vec2(ui.available_width(), 3.0),
        egui::Sense::hover(),
    );
    let radius = egui::CornerRadius::same(2);
    let painter = ui.painter();
    painter.rect_filled(bar, radius, pal.input_fill);
    let filled = egui::Rect::from_min_size(
        bar.min,
        egui::vec2(bar.width() * (row.cpu / 100.0).clamp(0.0, 1.0), bar.height()),
    );
    painter.rect_filled(filled, radius, pal.accent);
    ui.add_space(6.0);
}

/// Содержимое оверлея.
///
/// Свободная функция, а не метод: замыкание дочернего окна обязано быть
/// `Send + Sync + 'static` (так требует `show_viewport_deferred`), то есть
/// до полей `SavioApp` ему не дотянуться. Всё, что оно видит, приходит
/// через `Arc`.
///
/// Прозрачным окно намеренно не сделано, хотя просится. Подробности —
/// в CLAUDE.md, коротко: у wgpu прозрачность включается на весь `Painter`
/// сразу и берётся из настроек **главного** окна, а поверхность обычного
/// окна на Windows отдаёт единственный режим смешения — непрозрачный.
/// Запрос прозрачности собрался бы, прошёл бы clippy и тесты — и уехал бы
/// в `log::warn`, которого никто не увидит.
fn overlay_ui(
    ui: &mut egui::Ui,
    pal: theme::Palette,
    class: egui::ViewportClass,
    lang: Lang,
    sample: &Mutex<Option<PerfSample>>,
    closing: &AtomicBool,
) {
    // Окно закрыли системой — Alt+F4 или «Закрыть» из панели задач. Гасить
    // галочку отсюда некому, поэтому передаём просьбу главному окну.
    if ui.ctx().input(|i| i.viewport().close_requested()) {
        closing.store(true, Ordering::Relaxed);
    }

    egui::CentralPanel::default()
        .frame(
            egui::Frame::new()
                .fill(pal.modal_fill)
                .stroke(egui::Stroke::new(1.0, pal.border_strong))
                .inner_margin(egui::Margin::symmetric(12, 10)),
        )
        .show(ui, |ui| {
            // Отступы темы рассчитаны на окно, а не на полоску в треть его
            // ширины: штатная строка виджета — 32 точки, и четыре строки
            // с заголовком не поместились бы в оверлей никакой разумной
            // высоты. Правится здесь, а не в теме: там эти числа держат
            // раскладку главного окна.
            ui.spacing_mut().interact_size.y = 0.0;
            ui.spacing_mut().item_spacing.y = 4.0;
            ui.spacing_mut().button_padding = egui::vec2(8.0, 2.0);

            // Выделение текста здесь выключено не ради вида, а ради
            // перетаскивания. Подписи у egui по умолчанию выделяемые, то есть
            // сами ловят нажатие и протаскивание, — и окно, схваченное за
            // строку «ЦП 24%», не двигалось никуда. Проверено вживую: за пустое
            // место оверлей тянулся, за любую надпись — нет, а надписи занимают
            // почти всю его площадь. Ни сборка, ни `clippy`, ни тесты этого
            // не видят: и там и там нажатие «сработало», просто на другом
            // виджете. Выделять в оверлее всё равно нечего — числа меняются
            // раз в секунду.
            ui.style_mut().interaction.selectable_labels = false;

            // Перетаскивание вешаем ПЕРВЫМ, до кнопки: у egui щелчок достаётся
            // тому, кого положили позже. Наоборот — и кнопка «Закрыть»
            // перестала бы нажиматься, а окно ездило бы по экрану от каждого
            // тычка в неё.
            //
            // Своего заголовка у окна нет (`with_decorations(false)`), так что
            // без этого оверлей нельзя было бы сдвинуть с того места, куда его
            // поставила система. Во встроенном окне (`EmbeddedWindow`, сборка
            // без поддержки нескольких окон) команда бессмысленна: там его
            // таскает сам egui за свою рамку.
            if class != egui::ViewportClass::EmbeddedWindow {
                let drag = ui.interact(
                    ui.max_rect(),
                    ui.id().with("savio-overlay-drag"),
                    egui::Sense::click_and_drag(),
                );
                // Спрашиваем «кнопка нажата на нас», а не `drag_started`, и это
                // не придирка: как только команда ушла, окно уводит система —
                // мышь захватывает её собственный цикл перетаскивания, и до
                // egui события больше не доходят. Порога сдвига, по которому
                // `drag_started` только и срабатывает, оно набрать не успевает,
                // так что оверлей просто не двигался. Проверено вживую: с
                // `drag_started` сдвиг ровно ноль. Так же устроен и штатный
                // пример egui с окном без рамки.
                if drag.is_pointer_button_down_on() {
                    ui.ctx().send_viewport_cmd(egui::ViewportCommand::StartDrag);
                }
            }

            ui.horizontal(|ui| {
                ui.add(
                    egui::Label::new(
                        egui::RichText::new("Savio")
                            .small()
                            .color(pal.text_muted),
                    )
                    .truncate(),
                );
                ui.with_layout(egui::Layout::right_to_left(egui::Align::Center), |ui| {
                    // Словом, а не крестиком: своих шрифтов Savio не
                    // подключает, а в тех, что кладёт eframe, знаки вроде
                    // `✕` рисуются пустым прямоугольником — ровно так уже
                    // вышло со стрелкой `→` (Правило 4).
                    let close = ui.add(egui::Button::new(
                        egui::RichText::new(i18n::t(lang, Key::UiClose)).small(),
                    ));
                    if close.clicked() {
                        closing.store(true, Ordering::Relaxed);
                    }
                });
            });

            ui.add_space(6.0);

            let Ok(slot) = sample.lock() else {
                return;
            };
            let Some(sample) = slot.as_ref() else {
                note(ui, i18n::t(lang, Key::UiMonitorMeasuring), pal.text_muted);
                return;
            };

            let row = |ui: &mut egui::Ui, key, value| {
                overlay_row(ui, pal, i18n::t(lang, key), value)
            };
            row(ui, Key::UiOverlayCpu, sample.cpu.percent_text.as_deref());
            row(ui, Key::UiOverlayRam, sample.mem.percent_text.as_deref());
            row(ui, Key::UiNetwork, sample.net.as_deref());
            row(ui, Key::UiOverlayDisk, sample.disk.as_deref());
        });
}

/// Одна строка оверлея.
///
/// Своя, а не `stat_row`: там подпись занимает 42% ширины ради колонки из
/// длинных названий, а здесь подписи в три буквы и места всего 230 точек —
/// колонка съела бы половину окна.
fn overlay_row(ui: &mut egui::Ui, pal: theme::Palette, label: &str, value: Option<&str>) {
    ui.horizontal(|ui| {
        ui.spacing_mut().item_spacing.x = 6.0;
        ui.add(
            egui::Label::new(
                egui::RichText::new(label)
                    .small()
                    .color(pal.text_muted),
            )
            .truncate(),
        );
        ui.add(
            egui::Label::new(
                egui::RichText::new(value.unwrap_or(DASH))
                    .font(theme::bold(12.5))
                    .color(pal.text_primary),
            )
            .truncate(),
        );
    });
}

/// Сообщение об ошибке или предупреждение: цветная полоса слева, текст справа.
fn banner(ui: &mut egui::Ui, pal: theme::Palette, text: &str, color: egui::Color32) {
    egui::Frame::new()
        .fill(pal.card_inner)
        .stroke(egui::Stroke::new(1.0, pal.border_subtle))
        .corner_radius(egui::CornerRadius::same(theme::RADIUS_INNER))
        .inner_margin(egui::Margin::symmetric(14, 12))
        .show(ui, |ui| {
            ui.set_width(ui.available_width());
            ui.horizontal_top(|ui| {
                ui.spacing_mut().item_spacing.x = 10.0;
                let height = ui.text_style_height(&egui::TextStyle::Body);
                let (stripe, _) =
                    ui.allocate_exact_size(egui::vec2(3.0, height), egui::Sense::hover());
                ui.painter()
                    .rect_filled(stripe, egui::CornerRadius::same(2), color);
                // `wrap()` обязателен: в горизонтальной раскладке egui берёт
                // для текста режим `Extend`, то есть кладёт абзац в одну
                // строку любой длины и молча срезает её кромкой окна. Ни
                // сборка, ни тесты этого не видят, а объяснения в баннерах —
                // длинные: без переноса читалась бы только их первая треть.
                ui.add(egui::Label::new(egui::RichText::new(text).color(color)).wrap());
            });
        });
}

/// Показывает папку в файловом менеджере системы. Адреса — через
/// [`open_url`]: `explorer` в них не разбирается.
fn open_dir(dir: &Path) {
    #[cfg(windows)]
    let (program, args) = ("explorer", vec![dir.to_string_lossy().into_owned()]);
    #[cfg(target_os = "macos")]
    let (program, args) = ("open", vec![dir.to_string_lossy().into_owned()]);
    #[cfg(all(unix, not(target_os = "macos")))]
    let (program, args) = ("xdg-open", vec![dir.to_string_lossy().into_owned()]);

    let _ = std::process::Command::new(program).args(args).spawn();
}

/// Открывает адрес — страницу или `mailto:` — той программой, что назначена
/// в системе для его схемы, как если бы по нему щёлкнули где угодно.
///
/// На Windows это `url.dll,FileProtocolHandler`, то есть ShellExecute, и
/// ни один из двух напрашивающихся путей не годится — оба ошибаются молча:
///
/// * `explorer`, которым открывается папка, в адресах не разбирается.
///   Проверено вживую (2026-09-11, Windows 11, почтовая программа не
///   назначена): `mailto:` с темой письма он открывает как… папку
///   «Документы» — ни письма, ни ошибки. ShellExecute по тому же адресу
///   честно спрашивает, чем его открыть.
/// * Штатный `ctx.open_url` eframe идёт крейтом `webbrowser`, а тот на
///   Windows спрашивает систему, чем открывается **http**, и отдаёт этой
///   программе любой адрес (webbrowser 1.2.4, windows.rs:41–83): письмо
///   уехало бы в браузер, а не в почтовую программу.
///
/// Пробелов в адресе быть не должно: `FileProtocolHandler` берёт остаток
/// командной строки целиком, и кавычки, которыми `Command` обернул бы такой
/// аргумент, доехали бы до него как часть адреса. Наши адреса — константы
/// без пробелов, а у темы письма пробел закодирован (`feedback_mailto`).
fn open_url(url: &str) {
    #[cfg(windows)]
    let mut command = {
        let mut command = std::process::Command::new("rundll32");
        command.arg("url.dll,FileProtocolHandler");
        command
    };
    #[cfg(target_os = "macos")]
    let mut command = std::process::Command::new("open");
    #[cfg(all(unix, not(target_os = "macos")))]
    let mut command = std::process::Command::new("xdg-open");

    let _ = command.arg(url).spawn();
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::model::{MetaReport, NO_DOWNLOAD, Tag, TagRole};

    fn request(url: &str, format: Format, quality: Quality) -> Request {
        Request {
            url: url.to_owned(),
            format,
            quality,
            options: DownloadOptions::default(),
            section: Section::default(),
            cookies: CookieSource::default(),
            cookie_file: None,
            sub_lang: SubLang::default(),
        }
    }

    /// Очередь из `count` одинаковых ожидающих ссылок.
    fn queue_with(count: usize) -> Queue {
        let mut queue = Queue::new(Lang::Ru);
        for i in 0..count {
            let url = format!("https://site/{i}");
            assert!(
                queue
                    .push(
                        request(&url, Format::Mp4, Quality::Best),
                        PathBuf::from("/dl"),
                        None
                    )
                    .is_some(),
                "{url} не влезла в очередь"
            );
        }
        queue
    }

    fn ids(queue: &Queue) -> Vec<DownloadId> {
        queue.items.iter().map(|item| item.id).collect()
    }

    fn info(title: &str) -> MediaInfo {
        MediaInfo {
            title: Some(title.to_owned()),
            ..MediaInfo::default()
        }
    }

    /// Предпросмотр, уже спросивший про эту ссылку.
    ///
    /// Ручку движка тест завести не может — её отдаёт только
    /// `engine::start_probe`, — но для развязки поколений она и не нужна:
    /// всё решает приёмник, а ручка лишь убивает процесс.
    fn asking(url: &str) -> (Preview, std::sync::mpsc::Sender<Event>) {
        let mut preview = Preview::default();
        assert!(preview.retarget(url, CookieSource::None, None, 0.0), "{url}");

        let (tx, rx) = channel();
        preview.due = None;
        preview.rx = Some(rx);
        (preview, tx)
    }

    /// Ответ по прежней ссылке не должен попасть в окно.
    ///
    /// Это и есть та тихая беда, ради которой запрос живёт на своём канале:
    /// медленный сайт отвечает про первую ссылку позже, чем быстрый про
    /// вторую, и в карточке оказывается чужое название. Ни компилятор, ни
    /// сборка, ни глазной прогон такого не ловят — воспроизводится оно только
    /// на разной скорости ответов.
    #[test]
    fn an_answer_about_the_previous_link_never_reaches_the_screen() {
        let (mut preview, slow) = asking("https://site.ru/a");
        // Ответ по первой ссылке уже в пути, а в поле за это время оказалась
        // вторая.
        slow.send(Event::Info(info("Ролик по прежней ссылке")))
            .expect("канал ещё жив");
        assert!(preview.retarget("https://site.ru/b", CookieSource::None, None, 0.0));

        assert!(
            preview.take_events().is_empty(),
            "ответ по прежней ссылке обязан пропасть вместе с приёмником"
        );
        assert!(preview.info.is_none(), "и ничего после себя не оставить");
    }

    /// Обратная половина: ответ по той ссылке, что в поле, доезжает.
    /// Поодиночке любой из двух тестов прошёл бы и на предпросмотре,
    /// который не работает вовсе.
    #[test]
    fn an_answer_about_the_link_in_the_field_reaches_the_screen() {
        let (mut preview, tx) = asking("https://site.ru/a");
        tx.send(Event::Info(info("Тот самый ролик")))
            .expect("канал ещё жив");

        let events = preview.take_events();
        assert_eq!(events.len(), 1, "ответ обязан доехать: {events:?}");
    }

    /// Молчание — законный исход: про отсутствие yt-dlp и незнакомый сайт
    /// предпросмотр не говорит ничего, и единственный его признак —
    /// закрытый канал без `Info`. Спутать одно с другим нельзя: в первом
    /// случае под ссылкой надо объясниться, во втором — показать ролик.
    #[test]
    fn silence_and_an_answer_are_told_apart() {
        let (mut preview, tx) = asking("https://site.ru/a");
        drop(tx);
        assert!(preview.take_events().is_empty());
        assert_eq!(preview.state, PreviewState::Failed);

        let (mut preview, tx) = asking("https://site.ru/a");
        tx.send(Event::Info(info("Ролик"))).expect("канал ещё жив");
        drop(tx);
        assert_eq!(preview.take_events().len(), 1);
        assert_ne!(
            preview.state,
            PreviewState::Failed,
            "ответ пришёл — жаловаться не на что"
        );
    }

    /// Окно ожидания отсчитывается от последней правки, а не от первой:
    /// иначе ссылка, набранная руками, ушла бы в сеть недописанной.
    #[test]
    fn the_site_is_asked_only_after_a_pause() {
        let mut preview = Preview::default();

        assert!(preview.retarget("https://site.ru/a", CookieSource::None, None, 10.0));
        assert_eq!(preview.due, Some(10.0 + PREVIEW_DEBOUNCE));

        assert!(preview.retarget("https://site.ru/ab", CookieSource::None, None, 10.4));
        assert_eq!(preview.due, Some(10.4 + PREVIEW_DEBOUNCE));

        // Та же ссылка и тот же вход — спрашивать заново нечего: срок
        // не сдвигается, а начатое не бросается.
        assert!(!preview.retarget("https://site.ru/ab", CookieSource::None, None, 10.9));
        assert_eq!(preview.due, Some(10.4 + PREVIEW_DEBOUNCE));
    }

    /// Обрывок текста из буфера обмена в yt-dlp не отправляем: кнопку такая
    /// строка не блокирует, но процесс и поход в сеть стоят дороже догадки.
    #[test]
    fn junk_from_the_clipboard_is_not_worth_a_request() {
        let mut preview = Preview::default();
        for text in ["", " ", "просто текст", "site.com/watch?v=a", "https://"] {
            preview.retarget(text, CookieSource::None, None, 0.0);
            assert_eq!(preview.due, None, "спросили про {text:?}");
            assert_eq!(preview.state, PreviewState::Idle, "на {text:?}");
        }
    }

    /// Готовый ответ переиспользуется загрузкой — но только тот же самый.
    /// Тот же адрес, спрошенный с чужим входом в аккаунт, у YouTube отдаёт
    /// другое вплоть до пустого списка дорожек.
    #[test]
    fn the_answer_is_reused_only_for_the_very_same_request() {
        let mut preview = Preview::default();
        preview.retarget("https://site.ru/a", CookieSource::None, None, 0.0);
        preview.info = Some(info("Ролик"));

        let mut same = request("https://site.ru/a", Format::Mp4, Quality::Best);
        assert!(preview.answer_for(&same).is_some());

        let other = request("https://site.ru/b", Format::Mp4, Quality::Best);
        assert!(preview.answer_for(&other).is_none(), "чужая ссылка");

        same.cookies = CookieSource::Firefox;
        assert!(preview.answer_for(&same).is_none(), "чужой вход в аккаунт");
    }

    /// Тот же вопрос про файл: два разных файла cookies — это два разных
    /// входа в аккаунт, и ответ по одному нельзя показывать под другим.
    /// Сам источник (`File`) при этом не меняется, так что без сверки путей
    /// подмена прошла бы незамеченной.
    #[test]
    fn a_different_cookie_file_is_a_different_question() {
        let mine = PathBuf::from("/home/me/cookies.txt");
        let other = PathBuf::from("/home/me/другой.txt");

        let mut preview = Preview::default();
        preview.retarget("https://site.ru/a", CookieSource::File, Some(&mine), 0.0);
        preview.info = Some(info("Ролик"));

        let mut request = request("https://site.ru/a", Format::Mp4, Quality::Best);
        request.cookies = CookieSource::File;
        request.cookie_file = Some(mine.clone());
        assert!(preview.answer_for(&request).is_some(), "свой же ответ");

        request.cookie_file = Some(other.clone());
        assert!(preview.answer_for(&request).is_none(), "ответ по чужому файлу");

        // И смена файла обязана перезапустить запрос — иначе на экране
        // осталось бы название, полученное прежним входом.
        assert!(
            preview.retarget("https://site.ru/a", CookieSource::File, Some(&other), 1.0),
            "смену файла не заметили"
        );
        assert!(
            !preview.retarget("https://site.ru/a", CookieSource::File, Some(&other), 2.0),
            "тот же файл — спрашивать заново нечего"
        );
    }

    /// Строка очереди называется роликом сразу, а не через час, когда до неё
    /// дойдёт очередь: название уже спрошено предпросмотром.
    #[test]
    fn a_queued_row_is_named_by_the_preview_right_away() {
        let mut queue = Queue::new(Lang::Ru);
        queue
            .push(
                request("https://site/watch?v=abc", Format::Mp4, Quality::Best),
                PathBuf::from("/dl"),
                Some(info("Ролик про кота")),
            )
            .expect("место в пустой очереди есть");

        assert_eq!(queue.items[0].title, "Ролик про кота");
    }

    /// Ноль занят под `NO_DOWNLOAD` — событие установки или разбора
    /// метаданных. Выдай очередь этот номер ссылке, и чужой `Failed`
    /// пометил бы её ошибкой.
    #[test]
    fn numbering_never_hands_out_the_reserved_zero() {
        let mut queue = Queue::new(Lang::Ru);
        assert_ne!(queue.next_id, NO_DOWNLOAD);

        // Четыре миллиарда ссылок за запуск недостижимы, но проверить обход
        // нуля дёшево, а `+= 1` на этом месте ещё и паникует в отладке.
        queue.next_id = u32::MAX;
        let last = queue
            .push(
                request("https://site/a", Format::Mp4, Quality::Best),
                PathBuf::from("/dl"),
                None,
            )
            .unwrap();
        let wrapped = queue
            .push(
                request("https://site/b", Format::Mp4, Quality::Best),
                PathBuf::from("/dl"),
                None,
            )
            .unwrap();

        assert_eq!(last, u32::MAX);
        assert_eq!(wrapped, 1, "после переполнения нумерация обходит ноль");
    }

    /// Потолок обязателен по Правилу 1, как и у журнала с историей. Но
    /// выбрасывать можно только отработавшее: ожидающая ссылка — это
    /// невыполненная просьба, и потерять её молча нельзя.
    #[test]
    fn queue_stays_bounded_by_dropping_what_already_finished() {
        let mut queue = queue_with(QUEUE_LIMIT);
        assert_eq!(queue.items.len(), QUEUE_LIMIT);
        assert!(queue.full, "мест нет и освободить нечем");

        let extra = request("https://site/extra", Format::Mp4, Quality::Best);
        assert_eq!(queue.push(extra.clone(), PathBuf::from("/dl"), None), None);
        assert_eq!(queue.items.len(), QUEUE_LIMIT, "ожидающую не выбросили");

        // Первая скачалась — место освободилось, и уходит именно она.
        let oldest = queue.items[0].id;
        queue.set_status(oldest, QueueStatus::Done);
        assert!(!queue.full);

        assert!(queue.push(extra, PathBuf::from("/dl"), None).is_some());
        assert_eq!(queue.items.len(), QUEUE_LIMIT);
        assert!(
            queue.items.iter().all(|item| item.id != oldest),
            "место обязана освободить отработавшая строка"
        );
    }

    /// Очередь идёт сверху вниз и не выдаёт дважды одно и то же: выдай она
    /// идущую ссылку второй раз — и тот же ролик качался бы в два потока.
    #[test]
    fn the_queue_goes_top_down_and_skips_what_already_ran() {
        let mut queue = queue_with(3);
        let id = ids(&queue);
        let next = |q: &Queue| q.next_waiting().map(|(id, ..)| id);

        assert_eq!(next(&queue), Some(id[0]));
        queue.set_status(id[0], QueueStatus::Done);
        assert_eq!(next(&queue), Some(id[1]));
        queue.set_status(id[1], QueueStatus::Running);
        assert_eq!(next(&queue), Some(id[2]));

        queue.set_status(id[2], QueueStatus::Failed("нет такой страницы".into()));
        assert_eq!(next(&queue), None);
        assert!(!queue.has_waiting());
    }

    /// Тот самый случай, ради которого номера и заведены: у снятой загрузки
    /// поток движка живёт ещё секунду и досылает свой исход. Достанься он
    /// следующему элементу — исправная загрузка показалась бы сорванной.
    #[test]
    fn a_late_event_of_a_dropped_download_belongs_to_no_one() {
        let mut queue = queue_with(2);
        let id = ids(&queue);

        queue.set_status(id[0], QueueStatus::Running);
        assert!(queue.is_running(id[0]));
        assert!(!queue.is_running(id[1]), "ожидающая ещё не идёт");

        queue.set_status(id[0], QueueStatus::Cancelled);
        queue.set_status(id[1], QueueStatus::Running);

        assert!(!queue.is_running(id[0]), "запоздалое событие снятой загрузки");
        assert!(queue.is_running(id[1]));
        // Установка и метаданные ходят без номера — их события в очередь
        // не попадают вовсе.
        assert!(!queue.is_running(NO_DOWNLOAD));
        assert_eq!(queue.running_id(), Some(id[1]));
    }

    /// Строка списка обязана говорить, что именно уедет на диск: настройки
    /// снимаются в момент постановки, и переключатели на экране к ней уже
    /// отношения не имеют.
    #[test]
    fn a_row_says_what_it_will_download_and_in_what_state() {
        let mut queue = Queue::new(Lang::Ru);
        let id = queue
            .push(
                request("https://site/a", Format::Mp3, Quality::P1080),
                PathBuf::from("/dl"),
                None,
            )
            .unwrap();

        let detail = queue.items[0].detail.clone();
        assert!(detail.starts_with("Ожидает"), "{detail}");
        // Единица обязательна: «MP3 · 192» читается как загадка.
        assert!(detail.contains("MP3 · 192 кбит/с"), "{detail}");

        queue.set_status(id, QueueStatus::Running);
        let detail = &queue.items[0].detail;
        assert!(detail.starts_with("Качается"), "{detail}");
        assert!(detail.contains("MP3 · 192 кбит/с"), "{detail}");
    }

    /// `explain_failure` отдаёт объяснение с переносами строк, а метка
    /// с `truncate()` показывает ровно первую из них: в списке выходило
    /// «Ошибка (код 1):…» — подпись, не говорящая ничего.
    #[test]
    fn the_reason_for_failure_is_flattened_into_one_line() {
        let mut queue = queue_with(1);
        let id = queue.items[0].id;
        assert!(queue.items[0].error_line.is_empty(), "отказа ещё не было");

        queue.set_status(
            id,
            QueueStatus::Failed("Ошибка (код 1):\nERROR: Unsupported URL:\n  https://site".into()),
        );

        let line = &queue.items[0].error_line;
        assert!(!line.contains('\n'), "перенос остался: {line}");
        assert_eq!(
            line,
            "Ошибка (код 1): ERROR: Unsupported URL: https://site"
        );

        // Ушёл отказ — ушла и строка: причина позапрошлой беды рядом
        // с готовым файлом читается как новая.
        queue.set_status(id, QueueStatus::Done);
        assert!(queue.items[0].error_line.is_empty());
    }

    /// До `probe` названия нет, и в строке стоит сама ссылка: пустая строка
    /// выглядела бы поломкой, а десяток ссылок с одного сайта различается
    /// тремя символами в конце.
    #[test]
    fn the_link_gives_way_to_the_title_when_it_arrives() {
        let mut queue = Queue::new(Lang::Ru);
        let id = queue
            .push(
                request("https://site/watch?v=abc", Format::Mp4, Quality::Best),
                PathBuf::from("/dl"),
                None,
            )
            .unwrap();

        assert_eq!(queue.items[0].title, "https://site/watch?v=abc");
        queue.set_title(id, "Ролик про кота");
        assert_eq!(queue.items[0].title, "Ролик про кота");
    }

    #[test]
    fn summary_counts_every_state_a_row_can_be_in() {
        let mut queue = queue_with(5);
        let id = ids(&queue);
        queue.set_status(id[0], QueueStatus::Running);
        queue.set_status(id[1], QueueStatus::Done);
        queue.set_status(id[2], QueueStatus::Failed("не вышло".into()));
        queue.set_status(id[3], QueueStatus::Cancelled);

        assert_eq!(
            queue.summary,
            "Идёт: 1 · В очереди: 1 · Готово: 1 · Ошибок: 1 · Снято: 1"
        );

        // Пустых пар в сводке быть не должно: «Ошибок: 0» рядом с готовым
        // выглядит как доклад о беде, которой не было.
        let empty = Queue::new(Lang::Ru);
        assert!(empty.summary.is_empty());
    }

    /// Идущую загрузку не выбрасывает ни «убрать», ни «Очистить»: процесс
    /// продолжил бы качать, а показать его исход стало бы негде.
    #[test]
    fn neither_removing_nor_clearing_drops_the_running_download() {
        let mut queue = queue_with(3);
        let id = ids(&queue);
        queue.set_status(id[1], QueueStatus::Running);

        queue.remove(id[1]);
        assert!(queue.items.iter().any(|item| item.id == id[1]));

        queue.remove(id[0]);
        assert!(queue.items.iter().all(|item| item.id != id[0]));

        queue.clear();
        assert_eq!(queue.items.len(), 1);
        assert_eq!(queue.items[0].id, id[1]);
        assert_eq!(queue.summary, "Идёт: 1");
    }

    /// Помеченная крестиком строка ещё рисуется, но очередью уже не является.
    ///
    /// Это и есть цена отложенного удаления (приём 10): строка остаётся в
    /// списке лишние четверть секунды, и всё, что считает очередь, обязано
    /// её при этом не видеть. Промах тут тихий и злой — «Скачать», нажатое
    /// в это окно, запустило бы ровно то, что убрали.
    #[test]
    fn a_row_on_its_way_out_is_no_longer_queued() {
        let mut queue = queue_with(2);
        let id = ids(&queue);

        assert_eq!(queue.summary, "В очереди: 2");
        queue.mark_removing(id[0], 100.0);

        assert!(
            queue.items.iter().any(|item| item.id == id[0]),
            "строку убрали сразу — складываться будет нечему"
        );
        assert_eq!(queue.summary, "В очереди: 1", "сводка считает убранную");
        assert_eq!(
            queue.next_waiting().map(|(id, ..)| id),
            Some(id[1]),
            "следующей на запуск оказалась убранная строка"
        );

        // Обе убрали — ждать больше нечего, хотя строки ещё на экране.
        queue.mark_removing(id[1], 100.0);
        assert!(!queue.has_waiting());
    }

    /// Идущую загрузку крестик не помечает даже по ошибке: у неё для этого
    /// есть «Отмена», а строка — единственный след того, чем всё кончилось.
    #[test]
    fn the_running_download_cannot_be_marked_for_removal() {
        let mut queue = queue_with(2);
        let id = ids(&queue);
        queue.set_status(id[0], QueueStatus::Running);

        queue.mark_removing(id[0], 100.0);
        assert!(queue.items[0].removing_since.is_none());
        assert_eq!(queue.summary, "Идёт: 1 · В очереди: 1");
    }

    /// Слова состояний человек читает в списке глазами: одинаковые или
    /// пустые превратили бы очередь в набор одинаковых строк.
    #[test]
    fn queue_states_explain_themselves_distinctly() {
        let all = [
            QueueStatus::Waiting,
            QueueStatus::Running,
            QueueStatus::Done,
            QueueStatus::Failed(String::new()),
            QueueStatus::Cancelled,
        ];

        // Каждый язык проверяется отдельно: подписи, различимые по-русски,
        // в переводе легко слипаются («Готово» и «Отменено» — Done и
        // Cancelled, а вот «Ждёт» и «В очереди» уже спорят).
        for lang in Lang::ALL {
            let mut seen: Vec<&str> = Vec::new();
            for status in &all {
                let label = status.label(lang);
                assert!(
                    !label.trim().is_empty(),
                    "{lang:?} {status:?}: пустая подпись"
                );
                assert!(
                    !seen.contains(&label),
                    "{lang:?} {label}: подпись повторяется"
                );
                seen.push(label);
            }
        }

        // Освобождать место можно только за счёт отработавших.
        assert!(!QueueStatus::Waiting.finished());
        assert!(!QueueStatus::Running.finished());
        assert!(QueueStatus::Done.finished());
        assert!(QueueStatus::Failed(String::new()).finished());
        assert!(QueueStatus::Cancelled.finished());
    }

    /// Потолок обязателен: по одной ссылке-плейлисту `Event::Done` приходит
    /// столько раз, сколько в нём роликов, и без обрезки список рос бы вместе
    /// с памятью — ровно то, от чего защищает `LOG_LIMIT` у журнала.
    #[test]
    fn history_stays_bounded() {
        let mut history = History::default();
        for i in 0..HISTORY_LIMIT + 10 {
            let path = format!("/dl/{i}.mp4");
            history.remember(Path::new(&path));
        }

        assert_eq!(history.entries.len(), HISTORY_LIMIT);
        // Выбрасывается самое старое, а не самое свежее.
        let newest = format!("{}.mp4", HISTORY_LIMIT + 9);
        assert_eq!(history.entries[0].name, newest);
        assert!(
            history.entries.iter().all(|entry| entry.name != "0.mp4"),
            "самая старая запись обязана уйти первой"
        );
    }

    /// Сверху — последнее скачанное: за ним возвращаются чаще всего.
    #[test]
    fn newest_download_comes_first() {
        let mut history = History::default();
        history.remember(Path::new("/dl/первый.mp4"));
        history.remember(Path::new("/dl/второй.mp3"));

        assert_eq!(history.entries[0].name, "второй.mp3");
        assert_eq!(history.entries[1].name, "первый.mp4");
    }

    /// Повторная загрузка того же файла (выбрали не тот формат, оборвалась
    /// связь) не должна плодить одинаковые строки подряд.
    #[test]
    fn repeat_moves_the_entry_up_instead_of_duplicating_it() {
        let mut history = History::default();
        history.remember(Path::new("/dl/a.mp4"));
        history.remember(Path::new("/dl/b.mp4"));
        history.remember(Path::new("/dl/a.mp4"));

        assert_eq!(history.entries.len(), 2);
        assert_eq!(history.entries[0].name, "a.mp4");
        assert_eq!(history.entries[1].name, "b.mp4");
    }

    #[test]
    fn entry_splits_the_path_into_name_and_folder() {
        let mut history = History::default();
        history.remember(Path::new("/dl/Ролик [id].mp4"));

        let entry = &history.entries[0];
        assert_eq!(entry.name, "Ролик [id].mp4");
        assert_eq!(entry.dir.as_deref(), Some(Path::new("/dl")));
        assert!(!entry.dir_display.is_empty());
    }

    /// От yt-dlp приходят абсолютные пути, но UI не должен зависеть от их
    /// формы: у имени без папки `parent()` возвращает не `None`, а `Some("")`,
    /// и открывать такую «папку» нельзя — кнопки в этой строке не будет.
    #[test]
    fn entry_without_a_folder_has_nothing_to_open() {
        let mut history = History::default();
        history.remember(Path::new("file.mp4"));

        let entry = &history.entries[0];
        assert_eq!(entry.name, "file.mp4");
        assert_eq!(entry.dir, None);
        assert!(entry.dir_display.is_empty());
    }

    /// Настоящее сообщение wgpu 29 — то самое, от которого раньше падал
    /// процесс. Проверено вживую на окне с клиентом 504×8193.
    const TOO_LARGE: &str = "Validation Error\n\nCaused by:\n  In Surface::configure\n \
         `Surface` width and height must be within the maximum supported texture size. \
         Requested was (504, 8193), maximum extent for either dimension is 8192.";

    #[test]
    fn oversized_window_is_explained_in_russian() {
        let line = gpu_error_line(TOO_LARGE, Lang::Ru);
        assert!(line.contains("больше, чем может отрисовать"), "{line}");
        // Английский текст wgpu пользователю не показываем: он про текстуру,
        // а человек видит окно.
        assert!(!line.contains("Surface"), "{line}");
    }

    /// Приметы принадлежат wgpu и могут смениться с новой версией. Промах не
    /// поймает ни компилятор, ни сборка, поэтому запасной исход обязателен:
    /// потерять подсказку терпимо, потерять сообщение целиком — нет.
    #[test]
    fn unknown_gpu_error_keeps_its_own_text() {
        let line = gpu_error_line("Validation Error: something else entirely", Lang::Ru);
        assert!(line.starts_with("Ошибка отрисовки: "), "{line}");
        assert!(line.contains("something else entirely"), "{line}");
    }

    /// Пока окно остаётся большим, ошибка приходит без конца. Журнал у Savio
    /// один и ограничен, так что повтор туда пускать нельзя.
    #[test]
    fn repeated_gpu_errors_are_collapsed_and_capped() {
        let errors = GpuErrors::default();
        for _ in 0..100 {
            errors.push(TOO_LARGE.to_owned());
        }
        assert_eq!(errors.take().len(), 1);

        for i in 0..100 {
            errors.push(format!("ошибка {i}"));
        }
        assert_eq!(errors.take().len(), GPU_ERROR_LIMIT);
    }

    /// Про один и тот же предел wgpu присылает два РАЗНЫХ сообщения: про
    /// поверхность и про `set_viewport`. Человеку они говорят одно и то же,
    /// поэтому повторы в журнале гасятся по готовой строке, а не по тексту
    /// wgpu. Без этого запись двоилась — видно только глазами, ни сборка,
    /// ни clippy этого не ловят.
    #[test]
    fn different_wgpu_messages_about_one_limit_give_the_same_line() {
        let viewport = "Validation Error\n\nCaused by:\n  In a CommandEncoder, label = 'encoder'\n \
             In a set_viewport command\n      Viewport size { w: 9984, h: 381 } greater than \
             device's requested `max_texture_dimension_2d` limit 8192, or less than zero";
        assert_eq!(gpu_error_line(TOO_LARGE, Lang::Ru), gpu_error_line(viewport, Lang::Ru));
    }

    #[test]
    fn a_folded_group_admits_what_it_hides() {
        // Язык назван явно, а не взят по умолчанию: проверка сравнивает
        // с русским текстом, и молча сменившееся умолчание превратило бы
        // её в проверку перевода вместо проверки сводки.
        let ru = Lang::Ru;
        let text = |summary: GroupSummary| summary.text;
        // Заданный фрагмент обязан быть виден в заголовке: свёрнутая группа —
        // единственное место, где о нём вообще можно узнать, а скачанный
        // кусок вместо ролика человек заметит уже в плеере.
        assert_eq!(text(advanced_summary(false, true, false, None, ru)), "фрагмент");
        assert_eq!(
            text(advanced_summary(true, false, false, None, ru)),
            "фрагмент задан неверно"
        );
        assert_eq!(text(advanced_summary(false, false, true, None, ru)), "вход на сайт");
        assert_eq!(
            text(advanced_summary(false, false, false, Some(&SubLang::Code("ru".to_owned())), ru)),
            "субтитры: ru"
        );
        assert_eq!(
            text(advanced_summary(false, true, true, Some(&SubLang::Code("de".to_owned())), ru)),
            "фрагмент · вход на сайт · субтитры: de"
        );
    }

    /// Сводка не пустеет ни на одном языке.
    ///
    /// Сравнивать перевод с записанной строкой незачем — это проверяло бы
    /// саму таблицу, — а вот «собралось хоть что-то» ловит забытую подстановку:
    /// пустой заголовок группы выглядит исправным.
    #[test]
    fn the_folded_group_speaks_in_every_language() {
        for lang in Lang::ALL {
            for state in [(false, false, false), (false, true, true), (true, false, false)] {
                let summary = advanced_summary(state.0, state.1, state.2, None, lang);
                assert!(!summary.text.trim().is_empty(), "{lang:?} {state:?}: пусто");
            }
        }
    }

    #[test]
    fn an_untouched_group_lists_what_lies_inside() {
        // Ничего не включено — перечисляем содержимое, а не «ничего не
        // задано»: заголовок обязан объяснять, зачем группу вообще открывать.
        assert_eq!(
            advanced_summary(false, false, false, None, Lang::Ru),
            GroupSummary {
                text: "фрагмент, вход на сайт, язык субтитров".to_owned(),
                mark: None,
            }
        );
    }

    /// Включённый вход отличается от заглушки меткой, а не только словами
    /// (задача 51).
    ///
    /// Заглушка нетронутой группы перечисляет, что лежит внутри, и «вход на
    /// сайт» стоит в ней теми же словами, что у включённого входа. Пока вид
    /// был один, заголовок со входом, запомненным с прошлого запуска, взглядом
    /// не отличался от заголовка нетронутой группы, а при запуске он —
    /// единственный указатель на вход. Поэтому проверяется не текст, а метка,
    /// и на каждом языке: без метки у заглушки, с меткой у всего включённого.
    /// Что метку заголовок вправду рисует — отдельная проверка,
    /// `the_folded_header_lights_up_only_when_something_is_on`.
    ///
    /// Проверено красным: с `mark: None` у включённого проверка падает на
    /// первом же языке.
    #[test]
    fn a_login_left_on_does_not_look_like_the_placeholder() {
        let de = SubLang::Code("de".to_owned());
        for lang in Lang::ALL {
            assert_eq!(
                advanced_summary(false, false, false, None, lang).mark,
                None,
                "{lang:?}: заглушка выглядит включённой"
            );
            for (what, summary) in [
                ("вход", advanced_summary(false, false, true, None, lang)),
                ("фрагмент", advanced_summary(false, true, false, None, lang)),
                ("субтитры", advanced_summary(false, false, false, Some(&de), lang)),
            ] {
                assert_eq!(
                    summary.mark,
                    Some(Tone::Warn),
                    "{lang:?}: {what} выглядит как заглушка"
                );
            }
            // Неверный фрагмент держит «Скачать» выключенной — это уже не
            // оговорка, и его тон перекрывает соседей.
            assert_eq!(
                advanced_summary(true, false, true, Some(&de), lang).mark,
                Some(Tone::Bad),
                "{lang:?}: неверный фрагмент не выглядит ошибкой"
            );
        }
    }

    /// Язык субтитров, о которых не просили, в заголовок не попадает.
    ///
    /// Без `--embed-subs` язык в yt-dlp не уходит, а поле выбора внутри
    /// группы спрятано, — и «субтитры: de» называло бы то, чего, раскрыв
    /// группу, не найти. С горящей точкой это ещё и ложная тревога, а к
    /// ложной тревоге привыкают и перестают замечать настоящую.
    #[test]
    fn the_folded_group_keeps_quiet_about_subtitles_nobody_asked_for() {
        let unasked = advanced_summary(false, false, false, None, Lang::Ru);
        assert_eq!(unasked.mark, None);
        assert_eq!(
            unasked,
            advanced_summary(false, false, false, Some(&SubLang::Original), Lang::Ru),
            "«язык ролика» — умолчание, и называть его в заголовке незачем"
        );
    }

    /// Кадр без ошибок не должен ничего забирать: `ui()` зовут 60 раз
    /// в секунду, и пустой разбор обязан оставаться пустым.
    #[test]
    fn quiet_frame_takes_nothing() {
        let errors = GpuErrors::default();
        assert!(errors.take().is_empty());
    }

    // -----------------------------------------------------------------------
    // Питание
    // -----------------------------------------------------------------------

    fn plans() -> Vec<crate::model::PowerPlan> {
        vec![
            crate::model::PowerPlan {
                id: BALANCED_PLAN,
                name: "Сбалансированная".to_owned(),
            },
            crate::model::PowerPlan {
                id: crate::model::PlanId::from_parts(
                    0x8c5e_7fda,
                    0xe8bf,
                    0x4a96,
                    [0x9a, 0x85, 0xa6, 0xe2, 0x3a, 0x8c, 0x63, 0x5c],
                ),
                name: "Высокая производительность".to_owned(),
            },
        ]
    }

    fn high_performance() -> crate::model::PlanId {
        plans()[1].id
    }

    /// При сбалансированной схеме режим питания работает — предупреждать
    /// не о чем, и лишняя жёлтая строка только пугала бы.
    #[test]
    fn the_power_hint_stays_quiet_when_the_mode_really_applies() {
        let state = PowerState {
            plans: plans(),
            active: Some(BALANCED_PLAN),
            modes: PowerModes::Known {
                effective: Some(PowerMode::Max),
                ignored: None,
            },
            trouble: None,
        };
        assert_eq!(power_hint(&state, Lang::Ru), "");
    }

    /// Оговорка обязана появиться ДО нажатия: это единственное место, где
    /// Savio успевает предупредить о молчаливом отказе Windows.
    #[test]
    fn the_power_hint_warns_before_the_press_when_the_scheme_is_not_balanced() {
        let state = PowerState {
            plans: plans(),
            active: Some(high_performance()),
            modes: PowerModes::Known {
                effective: Some(PowerMode::Balanced),
                ignored: None,
            },
            trouble: None,
        };

        let hint = power_hint(&state, Lang::Ru);
        // Названа и та схема, что мешает, и та, что нужна: без первой
        // непонятно, что менять, без второй — на что.
        assert!(hint.contains("Высокая производительность"), "{hint}");
        assert!(hint.contains("Сбалансированная"), "{hint}");
    }

    /// Название схемы в подсказке взято в кавычки своего языка.
    ///
    /// Кавычки ставит код, а не таблица строк: имя схемы приходит от Windows.
    /// Зашитые в код «ёлочки» проверка кавычек таблицы не видит, и они
    /// уехали в английскую подсказку — «right now «High performance» is
    /// active». Прожило это с 0.28.0, нашлось глазами на снимке экрана.
    ///
    /// Проверено красным: с прежним `format!("«{name}»")` проверка падает
    /// на английском.
    #[test]
    fn the_power_hint_quotes_the_scheme_in_its_own_language() {
        let state = PowerState {
            plans: plans(),
            active: Some(high_performance()),
            modes: PowerModes::Known {
                effective: Some(PowerMode::Balanced),
                ignored: None,
            },
            trouble: None,
        };

        let en = power_hint(&state, Lang::En);
        assert!(
            !en.contains('«') && !en.contains('»'),
            "в английской подсказке русские кавычки: {en}"
        );
        assert!(en.contains('\u{201c}'), "английские кавычки пропали: {en}");

        let ru = power_hint(&state, Lang::Ru);
        assert!(ru.contains('«'), "русские кавычки пропали: {ru}");
    }

    /// Windows запомнила одно, а работает по-другому. Пока это не сказано
    /// словами, окно показывает выбранным режим, которого нет.
    #[test]
    fn the_power_hint_names_both_modes_when_the_stored_one_is_ignored() {
        let state = PowerState {
            plans: plans(),
            active: Some(high_performance()),
            modes: PowerModes::Known {
                effective: Some(PowerMode::Balanced),
                ignored: Some(PowerMode::Max),
            },
            trouble: None,
        };

        let hint = power_hint(&state, Lang::Ru);
        assert!(hint.contains(PowerMode::Max.label(Lang::Ru)), "{hint}");
        assert!(hint.contains(PowerMode::Balanced.label(Lang::Ru)), "{hint}");
    }

    /// Схему система назвать может и не суметь. Выдуманного имени в оговорке
    /// быть не должно — человек пойдёт искать его в параметрах Windows.
    #[test]
    fn the_power_hint_does_not_invent_a_scheme_name() {
        let state = PowerState {
            plans: Vec::new(),
            active: Some(high_performance()),
            modes: PowerModes::Known {
                effective: Some(PowerMode::Balanced),
                ignored: None,
            },
            trouble: None,
        };

        let hint = power_hint(&state, Lang::Ru);
        assert!(!hint.is_empty(), "предупредить всё равно надо");
        assert!(!hint.contains("Высокая производительность"), "{hint}");
    }

    /// Без режимов питания оговорка про них бессмысленна.
    #[test]
    fn the_power_hint_says_nothing_where_there_are_no_modes() {
        let state = PowerState {
            plans: plans(),
            active: Some(high_performance()),
            modes: PowerModes::Unsupported,
            trouble: Some("режимов нет".to_owned()),
        };
        assert_eq!(power_hint(&state, Lang::Ru), "");
    }

    /// Высота тела журнала после трёх кадров в окне 520×420, если заказать
    /// ему `wanted`.
    ///
    /// Три кадра, а не один: и панель, и прокрутка узнают свой размер по
    /// прошлому кадру, так что на первом высота ещё не установилась —
    /// ровно тот круг, который и разрывает пол высоты.
    ///
    /// `nested` выбирает раскладку: `false` — нынешняя, журнал в своей
    /// панели; `true` — та, в которой дефект 27 и нашли: журнал в самом
    /// низу длинной страницы внутри общей прокрутки, остаток до него
    /// нулевой.
    fn log_body_height(nested: bool, lines: usize, wanted: f32) -> f32 {
        let ctx = egui::Context::default();
        let mut height = 0.0;

        for _ in 0..3 {
            let input = egui::RawInput {
                screen_rect: Some(egui::Rect::from_min_size(
                    egui::Pos2::ZERO,
                    egui::vec2(520.0, 420.0),
                )),
                ..Default::default()
            };
            // Настоящий кадр egui без окна и без видеокарты: `Context`
            // самодостаточен, а штатных шрифтов хватает на разметку.
            let mut output = ctx.run_ui(input, |ui| {
                let mut body = |ui: &mut egui::Ui| {
                    // Меряем занятое место, а не `ScrollAreaOutput::inner_rect`:
                    // тот снят до сжатия по содержимому (scroll_area.rs:1039
                    // против 1179–1193) и при нынешней паре ограничителей
                    // равен заказанному всегда — то есть проверял бы сам себя.
                    height = ui
                        .scope(|ui| {
                            log_scroll(wanted).show(ui, |ui| {
                                for i in 0..lines {
                                    ui.monospace(format!("строка {i}"));
                                }
                            });
                        })
                        .response
                        .rect
                        .height();
                };

                if nested {
                    egui::CentralPanel::default().show(ui, |ui| {
                        egui::ScrollArea::vertical()
                            .auto_shrink([false, false])
                            .show(ui, |ui| {
                                ui.add_space(900.0);
                                body(ui);
                            });
                    });
                } else {
                    egui::Panel::bottom("тело журнала").show(ui, body);
                }
            });
            // Кадр вернул готовые к отрисовке текстуры, а рисовать их
            // здесь некому: epaint роняет тест паникой, если такой ответ
            // просто выбросить. Отказываемся от них явно.
            output.textures_delta.clear();
        }

        height
    }

    /// Тело журнала остаётся ровно заказанной высоты в обеих раскладках —
    /// и во весь рост, и урезанным в окне минимальной высоты.
    ///
    /// Дефект 27: без `min_scrolled_height` прокрутка внутри чужой
    /// прокрутки или растущей панели схлопывается до умолчания egui
    /// в 64 точки, и видно это только глазами и только в тесном окне —
    /// ни сборка, ни `clippy` высоты не знают. Проверено красным: без
    /// `.min_scrolled_height(height)` у [`log_scroll`] все четыре проверки
    /// падают (64 вместо 150 и 64 вместо 76 — в панели и внутри прокрутки).
    ///
    /// Урезанная высота здесь не для полноты. С тех пор как тело считается
    /// от окна (дефект 60), пол и потолок у прокрутки — любое число, а не
    /// одно, и держать неподвижную точку обязаны при каждом.
    #[test]
    fn the_log_body_keeps_its_height() {
        for wanted in [LOG_HEIGHT, log_height(420.0)] {
            assert_eq!(
                log_body_height(false, 200, wanted),
                wanted,
                "журнал в своей панели"
            );
            assert_eq!(
                log_body_height(true, 200, wanted),
                wanted,
                "журнал внутри чужой прокрутки"
            );
        }
    }

    /// Кадр окна с открытым длинным журналом: сколько прокрутки раздела
    /// видно и сколько заняла панель журнала.
    ///
    /// Окно собирается из тех же частей, что в `SavioApp::ui`: рельс своей
    /// ширины, [`log_panel`], раздел в [`content_frame`] со строкой
    /// заголовка и зазором под ней. Копией здесь остаётся только порядок
    /// частей, а каждое число берётся оттуда же, откуда его берёт окно.
    ///
    /// Видно из прокрутки её пересечение с отсечением раздела, а не вся
    /// `inner_rect`: у прокрутки свой пол в 64 точки, и в тесном окне она
    /// считает себя выше, чем её видно (scroll_area.rs:774–778).
    fn section_view_with_log(
        ctx: &egui::Context,
        lang: Lang,
        window: egui::Vec2,
        body: f32,
    ) -> (f32, f32) {
        let pal = theme::Palette::dark();
        let lines: Vec<String> = (0..200).map(|i| format!("строка журнала {i}")).collect();
        let mut copied_at = None;
        let (mut view, mut log) = (0.0, 0.0);

        // Три кадра — по той же причине, что у [`log_body_height`].
        for _ in 0..3 {
            let input = egui::RawInput {
                screen_rect: Some(egui::Rect::from_min_size(egui::Pos2::ZERO, window)),
                ..Default::default()
            };
            let mut output = ctx.run_ui(input, |ui| {
                egui::Panel::left("рельс")
                    .resizable(false)
                    .exact_size(RailLayout::for_window(window).width())
                    .show(ui, |_| {});
                log_panel(ui, pal, lang, 1.0, &lines, &mut copied_at, body);
                let section = egui::CentralPanel::default()
                    .frame(content_frame())
                    .show(ui, |ui| {
                        section_title_row(
                            ui,
                            pal,
                            lang,
                            1.0,
                            i18n::t(lang, Key::TabDownload),
                            Key::NavDownloadNote,
                        );
                        ui.add_space(SECTION_TITLE_GAP);
                        let scroll = egui::ScrollArea::vertical()
                            .auto_shrink([false, false])
                            .show(ui, |ui| ui.add_space(2000.0));
                        view = scroll.inner_rect.intersect(ui.clip_rect()).height();
                    });
                log = window.y - section.response.rect.height();
            });
            output.textures_delta.clear();
        }

        (view, log)
    }

    /// Открытый журнал оставляет разделу его прокрутку в любом разрешённом
    /// окне, а где места хватает — не урезается сам.
    ///
    /// Дефект 60: высота тела журнала была числом, и в окне 520×420 его
    /// панель занимала 249 точек из 420 — прокрутке раздела оставалось 86,
    /// и поле ссылки резалось поперёк. Сборка этого не видит, а глазами это
    /// видно только в низком окне, в которое Savio почти никогда не
    /// открывается: при запуске окно развёрнуто.
    ///
    /// Высоты — от разрешённого минимума до той, где тело уже во весь рост,
    /// и дальше до окна по умолчанию и большого экрана. Языки все три, хотя
    /// строки здесь заданной высоты: подпись, которая в переводе вдруг
    /// перенесётся, подняла бы обвязку, и заметно это было бы только здесь.
    ///
    /// Проверено красным: с прежним `LOG_HEIGHT` вместо [`log_height`]
    /// в окне 420 прокрутке раздела остаётся 86 точек, и проверка падает.
    #[test]
    fn the_open_log_leaves_the_section_its_view() {
        for lang in Lang::ALL {
            // Свой контекст на язык: общий помнит размеры от прошлого
            // и искажает первый кадр следующего.
            let ctx = egui::Context::default();
            theme::install_fonts(&ctx);
            theme::apply(&ctx, theme::Palette::dark());

            for height in (420..=520).step_by(10).chain([560, 1080]) {
                let window = egui::vec2(520.0, height as f32);
                let (view, log) = section_view_with_log(&ctx, lang, window, log_height(window.y));
                assert!(
                    view >= SECTION_VIEW_MIN - 0.5,
                    "{lang:?}, окно 520×{height}: журнал занял {log} точек, прокрутке \
                     раздела осталось {view} — проверьте LOG_FRAMING"
                );
            }
        }

        // Урезается журнал только в низком окне: в окне по умолчанию
        // (720×560) он во весь рост.
        assert_eq!(log_height(560.0), LOG_HEIGHT);
    }

    /// Пол высоты не мешает короткому журналу быть коротким.
    ///
    /// Обратная сторона предыдущей проверки: `min_scrolled_height` — это
    /// пол, и без `auto_shrink` по вертикали окошко стало бы ровно 150
    /// даже под двумя строками, с пустым полем под текстом.
    #[test]
    fn a_short_log_does_not_grow_to_the_full_height() {
        let short = log_body_height(false, 2, LOG_HEIGHT);
        assert!(short > 0.0, "две строки всё же занимают место");
        assert!(short < LOG_HEIGHT, "под двумя строками пусто: {short}");
    }

    /// Высота карточки, нарисованной в самом верху длинной прокрутки.
    ///
    /// Прокрутка здесь не для красоты: дефект 42 в том и состоит, что
    /// центрирующий ряд забирает весь остаток высоты, — а в окне остаток
    /// как раз и есть «до нижней кромки». В голом `Ui` остатка нет, и
    /// проверка прошла бы на сломанном коде.
    ///
    /// Три кадра — по той же причине, что у [`log_body_height`]: и
    /// прокрутка, и карточка узнают размер по прошлому кадру.
    fn card_height(add: impl Fn(&mut egui::Ui)) -> f32 {
        let pal = theme::Palette::dark();
        let ctx = egui::Context::default();
        // Без темы карточка мерилась бы чужими шрифтами, а `theme::display`
        // и вовсе уронил бы кадр: семейства с таким именем в умолчаниях нет.
        theme::install_fonts(&ctx);
        theme::apply(&ctx, pal);
        let mut height = 0.0;

        for _ in 0..3 {
            let input = egui::RawInput {
                screen_rect: Some(egui::Rect::from_min_size(
                    egui::Pos2::ZERO,
                    egui::vec2(520.0, 420.0),
                )),
                ..Default::default()
            };
            let mut output = ctx.run_ui(input, |ui| {
                egui::CentralPanel::default().show(ui, |ui| {
                    egui::ScrollArea::vertical()
                        .auto_shrink([false, false])
                        .show(ui, |ui| {
                            height = ui.scope(&add).response.rect.height();
                        });
                });
            });
            output.textures_delta.clear();
        }

        height
    }

    /// Дорожки формата и качества не вылезают за кромку ни на одном языке.
    ///
    /// Самое узкое место всей задачи про три языка. Сегмент просит `min_size`,
    /// а это только нижняя граница: подпись шире отведённой доли раздвигает
    /// кнопку, и дорожка из шести ступеней уезжает за кромку окна, утаскивая
    /// за собой карточку. По-русски ступени подогнаны под окно 520 впритык
    /// (поля сегмента ради этого урезаны с 16 до 10 — см. `segment_button`),
    /// так что любой перевод длиннее русского ломает раскладку молча: ни
    /// сборка, ни `clippy` ширин не знают, а глазной прогон идёт на одном
    /// языке из трёх.
    ///
    /// Меряется при этом разложенная подпись, а не сама дорожка: дорожка
    /// лежит во `Frame` и сжимается до доступной ширины всегда, то есть
    /// равна ей и на сломанной раскладке — проверяла бы сама себя. Вылезает
    /// же за кромку то, что внутри: подпись, не влезшая в свою долю,
    /// раздвигает кнопку, а кнопка — дорожку.
    ///
    /// Проверено красным: с полями сегмента 16 вместо 10 не влезают армянские
    /// ступени MP3, и проверка падает.
    #[test]
    fn the_segment_tracks_fit_the_smallest_window() {
        for lang in Lang::ALL {
            for format in [Format::Mp4, Format::Mp3] {
                let quality: Vec<&str> = Quality::ALL
                    .iter()
                    .map(|step| step.label(format, lang))
                    .collect();
                let formats = [Format::Mp4.label(lang), Format::Mp3.label(lang)];

                for (name, labels) in [("качество", &quality[..]), ("формат", &formats[..])] {
                    let (widest, slot) = widest_segment(labels);
                    assert!(
                        widest <= slot,
                        "{lang:?}/{format:?}: подпись дорожки «{name}» не влезает \
                         в свою долю: {widest} при {slot}"
                    );
                }
            }
        }
    }

    /// Раскладывает подписи дорожки в карточке окна 520 и отдаёт пару
    /// «самая широкая подпись с полями — сколько отведено одному сегменту».
    ///
    /// Поля и промежуток берутся из тех же мест, что и в `segment_button`
    /// с `segment_track`: числа, списанные сюда руками, разъехались бы
    /// с раскладкой при первой же правке темы.
    fn widest_segment(labels: &[&str]) -> (f32, f32) {
        let pal = theme::Palette::dark();
        let ctx = egui::Context::default();
        theme::install_fonts(&ctx);
        theme::apply(&ctx, pal);
        let (mut widest, mut slot) = (0.0_f32, 0.0_f32);

        for _ in 0..3 {
            let input = egui::RawInput {
                screen_rect: Some(egui::Rect::from_min_size(
                    egui::Pos2::ZERO,
                    egui::vec2(520.0, 420.0),
                )),
                ..Default::default()
            };
            let mut output = ctx.run_ui(input, |ui| {
                egui::CentralPanel::default().show(ui, |ui| {
                    theme::card(ui, pal, |ui| {
                        // Доля одного сегмента: ширина дорожки за вычетом
                        // промежутков, поделённая на число сегментов.
                        let n = labels.len() as f32;
                        let inner =
                            ui.available_width() - theme::track_frame(pal).total_margin().sum().x;
                        slot = (inner - theme::SEGMENT_GAP * (n - 1.0)) / n;

                        let font = egui::TextStyle::Button.resolve(ui.style());
                        widest = labels
                            .iter()
                            .map(|label| {
                                let text = ui.painter().layout_no_wrap(
                                    (*label).to_owned(),
                                    font.clone(),
                                    pal.text_primary,
                                );
                                text.size().x + theme::SEGMENT_PADDING * 2.0
                            })
                            .fold(0.0_f32, f32::max);
                    });
                });
            });
            output.textures_delta.clear();
        }

        (widest, slot)
    }

    /// Подписи полей укладываются в свою колонку на всех трёх языках.
    ///
    /// Колонка узкая и расширить её нечем: она отнимает ширину у дорожки
    /// качества, а там шесть ступеней. Не влезшая подпись не ломается
    /// заметно — она молча обрезается в «Բիթրեյթ, կբիթ…», и увидеть это
    /// можно только глазами и только на том языке, который сейчас выбран.
    ///
    /// Проверено красным: с «Բիթրեյթ, կբիթ/վ» (первый перевод) проверка
    /// падает на армянском битрейте.
    #[test]
    fn the_field_labels_fit_their_column() {
        let pal = theme::Palette::dark();
        let ctx = egui::Context::default();
        theme::install_fonts(&ctx);
        theme::apply(&ctx, pal);

        let mut output = ctx.run_ui(egui::RawInput::default(), |ui| {
            // `.small()`, как у самой подписи (`labelled_row`, `field_label`):
            // с обычным начертанием проверка мерила бы не тот текст и падала
            // бы уже на русском, который на экране влезает.
            let font = egui::TextStyle::Small.resolve(ui.style());
            for lang in Lang::ALL {
                for key in LABEL_KEYS {
                    let label = i18n::t(lang, key);
                    let width = ui
                        .painter()
                        .layout_no_wrap(label.to_owned(), font.clone(), pal.text_muted)
                        .size()
                        .x;
                    assert!(
                        width <= LABEL_COLUMN,
                        "{lang:?}/{key:?}: подпись «{label}» не влезает в колонку: \
                         {width} при {LABEL_COLUMN}"
                    );
                }
            }
        });
        output.textures_delta.clear();
    }

    /// Плашка состояния просит ровно свою ширину — и справа налево тоже.
    ///
    /// Вторая половина дефекта 42, и от первой она не зависит: у области,
    /// разложенной справа налево, `min_rect` растёт от правого края, а
    /// прежняя оболочка плашки клала своё содержимое от левого — между
    /// ними оказывалась вся ширина карточки. Раздувшаяся плашка не
    /// оставляла места заголовку, и тот схлопывался в «…».
    ///
    /// Проверено красным: с прежней оболочкой из `Frame` проверка падает —
    /// 884 точки против 99 при ширине окна 900.
    #[test]
    fn a_status_pill_asks_only_for_its_own_width() {
        let pal = theme::Palette::dark();
        let ctx = egui::Context::default();
        theme::install_fonts(&ctx);
        theme::apply(&ctx, pal);
        let (mut backwards, mut plain) = (0.0, 0.0);

        for _ in 0..3 {
            let input = egui::RawInput {
                screen_rect: Some(egui::Rect::from_min_size(
                    egui::Pos2::ZERO,
                    egui::vec2(900.0, 420.0),
                )),
                ..Default::default()
            };
            let mut output = ctx.run_ui(input, |ui| {
                egui::CentralPanel::default().show(ui, |ui| {
                    // Ровно то окружение, в котором плашка и живёт: ряд
                    // заголовка карточки, разложенный справа налево.
                    ui.allocate_ui_with_layout(
                        egui::vec2(ui.available_width(), theme::CONTROL_HEIGHT),
                        egui::Layout::right_to_left(egui::Align::Center),
                        |ui| {
                            backwards = ui
                                .scope(|ui| status_pill(ui, pal, "В порядке", pal.accent))
                                .response
                                .rect
                                .width();
                        },
                    );
                    ui.horizontal(|ui| {
                        plain = ui
                            .scope(|ui| status_pill(ui, pal, "В порядке", pal.accent))
                            .response
                            .rect
                            .width();
                    });
                });
            });
            output.textures_delta.clear();
        }

        assert!(plain > 40.0, "плашка схлопнулась: {plain}");
        assert!(plain < 200.0, "плашка непомерно широка: {plain}");
        assert_eq!(
            backwards, plain,
            "справа налево плашка шире самой себя: {backwards} против {plain}"
        );
    }

    /// Каждая фигура кадра, включая вложенные в `Shape::Vec`.
    fn each_shape(shapes: &[egui::epaint::ClippedShape], mut visit: impl FnMut(&egui::Shape)) {
        fn walk(shape: &egui::Shape, visit: &mut impl FnMut(&egui::Shape)) {
            if let egui::Shape::Vec(list) = shape {
                for shape in list {
                    walk(shape, visit);
                }
            } else {
                visit(shape);
            }
        }
        for clipped in shapes {
            walk(&clipped.shape, &mut visit);
        }
    }

    /// Цвет, которым в кадре написан этот текст.
    ///
    /// Проверка палитры говорит, что нужный цвет в ней есть и проходит
    /// порог, а не то, что виджет его взял, — это видно только по кадру.
    fn ink(shapes: &[egui::epaint::ClippedShape], text: &str) -> Option<egui::Color32> {
        let mut found = None;
        each_shape(shapes, |shape| {
            if let egui::Shape::Text(t) = shape
                && t.galley.job.text.trim() == text
            {
                found = t
                    .override_text_color
                    .or_else(|| t.galley.job.sections.first().map(|s| s.format.color));
            }
        });
        found
    }

    /// Закрашенные круги кадра: середина, радиус и заливка.
    fn dots(shapes: &[egui::epaint::ClippedShape]) -> Vec<(egui::Pos2, f32, egui::Color32)> {
        let mut found = Vec::new();
        each_shape(shapes, |shape| {
            if let egui::Shape::Circle(circle) = shape {
                found.push((circle.center, circle.radius, circle.fill));
            }
        });
        found
    }

    /// Выключенная главная кнопка подписана своим цветом, а не цветом
    /// включённой.
    ///
    /// В тёмной теме эти два цвета совпадают, поэтому промах там невидим —
    /// и ровно поэтому его легко внести. В светлой теме включённая кнопка
    /// тёмная и подписана белым, а выключенная пастельная: белым по ней
    /// выходит 1.9:1, то есть «Скачать» читается как пустая таблетка.
    /// Проверено глазами, и ровно так эта беда и нашлась.
    ///
    /// Палитра сама по себе тут не спасает: `every_colour_passes_its_threshold`
    /// проверяет, что нужный цвет в палитре есть и проходит порог, а не то,
    /// что кнопка его взяла.
    ///
    /// Проверено красным: с `pal.text_on_accent` в обеих ветках проверка
    /// падает на светлой теме.
    #[test]
    fn a_disabled_main_button_keeps_its_own_ink() {
        for (theme, pal) in [("тёмная", theme::Palette::dark()), ("светлая", theme::Palette::light())]
        {
            let ctx = egui::Context::default();
            theme::install_fonts(&ctx);
            theme::apply(&ctx, pal);

            let mut output = ctx.run_ui(egui::RawInput::default(), |ui| {
                egui::CentralPanel::default().show(ui, |ui| {
                    accent_button(ui, pal, "выключено", 200.0, false, "почему");
                    accent_button(ui, pal, "включено", 200.0, true, "");
                });
            });
            let off = ink(&output.shapes, "выключено");
            let on = ink(&output.shapes, "включено");
            output.textures_delta.clear();

            assert_eq!(
                off,
                Some(pal.text_on_accent_disabled),
                "{theme}: выключенная кнопка подписана не своим цветом"
            );
            assert_eq!(
                on,
                Some(pal.text_on_accent),
                "{theme}: включённая кнопка подписана не своим цветом"
            );
        }
    }

    /// Заголовок группы вправду рисует метку сводки: точку и цвет у
    /// включённого, ни того ни другого у заглушки (задача 51).
    ///
    /// `a_login_left_on_does_not_look_like_the_placeholder` проверяет, что
    /// метка есть в сводке, а не то, что заголовок её взял, — та же пара,
    /// что у палитры с `a_disabled_main_button_keeps_its_own_ink`. Обе темы,
    /// и светлая тут важнее: приглушённый серый и цвет предупреждения в ней
    /// почти одной яркости, так что взглядом их различает прежде всего точка.
    ///
    /// Проверено красным: с `pal.text_muted` вместо тона метки проверка
    /// падает на цвете, без точки — на её подсчёте.
    #[test]
    fn the_folded_header_lights_up_only_when_something_is_on() {
        for (theme, pal) in [("тёмная", theme::Palette::dark()), ("светлая", theme::Palette::light())]
        {
            let ctx = egui::Context::default();
            theme::install_fonts(&ctx);
            theme::apply(&ctx, pal);
            let idle = GroupSummary {
                text: "что лежит внутри".to_owned(),
                mark: None,
            };
            let lit = GroupSummary {
                text: "вход на сайт".to_owned(),
                mark: Some(Tone::Warn),
            };

            let mut output = ctx.run_ui(egui::RawInput::default(), |ui| {
                egui::CentralPanel::default().show(ui, |ui| {
                    disclosure_row(ui, pal, false, "Нетронутая", &idle, 1.0);
                    disclosure_row(ui, pal, false, "Включённая", &lit, 1.0);
                });
            });
            let idle_ink = ink(&output.shapes, &idle.text);
            let lit_ink = ink(&output.shapes, &lit.text);
            let spots = dots(&output.shapes);
            output.textures_delta.clear();

            assert_eq!(idle_ink, Some(pal.text_muted), "{theme}: заглушка не того цвета");
            assert_eq!(
                lit_ink,
                Some(pal.state_warning),
                "{theme}: включённое не того цвета"
            );
            let fills: Vec<egui::Color32> = spots.iter().map(|&(_, _, fill)| fill).collect();
            assert_eq!(
                fills,
                [pal.state_warning],
                "{theme}: точка должна гореть одна и цветом метки"
            );
        }
    }

    /// Точка у обрезанной сводки держится своей сводки и не налезает на
    /// название группы — ни на одном языке.
    ///
    /// Сводка обрезается сама и в раскладке справа налево забирает весь
    /// остаток строки, а точка стоит левее неё и потому кладётся после.
    /// Без места, вычтенного заранее, ей его не остаётся, и она ложится
    /// на название, — только в узком окне и только с длинной сводкой, то
    /// есть там, куда глазной прогон заглядывает реже всего. Места ищутся
    /// по именам, а не по координатам, списанным в тест: они зависят от
    /// шрифтов и языка.
    ///
    /// Требование — «ближе к сводке, чем к названию», а не «не налезает»,
    /// и дело не в строгости. Обрезанная метка оставляет у своего края
    /// хвост короче одного знака, и насколько точка сдвинется на название,
    /// решает длина этого хвоста, то есть шрифт и язык. Проверено красным:
    /// без вычтенного места точка залезает на название по-английски на 3
    /// точки, по-русски на 0.125, а по-армянски не залезает вовсе — ложится
    /// в 2.4 точки от него при 7 до своей сводки. Проверка «не налезает»
    /// армянский пропустила бы, а точка, прижатая к названию, читается его
    /// меткой и без перекрытия. С вычетом до названия не меньше 10 точек.
    #[test]
    fn the_dot_keeps_clear_of_the_title_in_a_narrow_row() {
        const WIDTH: f32 = 320.0;
        let pal = theme::Palette::dark();
        let de = SubLang::Code("de".to_owned());
        let mut failures = Vec::new();

        for lang in Lang::ALL {
            // Свой контекст на язык: общий помнит размеры от прошлого кадра
            // и исказил бы первый кадр следующего.
            let ctx = egui::Context::default();
            theme::install_fonts(&ctx);
            theme::apply(&ctx, pal);
            ctx.enable_accesskit();

            let title = i18n::t(lang, Key::UiAdvanced);
            // Самая длинная сводка, какая бывает: включено всё, и фрагмент
            // вдобавок задан неверно.
            let summary = advanced_summary(true, false, true, Some(&de), lang);
            let (mut named, mut spots, mut natural) = (Vec::new(), Vec::new(), 0.0);

            for _ in 0..2 {
                let input = egui::RawInput {
                    screen_rect: Some(egui::Rect::from_min_size(
                        egui::Pos2::ZERO,
                        egui::vec2(WIDTH, 200.0),
                    )),
                    ..Default::default()
                };
                let mut output = ctx.run_ui(input, |ui| {
                    egui::CentralPanel::default().show(ui, |ui| {
                        natural = ui
                            .painter()
                            .layout_no_wrap(
                                summary.text.clone(),
                                egui::TextStyle::Small.resolve(ui.style()),
                                egui::Color32::PLACEHOLDER,
                            )
                            .size()
                            .x;
                        disclosure_row(ui, pal, false, title, &summary, 1.0);
                    });
                });
                spots = dots(&output.shapes);
                named = named_widgets(&mut output);
                output.textures_delta.clear();
            }

            let find = |name: &str| {
                named
                    .iter()
                    .find(|(found, _)| found == name)
                    .map(|&(_, rect)| rect)
                    .unwrap_or_else(|| panic!("{lang:?}: в кадре нет «{name}»"))
            };
            let title_rect = find(title);
            let text_rect = find(&summary.text);
            // Сторож самой проверки: необрезанная сводка оставила бы точке
            // место и без вычета, и проверка прошла бы на сломанном коде.
            assert!(
                text_rect.width() + 1.0 < natural,
                "{lang:?}: сводка не обрезана ({} из {natural}) — строка слишком широка \
                 для этой проверки",
                text_rect.width()
            );
            let [(center, radius, _)] = spots[..] else {
                panic!("{lang:?}: точек {} вместо одной", spots.len());
            };
            let to_title = center.x - radius - title_rect.right();
            let to_text = text_rect.left() - (center.x + radius);
            if to_text < 0.0 {
                failures.push(format!("{lang:?}: точка налезает на сводку на {}", -to_text));
            }
            if to_title <= to_text {
                failures.push(format!(
                    "{lang:?}: до названия {to_title}, до сводки {to_text} — точка \
                     прижата к названию"
                ));
            }
            if text_rect.right() > WIDTH {
                failures.push(format!(
                    "{lang:?}: сводка вылезла за кромку: {}",
                    text_rect.right()
                ));
            }
        }

        assert!(failures.is_empty(), "{}", failures.join("\n"));
    }

    /// Дорожка переключателя идёт слева направо, куда бы её ни поставили.
    ///
    /// `ui.horizontal` не «начинает слева направо», а продолжает направление
    /// родителя (`horizontal_with_main_wrap_dyn` спрашивает у него
    /// `prefer_right_to_left`). Дорожка, поставленная в подвал, разложенный
    /// справа налево, поэтому рисовала сегменты задом наперёд: список
    /// `[Тёмная, Светлая]` выходил в окне как «Светлая | Тёмная», и выбранной
    /// выглядела не та подпись, под которой человек искал свою тему.
    ///
    /// Меряется положение самих подписей, а не дорожки: дорожка лежит во
    /// `Frame` и занимает одно и то же место при любом порядке содержимого,
    /// то есть проверяла бы сама себя.
    ///
    /// Проверено красным: с `ui.horizontal` вместо явной раскладки проверка
    /// падает на второй половине — справа налево «раз» оказывается правее
    /// «двух».
    #[test]
    fn a_segment_track_reads_left_to_right_wherever_it_stands() {
        /// Где легла подпись с таким текстом, по левому краю.
        fn label_x(shapes: &[egui::epaint::ClippedShape], text: &str) -> Option<f32> {
            fn walk(shape: &egui::Shape, text: &str, found: &mut Option<f32>) {
                match shape {
                    egui::Shape::Text(t) => {
                        if t.galley.job.text.trim() == text {
                            *found = Some(t.pos.x);
                        }
                    }
                    egui::Shape::Vec(list) => {
                        for shape in list {
                            walk(shape, text, found);
                        }
                    }
                    _ => {}
                }
            }
            let mut found = None;
            for clipped in shapes {
                walk(&clipped.shape, text, &mut found);
            }
            found
        }

        let pal = theme::Palette::dark();
        let items = [(0_u8, "раз"), (1, "два")];
        let ctx = egui::Context::default();
        theme::install_fonts(&ctx);
        theme::apply(&ctx, pal);

        // Обе раскладки в одном кадре, и у каждой дорожки свой `Id`: с общим
        // таблетка выбранного сегмента летала бы между ними.
        let (mut plain, mut backwards) = ((0.0, 0.0), (0.0, 0.0));
        for _ in 0..3 {
            let input = egui::RawInput {
                screen_rect: Some(egui::Rect::from_min_size(
                    egui::Pos2::ZERO,
                    egui::vec2(900.0, 420.0),
                )),
                ..Default::default()
            };
            let mut output = ctx.run_ui(input, |ui| {
                egui::CentralPanel::default().show(ui, |ui| {
                    ui.horizontal(|ui| {
                        segment_track(ui, pal, egui::Id::new("прямо"), 1.0, 0, &items, false);
                    });
                });
            });
            plain = (
                label_x(&output.shapes, "раз").unwrap_or(f32::NAN),
                label_x(&output.shapes, "два").unwrap_or(f32::NAN),
            );
            output.textures_delta.clear();

            let input = egui::RawInput {
                screen_rect: Some(egui::Rect::from_min_size(
                    egui::Pos2::ZERO,
                    egui::vec2(900.0, 420.0),
                )),
                ..Default::default()
            };
            let mut output = ctx.run_ui(input, |ui| {
                egui::CentralPanel::default().show(ui, |ui| {
                    // Ровно то окружение, в котором дорожка темы и живёт:
                    // ряд подвала, разложенный справа налево.
                    ui.allocate_ui_with_layout(
                        egui::vec2(ui.available_width(), theme::CONTROL_HEIGHT),
                        egui::Layout::right_to_left(egui::Align::Center),
                        |ui| {
                            segment_track(
                                ui,
                                pal,
                                egui::Id::new("наоборот"),
                                1.0,
                                0,
                                &items,
                                false,
                            );
                        },
                    );
                });
            });
            backwards = (
                label_x(&output.shapes, "раз").unwrap_or(f32::NAN),
                label_x(&output.shapes, "два").unwrap_or(f32::NAN),
            );
            output.textures_delta.clear();
        }

        assert!(
            plain.0 < plain.1,
            "слева направо порядок уже сломан: «раз» на {}, «два» на {}",
            plain.0,
            plain.1
        );
        assert!(
            backwards.0 < backwards.1,
            "справа налево дорожка перевернулась: «раз» на {}, «два» на {}",
            backwards.0,
            backwards.1
        );
    }

    /// Карточки «Машины» занимают своё содержимое, а не весь экран.
    ///
    /// Дефект 42: `with_layout(right_to_left(Align::Center))` отдаёт ряду
    /// всю оставшуюся высоту, а центрирующая раскладка считает её занятой
    /// целиком (`Placer::advance_after_rects`, «pretend we used whole
    /// frame»). Внутри прокрутки остаток — почти весь экран, и первая же
    /// карточка вырастала до нижней кромки, вытесняя остальные.
    ///
    /// Проверено красным: с прежним `ui.with_layout` вместо
    /// `allocate_ui_with_layout` обе проверки падают — 434 точки при окне
    /// высотой 420. Стало 102 и 175.
    ///
    /// Нижние границы тут не для симметрии: заниженная высота ряда обрезала
    /// бы содержимое сверху, а число показателя набрано тридцатым кеглем —
    /// оно выше кнопки, и `CONTROL_HEIGHT` ему мал.
    #[test]
    fn a_machine_card_does_not_stretch_to_the_whole_window() {
        let pal = theme::Palette::dark();
        let checked = card_height(|ui| check_card(ui, pal, &sample_check(), Lang::Ru));
        assert!(checked > 60.0, "карточка пункта обрезана: {checked}");
        assert!(checked < 160.0, "карточка пункта во весь экран: {checked}");

        let metric = Metric::new(37.0, Some("13.1 ГБ из 31.9 ГБ".to_owned()));
        let trace = Trace::default();
        let measured = card_height(|ui| {
            let plot = Plot::new(&trace, pal.accent, 0.0);
            metric_card(ui, pal, "Процессор", &metric, plot, 1.0, None);
        });
        assert!(measured > 140.0, "карточка показателя обрезана: {measured}");
        assert!(
            measured < 220.0,
            "карточка показателя во весь экран: {measured}"
        );
    }

    /// Те же ряды, что уже лежат в `ui.horizontal`, не растягиваются и так.
    ///
    /// Это не повтор предыдущей проверки, а её обратная сторона.
    /// `ui.horizontal` задаёт потомку высоту (`interact_size.y`), поэтому
    /// вложенный в него центрирующий ряд ничего лишнего не забирает — и
    /// правки дефекта 42 этим местам не понадобилось. Сторож нужен затем,
    /// что обёртка выглядит лишней прослойкой и её тянет заменить прямым
    /// `with_layout`: сборка, `clippy` и тесты такой замены не заметили бы.
    ///
    /// Проверено красным: с `ui.with_layout(left_to_right(Center))` вместо
    /// `ui.horizontal` в [`process_row`] проверка падает (431 против 61).
    #[test]
    fn a_row_inside_a_horizontal_keeps_its_height() {
        let pal = theme::Palette::dark();
        let row = crate::model::ProcRow {
            name: "yt-dlp.exe".to_owned(),
            cpu: 12.0,
            cpu_text: "12%".to_owned(),
            mem_text: "310 МБ".to_owned(),
        };
        let process = card_height(|ui| process_row(ui, pal, &row));
        assert!(process > 30.0, "строка процесса обрезана: {process}");
        assert!(process < 100.0, "строка процесса во весь экран: {process}");

        // Обе сводки, и горящая тут не для полноты: у неё подпись лежит
        // в своём ряду с заданной высотой, и забери он остаток — заголовок
        // вырос бы ровно так, как ловит эта проверка.
        for mark in [None, Some(Tone::Warn)] {
            let summary = GroupSummary {
                text: "по умолчанию".to_owned(),
                mark,
            };
            let disclosure = card_height(|ui| {
                disclosure_row(ui, pal, false, "Тонкие настройки", &summary, 1.0);
            });
            assert!(disclosure > 20.0, "{mark:?}: заголовок группы обрезан: {disclosure}");
            assert!(
                disclosure < 100.0,
                "{mark:?}: заголовок группы во весь экран: {disclosure}"
            );
        }
    }

    /// Описание в окне «О программе» — дословно вступление README.
    ///
    /// Два описания одной программы, правленные в разное время, расходятся
    /// молча: ни сборка, ни `clippy` не знают, что это один и тот же текст.
    /// Жирное начертание в README — разметка, а не слова, поэтому `**`
    /// снимается перед сверкой.
    #[test]
    fn the_about_text_is_the_readme_intro() {
        let readme = include_str!("../README.md");
        let intro: Vec<&str> = readme
            .lines()
            .skip_while(|line| !line.starts_with("# "))
            .skip(1)
            .skip_while(|line| line.trim().is_empty())
            .take_while(|line| !line.trim().is_empty())
            .map(str::trim)
            .collect();
        // README один и по-русски, так что и сверять его есть с чем только
        // по-русски. Переводы этой строки проверяет таблица (у каждого ключа
        // есть текст на всех трёх языках), а не README.
        assert_eq!(
            intro.join(" ").replace("**", ""),
            i18n::t(Lang::Ru, ABOUT_TEXT),
            "вступление README разошлось с окном «О программе» — поправьте ABOUT_TEXT"
        );
    }

    /// Письмо из «Написать» уходит по адресу для отзывов и с версией в теме.
    ///
    /// Адрес сверяется целиком, и это не придирка: он отличается от адреса
    /// в истории коммитов, и «поправить» его по ней тянет при первом взгляде.
    /// А только ASCII и без пробелов — потому что `mailto:` это адрес, и сырой
    /// пробел или кириллицу почтовые программы понимают по-разному; пробел
    /// вдобавок заставил бы `Command` взять адрес в кавычки, и они доехали бы
    /// до `url.dll,FileProtocolHandler` как его часть (см. [`open_url`]).
    #[test]
    fn the_feedback_letter_carries_the_address_and_the_version() {
        let mailto = feedback_mailto();
        assert!(
            mailto.starts_with("mailto:cholakhyanerik@hotmail.com?subject="),
            "{mailto}"
        );
        assert!(
            mailto.ends_with(concat!("v", env!("CARGO_PKG_VERSION"))),
            "в теме нет версии: {mailto}"
        );
        assert!(mailto.is_ascii() && !mailto.contains(' '), "{mailto}");
    }

    /// Адрес страницы и лицензия приехали из `Cargo.toml`.
    ///
    /// `env!` на поле, которого в `Cargo.toml` нет, не падает, а отдаёт
    /// пустую строку: убери `repository` — и кнопки открывали бы
    /// «/blob/main/CHANGELOG.md», а строка лицензии осталась бы пустой.
    #[test]
    fn the_about_links_come_from_the_manifest() {
        assert!(PROJECT_URL.starts_with("https://github.com/"), "{PROJECT_URL}");
        assert!(
            CHANGELOG_URL.starts_with(PROJECT_URL) && CHANGELOG_URL.ends_with("/CHANGELOG.md"),
            "{CHANGELOG_URL}"
        );
        assert_eq!(LICENSE, "MIT");
    }

    /// Окно «О программе» целиком помещается в окно минимального размера.
    ///
    /// Ровно так уже ломалось окно метаданных: в 520×420 модалка
    /// фиксированного размера теряла заголовок сверху и «Закрыть» снизу,
    /// и закрыть её становилось нечем. Сборка этого не видит, а тест
    /// видит — модалка, которой не хватило высоты, выходит за кромку.
    ///
    /// Три кадра — по той же причине, что у [`log_body_height`]: модалка —
    /// это `Area`, и свой размер она узнаёт по прошлому кадру.
    ///
    /// Все три языка, а не один: перевод длиннее оригинала — обычное дело,
    /// и окно, влезающее по-русски, по-английски вылезает за кромку. Ловится
    /// это только здесь: глазной прогон идёт на том языке, что выбран.
    #[test]
    fn the_about_window_fits_the_smallest_window() {
        let pal = theme::Palette::dark();
        let screen = egui::Rect::from_min_size(egui::Pos2::ZERO, egui::vec2(520.0, 420.0));

        for lang in Lang::ALL {
            // Свой контекст на язык: у модалки есть память между кадрами,
            // и размер от прошлого языка исказил бы первый кадр следующего.
            let ctx = egui::Context::default();
            theme::install_fonts(&ctx);
        theme::apply(&ctx, pal);
            let mut rect = egui::Rect::NOTHING;

            for _ in 0..3 {
                let input = egui::RawInput {
                    screen_rect: Some(screen),
                    ..Default::default()
                };
                let mut output = ctx.run_ui(input, |ui| {
                    // «Скопировано» горит: так ряд с адресом самый широкий.
                    rect = about_window(pal, ui.ctx(), lang, 1.0, true).response.rect;
                });
                output.textures_delta.clear();
            }

            assert!(rect.height() > 200.0, "{lang:?}: окно схлопнулось: {rect:?}");
            assert!(
                screen.contains_rect(rect),
                "{lang:?}: окно «О программе» не влезает в 520×420: {rect:?}"
            );
        }
    }

    /// Кадры «О программе» в окне заданного размера: где легла модалка и её
    /// кнопки в последнем кадре по дереву доступности.
    ///
    /// Кадров восемь, с запасом: первый проход модалки примерочный, и до
    /// своего размера она дорастает не сразу, а на высоту рядов кнопок
    /// за кадр (сейчас ей хватает двух).
    fn about_frames(
        ctx: &egui::Context,
        lang: Lang,
        window: egui::Vec2,
    ) -> (egui::Rect, Vec<(String, egui::Rect)>) {
        let pal = theme::Palette::dark();
        let mut rect = egui::Rect::NOTHING;
        let mut buttons = Vec::new();
        for _ in 0..8 {
            let input = egui::RawInput {
                screen_rect: Some(egui::Rect::from_min_size(egui::Pos2::ZERO, window)),
                ..Default::default()
            };
            let mut output = ctx.run_ui(input, |ui| {
                // «Скопировано» горит: так ряд с адресом самый широкий.
                rect = about_window(pal, ui.ctx(), lang, 1.0, true).response.rect;
            });
            output.textures_delta.clear();
            buttons = named_buttons(&mut output);
        }
        (rect, buttons)
    }

    /// Кнопки «О программе» видны без прокрутки в окне любого размера.
    ///
    /// Дефект (задача 69): всё под заголовком, кнопки тоже, лежало в
    /// прокрутке, а примерочный проход модалки берёт высоту из
    /// `default_area_size` — 400 точек. Прокрутка в них вписывалась, а не
    /// переполняла, и модалка так и оставалась в 400 точек даже во весь
    /// экран: «Написать» и «Закрыть» лежали под кромкой прокрутки, а подпись
    /// над ними рассказывала про кнопку, которой не видно.
    ///
    /// Меряется место кнопки относительно модалки, а не модалка относительно
    /// экрана: зажатая модалка помещается в окно всегда, и проверка размера
    /// этого дефекта не видит. Окно 520×420 здесь же: в нём прокрутка нужна
    /// по-настоящему, и кнопки обязаны уместиться под ней вместе с заголовком
    /// на всех трёх языках.
    ///
    /// Проверено красным дважды: с кнопками в прокрутке модалка во всех трёх
    /// окнах остаётся в 400 точек и все пять кнопок на всех языках лежат
    /// ниже её кромки, а без запаса под ряды в потолке прокрутки модалка
    /// в окне 520×420 вылезает за кромку окна на всех трёх языках.
    #[test]
    fn the_about_buttons_stay_in_sight() {
        const BUTTONS: [Key; 5] = [
            Key::UiWrite,
            Key::UiCopyAddress,
            Key::UiProjectPage,
            Key::UiWhatChanged,
            Key::UiClose,
        ];
        let windows = [
            egui::vec2(520.0, 420.0),
            egui::vec2(1280.0, 900.0),
            egui::vec2(2560.0, 1369.0),
        ];

        // Провалы копятся и выдаются разом: язык, упавший первым, не должен
        // заслонять остальные.
        let mut failures = Vec::new();
        for window in windows {
            let screen = egui::Rect::from_min_size(egui::Pos2::ZERO, window);
            for lang in Lang::ALL {
                // Свой контекст на язык и окно: модалка помнит размер.
                let ctx = rail_test_ctx();
                let (modal, buttons) = about_frames(&ctx, lang, window);
                if !screen.contains_rect(modal) {
                    failures.push(format!("{lang:?}, окно {window}: модалка {modal:?}"));
                }
                for key in BUTTONS {
                    let name = i18n::t(lang, key);
                    match buttons.iter().find(|(n, _)| n == name) {
                        None => failures.push(format!("{lang:?}, окно {window}: нет «{name}»")),
                        Some((_, rect)) if !modal.contains_rect(*rect) => failures.push(format!(
                            "{lang:?}, окно {window}: «{name}» {rect:?} вне модалки {modal:?}"
                        )),
                        Some(_) => {}
                    }
                }
            }
        }
        assert!(failures.is_empty(), "\n{}", failures.join("\n"));
    }

    /// Подписи кнопок запуска умещаются в свою долю карточки.
    ///
    /// «В очередь» переименована в «Отложить в очередь», и это вдвое длиннее.
    /// Кнопке достаётся треть строки, а строка в окне минимальной ширины —
    /// это около 390 точек: доля выходит меньше полутораста, и подпись
    /// в один ряд не встаёт ни на одном языке. Поэтому она переносится,
    /// а проверка следит за тем, что двух строк хватает: на третьей кнопка
    /// вырастает настолько, что выдавливает «Скачать» из карточки.
    ///
    /// Ширина считается по тем же числам, что и раскладка, а не копией:
    /// своя копия разъехалась бы при первой же правке и перестала бы что-либо
    /// ловить. Проверено красным: без `.wrap()` у кнопки подпись остаётся
    /// одной строкой и проверка падает на русском и армянском.
    #[test]
    fn the_action_buttons_fit_the_card() {
        let pal = theme::Palette::dark();
        let ctx = egui::Context::default();
        theme::install_fonts(&ctx);
        theme::apply(&ctx, pal);

        // Окно минимальной ширины, свёрнутый рельс, поля содержимого и
        // поля карточки — всё, что стоит между кромкой окна и кнопкой.
        let card = 520.0
            - theme::NAV_NARROW
            - theme::CONTENT_MARGIN * 2.0
            - 18.0 * 2.0;
        const GAP: f32 = 10.0;
        let secondary = ((card - GAP) / 3.0).max(90.0);

        let mut output = ctx.run_ui(egui::RawInput::default(), |ui| {
            let font = egui::TextStyle::Button.resolve(ui.style());
            for lang in Lang::ALL {
                for (key, room) in [
                    (Key::UiEnqueue, secondary),
                    (Key::UiDownload, card - secondary - GAP),
                ] {
                    let label = i18n::t(lang, key);
                    // Поля кнопки с обеих сторон — штатные 16 из темы.
                    let room = room - 16.0 * 2.0;
                    let galley = ui.ctx().fonts_mut(|fonts| {
                        fonts.layout(label.to_owned(), font.clone(), pal.text_primary, room)
                    });
                    assert!(
                        galley.rows.len() <= 2,
                        "{lang:?}: кнопка «{label}» разворачивается в {} строки при ширине {room}",
                        galley.rows.len()
                    );
                    assert!(
                        galley.size().x <= room + 0.5,
                        "{lang:?}: кнопка «{label}» не умещается даже с переносом: {} при {room}",
                        galley.size().x
                    );
                }
            }
        });
        output.textures_delta.clear();
    }

    /// Пояснение к разделу не налезает на номер версии.
    ///
    /// `Label::truncate()` занимает столько, сколько просит текст, и о соседе
    /// справа ничего не знает: поставленный после него виджет вытесняется
    /// влево и уезжает под подпись. В окне 520 это выглядело как «…over
    /// yo0.32.1» — версия поверх последних букв пояснения. Лечится порядком:
    /// версия кладётся **первой** в раскладке справа налево, а пояснение
    /// живёт во вложенной раскладке слева направо, где ему достаётся остаток.
    ///
    /// Проверяются все разделы и все языки: пояснения у них разной длины,
    /// а перевод длиннее русского — «влезло на одном» тут ничего не значит.
    ///
    /// Проверено красным: с версией, положенной последней, проверка падает
    /// на «Телефоне» по-английски.
    #[test]
    fn the_section_title_leaves_room_for_the_version() {
        let pal = theme::Palette::dark();
        // Раздел, пояснение — самое длинное из всех, и ширина окна
        // минимальная за вычетом свёрнутого рельса и полей содержимого.
        const NOTES: [(&str, Key); 4] = [
            ("Загрузка", Key::NavDownloadNote),
            ("Телефон", Key::NavPhoneNote),
            ("Метаданные", Key::NavMetadataNote),
            ("Сейчас", Key::NavMachineNowNote),
        ];
        let room = 520.0 - theme::NAV_NARROW - theme::CONTENT_MARGIN * 2.0;

        for lang in Lang::ALL {
            let ctx = egui::Context::default();
            theme::install_fonts(&ctx);
            theme::apply(&ctx, pal);

            for (title, note) in NOTES {
                let mut row = None;
                for _ in 0..3 {
                    let input = egui::RawInput {
                        screen_rect: Some(egui::Rect::from_min_size(
                            egui::Pos2::ZERO,
                            egui::vec2(520.0, 420.0),
                        )),
                        ..Default::default()
                    };
                    let mut output = ctx.run_ui(input, |ui| {
                        egui::CentralPanel::default().show(ui, |ui| {
                            ui.set_max_width(room);
                            row = Some(section_title_row(ui, pal, lang, 1.0, title, note));
                        });
                    });
                    output.textures_delta.clear();
                }

                let row = row.expect("строка заголовка нарисована");
                assert!(
                    row.version.width() > 20.0,
                    "{lang:?}/{title}: номер версии пропал: {:?}",
                    row.version
                );
                assert!(
                    row.note.right() <= row.version.left() + 0.5,
                    "{lang:?}/{title}: пояснение налезает на номер версии: {:?} и {:?}",
                    row.note,
                    row.version
                );
            }
        }
    }

    /// Приветствие помещается в окно минимальной ширины на всех языках.
    ///
    /// Та же проверка, что у «О программе», и та же причина: модалка растёт
    /// по содержимому, а шесть карточек разделов в узком окне встают тремя
    /// группами одна под другой — без потолка по высоте заголовок уходит за
    /// верхнюю кромку, а «Начать» за нижнюю. Приветствие, которое нельзя ни
    /// дочитать, ни закрыть кнопкой, — худшее из первых впечатлений, и
    /// увидеть это можно только глазами: окно рисуется больше экрана без
    /// единой жалобы.
    ///
    /// Проверено красным дважды: на трёх шагах загрузки и заново на шести
    /// разделах — без потолка прокрутки модалка по-русски вырастает до 601
    /// точки при окне в 420.
    #[test]
    fn the_welcome_window_fits_the_smallest_window() {
        let pal = theme::Palette::dark();
        let screen = egui::Rect::from_min_size(egui::Pos2::ZERO, egui::vec2(520.0, 420.0));

        for lang in Lang::ALL {
            // Свой контекст на язык: у модалки есть память между кадрами,
            // и размер от прошлого языка исказил бы первый кадр следующего.
            let ctx = egui::Context::default();
            theme::install_fonts(&ctx);
            theme::apply(&ctx, pal);
            let groups = nav_groups(lang);
            let mut rect = egui::Rect::NOTHING;

            for _ in 0..3 {
                let input = egui::RawInput {
                    screen_rect: Some(screen),
                    ..Default::default()
                };
                let mut output = ctx.run_ui(input, |ui| {
                    rect = welcome_window(pal, ui.ctx(), lang, &groups, 1.0).response.rect;
                });
                output.textures_delta.clear();
            }

            assert!(rect.height() > 150.0, "{lang:?}: окно схлопнулось: {rect:?}");
            assert!(
                screen.contains_rect(rect),
                "{lang:?}: приветствие не влезает в 520×420: {rect:?}"
            );
        }
    }

    /// Кадры приветствия в окне заданного размера: что в нём нажали, где
    /// легла модалка и кнопки последнего кадра по дереву доступности.
    ///
    /// Кадров обычно нужно несколько: первый проход модалки примерочный, и до
    /// своего размера она дорастает не сразу.
    fn welcome_frames(
        ctx: &egui::Context,
        lang: Lang,
        window: egui::Vec2,
        frames: Vec<Vec<egui::Event>>,
    ) -> (Option<WelcomeAction>, egui::Rect, Vec<(String, egui::Rect)>) {
        let pal = theme::Palette::dark();
        let groups = nav_groups(lang);
        let mut action = None;
        let mut rect = egui::Rect::NOTHING;
        let mut buttons = Vec::new();
        for events in frames {
            let input = egui::RawInput {
                screen_rect: Some(egui::Rect::from_min_size(egui::Pos2::ZERO, window)),
                events,
                ..Default::default()
            };
            let mut output = ctx.run_ui(input, |ui| {
                let window = welcome_window(pal, ui.ctx(), lang, &groups, 1.0);
                rect = window.response.rect;
                action = action.or(window.inner);
            });
            output.textures_delta.clear();
            buttons = named_buttons(&mut output);
        }
        (action, rect, buttons)
    }

    /// Место кнопки с этим именем; нет такой — проверка падает с `what`.
    fn button_rect(buttons: &[(String, egui::Rect)], name: &str, what: &str) -> egui::Rect {
        buttons
            .iter()
            .find(|(n, _)| n == name)
            .map(|(_, rect)| *rect)
            .unwrap_or_else(|| panic!("{what}: нет кнопки «{name}»"))
    }

    /// Каждый пункт рельса назван в приветствии и открывается его карточкой.
    ///
    /// Приветствие строится по `NAV`, а не своим списком, и проверка держит
    /// ровно это: раздел, добавленный в рельс, обязан появиться и здесь —
    /// кнопкой, которая открывает именно его, а у «Машины» — именно ту
    /// половину. Карточка ищется по имени в дереве доступности, как её
    /// найдёт экранный диктор, и на всех трёх языках: имя — это перевод.
    ///
    /// Раскладки обе, и какая где — проверяется тут же: у колонок и у строк
    /// свой обход `NAV`, потерять пункт может любой, а после правки порога
    /// два окна молча проверяли бы одну и ту же раскладку. Узкое окно
    /// высокое, чтобы ни одна карточка не ушла под прокрутку: щелчок по
    /// спрятанной пришёлся бы не в неё.
    ///
    /// Проверено красным трижды: с одним рядом карточек в колонках пропадают
    /// «Метаданные», со строками по одной карточке из пары — тоже, а без
    /// половины в ответе карточка «Сейчас» открывает «Машину» вообще, а не
    /// свою половину.
    #[test]
    fn every_rail_item_is_named_and_opened_by_the_welcome() {
        // Окно и пункт, который в этой раскладке стоит рядом с «Загрузкой».
        let cases = [
            (egui::vec2(1280.0, 800.0), Key::MachineNow),
            (egui::vec2(600.0, 1000.0), Key::TabMetadata),
        ];
        for (window, beside) in cases {
            for lang in Lang::ALL {
                let what = format!("{lang:?}, окно {window:?}");
                let ctx = rail_test_ctx();
                let (_, _, buttons) = welcome_frames(&ctx, lang, window, vec![Vec::new(); 6]);

                let first = button_rect(&buttons, i18n::t(lang, Key::TabDownload), &what);
                let next = button_rect(&buttons, i18n::t(lang, beside), &what);
                assert!(
                    (first.top() - next.top()).abs() < 0.5 && next.left() > first.right(),
                    "{what}: рядом с «Загрузкой» не «{}» — раскладка не та: {first:?} и {next:?}",
                    i18n::t(lang, beside)
                );

                for item in NAV.iter().flat_map(|(_, items)| items.iter()) {
                    let name = i18n::t(lang, item.label);
                    let card = button_rect(&buttons, name, &what);
                    let (action, _, _) =
                        welcome_frames(&ctx, lang, window, click_at(card.center()).to_vec());
                    assert_eq!(
                        action,
                        Some(WelcomeAction::Open(item.tab, item.half)),
                        "{what}: карточка «{name}» открывает не свой раздел"
                    );
                }
            }
        }
    }

    /// В окне по умолчанию приветствие видно целиком, без прокрутки.
    ///
    /// 720×560 — размер, к которому окно возвращается из развёрнутого
    /// (`with_inner_size` в main.rs). Модалка, которую приходится
    /// прокручивать в окне обычного размера, перестаёт быть приветствием:
    /// нижний ряд карточек уходит под кромку, и о двух-трёх разделах
    /// человек не узнает, если не догадается крутить. Ради этого группы
    /// в широком окне и стоят колонками.
    ///
    /// Прокрутку видно по зазору между последней карточкой и «Начать»: пока
    /// всё помещается, он тот же, что в заведомо высоком окне, а стоит
    /// содержимому уйти под кромку прокрутки — «Начать» поднимается над
    /// карточками, и зазор сжимается. Высота самой модалки тут ничего не
    /// скажет: с потолком прокрутки она помещается в окно всегда.
    ///
    /// Проверено красным: с `PITCH_MIN_WIDTH` 200 группы в этом окне встают
    /// строками, и по-русски 68 точек разделов уходят под прокрутку.
    #[test]
    fn the_welcome_needs_no_scrolling_in_the_default_window() {
        let window = egui::vec2(720.0, 560.0);
        let tall = egui::vec2(window.x, 2000.0);
        for lang in Lang::ALL {
            let gap = |window: egui::Vec2| {
                let what = format!("{lang:?}, окно {window:?}");
                let ctx = rail_test_ctx();
                let (_, rect, buttons) = welcome_frames(&ctx, lang, window, vec![Vec::new(); 8]);
                assert!(
                    egui::Rect::from_min_size(egui::Pos2::ZERO, window).contains_rect(rect),
                    "{what}: приветствие не влезает в окно: {rect:?}"
                );
                let start = button_rect(&buttons, i18n::t(lang, Key::WelcomeStart), &what);
                let bottom = NAV
                    .iter()
                    .flat_map(|(_, items)| items.iter())
                    .map(|item| button_rect(&buttons, i18n::t(lang, item.label), &what).bottom())
                    .fold(f32::MIN, f32::max);
                start.top() - bottom
            };
            let (here, free) = (gap(window), gap(tall));
            assert!(
                here >= free - 0.5,
                "{lang:?}: в окне {window:?} разделы уходят под прокрутку на {}",
                free - here
            );
        }
    }

    /// Карточки разделов в приветствии читаются в окне любого размера:
    /// название — в одну строку рядом со значком, строка «что это даёт» —
    /// не длиннее четырёх строк, на всех трёх языках.
    ///
    /// Уже [`PITCH_MIN_WIDTH`] текст карточки не бывает ни в одной
    /// раскладке, поэтому и мерить достаточно на нём: колонки выбираются
    /// по нему же, а что в строках по две карточка шире и в самом узком
    /// окне, проверяется здесь арифметикой из тех же чисел, что у раскладки.
    ///
    /// Меряется разложенный текст, а не карточка: карточка занимает свою
    /// ширину всегда, и на сломанной раскладке тоже, — проверяла бы сама себя.
    ///
    /// Проверено красным: с `PITCH_MIN_WIDTH` 150 армянская строка «Сейчас»
    /// занимает пять строк.
    #[test]
    fn the_welcome_cards_stay_readable() {
        const MAX_ROWS: usize = 4;
        let pal = theme::Palette::dark();
        let ctx = rail_test_ctx();
        let mut output = ctx.run_ui(egui::RawInput::default(), |ui| {
            let font = egui::TextStyle::Small.resolve(ui.style());
            for lang in Lang::ALL {
                for item in NAV.iter().flat_map(|(_, items)| items.iter()) {
                    let pitch = i18n::t(lang, item.pitch);
                    let rows = ui
                        .painter()
                        .layout(pitch.to_owned(), font.clone(), pal.text_muted, PITCH_MIN_WIDTH)
                        .rows
                        .len();
                    assert!(
                        rows <= MAX_ROWS,
                        "{lang:?}: «{pitch}» занимает {rows} строк при {PITCH_MIN_WIDTH}"
                    );

                    let name = i18n::t(lang, item.label);
                    let width = ui
                        .painter()
                        .layout_no_wrap(name.to_owned(), welcome_title_font(), pal.text_primary)
                        .size()
                        .x;
                    assert!(
                        WELCOME_BADGE + WELCOME_BADGE_GAP + width <= PITCH_MIN_WIDTH,
                        "{lang:?}: «{name}» не помещается рядом со значком: {width}"
                    );
                }
            }
        });
        output.textures_delta.clear();

        let margin = theme::inner_frame(pal).total_margin().sum().x;
        let narrowest = welcome_cell_width(welcome_width(520.0), WELCOME_PER_ROW) - margin;
        assert!(
            narrowest >= PITCH_MIN_WIDTH,
            "в окне 520 точек карточке из пары остаётся под текст {narrowest}"
        );
    }

    /// Разворот рельса не отнимает у содержимого вторую колонку.
    ///
    /// Раскладка обязана быть монотонной по ширине окна: расширил окно —
    /// содержимому стало не хуже. Рельс это нарушает легко, потому что при
    /// развороте забирает себе 160 точек разом, и если позволить ему
    /// разворачиваться раньше времени, окно шире на одну точку схлопывает
    /// две колонки в одну.
    ///
    /// Ровно это стояло в макете: при пороге 900 окно 899 давало содержимому
    /// 803 точки и две колонки, а окно 900 — 644 и одну. Поэтому порог здесь
    /// выведен из `TWO_COLUMN_MIN`, а не переписан из документа.
    ///
    /// Арифметика, а не кадр: проверяется договорённость между тремя числами
    /// темы, и рисовать для этого нечего. Проверено красным: с порогом 900
    /// вместо `NAV_WIDE_MIN` проверка падает на 900.
    #[test]
    fn the_content_never_loses_room_as_the_window_grows() {
        /// Сколько места достаётся содержимому при такой ширине окна.
        ///
        /// Высота — с запасом, чтобы решала одна ширина; вид рельса берётся
        /// у того же `RailLayout::for_window`, что и в окне, а не копией
        /// условия: копия разъехалась бы с ним при первой же правке.
        fn content(window: f32) -> f32 {
            let rail = RailLayout::for_window(egui::vec2(window, 2000.0)).width();
            window - rail - theme::CONTENT_MARGIN * 2.0
        }

        // Меряется число колонок, а не голая ширина, и это выяснилось на
        // красном прогоне. Голая ширина на пороге обязана просесть: рельс
        // разворачивается и забирает себе 160 точек разом — 919 превращаются
        // в 760. Это цена любого сворачивающегося рельса, и терпима она
        // ровно до тех пор, пока содержимое не теряет колонку.
        let mut columns = 0_u8;
        for window in 520..=2600 {
            let room = content(window as f32);
            let now = if room >= theme::TWO_COLUMN_MIN { 2 } else { 1 };
            assert!(
                now >= columns,
                "окно {window}: колонок стало меньше — {now} против {columns}"
            );
            columns = now;
        }

        // И, наконец, сам разворот обязан оставлять место обеим колонкам:
        // иначе монотонность соблюдалась бы ценой рельса, который никогда
        // не разворачивается.
        assert!(
            content(theme::NAV_WIDE_MIN) >= theme::TWO_COLUMN_MIN,
            "развёрнутый рельс не оставляет места второй колонке: {}",
            content(theme::NAV_WIDE_MIN)
        );
    }

    /// Подписи рельса влезают в его ширину на всех трёх языках.
    ///
    /// То же узкое место, что у дорожек качества, и та же причина: ширина
    /// подобрана под русский, а перевод длиннее. Не влезшая подпись в рельсе
    /// не переносится и не обрезается сама — она рисуется кистью, то есть
    /// просто уезжает под кромку и наползает на содержимое.
    ///
    /// Пункты меряются разложенным текстом, а не самим пунктом: пункт
    /// занимает всю ширину рельса всегда, и на сломанной раскладке тоже, —
    /// проверял бы сам себя. Числа берутся из темы, а не копией: своя копия
    /// разъехалась бы с раскладкой при первой же правке.
    ///
    /// А нижний блок меряется настоящим кадром. Прежде и он считался
    /// арифметикой по каждой кнопке в отдельности, и ряд «?», язык, журнал
    /// она пропустила: каждая подпись влезала, а все три вместе — нет, и ряд
    /// вылезал за кромку блока. Вылезший ряд к тому же раздвигает раскладку
    /// и тянет за собой соседей снизу, так что проверяется место каждой
    /// кнопки, а не только этого ряда.
    ///
    /// Проверено красным: с `NAV_WIDTH` 150 вместо 216 не влезают подписи
    /// пунктов, а с прежним рядом из трёх кнопок «Журнал» вылезает из блока
    /// уже по-русски.
    #[test]
    fn the_rail_labels_fit_their_width() {
        let pal = theme::Palette::dark();
        let ctx = egui::Context::default();
        theme::install_fonts(&ctx);
        theme::apply(&ctx, pal);

        let mut output = ctx.run_ui(egui::RawInput::default(), |ui| {
            let item_font = egui::FontId::new(15.0, egui::FontFamily::Proportional);
            for lang in Lang::ALL {
                // Подпись «Настройки» стоит в том же ряду, что и пункты, и
                // рисуется тем же `paint_rail_label`.
                let items = NAV
                    .iter()
                    .flat_map(|(_, items)| items.iter().map(|item| item.label))
                    .chain([Key::NavSettings]);
                for key in items {
                    let label = i18n::t(lang, key);
                    let w = ui
                        .painter()
                        .layout_no_wrap(label.to_owned(), item_font.clone(), pal.text_primary)
                        .size()
                        .x;
                    assert!(
                        w <= theme::NAV_LABEL_WIDTH,
                        "{lang:?}: пункт «{label}» не влезает в рельс: {w} при {}",
                        theme::NAV_LABEL_WIDTH
                    );
                }
            }
        });
        output.textures_delta.clear();

        // Колонка нижнего блока: рельс начинается у левой кромки окна.
        let left = theme::NAV_PADDING + theme::NAV_BLOCK_MARGIN;
        let right = left + theme::NAV_BLOCK_WIDTH;
        for lang in Lang::ALL {
            // Свой контекст на язык: общий помнит размеры от прошлого
            // и искажает первый кадр следующего.
            let ctx = rail_test_ctx();
            let tall = egui::vec2(theme::NAV_WIDE_MIN, 1200.0);
            let mut named = Vec::new();
            for _ in 0..3 {
                named = rail_test_frame(&ctx, lang, tall, RailLayout::Full, false, Vec::new()).1;
            }

            // Кнопки с переносом разворачиваются меньше чем в три строки: на
            // третьей блок вырастает настолько, что порог высоты окна для
            // развёрнутого рельса уезжает вверх. Порог — между двумя и тремя
            // строками, а не ровно две: строка кириллицы чуть выше латинской
            // (другая гарнитура), и точное число на ней промахивалось бы.
            let style = ctx.global_style();
            let row = ctx.fonts_mut(|f| f.row_height(&egui::TextStyle::Button.resolve(&style)));
            let three_lines = 3.0 * row + 2.0 * style.spacing.button_padding.y;
            let wrapping = [Key::UiUpdateEngine, Key::UiUpdateFfmpeg, Key::UiAbout];

            let block = [Key::UiUpdateEngine, Key::UiUpdateFfmpeg, Key::UiLog, Key::UiAbout]
                .into_iter()
                .chain([Key::UiHelpButtonHint])
                .map(|key| (Some(key), i18n::t(lang, key)))
                .chain([(None, lang.label())]);
            for (key, label) in block {
                let Some((_, rect)) = named.iter().find(|(name, _)| name == label) else {
                    panic!("{lang:?}: в нижнем блоке нет «{label}»");
                };
                assert!(
                    rect.min.x >= left - 0.5 && rect.max.x <= right + 0.5,
                    "{lang:?}: «{label}» вылезает из колонки блока {left}…{right}: {rect:?}"
                );
                if key.is_some_and(|key| wrapping.contains(&key)) {
                    assert!(
                        rect.height() < three_lines - 1.0,
                        "{lang:?}: «{label}» разворачивается в три строки: {} при {three_lines}",
                        rect.height()
                    );
                }
            }

            // «?» делит строку с «всё на месте» и не ложится на подпись.
            let find = |label: &str| {
                named
                    .iter()
                    .find(|(name, _)| name == label)
                    .map(|(_, rect)| *rect)
                    .unwrap_or_else(|| panic!("{lang:?}: в блоке нет «{label}»"))
            };
            let status = find(i18n::t(lang, Key::UiAllInPlaceShort));
            let help = find(i18n::t(lang, Key::UiHelpButtonHint));
            assert!(
                !status.intersects(help),
                "{lang:?}: «?» лёг на строку состояния: {status:?} и {help:?}"
            );
        }
    }

    /// Развёрнутый рельс не ложится нижним блоком на свои же пункты.
    ///
    /// Дефект: рельс разворачивался по одной ширине окна, а прокрутки у
    /// него нет — в окне 1400×420 блок обслуживания рисовался прямо поверх
    /// пунктов, и половина подписей читалась одна сквозь другую. Теперь вид
    /// рельса выбирает и высота (`RailLayout::for_window`), и проверка рисует
    /// оба развёрнутых вида ровно на их пороге: пункты обязаны кончиться
    /// выше того, что под ними, с зазором, на всех трёх языках — по-армянски
    /// блок выше всех.
    ///
    /// Проверено красным: с порогами на 60 точек ниже и то и другое
    /// налезает на пункты.
    #[test]
    fn the_wide_rail_does_not_cover_its_own_items() {
        for lang in Lang::ALL {
            // Под пунктами: весь блок, а в окне пониже — одна кнопка
            // «Настройки». Верх блока — от его первой строки, «всё на месте»,
            // минус поле самого блока.
            let cases = [
                (
                    RailLayout::Full,
                    theme::NAV_WIDE_MIN_HEIGHT,
                    Key::UiAllInPlaceShort,
                    theme::NAV_BLOCK_MARGIN,
                ),
                (RailLayout::Labels, theme::NAV_LABELS_MIN_HEIGHT, Key::NavSettings, 0.0),
            ];
            for (layout, height, below, margin) in cases {
                let window = egui::vec2(theme::NAV_WIDE_MIN, height);
                assert_eq!(RailLayout::for_window(window), layout, "порог {height}");

                let ctx = rail_test_ctx();
                let mut named = Vec::new();
                for _ in 0..3 {
                    named = rail_test_frame(&ctx, lang, window, layout, false, Vec::new()).1;
                }
                let find = |label: &str| {
                    named
                        .iter()
                        .find(|(name, _)| name == label)
                        .map(|(_, rect)| *rect)
                        .unwrap_or_else(|| panic!("{lang:?}, {layout:?}: в рельсе нет «{label}»"))
                };
                let items_bottom = NAV
                    .iter()
                    .flat_map(|(_, items)| items.iter())
                    .map(|item| find(i18n::t(lang, item.label)).max.y)
                    .fold(f32::MIN, f32::max);
                let under_top = find(i18n::t(lang, below)).min.y - margin;
                let overlap = items_bottom + theme::NAV_BLOCK_GAP - under_top;
                assert!(
                    overlap <= 0.5,
                    "{lang:?}, {layout:?}: при высоте окна {height} низ рельса налезает \
                     на пункты на {overlap}"
                );
            }
        }
    }

    /// Окно минимального размера, в котором меряется свёрнутый рельс.
    const SMALLEST_WINDOW: egui::Rect =
        egui::Rect::from_min_max(egui::Pos2::ZERO, egui::pos2(520.0, 420.0));

    /// Контекст для кадров рельса: тема, шрифты и дерево доступности.
    fn rail_test_ctx() -> egui::Context {
        let ctx = egui::Context::default();
        theme::install_fonts(&ctx);
        theme::apply(&ctx, theme::Palette::dark());
        ctx.enable_accesskit();
        ctx
    }

    /// Виджеты кадра по дереву доступности: имя и место на экране.
    ///
    /// Кнопку ищут по имени, а не по координатам, списанным в тест: её место
    /// зависит от шрифтов и языка, и число разъехалось бы с ним при первой
    /// же правке. Заодно проверка держит и сами имена: виджет, который
    /// диктору не назван, не найдётся и здесь.
    fn named_widgets(output: &mut egui::FullOutput) -> Vec<(String, egui::Rect)> {
        named_nodes(output, |_| true)
    }

    /// Только кнопки кадра — имя и место, как у [`named_widgets`].
    ///
    /// Нужны там, где у кнопки то же имя, что у подписи рядом: карточка
    /// раздела в приветствии называется так же, как название внутри неё, и
    /// поиск по одному имени нашёл бы подпись, а кнопку счёл бы найденной.
    fn named_buttons(output: &mut egui::FullOutput) -> Vec<(String, egui::Rect)> {
        named_nodes(output, |role| role == egui::accesskit::Role::Button)
    }

    /// Узлы дерева доступности с именем и местом, отобранные по роли.
    fn named_nodes(
        output: &mut egui::FullOutput,
        keep: impl Fn(egui::accesskit::Role) -> bool,
    ) -> Vec<(String, egui::Rect)> {
        let Some(update) = output.platform_output.accesskit_update.take() else {
            return Vec::new();
        };
        update
            .nodes
            .into_iter()
            .filter(|(_, node)| keep(node.role()))
            .filter_map(|(_, node)| {
                // У подписи текст лежит в `value`, у кнопки — в `label`.
                let name = node.label().or_else(|| node.value())?.to_owned();
                let b = node.bounds()?;
                let rect = egui::Rect::from_min_max(
                    egui::pos2(b.x0 as f32, b.y0 as f32),
                    egui::pos2(b.x1 as f32, b.y1 as f32),
                );
                Some((name, rect))
            })
            .collect()
    }

    /// Один кадр свёрнутого рельса в окне 520×420.
    fn narrow_rail_frame(
        ctx: &egui::Context,
        lang: Lang,
        more_open: bool,
        events: Vec<egui::Event>,
    ) -> (RailPicks, Vec<(String, egui::Rect)>) {
        let window = SMALLEST_WINDOW.size();
        assert_eq!(RailLayout::for_window(window), RailLayout::Narrow);
        rail_test_frame(ctx, lang, window, RailLayout::Narrow, more_open, events)
    }

    /// Один кадр рельса в окне заданного размера.
    ///
    /// Вид передаётся явно, а не выводится из окна: проверке высоты нужен
    /// развёрнутый рельс ровно на пороге, где решение как раз меняется.
    fn rail_test_frame(
        ctx: &egui::Context,
        lang: Lang,
        window: egui::Vec2,
        layout: RailLayout,
        more_open: bool,
        events: Vec<egui::Event>,
    ) -> (RailPicks, Vec<(String, egui::Rect)>) {
        let pal = theme::Palette::dark();
        let groups = nav_groups(lang);
        let input = egui::RawInput {
            screen_rect: Some(egui::Rect::from_min_size(egui::Pos2::ZERO, window)),
            events,
            ..Default::default()
        };
        let mut picks = None;
        let mut output = ctx.run_ui(input, |ui| {
            let state = RailState {
                pal,
                speed: 1.0,
                lang,
                tab: Tab::Download,
                half: MachineTab::Now,
                appearance: Appearance::Dark,
                groups: &groups,
                tools: "yt-dlp 2026.07.04",
                smooth: true,
                has_log: true,
                log_open: false,
                busy: false,
                more_open,
            };
            egui::Panel::left("рельс")
                .resizable(false)
                .exact_size(layout.width())
                .frame(theme::rail_frame(pal))
                .show(ui, |ui| picks = Some(rail_body(ui, &state, layout)));
        });
        output.textures_delta.clear();
        let named = named_widgets(&mut output);
        (picks.expect("рельс не нарисовался"), named)
    }

    /// Щелчок левой кнопкой: нажатие одним кадром, отпускание следующим —
    /// egui засчитывает щелчок на отпускании.
    fn click_at(at: egui::Pos2) -> [Vec<egui::Event>; 2] {
        let button = |pressed| egui::Event::PointerButton {
            pos: at,
            button: egui::PointerButton::Primary,
            pressed,
            modifiers: egui::Modifiers::NONE,
        };
        [vec![egui::Event::PointerMoved(at), button(true)], vec![button(false)]]
    }

    /// Середина виджета с этим именем, если он есть в кадре.
    fn center_of(named: &[(String, egui::Rect)], name: &str) -> Option<egui::Pos2> {
        named
            .iter()
            .find(|(n, _)| n == name)
            .map(|(_, rect)| rect.center())
    }

    /// В окне минимальной ширины рельс свёрнут, и всё, что в нём было,
    /// остаётся достижимым.
    ///
    /// Прежде это держал `the_header_fits_the_smallest_window`: шапка с
    /// дорожкой разделов в 520 точек сходилась впритык. Шапки больше нет,
    /// и вопрос сменился — не «влезло ли», а «не пропало ли»: в свёрнутом
    /// рельсе подписи спрятаны, и если пункт или кнопка нижнего блока
    /// перестанут рисоваться или уедут за нижнюю кромку, окно от этого не
    /// сломается, просто часть программы станет недостижимой.
    ///
    /// Меряются нарисованные пункты, а не сумма высот из темы: сумма
    /// сходилась бы и тогда, когда пункт не рисуется вовсе. Проверено
    /// красным дважды: с `NAV_ITEM_HEIGHT` 60 вместо 38 «Телефон» уезжает
    /// за кромку окна 420, а пункт без имени для диктора не находится.
    #[test]
    fn the_narrow_rail_keeps_every_section_reachable() {
        for lang in Lang::ALL {
            // Свой контекст на язык: общий помнит размеры от прошлого
            // и искажает первый кадр следующего.
            let ctx = rail_test_ctx();
            let mut named = Vec::new();
            for _ in 0..3 {
                named = narrow_rail_frame(&ctx, lang, false, Vec::new()).1;
            }

            let more = i18n::t(lang, Key::NavSettings);
            let labels = NAV
                .iter()
                .flat_map(|(_, items)| items.iter())
                .map(|item| i18n::t(lang, item.label))
                .chain([more]);
            for label in labels {
                let Some((_, rect)) = named.iter().find(|(name, _)| name == label) else {
                    panic!("{lang:?}: в свёрнутом рельсе нет «{label}»");
                };
                assert!(
                    SMALLEST_WINDOW.contains_rect(*rect),
                    "{lang:?}: «{label}» за кромкой окна 520×420: {rect:?}"
                );
                assert!(
                    rect.max.x <= theme::NAV_NARROW + 0.5,
                    "{lang:?}: «{label}» шире свёрнутого рельса: {rect:?}"
                );
            }
        }
    }

    /// В окне минимальной ширины язык меняется из меню свёрнутого рельса.
    ///
    /// Дефект: меню «ещё» закрывалось от любого щелчка, в том числе внутри
    /// себя (`CloseOnClick` — умолчание `Popup`), и щелчок по кнопке языка
    /// закрывал его вместе с только что открытым списком языков. В узком
    /// окне язык было не сменить вовсе, а в широком всё работало: блок там
    /// стоит на месте, без меню вокруг. Проверено красным: с прежним
    /// умолчанием меню закрывается на щелчке по кнопке языка.
    #[test]
    fn the_language_changes_from_the_narrow_rail() {
        let lang = Lang::En;
        let ctx = rail_test_ctx();

        // Меню открыто; первый кадр всплывающего окна — примерочный и
        // невидимый, поэтому кадров несколько.
        let mut named = Vec::new();
        for _ in 0..3 {
            named = narrow_rail_frame(&ctx, lang, true, Vec::new()).1;
        }
        let button = center_of(&named, lang.label()).expect("в меню нет кнопки языка");

        let mut open = true;
        for events in click_at(button) {
            open = narrow_rail_frame(&ctx, lang, open, events).0.more_open;
        }
        assert!(open, "щелчок по кнопке языка закрыл меню свёрнутого рельса");

        for _ in 0..2 {
            named = narrow_rail_frame(&ctx, lang, open, Vec::new()).1;
        }
        let russian = center_of(&named, Lang::Ru.label()).expect("список языков не открылся");

        let mut picked = None;
        for events in click_at(russian) {
            let (picks, _) = narrow_rail_frame(&ctx, lang, open, events);
            open = picks.more_open;
            picked = picked.or(picks.lang);
        }
        assert_eq!(picked, Some(Lang::Ru), "язык из списка не выбрался");
    }

    /// Главная кнопка ряда загрузки в кадрах без окна и со своими часами.
    ///
    /// Щелчок по ней делает то же, что `action_button`: «Отмена» снимает
    /// загрузку, «Скачать» запускает, — так что со следующего кадра на том
    /// же месте стоит кнопка с другим смыслом, ровно как в окне.
    struct CtaRig {
        ctx: egui::Context,
        pause: SwapPause,
        /// Идёт ли загрузка, то есть «Отмена» ли на кнопке.
        running: bool,
        time: f64,
    }

    impl CtaRig {
        /// Три кадра покоя, чтобы кнопка встала на место, и её середина.
        ///
        /// Пауза с самого начала помнит тот смысл, с которым кнопка стоит:
        /// стенд изображает кнопку, висящую так давно, а не только что
        /// сменившуюся. Иначе «Отмена» на первом кадре выглядела бы сменой,
        /// и тесты молча опирались бы на правило про невидимую кнопку.
        fn new(running: bool) -> (Self, egui::Pos2) {
            let mut rig = Self {
                ctx: rail_test_ctx(),
                pause: SwapPause {
                    cancels: running,
                    ..SwapPause::default()
                },
                running,
                time: 0.0,
            };
            let mut named = Vec::new();
            for _ in 0..3 {
                named = rig.frame(0.1, Vec::new()).0;
            }
            let name = i18n::t(Lang::Ru, if running { Key::UiCancel } else { Key::UiDownload });
            let at = center_of(&named, name).unwrap_or_else(|| panic!("в кадре нет «{name}»"));
            (rig, at)
        }

        /// Кадр через `step` секунд после прошлого. Возвращает имена
        /// виджетов и то, через сколько кадр попросил следующий.
        fn frame(
            &mut self,
            step: f64,
            events: Vec<egui::Event>,
        ) -> (Vec<(String, egui::Rect)>, std::time::Duration) {
            self.time += step;
            let input = egui::RawInput {
                screen_rect: Some(SMALLEST_WINDOW),
                time: Some(self.time),
                events,
                ..Default::default()
            };
            let (pause, running) = (&mut self.pause, self.running);
            let mut clicked = false;
            let mut output = self.ctx.run_ui(input, |ui| {
                egui::CentralPanel::default().show(ui, |ui| {
                    ui.horizontal(|ui| {
                        let cta = if running {
                            Cta::Cancel
                        } else {
                            Cta::Download {
                                enabled: true,
                                hint: "",
                            }
                        };
                        clicked = cta_button(ui, theme::Palette::dark(), Lang::Ru, 300.0, cta, pause);
                    });
                });
            });
            if clicked {
                self.running = !self.running;
            }
            output.textures_delta.clear();
            let asked = output
                .viewport_output
                .get(&egui::ViewportId::ROOT)
                .map_or(std::time::Duration::MAX, |viewport| viewport.repaint_delay);
            (named_widgets(&mut output), asked)
        }

        /// Кадр, в котором кнопки нет: человек в другом разделе.
        fn away(&mut self, step: f64) {
            self.time += step;
            let input = egui::RawInput {
                screen_rect: Some(SMALLEST_WINDOW),
                time: Some(self.time),
                ..Default::default()
            };
            let mut output = self.ctx.run_ui(input, |_| {});
            output.textures_delta.clear();
        }

        /// Щелчок в точке `at`: нажатие через `after` секунд после прошлого
        /// кадра, отпускание через `hold` после нажатия и кадр следом — на
        /// нём, как и в окне, кнопка впервые рисуется с новым смыслом.
        fn click(&mut self, at: egui::Pos2, after: f64, hold: f64) {
            let [press, release] = click_at(at);
            self.frame(after, press);
            self.frame(hold, release);
            self.frame(0.016, Vec::new());
        }
    }

    /// Второй щелчок по «Отмене» не запускает снятую загрузку заново
    /// (задача 54).
    ///
    /// «Скачать» и «Отмена» — одна кнопка на одном месте: после первого
    /// щелчка под курсором уже «Скачать», и второй, нетерпеливый, попадал
    /// в неё. Вживую — два щелчка с промежутком в 250 мс, и 4K-ролик
    /// качался по новой. Пауза при этом не навсегда: дождавшись её конца,
    /// «Скачать» запускает, как и раньше.
    ///
    /// Проверено красным: без паузы в `cta_button` второй щелчок проходит.
    #[test]
    fn a_second_cancel_does_not_restart_the_download() {
        let (mut rig, at) = CtaRig::new(true);
        rig.click(at, 0.1, 0.05);
        assert!(!rig.running, "«Отмена» не сняла загрузку");
        rig.click(at, 0.2, 0.05);
        assert!(!rig.running, "второй щелчок по «Отмене» запустил загрузку заново");

        rig.frame(SWAP_PAUSE_SECS, Vec::new());
        rig.click(at, 0.1, 0.05);
        assert!(rig.running, "«Скачать» не ожила после паузы");
    }

    /// Двойной щелчок по «Скачать» не снимает только что начатую загрузку.
    ///
    /// Та же беда в обратную сторону: egui засчитывает оба щелчка двойного
    /// нажатия, и второй приходился уже на «Отмену».
    ///
    /// Проверено красным: без паузы в `cta_button` загрузка снимается.
    #[test]
    fn a_double_click_on_download_does_not_cancel_it() {
        let (mut rig, at) = CtaRig::new(false);
        rig.click(at, 0.1, 0.05);
        assert!(rig.running, "«Скачать» не запустила загрузку");
        rig.click(at, 0.1, 0.05);
        assert!(
            rig.running,
            "двойной щелчок по «Скачать» снял только что начатую загрузку"
        );
    }

    /// Щелчок, нажатый в паузе и отпущенный после неё, не засчитывается.
    ///
    /// Держит это уже egui, а не Savio: выключенная кнопка нажатия не ловит
    /// (`hit_test.rs`), а отпускание без нажатия щелчком не считается. Потому
    /// кнопка в паузе и выключается, а не «пропускает мимо ушей» щелчки при
    /// включённом виде: так отпущенный после паузы щелчок засчитался бы. И
    /// если обновление egui это правило поменяет, заметно станет отсюда.
    ///
    /// Проверено красным дважды: без паузы в `cta_button` и с паузой,
    /// которая не выключает кнопку, а только гасит её щелчки, — вторая
    /// держит оба теста выше и пропускает этот.
    #[test]
    fn a_click_pressed_in_the_pause_does_not_count() {
        let (mut rig, at) = CtaRig::new(true);
        rig.click(at, 0.1, 0.05);
        assert!(!rig.running, "«Отмена» не сняла загрузку");
        // Нажали за 50 мс до конца паузы, отпустили через 50 мс после.
        rig.click(at, SWAP_PAUSE_SECS - 0.05, 0.1);
        assert!(!rig.running, "щелчок, нажатый ещё в паузе, запустил загрузку");
    }

    /// Главная кнопка оживает после паузы сама, без движения мыши.
    ///
    /// egui рисует кадр по вводу и по просьбе, а не по таймеру: не попроси
    /// кнопка кадр к концу паузы, она осталась бы выключенной, пока человек
    /// не шевельнёт мышью. Меряется кадр без ввода через 0.2 с после щелчка,
    /// пока пауза ещё идёт, а не кадр сразу за щелчком: тот egui просит сам,
    /// и нулевую задержку он показывает и без кнопки — тест на нём прошёл бы
    /// со сломанной починкой, так и было.
    ///
    /// Проверено красным: без `request_repaint_after` в `cta_button` этот
    /// кадр следующего не просит вовсе (`Duration::MAX`).
    #[test]
    fn the_main_button_wakes_up_after_the_pause_by_itself() {
        let (mut rig, at) = CtaRig::new(true);
        rig.click(at, 0.1, 0.05);
        assert!(!rig.running, "«Отмена» не сняла загрузку");
        let (_, asked) = rig.frame(0.2, Vec::new());
        assert!(
            asked <= std::time::Duration::from_secs_f64(SWAP_PAUSE_SECS),
            "кнопка в паузе не попросила кадр к её концу: {asked:?}"
        );
    }

    /// Смена смысла, пока главную кнопку не рисовали, паузы не заводит.
    ///
    /// Загрузка кончается и тогда, когда человек в другом разделе, а под
    /// курсором кнопки при этом нет, и ловить нечего. С паузой на любую
    /// смену вернувшийся застал бы «Скачать» выключенной ни с того ни с сего.
    ///
    /// Проверено красным: с паузой на любую смену щелчок сразу после
    /// возвращения не проходит.
    #[test]
    fn a_swap_out_of_sight_leaves_the_main_button_alone() {
        let (mut rig, at) = CtaRig::new(true);

        rig.away(0.1);
        rig.running = false;
        rig.away(0.1);
        rig.frame(0.1, Vec::new());
        rig.click(at, 0.1, 0.05);
        assert!(rig.running, "вернувшись, «Скачать» не приняла щелчка");
    }

    /// Строка недельного прогноза занимает свою высоту, а не весь экран.
    ///
    /// Та же беда, что дефект 42: центрирующий ряд без заданной высоты
    /// забирает весь остаток прокрутки. Проверено красным: с `ui.with_layout`
    /// вместо `allocate_ui_with_layout` в [`day_row`] строка вырастает до
    /// нижней кромки окна.
    #[test]
    fn a_weather_day_row_keeps_its_height() {
        let pal = theme::Palette::dark();
        let day = crate::model::DayView {
            label: "ср, 16 сен".to_owned(),
            temperatures: "−12° … −3°".to_owned(),
            chance: Some("40%".to_owned()),
            sky: Sky::Rain,
            description: "Дождь",
        };
        let height = card_height(|ui| day_row(ui, pal, &day));
        assert!(height > 20.0, "строка дня обрезана: {height}");
        assert!(height < 80.0, "строка дня во весь экран: {height}");
    }

    /// Каждый значок погоды рисуется, днём и ночью, и ни одна фигура не
    /// уезжает в бесконечность.
    ///
    /// Месяц считается тригонометрией (`crescent`), и промах в ней даёт не
    /// панику, а `NaN` в вершинах — значок просто пропадает с экрана, молча.
    #[test]
    fn every_weather_icon_draws_finite_shapes() {
        let pal = theme::Palette::dark();
        const SKIES: [Sky; 9] = [
            Sky::Clear,
            Sky::PartlyCloudy,
            Sky::Cloudy,
            Sky::Fog,
            Sky::Drizzle,
            Sky::Rain,
            Sky::Snow,
            Sky::Thunder,
            Sky::Unknown,
        ];
        let ctx = egui::Context::default();
        theme::install_fonts(&ctx);
        theme::apply(&ctx, pal);
        let input = egui::RawInput {
            screen_rect: Some(egui::Rect::from_min_size(
                egui::Pos2::ZERO,
                egui::vec2(1200.0, 420.0),
            )),
            ..Default::default()
        };
        let mut output = ctx.run_ui(input, |ui| {
            ui.horizontal_wrapped(|ui| {
                for night in [false, true] {
                    for sky in SKIES {
                        let (rect, _) =
                            ui.allocate_exact_size(egui::vec2(64.0, 64.0), egui::Sense::hover());
                        weather_icon(pal, ui.painter(), rect, sky, night);
                    }
                }
            });
        });
        output.textures_delta.clear();

        let mut meshes = 0;
        for clipped in &output.shapes {
            if let egui::Shape::Mesh(mesh) = &clipped.shape {
                meshes += 1;
                assert!(mesh.vertices.len() > 4, "месяц без вершин");
                for vertex in &mesh.vertices {
                    assert!(
                        vertex.pos.x.is_finite() && vertex.pos.y.is_finite(),
                        "вершина месяца в бесконечности: {:?}",
                        vertex.pos
                    );
                }
            }
            let bounds = clipped.shape.visual_bounding_rect();
            assert!(
                !bounds.any_nan(),
                "фигура значка с NaN: {:?}",
                clipped.shape
            );
        }
        // Месяц есть у ясной ночи и у переменной облачности ночью.
        assert!(meshes >= 2, "месяц не нарисовался: {meshes}");
    }

    /// Месяц — серп внутри луны, а не круг.
    ///
    /// Дефект найден глазами при задаче 29: из двух путей по краю тени
    /// выбирался внешний, и полоса между дугами заливала луну целиком —
    /// в ночных столбиках прогноза стояли круги, неотличимые от солнца без
    /// лучей. Ни паники, ни `NaN` при этом не было, так что проверка на
    /// конечность вершин его не видела. Проверено красным: с прежней
    /// свёрткой угла (`(x).rem_euclid(TAU) - PI`) точка серпа уходит за край
    /// луны (22.1 при радиусе 20), и тест падает на первой же проверке.
    #[test]
    fn the_crescent_stays_inside_the_moon() {
        let center = egui::pos2(100.0, 100.0);
        let radius = 20.0;
        let (outer, inner) = crescent_arcs(center, radius);

        for point in outer.iter().chain(&inner) {
            let distance = (*point - center).length();
            assert!(
                distance <= radius * 1.001,
                "точка серпа вне луны: {point:?}, {distance} при радиусе {radius}"
            );
        }

        // Посередине серп толщиной около полрадиуса: тень сдвинута ровно
        // на столько. Круг вместо серпа дал бы здесь почти два радиуса.
        let middle = CRESCENT_STEPS / 2;
        let thickness = (outer[middle] - inner[middle]).length();
        assert!(
            (radius * 0.4..radius * 0.6).contains(&thickness),
            "толщина серпа посередине {thickness} при радиусе {radius}"
        );
    }

    fn sample_check() -> crate::model::Check {
        crate::model::Check {
            name: "Процессор".to_owned(),
            status: crate::model::CheckStatus::Ok,
            summary: "Загрузка в норме.".to_owned(),
            rows: Vec::new(),
            advice: None,
        }
    }

    // -----------------------------------------------------------------------
    // Метаданные
    // -----------------------------------------------------------------------

    /// Панель метаданных посреди задачи — с приёмником, в который тест шлёт
    /// события сам.
    ///
    /// Файла по этому пути нет, и это нарочно: перечитывание, которого ждут
    /// проверки, уходит в настоящий поток движка, а тот на пропавший файл
    /// отвечает мгновенным отказом — ни диска, ни ffprobe.
    fn meta_running(task: MetaTask) -> (MetaPanel, std::sync::mpsc::Sender<Event>) {
        let mut meta = MetaPanel::new();
        meta.path = Some(std::env::temp_dir().join("savio-нет-такого-файла.jpg"));
        meta.readable = true;
        meta.cleanable = true;
        let (tx, rx) = channel();
        meta.rx = Some(rx);
        meta.running = Some(task);
        (meta, tx)
    }

    fn one_place() -> MetaSummary {
        MetaSummary::new(
            &MetaReport {
                size: Some(1),
                tags: vec![Tag::new(TagRole::Place, "Координаты места", "40.1772, 44.5035")],
            },
            Lang::Ru,
        )
    }

    /// После очистки прежняя таблица уходит сразу, а файл перечитывается.
    ///
    /// Иначе стёртые координаты остались бы на экране жёлтой строкой — ровно
    /// то, что человек только что стёр, выглядело бы найденным. И второе:
    /// поток очистки, закончив, закрывает свой канал, и это закрытие не
    /// должно сбросить канал нового чтения. Проверено красным: без
    /// перечитывания в `drain` проверка падает на первом же утверждении
    /// о чтении.
    #[test]
    fn a_wipe_is_followed_by_a_fresh_read() {
        let ctx = egui::Context::default();
        let (mut meta, tx) = meta_running(MetaTask::Clean);
        meta.summary = Some(one_place());
        tx.send(Event::Cleaned(2048)).expect("канал жив");
        drop(tx);

        meta.drain(Lang::Ru, &ctx);

        assert!(meta.summary.is_none(), "таблица до очистки осталась на экране");
        assert_eq!(meta.running, Some(MetaTask::Read), "файл не перечитывается");
        assert!(meta.rx.is_some(), "закрытие старого канала сбросило новый");
        assert!(matches!(meta.outcome, Some((_, Tone::Good))), "{:?}", meta.outcome);
    }

    /// Несостоявшееся чтение встаёт на место таблицы, несостоявшаяся очистка —
    /// под кнопки, и таблица рядом с ней остаётся: файл не тронут.
    #[test]
    fn a_failure_lands_where_its_task_is_shown() {
        let ctx = egui::Context::default();
        let failed = |message: &str| Event::Failed {
            id: NO_DOWNLOAD,
            message: message.to_owned(),
        };

        let (mut meta, tx) = meta_running(MetaTask::Read);
        meta.summary = Some(one_place());
        tx.send(failed("не прочитать")).expect("канал жив");
        meta.drain(Lang::Ru, &ctx);
        assert_eq!(meta.read_error.as_deref(), Some("не прочитать"));
        assert!(meta.summary.is_none(), "таблица пережила отказ перечитать файл");
        assert!(meta.outcome.is_none());

        let (mut meta, tx) = meta_running(MetaTask::Clean);
        meta.summary = Some(one_place());
        tx.send(failed("не стереть")).expect("канал жив");
        meta.drain(Lang::Ru, &ctx);
        assert_eq!(meta.outcome, Some(("не стереть".to_owned(), Tone::Bad)));
        assert!(meta.summary.is_some(), "файл не тронут — таблица по-прежнему верна");
        assert!(meta.read_error.is_none());
    }

    /// Поток, умерший молча — без ответа и без отказа, — это отказ, и его
    /// надо сказать словами.
    ///
    /// Разбор чужих файлов — ровно то место, где прячется паника на битом
    /// входе, и без этой ветки на месте таблицы навсегда остался бы
    /// индикатор «читаю»: задача уже не идёт, а экран об этом не знает.
    /// Проверено красным: без неё проверка падает на отсутствии объяснения.
    #[test]
    fn a_reader_that_dies_silently_is_reported_in_words() {
        let ctx = egui::Context::default();
        let (mut meta, tx) = meta_running(MetaTask::Read);
        drop(tx);
        meta.drain(Lang::Ru, &ctx);
        assert_eq!(meta.running, None, "задача числится идущей после смерти потока");
        assert_eq!(
            meta.read_error.as_deref(),
            Some(i18n::t(Lang::Ru, Key::UiMetaNoAnswer)),
            "молчание потока не объяснено"
        );
    }

    /// Имена и значения записей переводит движок в момент чтения, так что на
    /// смене языка таблицу пересобрать не из чего — файл читается заново.
    /// Посреди очистки — нет: сразу после неё файл перечитается и так.
    #[test]
    fn a_language_change_rereads_what_is_on_screen() {
        let ctx = egui::Context::default();

        let (mut meta, _tx) = meta_running(MetaTask::Read);
        meta.running = None;
        meta.summary = Some(one_place());
        meta.relabel(Lang::En, &ctx);
        assert_eq!(
            meta.running,
            Some(MetaTask::Read),
            "таблица осталась на прежнем языке"
        );

        let (mut meta, _tx) = meta_running(MetaTask::Clean);
        meta.summary = Some(one_place());
        meta.relabel(Lang::En, &ctx);
        assert_eq!(
            meta.running,
            Some(MetaTask::Clean),
            "чтение пошло поперёк очистки"
        );
    }

    /// Итог очистки — готовая строка, и сама она на смене языка не
    /// обновится: пересобирается из запомненного числа.
    #[test]
    fn the_wipe_outcome_follows_the_language() {
        let ctx = egui::Context::default();
        let mut meta = MetaPanel::new();
        meta.freed = Some(2048);
        meta.outcome = Some(wipe_outcome(2048, Lang::Ru));
        meta.relabel(Lang::En, &ctx);
        assert_eq!(
            meta.outcome,
            Some(("Metadata removed, 2.0 KB freed".to_owned(), Tone::Good))
        );
    }

    /// Сводка снимка с телефона — с самыми длинными подписями, какие бывают.
    fn sample_meta(lang: Lang) -> MetaSummary {
        let t = |key| i18n::t(lang, key);
        let tags = vec![
            Tag::new(TagRole::Place, t(Key::TagPlace), "40.1772, 44.5035 · 1180 м"),
            Tag::new(TagRole::Taken, t(Key::TagDateTaken), "14 сен 2025, 19:42"),
            Tag::new(TagRole::Owner, t(Key::TagCameraOwner), "Эрик Чолахян"),
            Tag::new(TagRole::Serial, t(Key::TagCameraSerial), "C39XK0L2HG7F"),
            Tag::new(TagRole::Serial, t(Key::TagLensSerial), "LENS-4821"),
            Tag::new(TagRole::Camera, t(Key::TagMaker), "Apple"),
            Tag::new(TagRole::Camera, t(Key::TagCameraModel), "iPhone 14 Pro"),
            Tag::new(TagRole::Shot, t(Key::TagFocalLength), "6.86 мм"),
            Tag::new(TagRole::Shot, t(Key::TagAperture), "f/1.78"),
            Tag::new(TagRole::Shot, t(Key::TagExposure), "1/120"),
            Tag::new(TagRole::Shot, "ISO", "ISO 250"),
            Tag::new(TagRole::Software, t(Key::TagSoftware), "Adobe Lightroom 7.4"),
            // Слово длиннее строки — худший случай для переноса: пробела,
            // по которому перенести, в нём нет.
            Tag::new(TagRole::Named, t(Key::TagDescription), "Ж".repeat(90)),
            Tag::new(TagRole::Service, t(Key::TagOrientation), "1"),
            Tag::new(TagRole::Service, t(Key::TagDateModified), "15 сен 2025, 08:00"),
            Tag::new(TagRole::Service, t(Key::TagDimensions), "4032 × 3024"),
            Tag::new(
                TagRole::Service,
                t(Key::TagLensModel),
                "iPhone 14 Pro back triple camera 6.86mm f/1.78",
            ),
            Tag::new(TagRole::Service, t(Key::TagThumbnail), "присутствует, 8.0 КБ"),
        ];
        MetaSummary::new(
            &MetaReport {
                size: Some(4_404_019),
                tags,
            },
            lang,
        )
    }

    /// Самые узкие главные колонки «Метаданных». Их две, и уже — вторая:
    /// в окне 520 колонка одна, но во всю ширину (окно минус свёрнутый рельс
    /// и поля), а сразу за порогом двух колонок главной остаётся порог минус
    /// правая колонка и зазор между ними.
    fn main_columns() -> [f32; 2] {
        [
            SMALLEST_WINDOW.width() - theme::NAV_NARROW - theme::CONTENT_MARGIN * 2.0,
            theme::TWO_COLUMN_MIN - theme::RAIL_WIDTH - COLUMN_GAP,
        ]
    }

    /// Один кадр внутри карточки главной колонки: что нарисовано и где
    /// карточка. Высота своя: мерить ширину надо в низком окне, где у
    /// прокрутки есть полоса, а щёлкать — в высоком, где нужная строка не
    /// уехала за нижнюю кромку. Дерево доступности знает и об уехавшей
    /// строке, а вот указатель до неё не дотянется.
    fn card_frame<R>(
        ctx: &egui::Context,
        size: egui::Vec2,
        events: Vec<egui::Event>,
        add: impl FnOnce(&mut egui::Ui) -> R,
    ) -> (R, Vec<(String, egui::Rect)>, egui::Rect) {
        let pal = theme::Palette::dark();
        let input = egui::RawInput {
            screen_rect: Some(egui::Rect::from_min_size(egui::Pos2::ZERO, size)),
            events,
            ..Default::default()
        };
        let mut inner = None;
        let mut add = Some(add);
        let mut card = egui::Rect::NOTHING;
        let mut output = ctx.run_ui(input, |ui| {
            egui::CentralPanel::default()
                .frame(egui::Frame::NONE)
                .show(ui, |ui| {
                    egui::ScrollArea::vertical()
                        .auto_shrink([false, false])
                        .show(ui, |ui| {
                            let add = add.take().expect("кадр рисуется один раз");
                            let shown = theme::card(ui, pal, |ui| add(ui));
                            card = shown.response.rect;
                            inner = Some(shown.inner);
                        });
                });
        });
        output.textures_delta.clear();
        (
            inner.expect("карточка не нарисовалась"),
            named_widgets(&mut output),
            card,
        )
    }

    /// Кадр таблицы метаданных: щёлкнули ли по свёрнутой строке, что
    /// нарисовано и где карточка. Скорость ноль — как с выключенными
    /// «Плавными переходами»: раскрытие без промежуточных кадров.
    fn meta_table_frame(
        ctx: &egui::Context,
        lang: Lang,
        summary: &MetaSummary,
        open: bool,
        size: egui::Vec2,
        events: Vec<egui::Event>,
    ) -> (bool, Vec<(String, egui::Rect)>, egui::Rect) {
        let pal = theme::Palette::dark();
        card_frame(ctx, size, events, |ui| {
            meta_table(ui, pal, summary, lang, open, 0, 0.0)
        })
    }

    /// Прямоугольник виджета с этим именем — или паника с тем, чего нет.
    fn rect_named(named: &[(String, egui::Rect)], lang: Lang, text: &str) -> egui::Rect {
        named
            .iter()
            .find(|(name, _)| name == text)
            .map(|(_, rect)| *rect)
            .unwrap_or_else(|| panic!("{lang:?}: в кадре нет «{text}»"))
    }

    /// Таблица метаданных помещается в самые узкие главные колонки на всех
    /// трёх языках, и значения стоят одной колонкой.
    ///
    /// Колонка подписей — 180 точек, как в макете, и значению остаётся меньше
    /// половины строки. Армянские подписи длиннее русских и переносятся; не
    /// влезшее значение ушло бы за кромку карточки, а подпись, наехавшая на
    /// значение, спутала бы строки. Глазной прогон идёт на одном языке из
    /// трёх и на одной ширине, поэтому и мерит это тест.
    #[test]
    fn the_metadata_table_fits_the_narrowest_column() {
        for width in main_columns() {
            for lang in Lang::ALL {
                // Свой контекст на язык: общий помнит размеры от прошлого и
                // искажает первый кадр следующего.
                let ctx = rail_test_ctx();
                let summary = sample_meta(lang);
                let size = egui::vec2(width, SMALLEST_WINDOW.height());
                let mut frame = (false, Vec::new(), egui::Rect::NOTHING);
                for _ in 0..3 {
                    frame = meta_table_frame(&ctx, lang, &summary, true, size, Vec::new());
                }
                let (_, named, card) = frame;

                let mut column = None;
                for row in summary.rows.iter().chain(&summary.service) {
                    let label = rect_named(&named, lang, &row.label);
                    let value = rect_named(&named, lang, &row.value);
                    assert!(
                        label.max.x <= value.min.x,
                        "{lang:?}, {width}: подпись «{}» налезает на значение",
                        row.label
                    );
                    assert!(
                        value.max.x <= card.max.x,
                        "{lang:?}, {width}: значение «{}» вылезает за карточку: \
                         {value:?} при {card:?}",
                        row.value
                    );
                    let left = *column.get_or_insert(value.min.x);
                    assert!(
                        (value.min.x - left).abs() < 0.5,
                        "{lang:?}, {width}: значение «{}» не в колонке: {} против {left}",
                        row.value,
                        value.min.x
                    );
                }
                assert!(summary.rows[0].personal, "первая строка сводки — не личная");
            }
        }
    }

    /// Плашка с числом личных записей не ложится на название шага.
    ///
    /// `step_header` кладёт её от правой кромки, и если строки не хватает,
    /// она уезжает влево — поверх названия. По-армянски «Ֆայլի մետատվյալներ»
    /// и «12 անձնական գրառում» вместе длиннее строки узкой карточки (найдено
    /// ревью задачи 65). Проверено красным: с плашкой, всегда стоящей рядом
    /// с названием, проверка падает на армянском.
    #[test]
    fn the_personal_plate_never_covers_the_step_title() {
        let pal = theme::Palette::dark();
        for width in main_columns() {
            for lang in Lang::ALL {
                for count in [4_u64, 12] {
                    let words = i18n::plural(
                        lang,
                        count,
                        i18n::t(lang, Key::UiMetaPersonalOne),
                        i18n::t(lang, Key::UiMetaPersonalFew),
                        i18n::t(lang, Key::UiMetaPersonalMany),
                    );
                    let plate = i18n::fill(
                        i18n::t(lang, Key::UiMetaPersonalCount),
                        &[&count.to_string(), words],
                    );
                    let ctx = rail_test_ctx();
                    let size = egui::vec2(width, SMALLEST_WINDOW.height());
                    let mut named = Vec::new();
                    for _ in 0..3 {
                        named = card_frame(&ctx, size, Vec::new(), |ui| {
                            findings_header(ui, pal, lang, &plate)
                        })
                        .1;
                    }
                    let title = rect_named(&named, lang, i18n::t(lang, Key::UiMetaFileTags));
                    let pill = rect_named(&named, lang, &plate);
                    assert!(
                        title.max.x <= pill.min.x || title.max.y <= pill.min.y,
                        "{lang:?}, {width}, {count}: плашка {pill:?} лежит на названии {title:?}"
                    );
                }
            }
        }
    }

    /// Служебные записи раскрываются щелчком по своей строке — и строка
    /// находится по имени, то есть названа и для экранного диктора.
    #[test]
    fn the_service_records_unfold_on_click() {
        let tall = egui::vec2(main_columns()[0], 1600.0);
        let lang = Lang::Ru;
        let ctx = rail_test_ctx();
        let summary = sample_meta(lang);
        assert!(!summary.service.is_empty(), "образец собран без хвоста");
        let hidden = &summary.service[0].value;

        let mut named = Vec::new();
        for _ in 0..3 {
            named = meta_table_frame(&ctx, lang, &summary, false, tall, Vec::new()).1;
        }
        assert!(
            !named.iter().any(|(name, _)| name == hidden),
            "свёрнутый хвост виден"
        );

        let row = center_of(&named, i18n::t(lang, Key::UiMetaServiceRecords))
            .expect("у свёрнутой строки нет имени");
        let mut toggled = false;
        for events in click_at(row) {
            toggled |= meta_table_frame(&ctx, lang, &summary, false, tall, events).0;
        }
        assert!(toggled, "щелчок по свёрнутой строке ничего не сделал");

        for _ in 0..3 {
            named = meta_table_frame(&ctx, lang, &summary, true, tall, Vec::new()).1;
        }
        assert!(
            named.iter().any(|(name, _)| name == hidden),
            "раскрытый хвост не показал записей"
        );
    }

    /// Кнопки раздела не вылезают за карточку ни на одном языке.
    ///
    /// «Прочитать снова» получает треть ширины, но это пол: армянская
    /// подпись в узкой колонке шире трети, и если бы ширины делились
    /// заранее, «Стереть всё» уехала бы за кромку.
    #[test]
    fn the_metadata_buttons_fit_the_narrowest_column() {
        let pal = theme::Palette::dark();
        for width in main_columns() {
            for lang in Lang::ALL {
                let ctx = rail_test_ctx();
                let size = egui::vec2(width, SMALLEST_WINDOW.height());
                let mut frame = ((), Vec::new(), egui::Rect::NOTHING);
                for _ in 0..3 {
                    frame = card_frame(&ctx, size, Vec::new(), |ui| {
                        meta_actions(ui, pal, lang, true, true, "");
                    });
                }
                let ((), named, card) = frame;

                let wipe_name = i18n::t(lang, Key::UiMetaWipe);
                let read = rect_named(&named, lang, i18n::t(lang, Key::UiMetaReadAgain));
                let wipe = rect_named(&named, lang, wipe_name);
                assert!(
                    read.max.x <= wipe.min.x,
                    "{lang:?}, {width}: кнопки налезают друг на друга"
                );
                assert!(
                    wipe.max.x <= card.max.x,
                    "{lang:?}, {width}: «{wipe_name}» вылезает за карточку: \
                     {wipe:?} при {card:?}"
                );
                assert!(
                    read.width() < wipe.width(),
                    "{lang:?}, {width}: главное действие раздела уже вторичного"
                );
            }
        }
    }

    /// Правая колонка помещается в свою ширину на всех трёх языках, а
    /// указатель на «Загрузку» — нажимается.
    #[test]
    fn the_metadata_rail_fits_and_points_to_the_download_section() {
        let pal = theme::Palette::dark();
        let width = theme::RAIL_WIDTH;
        for lang in Lang::ALL {
            let ctx = rail_test_ctx();
            let frame = |events: Vec<egui::Event>| {
                let input = egui::RawInput {
                    screen_rect: Some(egui::Rect::from_min_size(
                        egui::Pos2::ZERO,
                        egui::vec2(width, 900.0),
                    )),
                    events,
                    ..Default::default()
                };
                let mut clicked = false;
                let mut output = ctx.run_ui(input, |ui| {
                    egui::CentralPanel::default()
                        .frame(egui::Frame::NONE)
                        .show(ui, |ui| {
                            clicked = metadata_rail(ui, pal, lang, 0.0, None, None);
                        });
                });
                output.textures_delta.clear();
                (clicked, named_widgets(&mut output))
            };

            let mut named = Vec::new();
            for _ in 0..3 {
                named = frame(Vec::new()).1;
            }
            for (name, rect) in &named {
                assert!(
                    rect.max.x <= width + 0.5,
                    "{lang:?}: «{name}» вылезает из колонки: {rect:?}"
                );
            }

            let button = center_of(&named, i18n::t(lang, Key::UiMetaOpenDownload))
                .expect("нет указателя на «Загрузку»");
            let mut clicked = false;
            for events in click_at(button) {
                clicked |= frame(events).0;
            }
            assert!(clicked, "{lang:?}: указатель на «Загрузку» не нажимается");
        }
    }

    /// Имени файла в таблетке остаётся место, а сведения рядом с ним не
    /// выталкивают таблетку на кнопку выбора.
    ///
    /// Прежде место отмерялось сначала сведениям, и у MP3 хвост «размер ·
    /// длительность · битрейт» в окне 520 оставлял имени одну букву, а у
    /// записи на час с лишним рамка заезжала на «Выбрать другой» (найдено
    /// ревью задачи 65). Мерится весь ряд, с кнопкой и в карточке, — таблетка
    /// одна на всю колонку места имела бы вдвое больше и проверяла бы себя.
    /// Проверено красным: с прежним делением места падает на первом же MP3.
    #[test]
    fn a_file_name_keeps_its_share_next_to_long_facts() {
        let pal = theme::Palette::dark();
        let name = "Ночной трамвай (remastered 2025).mp3";
        for width in main_columns() {
            for lang in Lang::ALL {
                for facts in ["· 4.2 МБ · 3:25 · 320 кбит/с", "· 80.4 МБ · 1:23:45 · 128 кбит/с"] {
                    let ctx = rail_test_ctx();
                    let size = egui::vec2(width, SMALLEST_WINDOW.height());
                    let file = FilePill {
                        name,
                        facts,
                        path: "C:/музыка/Ночной трамвай (remastered 2025).mp3",
                    };
                    let mut named = Vec::new();
                    for _ in 0..3 {
                        named = card_frame(&ctx, size, Vec::new(), |ui| {
                            file_row(ui, pal, lang, Some(file), false, 0.0)
                        })
                        .1;
                    }

                    let button = rect_named(&named, lang, i18n::t(lang, Key::UiMetaPickAnother));
                    let shown = rect_named(&named, lang, name);
                    let tail = rect_named(&named, lang, facts);
                    assert!(
                        shown.width() >= 60.0,
                        "{lang:?}, {width}, «{facts}»: имени осталось {} точек",
                        shown.width()
                    );
                    assert!(
                        shown.max.x <= tail.min.x + 0.5,
                        "{lang:?}, {width}, «{facts}»: имя налезает на сведения"
                    );
                    assert!(
                        tail.max.x <= button.min.x,
                        "{lang:?}, {width}, «{facts}»: сведения {tail:?} заезжают на \
                         кнопку {button:?}"
                    );
                }
            }
        }
    }
}
